fn validator_funding_requirement_nwei() -> u64 {
    VALIDATOR_FUNDING_SNRG.saturating_mul(TOKEN_SCALE)
}

fn validator_fee_reserve_requirement_nwei() -> u64 {
    VALIDATOR_FEE_RESERVE_SNRG.saturating_mul(TOKEN_SCALE)
}

fn validator_fee_reserve_required_message() -> String {
    VALIDATOR_FEE_RESERVE_REQUIRED_MESSAGE.to_string()
}

fn validator_funding_amount_error(amount_snrg: u64) -> String {
    if amount_snrg == MINIMUM_STAKE_SNRG {
        validator_fee_reserve_required_message()
    } else {
        format!(
            "Validator funding requires at least {VALIDATOR_FUNDING_SNRG} SNRG: {MINIMUM_STAKE_SNRG} SNRG bond plus {VALIDATOR_FEE_RESERVE_SNRG} SNRG fee reserve; received {amount_snrg} SNRG."
        )
    }
}

fn validator_funding_status(balance_nwei: u64, staked_nwei: u64) -> &'static str {
    let funding_requirement_nwei = validator_funding_requirement_nwei();
    let fee_reserve_requirement_nwei = validator_fee_reserve_requirement_nwei();
    if balance_nwei >= funding_requirement_nwei
        || (staked_nwei >= MINIMUM_STAKE_SNRG.saturating_mul(TOKEN_SCALE)
            && balance_nwei >= fee_reserve_requirement_nwei)
    {
        "pass"
    } else if balance_nwei == MINIMUM_STAKE_SNRG.saturating_mul(TOKEN_SCALE)
        || (staked_nwei >= MINIMUM_STAKE_SNRG.saturating_mul(TOKEN_SCALE)
            && balance_nwei < validator_fee_reserve_requirement_nwei())
    {
        FEE_RESERVE_REQUIRED_STATUS
    } else {
        "fail"
    }
}

fn is_testnet_bootstrap_validator_address(address: &str) -> bool {
    let trimmed = address.trim();
    TESTNET_BOOTSTRAP_VALIDATOR_ORDER.contains(&trimmed)
}

fn is_false(value: &bool) -> bool {
    !*value
}

fn testnet_validator_quorum(total_validators: usize) -> usize {
    if total_validators == 0 {
        0
    } else {
        // Smallest q satisfying 3*q > 2*n, without multiplication overflow.
        total_validators - (total_validators - 1) / 3
    }
}

fn testnet_validator_cluster_quorum(cluster_size: usize) -> usize {
    testnet_validator_quorum(cluster_size)
}

fn testnet_validator_cluster_count(total_validators: usize) -> usize {
    if total_validators == 0 {
        0
    } else if total_validators < TESTNET_FIRST_CLUSTER_SPLIT_THRESHOLD {
        1
    } else if total_validators < TESTNET_THIRD_CLUSTER_SPLIT_THRESHOLD {
        2
    } else {
        total_validators / TESTNET_VALIDATOR_CLUSTER_TARGET_SIZE
    }
}

fn testnet_validator_cluster_size(total_validators: usize) -> usize {
    let cluster_count = testnet_validator_cluster_count(total_validators);
    if cluster_count == 0 {
        0
    } else {
        total_validators.div_ceil(cluster_count)
    }
}

fn testnet_epoch_for_block_height(block_height: u64) -> u64 {
    block_height.saturating_sub(1) / TESTNET_EPOCH_LENGTH as u64
}

fn testnet_epoch_start_height(epoch: u64) -> u64 {
    epoch
        .saturating_mul(TESTNET_EPOCH_LENGTH as u64)
        .saturating_add(1)
}

fn testnet_epoch_end_height(epoch: u64) -> u64 {
    epoch
        .saturating_add(1)
        .saturating_mul(TESTNET_EPOCH_LENGTH as u64)
}

fn testnet_is_epoch_start_height(block_height: u64) -> bool {
    block_height > 0
        && block_height == testnet_epoch_start_height(testnet_epoch_for_block_height(block_height))
}

fn testnet_is_epoch_end_height(block_height: u64) -> bool {
    block_height > 0
        && block_height == testnet_epoch_end_height(testnet_epoch_for_block_height(block_height))
}

fn current_testnet_validator_count() -> usize {
    let count = canonical_testnet_validator_peers().len();
    if count == 0 {
        TESTNET_GENESIS_SETUP_PACKAGE_VALIDATOR_COUNT
    } else {
        count
    }
}

