async fn query_validator_self_realignment_status(
    client: &Client,
    rpc_endpoint: &str,
    local_rpc_ready: bool,
) -> Value {
    if !local_rpc_ready {
        return json!({
            "available": false,
            "status": "local_rpc_unavailable",
            "errors": [],
            "operator_actions": {
                "force_active_available": false,
                "force_active_visible": false,
            },
        });
    }

    let (
        divergence_result,
        quarantine_result,
        self_heal_result,
        snapshot_catalog_result,
        shadow_result,
        rejoin_result,
    ) = tokio::join!(
        query_rpc_value(
            client,
            rpc_endpoint,
            "synergy_getDivergenceStatus",
            json!([])
        ),
        query_rpc_value(
            client,
            rpc_endpoint,
            "synergy_getQuarantineStatus",
            json!([])
        ),
        query_rpc_value(client, rpc_endpoint, "synergy_getSelfHealStatus", json!([])),
        query_rpc_value(
            client,
            rpc_endpoint,
            "synergy_getSnapshotCatalog",
            json!([])
        ),
        query_rpc_value(client, rpc_endpoint, "synergy_getShadowStatus", json!([])),
        query_rpc_value(
            client,
            rpc_endpoint,
            "synergy_getRejoinEligibility",
            json!([])
        ),
    );

    let mut output = serde_json::Map::new();
    let mut errors = Vec::new();
    insert_rpc_probe(
        &mut output,
        &mut errors,
        "divergence_status",
        "synergy_getDivergenceStatus",
        divergence_result,
    );
    insert_rpc_probe(
        &mut output,
        &mut errors,
        "quarantine_status",
        "synergy_getQuarantineStatus",
        quarantine_result,
    );
    insert_rpc_probe(
        &mut output,
        &mut errors,
        "self_heal_status",
        "synergy_getSelfHealStatus",
        self_heal_result,
    );
    insert_rpc_probe(
        &mut output,
        &mut errors,
        "snapshot_catalog",
        "synergy_getSnapshotCatalog",
        snapshot_catalog_result,
    );
    insert_rpc_probe(
        &mut output,
        &mut errors,
        "shadow_status",
        "synergy_getShadowStatus",
        shadow_result,
    );
    insert_rpc_probe(
        &mut output,
        &mut errors,
        "rejoin_eligibility",
        "synergy_getRejoinEligibility",
        rejoin_result,
    );
    output.insert("available".to_string(), json!(errors.len() < 6));
    output.insert("errors".to_string(), Value::Array(errors));
    output.insert(
        "operator_actions".to_string(),
        json!({
            "force_active_available": false,
            "force_active_visible": false,
            "self_heal_from_snapshot_available": true,
            "request_rejoin_available": true,
        }),
    );
    Value::Object(output)
}

fn insert_rpc_probe(
    output: &mut serde_json::Map<String, Value>,
    errors: &mut Vec<Value>,
    key: &str,
    method: &str,
    result: Result<Value, String>,
) {
    match result {
        Ok(value) => {
            output.insert(key.to_string(), value);
        }
        Err(error) => {
            output.insert(key.to_string(), Value::Null);
            errors.push(json!({
                "method": method,
                "error": error,
            }));
        }
    }
}

fn build_validator_quarantine_panel_status(
    self_realignment: &Value,
    recovery_state: &str,
    duty_can_vote: bool,
    duty_can_propose: bool,
    duty_can_aggregate_qc: bool,
    duty_can_count_toward_quorum: bool,
    duty_can_enter_proposer_schedule: bool,
) -> Value {
    let quarantine = self_realignment
        .get("quarantine_status")
        .cloned()
        .unwrap_or_else(|| json!({}));
    let divergence = self_realignment
        .get("divergence_status")
        .cloned()
        .unwrap_or_else(|| json!({}));
    let self_heal = self_realignment
        .get("self_heal_status")
        .cloned()
        .unwrap_or_else(|| json!({}));
    let shadow = self_realignment
        .get("shadow_status")
        .cloned()
        .unwrap_or_else(|| json!({}));
    let rejoin = self_realignment
        .get("rejoin_eligibility")
        .cloned()
        .unwrap_or_else(|| json!({}));
    let marker_paths = quarantine
        .get("marker_paths")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let evidence_path = marker_paths
        .as_array()
        .and_then(|items| items.first())
        .cloned()
        .unwrap_or(Value::Null);
    let quarantined = quarantine
        .get("quarantined")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let rejoin_eligible = rejoin
        .get("eligible")
        .and_then(Value::as_bool)
        .or_else(|| {
            quarantine
                .get("rejoin_eligibility")
                .and_then(Value::as_bool)
        })
        .unwrap_or(false);

    json!({
        "reason": if quarantined { json!("quarantine marker present") } else { Value::Null },
        "trigger": quarantine.get("status").cloned().unwrap_or(Value::Null),
        "divergence_height": divergence.get("canonical_lock_height").cloned().unwrap_or(Value::Null),
        "divergence_cause": if quarantined { "CANONICAL_DIVERGENCE_OR_LOCAL_QUARANTINE" } else { "NONE" },
        "local_divergent_block_hash": divergence.get("latest_hash").cloned().unwrap_or(Value::Null),
        "canonical_block_hash": divergence.get("latest_hash").cloned().unwrap_or(Value::Null),
        "reconciliation_step": recovery_state,
        "recovery_state": recovery_state,
        "evidence_path": evidence_path,
        "marker_paths": marker_paths,
        "voting_disabled": !duty_can_vote,
        "proposing_disabled": !duty_can_propose,
        "qc_aggregation_disabled": !duty_can_aggregate_qc,
        "count_toward_quorum_disabled": !duty_can_count_toward_quorum,
        "proposer_schedule_disabled": !duty_can_enter_proposer_schedule,
        "rejoin_eligible": rejoin_eligible,
        "rejoin_blocked_reasons": rejoin.get("blocked_reasons").cloned().unwrap_or_else(|| json!([])),
        "self_heal_status": self_heal,
        "shadow_status": shadow,
        "raw_quarantine_status": quarantine,
        "raw_divergence_status": divergence,
    })
}

fn snapshot_verification_status(self_realignment: &Value, is_syncing: bool) -> &'static str {
    let snapshot_count = self_realignment
        .get("snapshot_catalog")
        .and_then(|value| value.get("snapshots"))
        .and_then(Value::as_array)
        .map(|items| items.len())
        .unwrap_or(0);
    if snapshot_count > 0 {
        "catalog_available"
    } else if is_syncing {
        "pending"
    } else {
        "not_required"
    }
}

