pub async fn testnet_mark_setup_sync_complete(
    input: TestnetSetupSyncCompleteInput,
) -> Result<TestnetSetupSyncCompleteResult, String> {
    let root = ensure_testnet_root()?;
    let mut registry = load_registry(&root)?;
    let registry_reconstructed =
        reconstruct_validator_registry_from_workspace_identity(&mut registry)?;
    let registry_repaired = reconcile_validator_registry_from_workspace_identity(&mut registry)?;
    if registry_reconstructed || registry_repaired {
        save_registry(&root, &registry)?;
    }
    let node = registry
        .nodes
        .into_iter()
        .find(|node| node.id == input.node_id)
        .ok_or_else(|| format!("Testnet node {} not found.", input.node_id))?;

    if !role_supports_validator_registration(&node.role_id) {
        return Err(
            "Setup sync completion markers are only valid for validator nodes.".to_string(),
        );
    }
    if provisioned_node_uses_private_validator_mesh(&node) {
        return Err(
            "Operational validators using legacy private mesh topology do not use the setup sync gate."
                .to_string(),
        );
    }
    let normal_sync_requested = setup_sync_normal_mode_selected(&node, input.sync_mode.as_deref());
    let normal_head_evidence =
        if normal_sync_requested {
            match verified_normal_sync_head_evidence(&node) {
                Ok(evidence) => Some(evidence),
                Err(source_majority_error) => {
                    let local_height = input
                        .local_chain_height
                        .ok_or_else(|| source_majority_error.clone())?;
                    let client = Client::builder()
                        .timeout(Duration::from_secs(8))
                        .connect_timeout(Duration::from_secs(3))
                        .build()
                        .map_err(|error| format!("HTTP client error: {error}"))?;
                    Some(verified_normal_sync_resume_head_evidence(
                    &client,
                    &node,
                    local_height,
                    input.sync_target_height,
                )
                .await
                .map_err(|error| {
                    format!("{source_majority_error}; normal-sync resume proof rejected: {error}")
                })?)
                }
            }
        } else {
            None
        };
    let normal_account_state_parity = if normal_sync_requested {
        let client = Client::builder()
            .timeout(Duration::from_secs(8))
            .connect_timeout(Duration::from_secs(3))
            .build()
            .map_err(|error| format!("HTTP client error: {error}"))?;
        Some(verified_normal_sync_account_state_parity(&client, &node).await?)
    } else {
        None
    };
    if !normal_sync_requested && !validator_snapshot_restore_evidence_is_verified(&node) {
        return Err(
            "Cannot mark setup sync complete until archive-validator-produced validator-pruned snapshot restore evidence is verified."
                .to_string(),
        );
    }

    let local_chain_height = input.local_chain_height.ok_or_else(|| {
        "Cannot mark setup sync complete without a verified local chain height.".to_string()
    })?;
    if local_chain_height == 0 {
        return Err("Cannot mark setup sync complete at local chain height 0.".to_string());
    }
    if input
        .sync_gap
        .is_some_and(|gap| gap > TESTNET_ACTIVATION_MAX_SYNC_GAP)
    {
        return Err(format!(
            "Cannot mark setup sync complete while sync gap is above {TESTNET_ACTIVATION_MAX_SYNC_GAP} block(s)."
        ));
    }
    if let Some(target_height) = input.sync_target_height {
        let gap = target_height.saturating_sub(local_chain_height);
        if gap > TESTNET_ACTIVATION_MAX_SYNC_GAP {
            return Err(format!(
                "Cannot mark setup sync complete at h{local_chain_height}; target h{target_height} still has gap {gap}."
            ));
        }
    }

    if let Some((_, canonical_height, _)) = normal_head_evidence.as_ref() {
        if local_chain_height != *canonical_height {
            return Err(format!(
                "Cannot mark normal peer sync complete at local h{local_chain_height}; verified canonical head is h{canonical_height}."
            ));
        }
        if input
            .sync_target_height
            .is_some_and(|target_height| target_height != *canonical_height)
        {
            return Err(format!(
                "Cannot mark normal peer sync complete with target height {:?}; verified canonical head is h{canonical_height}.",
                input.sync_target_height
            ));
        }
        if input.sync_gap.is_some_and(|gap| gap != 0) {
            return Err(
                "Cannot mark normal peer sync complete while the reported sync gap is non-zero."
                    .to_string(),
            );
        }
    }

    let snapshot_restore_path = snapshot_restore_evidence_path(&node);
    let snapshot_restore = if normal_sync_requested {
        Value::Null
    } else {
        read_json_value(&snapshot_restore_path)?
    };
    let evidence_path = setup_sync_complete_evidence_path(&node);
    let evidence = json!({
        "status": "ok",
        "node_id": node.id,
        "validator_address": node.node_address,
        "chain_id": TESTNET_CHAIN_ID,
        "network_id": TESTNET_NETWORK_ID_V2,
        "sync_mode": if normal_sync_requested { "normal" } else { "snapshot" },
        "snapshot_class": if normal_sync_requested { "normal-peer-sync" } else { "validator-pruned" },
        "snapshot_restore_verified": !normal_sync_requested,
        "snapshot_restore_evidence_path": if normal_sync_requested { Value::Null } else { json!(snapshot_restore_path) },
        "snapshot_id": snapshot_restore.get("snapshot_id").cloned().unwrap_or(Value::Null),
        "snapshot_height": snapshot_restore.get("height").cloned().unwrap_or(Value::Null),
        "local_chain_height": local_chain_height,
        "sync_target_height": input.sync_target_height,
        "sync_gap": input.sync_gap,
        "head_match_evidence_path": normal_head_evidence.as_ref().map(|(path, _, _)| path),
        "head_match_evidence_verified": normal_head_evidence.is_some(),
        "canonical_head_height": normal_head_evidence
            .as_ref()
            .map(|(_, height, _)| *height),
        "canonical_head_hash": normal_head_evidence
            .as_ref()
            .map(|(_, _, hash)| hash),
        "account_state_parity_verified": normal_account_state_parity.is_some(),
        "account_state_parity_proof": normal_account_state_parity.unwrap_or(Value::Null),
        "completed_at_utc": Utc::now().to_rfc3339(),
    });
    write_json_file(&evidence_path, &evidence)?;

    Ok(TestnetSetupSyncCompleteResult {
        node_id: input.node_id,
        status: "ok".to_string(),
        evidence_path: evidence_path.to_string_lossy().to_string(),
        message: if normal_sync_requested {
            "Validator setup sync gate completed after verified normal peer synchronization to the canonical head.".to_string()
        } else {
            "Validator setup sync gate completed after verified archive snapshot restore and catch-up.".to_string()
        },
    })
}

pub async fn testnet_erase_local_machine_data(
    app_context: &AppContext,
    input: TestnetEraseNodeDataInput,
) -> Result<TestnetEraseNodeDataResult, String> {
    let requested_platform = normalize_testnet_cleanup_platform(&input.target_os)?;
    let current_platform = current_testnet_cleanup_platform();
    if requested_platform != current_platform {
        return Err(format!(
            "This Control Panel install is running on {}. Use the {} erase button on this machine.",
            current_platform, current_platform
        ));
    }

    let root = testnet_root_path()?;
    let registry = if root.exists() {
        load_registry(&root).unwrap_or_default()
    } else {
        TestnetRegistryFile::default()
    };

    let mut killed_process_count = 0usize;
    for node in &registry.nodes {
        killed_process_count = killed_process_count.saturating_add(
            force_kill_workspace_processes(Path::new(&node.workspace_directory)).unwrap_or(0),
        );
    }
    killed_process_count =
        killed_process_count.saturating_add(force_kill_testnet_processes_under_root(&root)?);

    let mut removed_paths = Vec::new();
    remove_path_if_exists(&root, &mut removed_paths)?;
    for path in candidate_local_testnet_cleanup_paths(app_context) {
        remove_path_if_exists(&path, &mut removed_paths)?;
    }
    erase_local_innernet_client_state(requested_platform, &mut removed_paths)?;

    let recreated_root = ensure_testnet_root()?;
    let _ = load_or_create_network_profile(&recreated_root)?;
    save_registry(
        &recreated_root,
        &TestnetRegistryFile {
            version: STATE_VERSION,
            nodes: Vec::new(),
        },
    )?;

    Ok(TestnetEraseNodeDataResult {
        target_os: requested_platform.to_string(),
        status: "erased".to_string(),
        message: format!(
            "Erased local Testnet node data for {}. Removed {} path(s), stopped {} process(es), and reset {} workspace record(s).",
            requested_platform,
            removed_paths.len(),
            killed_process_count,
            registry.nodes.len()
        ),
        erased_root: recreated_root.to_string_lossy().to_string(),
        removed_workspace_count: registry.nodes.len(),
        killed_process_count,
        removed_paths,
    })
}

pub async fn testnet_reset_innernet_client_state(
    input: TestnetEraseNodeDataInput,
) -> Result<TestnetEraseNodeDataResult, String> {
    let requested_platform = normalize_testnet_cleanup_platform(&input.target_os)?;
    let current_platform = current_testnet_cleanup_platform();
    if requested_platform != current_platform {
        return Err(format!(
            "This Control Panel install is running on {}. Use the {} secure-network reset button on this machine.",
            current_platform, current_platform
        ));
    }

    let mut removed_paths = Vec::new();
    erase_local_innernet_client_state(requested_platform, &mut removed_paths)?;

    Ok(TestnetEraseNodeDataResult {
        target_os: requested_platform.to_string(),
        status: "innernet-reset".to_string(),
        message: format!(
            "Reset local secure-network client state for {}. Removed stale sy-vpn config, service, interface, and Innernet logs without deleting validator keys, wallet, stake, or chain data.",
            requested_platform
        ),
        erased_root: String::new(),
        removed_workspace_count: 0,
        killed_process_count: 0,
        removed_paths,
    })
}

pub async fn testnet_import_ceremony_package(
    input: TestnetImportCeremonyPackageInput,
) -> Result<TestnetImportCeremonyPackageResult, String> {
    let requested_role = input
        .setup_role_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);

    let package_path = PathBuf::from(input.package_path.trim());
    if !package_path.exists() {
        return Err(format!(
            "Ceremony package not found: {}",
            package_path.display()
        ));
    }

    if matches!(
        requested_role.as_deref(),
        Some("bootnode") | Some("seed_server")
    ) {
        return import_bootstrap_bundle(
            requested_role.expect("validated bootstrap role should exist"),
            package_path,
            input.intended_directory,
        )
        .await;
    }

    let package = load_ceremony_package(&package_path)?;
    let resolved_role = validate_ceremony_package(&package, requested_role.as_deref())?;
    let requested_public_host = input
        .public_host
        .clone()
        .or_else(|| package.public_host.clone());
    let setup_public_host = if package.runtime_identity.is_some() {
        Some(requested_public_host.unwrap_or_else(|| "127.0.0.1".to_string()))
    } else {
        requested_public_host.clone()
    };

    let root = ensure_testnet_root()?;
    let mut reused_existing_workspace = false;
    let mut setup_result = if let Some(existing_node) = find_existing_ceremony_node_match(
        &load_registry(&root)?,
        &package,
        input.intended_directory.as_deref(),
    ) {
        reused_existing_workspace = true;
        let device_profile = detect_device_profile();
        let monitoring = write_onboarding_monitoring_artifacts(&existing_node, &device_profile)
            .unwrap_or_else(|error| monitoring_error_result(&existing_node, error));
        TestnetSetupResult {
            node: existing_node.clone(),
            network_profile: load_or_create_network_profile(&root)?,
            device_profile,
            monitoring,
            next_steps: vec![format!(
                "Reusing the existing Control Panel workspace at {} for this approved genesis assignment.",
                existing_node.workspace_directory
            )],
        }
    } else {
        testnet_setup_node(TestnetSetupInput {
            role_id: resolved_role.clone(),
            display_label: Some(package.display_name.clone()),
            intended_directory: input.intended_directory.clone(),
            public_host: setup_public_host,
            public_p2p_port: None,
            nat_mode: None,
            node_address_override: package
                .runtime_identity
                .as_ref()
                .map(|identity| identity.address.clone()),
            identity_passphrase: input.identity_passphrase.clone(),
            packaged_validator_identity: None,
            skip_canonical_manifests: true,
        })
        .await?
    };
    let workspace_directory = PathBuf::from(&setup_result.node.workspace_directory);
    let staged_package_path =
        workspace_manifest_directory_for_role(&package.role_id, &workspace_directory)
            .join("ceremony-package.json");
    write_json_file(
        &staged_package_path,
        &serde_json::to_value(&package)
            .map_err(|error| format!("Failed to serialize ceremony package: {error}"))?,
    )?;
    write_package_artifacts_to_workspace(&workspace_directory, &package.artifacts)?;

    let mut staged_paths = vec![
        staged_package_path.to_string_lossy().to_string(),
        workspace_directory
            .join("config")
            .join("genesis.json")
            .to_string_lossy()
            .to_string(),
        workspace_directory
            .join("config")
            .join("operational-manifest.json")
            .to_string_lossy()
            .to_string(),
    ];

    if let Some(runtime_identity) = package.runtime_identity.as_ref() {
        let identity_paths = apply_imported_runtime_identity(
            &root,
            &mut setup_result,
            runtime_identity,
            &package,
            input
                .public_host
                .as_deref()
                .or(package.public_host.as_deref()),
        )?;
        staged_paths.extend(identity_paths);
    }
    setup_result.monitoring =
        write_onboarding_monitoring_artifacts(&setup_result.node, &setup_result.device_profile)
            .unwrap_or_else(|error| monitoring_error_result(&setup_result.node, error));
    staged_paths.extend(setup_result.monitoring.generated_paths.clone());

    let message = if reused_existing_workspace && package.runtime_identity.is_some() {
        format!(
            "{} package refreshed the existing workspace at {}. Jarvis reused the current Control Panel workspace instead of provisioning a second validator runtime.",
            package.display_name,
            workspace_directory.display()
        )
    } else if reused_existing_workspace {
        format!(
            "{} package refreshed the existing workspace at {}. Jarvis reused the current Control Panel workspace instead of provisioning a second node workspace.",
            package.display_name,
            workspace_directory.display()
        )
    } else if package.runtime_identity.is_some() {
        format!(
            "{} package imported into {}. The validator appliance now carries the approved validator identity and canonical Testnet evidence.",
            package.display_name,
            workspace_directory.display()
        )
    } else {
        format!(
            "{} package imported into {}. The validator appliance now carries the canonical Testnet evidence and approved role metadata.",
            package.display_name,
            workspace_directory.display()
        )
    };

    let mut next_steps = setup_result.next_steps.clone();
    if !package.notes.is_empty() {
        next_steps.extend(package.notes.iter().cloned());
    }

    Ok(TestnetImportCeremonyPackageResult {
        import_mode: "runtime-role".to_string(),
        role_id: package.role_id,
        display_name: package.display_name,
        workspace_directory: workspace_directory.to_string_lossy().to_string(),
        package_path: package_path.to_string_lossy().to_string(),
        staged_paths,
        message,
        next_steps,
        node: Some(setup_result.node),
        network_profile: Some(setup_result.network_profile),
    })
}

