pub async fn testnet_get_live_status() -> Result<TestnetLiveStatus, String> {
    let state = build_state()?;
    let client = Client::builder()
        .timeout(Duration::from_secs(8))
        .build()
        .map_err(|error| format!("Failed to create live-status HTTP client: {error}"))?;

    let bootnodes_future = join_all(
        state
            .network_profile
            .bootnodes
            .iter()
            .cloned()
            .map(check_bootstrap_endpoint),
    );
    let seed_servers_future = join_all(
        state
            .network_profile
            .seed_servers
            .iter()
            .cloned()
            .map(|endpoint| check_seed_endpoint(&client, endpoint)),
    );
    let public_chain_height_future = query_public_chain_height(&client);
    let public_peer_count_future = query_public_peer_count(&client);
    let network_peer_count_future =
        query_seed_peer_count(&client, &state.network_profile.seed_servers);

    let (
        bootnodes,
        seed_servers,
        public_chain_height_result,
        public_peer_count_result,
        network_peer_count_result,
    ) = tokio::join!(
        bootnodes_future,
        seed_servers_future,
        public_chain_height_future,
        public_peer_count_future,
        network_peer_count_future,
    );

    let public_chain_height = public_chain_height_result.ok();
    let public_peer_count = public_peer_count_result.ok();
    let network_peer_count = network_peer_count_result.ok();
    let public_rpc_online = public_chain_height.is_some() || public_peer_count.is_some();

    let nodes = join_all(
        state
            .nodes
            .iter()
            .map(|node| build_node_live_status(&client, node, public_chain_height)),
    )
    .await;

    let healthy_bootnodes = bootnodes.iter().filter(|entry| entry.reachable).count();
    let healthy_seed_servers = seed_servers.iter().filter(|entry| entry.reachable).count();

    let (discovery_status, discovery_detail) = discovery_summary(
        healthy_bootnodes,
        bootnodes.len(),
        healthy_seed_servers,
        seed_servers.len(),
    );
    let (chain_status, chain_detail) = chain_summary(
        public_rpc_online,
        public_chain_height,
        public_peer_count,
        healthy_bootnodes,
        healthy_seed_servers,
    );

    Ok(TestnetLiveStatus {
        generated_at_utc: Utc::now().to_rfc3339(),
        chain_id: TESTNET_CHAIN_ID,
        network_id: TESTNET_NETWORK_ID_V2.to_string(),
        consensus_fork: testnet_fork_metadata(),
        public_rpc_endpoint: TESTNET_PUBLIC_RPC_ENDPOINT.to_string(),
        public_rpc_online,
        public_chain_height,
        public_peer_count,
        network_peer_count,
        discovery_status,
        discovery_detail,
        chain_status,
        chain_detail,
        bootnodes,
        seed_servers,
        nodes,
    })
}

pub async fn testnet_node_control(
    app_context: &AppContext,
    event_bus: Option<EventBus>,
    input: TestnetNodeControlInput,
) -> Result<TestnetNodeControlResult, String> {
    let state = build_state()?;
    let node = state
        .nodes
        .iter()
        .find(|entry| entry.id == input.node_id)
        .cloned()
        .ok_or_else(|| format!("Unknown Testnet node: {}", input.node_id))?;

    let workspace_directory = PathBuf::from(&node.workspace_directory);
    let config_path = workspace_directory.join("config").join("node.toml");
    if !config_path.is_file() {
        return Err(format!(
            "Configuration file not found for {} at {}",
            node.display_label,
            config_path.display()
        ));
    }

    repair_workspace_config_if_needed(&node.role_id, &config_path)?;
    let mut action = input.action.trim().to_ascii_lowercase();
    let running_processes = running_processes_for_workspace(&workspace_directory);
    let mut is_running = !running_processes.is_empty();
    let mut local_rpc_ready = if is_running {
        workspace_local_rpc_ready(&config_path).await
    } else {
        false
    };
    append_workspace_control_log(
        &workspace_directory,
        "INFO",
        "Control panel action requested",
        Some(json!({
            "action": action.clone(),
            "node_id": node.id.clone(),
            "display_label": node.display_label.clone(),
            "is_running": is_running,
            "local_rpc_ready": local_rpc_ready,
        })),
    );

    if action == "resync-time" {
        let (status, message, evidence_path) = resync_machine_time(&workspace_directory, &node);
        append_workspace_control_log(
            &workspace_directory,
            if status == "ok" { "INFO" } else { "WARN" },
            "Machine time resync requested",
            Some(json!({
                "action": "resync-time",
                "node_id": node.id.clone(),
                "status": status,
                "evidence_path": evidence_path,
            })),
        );
        return Ok(TestnetNodeControlResult {
            node_id: node.id,
            action: "resync-time".to_string(),
            status,
            message,
        });
    }

    let runner = resolve_testnet_runner(app_context, &node.role_id)?;
    if action == "restart" {
        if is_running {
            let _ = run_runner_and_wait(&runner, "stop", &config_path, &workspace_directory).await;
            let lingering = force_kill_workspace_processes(&workspace_directory)?;
            append_workspace_control_log(
                &workspace_directory,
                if lingering > 0 { "WARN" } else { "INFO" },
                "Node restart completed pre-start stop phase",
                Some(json!({
                    "action": "restart",
                    "node_id": node.id.clone(),
                    "cleared_processes": lingering,
                })),
            );
        }
        is_running = false;
        local_rpc_ready = false;
        action = "start".to_string();
    }

    match action.as_str() {
        "start" => {
            let mut launch_notices = Vec::new();
            let chain_state_requires_reset =
                workspace_chain_state_requires_canonical_reset(&workspace_directory)?;
            let is_validator_role = role_supports_validator_registration(&node.role_id)
                && !provisioned_node_uses_private_validator_mesh(&node);
            let mut restored_snapshot_available =
                validator_snapshot_restore_evidence_is_verified(&node);
            if role_supports_validator_registration(&node.role_id) {
                repair_validator_speed_sync_pause_marker(&node, &workspace_directory)?;
            }

            if is_running && local_rpc_ready && !chain_state_requires_reset {
                return Ok(TestnetNodeControlResult {
                    node_id: node.id,
                    action,
                    status: "ignored".to_string(),
                    message: "Node is already running.".to_string(),
                });
            }

            if is_running && chain_state_requires_reset {
                let _ =
                    run_runner_and_wait(&runner, "stop", &config_path, &workspace_directory).await;
                let killed = force_kill_workspace_processes(&workspace_directory)?;
                eprintln!(
                    "Warning: stopped {} before rebuilding stale chain state. Cleared {killed} lingering process(es).",
                    node.display_label
                );
            } else if is_running && !local_rpc_ready {
                let killed = force_kill_workspace_processes(&workspace_directory)?;
                eprintln!(
                    "Warning: removed {killed} stale Testnet process(es) before restarting {}.",
                    node.display_label
                );
            }

            if let Err(e) = write_canonical_workspace_manifests(&workspace_directory) {
                eprintln!(
                    "Warning: could not refresh launch manifests for {}: {e}",
                    node.display_label
                );
            }
            if let Some(message) = repair_workspace_chain_state_if_needed(&workspace_directory)? {
                eprintln!("Warning: {message}");
                launch_notices.push(message);
            }
            if let Err(error) = ensure_workspace_bootstrap_topology(
                &config_path,
                &workspace_directory,
                &state.network_profile,
                &node,
            ) {
                eprintln!(
                    "Warning: could not rewrite workspace bootstrap topology for {}: {error}",
                    node.display_label
                );
            }

            // Inject localhost dial targets for every other node provisioned on
            // this machine so same-machine validators can peer directly without
            // relying on NAT loop-back through the public IP.  We merge with
            // whatever the JS bootstrap refresh already wrote (seed-server peers)
            // so nothing is lost.
            if let Err(error) = refresh_workspace_peer_targets(
                &state.network_profile,
                &state.nodes,
                &node,
                &workspace_directory,
            )
            .await
            {
                eprintln!(
                    "Warning: could not refresh peers.toml for {}: {error}",
                    node.display_label
                );
            }
            if let Some(detail) =
                align_enrolled_validator_vpn_config(&node, &workspace_directory).await?
            {
                launch_notices.push(format!(
                    "Validator VPN config aligned from signed snapshot generation {}.",
                    detail
                        .get("snapshot_generation")
                        .and_then(Value::as_u64)
                        .unwrap_or(0)
                ));
            }
            validate_workspace_launch_preflight(&config_path, &workspace_directory).await?;

            if is_validator_role && !restored_snapshot_available {
                match restore_latest_validator_pruned_snapshot(app_context, &node).await {
                    Ok(snapshot_restore) => {
                        restored_snapshot_available = true;
                        launch_notices.push(snapshot_restore.detail);
                    }
                    Err(error) => {
                        return Err(format!(
                            "Validator start requires a verified archive-validator-produced validator-pruned snapshot restore before launch. {error}"
                        ));
                    }
                }
            }

            if is_validator_role && restored_snapshot_available {
                launch_notices.push(
                    "Verified archive-validator-produced validator-pruned snapshot state is present; starting runtime so it can continue live catch-up from peers."
                        .to_string(),
                );
            }

            launch_runner_detached(&runner, "start", &config_path, &workspace_directory).await?;
            wait_for_workspace_start(
                &config_path,
                &workspace_directory,
                workspace_start_timeout(&node),
            )
            .await?;
            if let Err(error) = register_node_with_seeds_async(&state.network_profile, &node).await
            {
                eprintln!("Warning: {error}");
            }
            if is_validator_role {
                let rpc_endpoint = parse_testnet_rpc_endpoint(&config_path)
                    .unwrap_or_else(|| format!("http://127.0.0.1:{TESTNET_RPC_PORT}"));
                let client = Client::builder()
                    .timeout(Duration::from_secs(3))
                    .connect_timeout(Duration::from_secs(2))
                    .build()
                    .unwrap_or_else(|_| Client::new());
                let height = query_local_chain_height(&client, &rpc_endpoint).await.map_err(|error| {
                    format!("Validator start could not confirm local chain height after snapshot-backed launch: {error}")
                })?;
                validate_validator_sync_height(height, restored_snapshot_available)?;
                launch_notices.push(format!("Local validator height after startup: {height}."));
            }
            append_workspace_control_log(
                &workspace_directory,
                "INFO",
                "Node start completed",
                Some(json!({
                    "action": "start",
                    "node_id": node.id.clone(),
                })),
            );
            Ok(TestnetNodeControlResult {
                node_id: node.id,
                action: "start".to_string(),
                status: "ok".to_string(),
                message: if launch_notices.is_empty() {
                    "Node is online and running in its workspace.".to_string()
                } else {
                    format!(
                        "{} Node is online after verified snapshot-backed launch.",
                        launch_notices.join(" ")
                    )
                },
            })
        }
        "stop" => {
            if !is_running {
                return Ok(TestnetNodeControlResult {
                    node_id: node.id,
                    action,
                    status: "ignored".to_string(),
                    message: "Node is already stopped.".to_string(),
                });
            }

            let stop_result =
                run_runner_and_wait(&runner, "stop", &config_path, &workspace_directory).await;
            let lingering = force_kill_workspace_processes(&workspace_directory)?;

            if lingering > 0 {
                append_workspace_control_log(
                    &workspace_directory,
                    "WARN",
                    "Node stop required lingering process cleanup",
                    Some(json!({
                        "action": "stop",
                        "node_id": node.id.clone(),
                        "cleared_processes": lingering,
                    })),
                );
                return Ok(TestnetNodeControlResult {
                    node_id: node.id,
                    action: "stop".to_string(),
                    status: "ok".to_string(),
                    message: format!(
                        "Node stop completed. Cleared {lingering} lingering process(es)."
                    ),
                });
            }

            stop_result?;
            append_workspace_control_log(
                &workspace_directory,
                "INFO",
                "Node stop completed",
                Some(json!({
                    "action": "stop",
                    "node_id": node.id.clone(),
                })),
            );
            Ok(TestnetNodeControlResult {
                node_id: node.id,
                action: "stop".to_string(),
                status: "ok".to_string(),
                message: "Node stop command completed.".to_string(),
            })
        }
        "safe-shutdown" => {
            if !is_running {
                return Ok(TestnetNodeControlResult {
                    node_id: node.id,
                    action,
                    status: "ignored".to_string(),
                    message: "Node is already stopped.".to_string(),
                });
            }

            let rpc_endpoint = parse_testnet_rpc_endpoint(&config_path)
                .unwrap_or_else(|| format!("http://127.0.0.1:{TESTNET_RPC_PORT}"));
            let shutdown_notes = if local_rpc_ready {
                gather_safe_shutdown_prechecks(
                    &rpc_endpoint,
                    role_supports_validator_registration(&node.role_id),
                    if role_supports_validator_registration(&node.role_id) {
                        Some(node.node_address.as_str())
                    } else {
                        None
                    },
                )
                .await
            } else {
                vec![
                    "Skipping safe-shutdown prechecks because local RPC is not responding."
                        .to_string(),
                ]
            };

            append_workspace_control_log(
                &workspace_directory,
                "INFO",
                "Safe shutdown prechecks",
                Some(json!({
                    "action": "safe-shutdown",
                    "node_id": node.id.clone(),
                    "prechecks": shutdown_notes.join(" "),
                })),
            );
            let stop_result =
                run_runner_and_wait(&runner, "stop", &config_path, &workspace_directory).await;
            let lingering = force_kill_workspace_processes(&workspace_directory)?;

            if lingering > 0 {
                append_workspace_control_log(
                    &workspace_directory,
                    "WARN",
                    "Safe shutdown required lingering process cleanup",
                    Some(json!({
                        "action": "safe-shutdown",
                        "node_id": node.id.clone(),
                        "cleared_processes": lingering,
                    })),
                );
                return Ok(TestnetNodeControlResult {
                    node_id: node.id,
                    action: "safe-shutdown".to_string(),
                    status: "ok".to_string(),
                    message: format!(
                        "Safe shutdown requested. Cleared {lingering} lingering process(es) after prechecks. {}",
                        shutdown_notes.join(" ")
                    ),
                });
            }

            stop_result?;
            append_workspace_control_log(
                &workspace_directory,
                "INFO",
                "Node safe shutdown completed",
                Some(json!({
                    "action": "safe-shutdown",
                    "node_id": node.id.clone(),
                })),
            );
            Ok(TestnetNodeControlResult {
                node_id: node.id,
                action: "safe-shutdown".to_string(),
                status: "ok".to_string(),
                message: if shutdown_notes.is_empty() {
                    "Safe shutdown completed.".to_string()
                } else {
                    format!("Safe shutdown completed. {}", shutdown_notes.join(" "))
                },
            })
        }
        "emergency-stop" => {
            if !is_running {
                return Ok(TestnetNodeControlResult {
                    node_id: node.id,
                    action,
                    status: "ignored".to_string(),
                    message: "Node is already stopped.".to_string(),
                });
            }

            let terminated = force_kill_workspace_processes(&workspace_directory)?;
            append_workspace_control_log(
                &workspace_directory,
                "WARN",
                "Emergency node stop completed",
                Some(json!({
                    "action": "emergency-stop",
                    "node_id": node.id.clone(),
                    "terminated_processes": terminated,
                })),
            );
            Ok(TestnetNodeControlResult {
                node_id: node.id,
                action: "emergency-stop".to_string(),
                status: "ok".to_string(),
                message: format!(
                    "Emergency stop completed. Terminated {terminated} node process(es)."
                ),
            })
        }
        "sync" => {
            let is_validator_live_sync_role = role_supports_validator_registration(&node.role_id)
                && !provisioned_node_uses_private_validator_mesh(&node);
            if is_validator_live_sync_role {
                return run_validator_live_sync_catch_up(
                    app_context,
                    event_bus.clone(),
                    &state,
                    &node,
                )
                .await;
            }

            let mut launch_notices = Vec::new();
            if is_running {
                let _ =
                    run_runner_and_wait(&runner, "stop", &config_path, &workspace_directory).await;
                force_kill_workspace_processes(&workspace_directory)?;
            }

            if let Err(e) = write_canonical_workspace_manifests(&workspace_directory) {
                eprintln!(
                    "Warning: could not refresh launch manifests for {}: {e}",
                    node.display_label
                );
            }
            if let Some(message) = repair_workspace_chain_state_if_needed(&workspace_directory)? {
                eprintln!("Warning: {message}");
                launch_notices.push(message);
            }
            if let Err(error) = ensure_workspace_bootstrap_topology(
                &config_path,
                &workspace_directory,
                &state.network_profile,
                &node,
            ) {
                eprintln!(
                    "Warning: could not rewrite workspace bootstrap topology for {}: {error}",
                    node.display_label
                );
            }

            // Same local-sibling injection as the start path.
            if let Err(error) = refresh_workspace_peer_targets(
                &state.network_profile,
                &state.nodes,
                &node,
                &workspace_directory,
            )
            .await
            {
                eprintln!(
                    "Warning: could not refresh peers.toml for {}: {error}",
                    node.display_label
                );
            }
            if let Some(detail) =
                align_enrolled_validator_vpn_config(&node, &workspace_directory).await?
            {
                launch_notices.push(format!(
                    "Validator VPN config aligned from signed snapshot generation {}.",
                    detail
                        .get("snapshot_generation")
                        .and_then(Value::as_u64)
                        .unwrap_or(0)
                ));
            }
            validate_workspace_launch_preflight(&config_path, &workspace_directory).await?;

            let is_validator_role = role_supports_validator_registration(&node.role_id)
                && !provisioned_node_uses_private_validator_mesh(&node);
            if role_supports_validator_registration(&node.role_id) {
                repair_validator_speed_sync_pause_marker(&node, &workspace_directory)?;
            }
            let sync_message = if is_validator_role {
                let snapshot_height = validator_snapshot_restore_height(&node).unwrap_or(0);
                let snapshot_verified = validator_snapshot_restore_evidence_is_verified(&node);
                let local_chain_height = estimate_workspace_chain_height(&workspace_directory);
                let should_restore_snapshot = if !snapshot_verified {
                    true
                } else {
                    local_chain_height.is_none() || local_chain_height <= Some(snapshot_height)
                };

                let snapshot_restore_message = if !should_restore_snapshot {
                    let current_height = local_chain_height.unwrap_or(0);
                    launch_notices.push(format!(
                        "Skipping snapshot restore; local chain height h{current_height} is already ahead of verifier snapshot height h{snapshot_height}. Continuing peer-based sync."
                    ));
                    "Validator local chain state is already above the verified archive snapshot height. Runtime restart will continue live catch-up from peers.".to_string()
                } else {
                    let snapshot_restore_note = match restore_latest_validator_pruned_snapshot(
                        app_context,
                        &node,
                    )
                    .await
                    {
                        Ok(snapshot_restore) => snapshot_restore.detail,
                        Err(error) => {
                            return Err(format!(
                                "Validator catch-up requires a verified archive-validator-produced validator-pruned snapshot restore. The control panel will not use unsafe RPC chain fallback for validators: {error}"
                            ));
                        }
                    };
                    format!(
                        "{snapshot_restore_note} Validator state restored from the latest verified archive-validator-produced validator-pruned snapshot. Runtime restart will continue live catch-up from peers."
                    )
                };

                let progress = validator_speed_sync_progress(event_bus.clone(), &node).await;
                let local_height_after_restore =
                    estimate_workspace_chain_height(&workspace_directory).unwrap_or(0);
                let should_run_speed_sync = progress
                    .target_height
                    .map(|target_height| {
                        target_height.saturating_sub(local_height_after_restore)
                            > TESTNET_ACTIVATION_MAX_SYNC_GAP
                    })
                    .unwrap_or(true);

                if should_run_speed_sync {
                    progress.start();
                    run_runner_and_wait_with_speed_sync_progress(
                        &runner,
                        &config_path,
                        &workspace_directory,
                        &progress,
                    )
                    .await
                    .map_err(|sync_error| {
                        format!(
                            "Validator speed-sync from verified archive snapshot failed ({sync_error}). Refusing unsafe RPC fallback; retry after confirming public relayer reachability."
                        )
                    })?;
                    let (local_height, peer_height) =
                        recent_speed_sync_hints(&workspace_directory, "sync");
                    progress.complete(local_height, peer_height);
                    let synced_height = estimate_workspace_chain_height(&workspace_directory)
                        .or(local_height)
                        .unwrap_or(local_height_after_restore);
                    validate_validator_sync_height(synced_height, true)?;
                    format!(
                        "{snapshot_restore_message} Offline validator speed-sync completed from h{local_height_after_restore} to h{synced_height} using public relayer/bootstrap peers."
                    )
                } else {
                    let target_note = progress
                        .target_height
                        .map(|target| {
                            format!(" Verified target is h{target}; local h{local_height_after_restore} is already inside the activation gap.")
                        })
                        .unwrap_or_default();
                    format!("{snapshot_restore_message}{target_note}")
                }
            } else {
                match run_runner_and_wait(&runner, "sync", &config_path, &workspace_directory).await
                {
                    Ok(()) => "P2P fast-sync completed.".to_string(),
                    Err(sync_error) => {
                        let fallback_message = rpc_fast_sync_workspace_chain(&workspace_directory)
                                .await
                                .map_err(|fallback_error| {
                                    format!(
                                        "P2P fast-sync failed ({sync_error}); RPC chain catch-up also failed ({fallback_error})."
                                    )
                                })?;
                        format!("P2P fast-sync needed RPC fallback. {fallback_message}")
                    }
                }
            };
            launch_runner_detached(&runner, "start", &config_path, &workspace_directory).await?;
            wait_for_workspace_start(
                &config_path,
                &workspace_directory,
                workspace_start_timeout(&node),
            )
            .await?;
            if let Err(error) = register_node_with_seeds_async(&state.network_profile, &node).await
            {
                eprintln!("Warning: {error}");
            }
            let mut post_start_sync_note = None;
            let mut result_status = "ok".to_string();
            if role_supports_validator_registration(&node.role_id) {
                let rpc_endpoint = parse_testnet_rpc_endpoint(&config_path)
                    .unwrap_or_else(|| format!("http://127.0.0.1:{TESTNET_RPC_PORT}"));
                let client = Client::builder()
                    .timeout(Duration::from_secs(3))
                    .connect_timeout(Duration::from_secs(2))
                    .build()
                    .unwrap_or_else(|_| Client::new());
                let height = query_local_chain_height(&client, &rpc_endpoint).await.map_err(|error| {
                    format!("Validator sync could not confirm local chain height after restart: {error}")
                })?;
                validate_validator_sync_height(height, is_validator_role)?;
                let public_chain_height = query_public_chain_height(&client).await.ok();
                let trusted_relayer_height = query_trusted_relayer_chain_height(&client).await;
                let target =
                    select_verified_sync_target(public_chain_height, trusted_relayer_height, None);
                post_start_sync_note = Some(if let Some(target_height) = target.height {
                    let gap = target_height.saturating_sub(height);
                    if gap > TESTNET_ACTIVATION_MAX_SYNC_GAP {
                        result_status = "syncing".to_string();
                    }
                    format!(
                        "Local height after restart: {height}. Verified target {} is h{target_height}; remaining gap is {gap} block(s).",
                        target.source
                    )
                } else {
                    result_status = "syncing".to_string();
                    format!(
                        "Local height after restart: {height}. Verified sync target is unavailable, so activation will remain blocked until public or relayer RPC height can be verified."
                    )
                });
            }
            append_workspace_control_log(
                &workspace_directory,
                "INFO",
                if is_validator_role {
                    "Validator snapshot catch-up started"
                } else {
                    "Node fast-sync completed"
                },
                Some(json!({
                    "action": "sync",
                    "mode": if is_validator_role { "snapshot-catch-up" } else { "fast-sync" },
                    "node_id": node.id.clone(),
                })),
            );

            let sync_message = if let Some(note) = post_start_sync_note {
                format!("{sync_message} {note}")
            } else {
                sync_message
            };
            Ok(TestnetNodeControlResult {
                node_id: node.id,
                action: "sync".to_string(),
                status: result_status,
                message: if launch_notices.is_empty() {
                    if is_validator_role {
                        format!(
                            "Validator catch-up started and the runtime is back online. {sync_message}"
                        )
                    } else {
                        format!("Node fast-sync completed and the runtime is back online. {sync_message}")
                    }
                } else {
                    format!(
                        "{} {} catch-up restarted from the active network. {sync_message}",
                        launch_notices.join(" "),
                        if is_validator_role {
                            "Validator"
                        } else {
                            "Node"
                        }
                    )
                },
            })
        }
        other => Err(format!("Unsupported Testnet node action: {other}")),
    }
}

pub async fn testnet_remove_node(
    app_context: &AppContext,
    input: TestnetRemoveNodeInput,
) -> Result<TestnetRemoveNodeResult, String> {
    let root = ensure_testnet_root()?;
    let mut registry = load_registry(&root)?;
    let network_profile = load_or_create_network_profile(&root)?;

    let node = registry
        .nodes
        .iter()
        .find(|entry| entry.id == input.node_id)
        .cloned()
        .ok_or_else(|| format!("Unknown Testnet node: {}", input.node_id))?;

    let workspace_directory = PathBuf::from(&node.workspace_directory);

    // Ensure node is stopped before removal.
    if let Some(pid) = running_pid_for_workspace(&workspace_directory) {
        let config_path = workspace_directory.join("config").join("node.toml");
        if config_path.is_file() {
            if let Ok(runner) = resolve_testnet_runner(app_context, &node.role_id) {
                let _ =
                    run_runner_and_wait(&runner, "stop", &config_path, &workspace_directory).await;
            }
        }
        // If the runner stop didn't work, kill the process directly.
        if running_pid_for_workspace(&workspace_directory).is_some() {
            let mut system = System::new_all();
            system.refresh_all();
            if let Some(process) = system.process(Pid::from_u32(pid)) {
                process.kill();
            }
        }
    }

    // Attempt to deregister from seed servers (best-effort).
    deregister_node_from_seeds(&network_profile, &node).await;

    // Remove the workspace directory.
    if workspace_directory.exists() {
        fs::remove_dir_all(&workspace_directory).map_err(|error| {
            format!(
                "Failed to remove workspace at {}: {error}",
                workspace_directory.display()
            )
        })?;
    }

    // Remove the associated funding manifest from the network profile.
    let mut updated_network_profile = network_profile;
    updated_network_profile
        .funding_manifests
        .retain(|manifest| manifest.id != node.funding_manifest_id);
    updated_network_profile.updated_at_utc = Utc::now().to_rfc3339();
    save_network_profile(&root, &updated_network_profile)?;

    // Remove from registry and persist.
    registry.nodes.retain(|entry| entry.id != input.node_id);
    save_registry(&root, &registry)?;

    Ok(TestnetRemoveNodeResult {
        node_id: input.node_id,
        status: "ok".to_string(),
        message: format!(
            "Node {} has been removed. Workspace deleted and seed registrations cleared.",
            node.display_label
        ),
    })
}

pub fn testnet_rename_node(
    input: TestnetRenameNodeInput,
) -> Result<TestnetRenameNodeResult, String> {
    let trimmed_label = input.display_label.trim();
    if trimmed_label.is_empty() {
        return Err("Node nickname cannot be empty.".to_string());
    }
    if trimmed_label.len() > 80 {
        return Err("Node nickname must be 80 characters or fewer.".to_string());
    }

    let root = ensure_testnet_root()?;
    let mut registry = load_registry(&root)?;
    let updated_node = {
        let node = registry
            .nodes
            .iter_mut()
            .find(|entry| entry.id == input.node_id)
            .ok_or_else(|| format!("Unknown Testnet node: {}", input.node_id))?;
        node.display_label = trimmed_label.to_string();
        node.clone()
    };
    save_registry(&root, &registry)?;

    let node_config_path = update_node_config_identity_label(&updated_node, trimmed_label)?;
    let atlas_profile_path = write_atlas_validator_profile(&updated_node, &[], &[])?;

    Ok(TestnetRenameNodeResult {
        node_id: input.node_id,
        display_label: trimmed_label.to_string(),
        validator_address: Some(updated_node.node_address.clone()),
        owner_wallet_address: updated_node.owner_wallet_address.clone(),
        atlas_profile_path: atlas_profile_path.map(path_to_string),
        node_config_path: node_config_path.map(path_to_string),
        status: "ok".to_string(),
        message: format!("Node nickname updated to {trimmed_label}."),
    })
}

pub fn testnet_set_validator_owner(
    input: TestnetSetValidatorOwnerInput,
) -> Result<TestnetSetValidatorOwnerResult, String> {
    let owner_wallet_address =
        normalize_owner_wallet_address(input.owner_wallet_address.as_deref())?;
    let root = ensure_testnet_root()?;
    let mut registry = load_registry(&root)?;
    let updated_node = {
        let node = registry
            .nodes
            .iter_mut()
            .find(|entry| entry.id == input.node_id)
            .ok_or_else(|| format!("Unknown Testnet node: {}", input.node_id))?;
        node.owner_wallet_address = owner_wallet_address.clone();
        node.clone()
    };
    save_registry(&root, &registry)?;

    let atlas_profile_path = write_atlas_validator_profile(&updated_node, &[], &[])?;
    let message = owner_wallet_address
        .as_deref()
        .map(|address| format!("Owner wallet set to {address}."))
        .unwrap_or_else(|| "Owner wallet cleared.".to_string());

    Ok(TestnetSetValidatorOwnerResult {
        node_id: input.node_id,
        validator_address: updated_node.node_address,
        owner_wallet_address,
        atlas_profile_path: atlas_profile_path.map(path_to_string),
        status: "ok".to_string(),
        message,
    })
}

pub fn testnet_apply_atlas_validator_profile(
    input: TestnetApplyAtlasValidatorProfileInput,
) -> Result<TestnetRenameNodeResult, String> {
    let root = ensure_testnet_root()?;
    let mut registry = load_registry(&root)?;
    let owner_wallet_address =
        normalize_owner_wallet_address(input.owner_wallet_address.as_deref())?;
    let normalized_validator_address = input
        .validator_address
        .as_deref()
        .map(|value| value.trim().to_lowercase())
        .filter(|value| !value.is_empty());
    let nickname = input
        .nickname
        .as_deref()
        .map(|value| value.trim().replace('\n', " "))
        .filter(|value| !value.is_empty());
    if let Some(label) = nickname.as_deref() {
        if label.len() > 80 {
            return Err("Validator nickname must be 80 characters or fewer.".to_string());
        }
    }

    let updated_node = {
        let node = registry
            .nodes
            .iter_mut()
            .find(|entry| {
                input
                    .node_id
                    .as_deref()
                    .map(|node_id| entry.id == node_id)
                    .unwrap_or(false)
                    || normalized_validator_address
                        .as_deref()
                        .map(|address| entry.node_address.eq_ignore_ascii_case(address))
                        .unwrap_or(false)
            })
            .ok_or_else(|| {
                "No local validator node matches the Atlas profile update.".to_string()
            })?;

        if let Some(label) = nickname.as_deref() {
            node.display_label = label.to_string();
        }
        if input.owner_wallet_address.is_some() {
            node.owner_wallet_address = owner_wallet_address.clone();
        }
        node.clone()
    };
    save_registry(&root, &registry)?;

    let node_config_path = if let Some(label) = nickname.as_deref() {
        update_node_config_identity_label(&updated_node, label)?
    } else {
        None
    };
    let public_tags = normalize_atlas_profile_tags(&input.public_tags);
    let private_tags = normalize_atlas_profile_tags(&input.private_tags);
    let atlas_profile_path =
        write_atlas_validator_profile(&updated_node, &public_tags, &private_tags)?;

    Ok(TestnetRenameNodeResult {
        node_id: updated_node.id.clone(),
        display_label: updated_node.display_label.clone(),
        validator_address: Some(updated_node.node_address.clone()),
        owner_wallet_address: updated_node.owner_wallet_address.clone(),
        atlas_profile_path: atlas_profile_path.map(path_to_string),
        node_config_path: node_config_path.map(path_to_string),
        status: "ok".to_string(),
        message: "Atlas validator profile applied locally.".to_string(),
    })
}

pub async fn testnet_publish_validator_profile_to_atlas(
    input: TestnetPublishValidatorProfileInput,
) -> Result<TestnetPublishValidatorProfileResult, String> {
    let root = ensure_testnet_root()?;
    let registry = load_registry(&root)?;
    let node = registry
        .nodes
        .iter()
        .find(|entry| entry.id == input.node_id)
        .cloned()
        .ok_or_else(|| format!("Unknown Testnet node: {}", input.node_id))?;

    if node
        .owner_wallet_address
        .as_deref()
        .unwrap_or("")
        .trim()
        .is_empty()
    {
        return Ok(TestnetPublishValidatorProfileResult {
            node_id: input.node_id,
            validator_address: node.node_address,
            owner_wallet_address: node.owner_wallet_address,
            published: false,
            atlas_url: None,
            status: "skipped".to_string(),
            message: "Set an owner wallet before publishing the validator profile to Atlas."
                .to_string(),
        });
    }

    let Some(sync_token) = atlas_profile_sync_token() else {
        return Ok(TestnetPublishValidatorProfileResult {
            node_id: input.node_id,
            validator_address: node.node_address,
            owner_wallet_address: node.owner_wallet_address,
            published: false,
            atlas_url: None,
            status: "skipped".to_string(),
            message: "Atlas profile sync token is not configured.".to_string(),
        });
    };

    let atlas_api_base = std::env::var("SYNERGY_ATLAS_API_BASE")
        .or_else(|_| std::env::var("ATLAS_API_BASE"))
        .unwrap_or_else(|_| DEFAULT_ATLAS_API_BASE.to_string())
        .trim_end_matches('/')
        .to_string();
    let url = format!(
        "{}/validators/{}/control-panel-profile",
        atlas_api_base, node.node_address
    );
    let profile = read_atlas_validator_profile(&node).unwrap_or_else(|| json!({}));
    let owner_wallet_address = node.owner_wallet_address.clone();
    let display_label = profile
        .get("nickname")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or(&node.display_label)
        .to_string();
    let public_tags = atlas_profile_tags_from_value(&profile, "publicTags");
    let private_tags = atlas_profile_tags_from_value(&profile, "privateTags");
    let client = Client::builder()
        .timeout(Duration::from_secs(8))
        .build()
        .map_err(|error| format!("Failed to create Atlas profile sync client: {error}"))?;
    let response = client
        .post(&url)
        .bearer_auth(sync_token)
        .json(&json!({
            "ownerWalletAddress": owner_wallet_address,
            "nickname": display_label,
            "publicTags": public_tags,
            "privateTags": private_tags,
        }))
        .send()
        .await
        .map_err(|error| format!("Failed to publish validator profile to Atlas: {error}"))?;
    if !response.status().is_success() {
        let status = response.status();
        let body = response.text().await.unwrap_or_default();
        return Err(format!(
            "Atlas profile sync failed with HTTP {status}: {}",
            body.trim()
        ));
    }

    Ok(TestnetPublishValidatorProfileResult {
        node_id: input.node_id,
        validator_address: node.node_address,
        owner_wallet_address: node.owner_wallet_address,
        published: true,
        atlas_url: Some(url),
        status: "ok".to_string(),
        message: "Validator profile published to Atlas.".to_string(),
    })
}

fn atlas_profile_sync_token() -> Option<String> {
    std::env::var("SYNERGY_ATLAS_CONTROL_PANEL_SYNC_TOKEN")
        .or_else(|_| std::env::var("ATLAS_CONTROL_PANEL_SYNC_TOKEN"))
        .ok()
        .map(|token| token.trim().to_string())
        .filter(|token| !token.is_empty())
}

fn normalize_owner_wallet_address(value: Option<&str>) -> Result<Option<String>, String> {
    let Some(raw) = value else {
        return Ok(None);
    };
    let address = raw.trim().to_lowercase();
    if address.is_empty() {
        return Ok(None);
    }
    if address.starts_with("synv") {
        return Err(
            "Validator owner must be a regular Synergy wallet address, not a validator address."
                .to_string(),
        );
    }
    if address.len() != TARGET_ADDRESS_LEN || !is_valid_address(&address) {
        return Err(format!(
            "Validator owner wallet must be a canonical {TARGET_ADDRESS_LEN}-character Synergy wallet address."
        ));
    }
    Ok(Some(address))
}

fn normalize_atlas_profile_tags(tags: &[String]) -> Vec<String> {
    let mut seen = HashSet::new();
    tags.iter()
        .map(|tag| tag.trim().split_whitespace().collect::<Vec<_>>().join(" "))
        .filter(|tag| !tag.is_empty() && tag.len() <= 32)
        .filter(|tag| seen.insert(tag.to_lowercase()))
        .take(12)
        .collect()
}

fn atlas_profile_tags_from_value(profile: &Value, key: &str) -> Vec<String> {
    let tags = profile
        .get(key)
        .and_then(Value::as_array)
        .map(|values| {
            values
                .iter()
                .filter_map(Value::as_str)
                .map(str::to_string)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    normalize_atlas_profile_tags(&tags)
}

fn read_atlas_validator_profile(node: &TestnetProvisionedNode) -> Option<Value> {
    let path = PathBuf::from(&node.workspace_directory)
        .join("config")
        .join("atlas-validator-profile.json");
    read_json_value(&path).ok()
}

fn update_node_config_identity_label(
    node: &TestnetProvisionedNode,
    display_label: &str,
) -> Result<Option<PathBuf>, String> {
    let Some(config_path) = config_path_for_node(node, "node.toml") else {
        return Ok(None);
    };
    if !config_path.exists() {
        return Ok(None);
    }

    let contents = fs::read_to_string(&config_path)
        .map_err(|error| format!("Failed to read {}: {error}", config_path.display()))?;
    let mut parsed: toml::Value = toml::from_str(&contents)
        .map_err(|error| format!("Failed to parse {}: {error}", config_path.display()))?;
    let root = parsed
        .as_table_mut()
        .ok_or_else(|| format!("{} is not a TOML table.", config_path.display()))?;
    let identity = root
        .entry("identity".to_string())
        .or_insert_with(|| toml::Value::Table(toml::map::Map::new()));
    let identity_table = identity
        .as_table_mut()
        .ok_or_else(|| "[identity] in node.toml must be a TOML table.".to_string())?;
    identity_table.insert(
        "label".to_string(),
        toml::Value::String(display_label.to_string()),
    );
    let rendered = toml::to_string_pretty(&parsed)
        .map_err(|error| format!("Failed to render {}: {error}", config_path.display()))?;
    write_file(&config_path, &rendered)?;
    Ok(Some(config_path))
}

fn write_atlas_validator_profile(
    node: &TestnetProvisionedNode,
    public_tags: &[String],
    private_tags: &[String],
) -> Result<Option<PathBuf>, String> {
    if node.node_address.trim().is_empty() {
        return Ok(None);
    }
    let path = PathBuf::from(&node.workspace_directory)
        .join("config")
        .join("atlas-validator-profile.json");
    let payload = json!({
        "version": 1,
        "validatorAddress": node.node_address,
        "nickname": node.display_label,
        "ownerWalletAddress": node.owner_wallet_address,
        "publicTags": public_tags,
        "privateTags": private_tags,
        "source": "synergy-node-control-panel",
        "updatedAtUtc": Utc::now().to_rfc3339(),
    });
    write_file(
        &path,
        &serde_json::to_string_pretty(&payload)
            .map_err(|error| format!("Failed to render Atlas validator profile: {error}"))?,
    )?;
    Ok(Some(path))
}

fn path_to_string(path: PathBuf) -> String {
    path.to_string_lossy().to_string()
}

async fn deregister_node_from_seeds(
    network_profile: &TestnetNetworkProfile,
    node: &TestnetProvisionedNode,
) {
    let client = match Client::builder().timeout(Duration::from_secs(4)).build() {
        Ok(client) => client,
        Err(_) => return,
    };

    let payload = serde_json::json!({
        "node_id": node.id,
        "action": "deregister",
    });

    let futures = network_profile
        .seed_servers
        .iter()
        .map(|seed| {
            let client = client.clone();
            let payload = payload.clone();
            async move {
                let _ = post_seed_json(&client, seed, "/peers/deregister", &payload).await;
            }
        })
        .collect::<Vec<_>>();

    let _ = join_all(futures).await;
}

pub fn testnet_reset_deferred_bootstrap_note() -> Result<String, String> {
    Ok("DNS bootnodes, DNS seed services, and seed registration are configured as the active multi-source discovery path.".to_string())
}

/// Returns recent blocks from the node's local chain via its JSON-RPC endpoint.
/// Fetches the last `count` blocks (default 20, max 100) using synergy_getBlockRange.
pub async fn testnet_get_chain_blocks(
    node_id: String,
    count: Option<u64>,
) -> Result<Vec<serde_json::Value>, String> {
    let root = ensure_testnet_root()?;
    let registry = load_registry(&root)?;
    let node = registry
        .nodes
        .iter()
        .find(|n| n.id == node_id)
        .ok_or_else(|| format!("Node not found: {}", node_id))?;

    let workspace = PathBuf::from(&node.workspace_directory);
    let config_path = workspace.join("config").join("node.toml");
    let rpc_endpoint = parse_testnet_rpc_endpoint(&config_path)
        .unwrap_or_else(|| format!("http://127.0.0.1:{TESTNET_RPC_PORT}"));

    let client = Client::builder()
        .timeout(std::time::Duration::from_secs(5))
        .build()
        .map_err(|e| format!("Failed to build HTTP client: {e}"))?;

    // Get current block height
    let height = match query_local_chain_height(&client, &rpc_endpoint).await {
        Ok(height) => height,
        Err(error) if rpc_error_is_transport_failure(&error) => {
            return Ok(Vec::new());
        }
        Err(error) => {
            return Err(format!(
                "Local chain RPC is not responding on {rpc_endpoint}: {error}"
            ));
        }
    };

    let fetch_count = count.unwrap_or(20).min(100);
    let start = if height >= fetch_count {
        height - fetch_count + 1
    } else {
        0
    };
    let end = height;

    let result = match query_rpc_value(
        &client,
        &rpc_endpoint,
        "synergy_getBlockRange",
        json!([start, end]),
    )
    .await
    {
        Ok(result) => result,
        Err(error) if rpc_error_is_transport_failure(&error) => return Ok(Vec::new()),
        Err(error) => {
            return Err(format!(
                "Local chain RPC is not responding on {rpc_endpoint}: {error}"
            ));
        }
    };

    let blocks = result.as_array().cloned().unwrap_or_default();

    // Return newest first
    let mut ordered = blocks;
    ordered.reverse();
    Ok(ordered)
}

pub async fn testnet_get_feature_snapshot(
    input: TestnetFeatureSnapshotInput,
) -> Result<Value, String> {
    let state = build_state()?;
    let selected_node = input
        .node_id
        .as_deref()
        .and_then(|node_id| state.nodes.iter().find(|node| node.id == node_id))
        .or_else(|| state.nodes.first());
    let generated_at_utc = Utc::now().to_rfc3339();

    let Some(node) = selected_node.cloned() else {
        return Ok(json!({
            "screenKey": input.screen_key,
            "generatedAtUtc": generated_at_utc,
            "node": Value::Null,
            "network": {
                "environmentId": state.environment_id,
                "chainName": state.network_profile.chain_name,
                "chainId": state.network_profile.chain_id,
                "networkId": state.network_profile.network_id,
                "consensusFork": state.network_profile.consensus_fork,
                "configuredNodes": state.nodes.len(),
            },
            "consensus": {
                "algorithm": TESTNET_CONSENSUS_ALGORITHM,
                "fork": state.consensus_fork,
                "parserMode": TESTNET_PARSER_MODE,
            },
            "metrics": [],
            "checks": [],
            "table": {
                "columns": ["State", "Detail"],
                "rows": [["No configured node", "Complete setup before using this production screen."]]
            }
        }));
    };

    let workspace = PathBuf::from(&node.workspace_directory);
    let config_path = workspace.join("config").join("node.toml");
    let rpc_endpoint = parse_testnet_rpc_endpoint(&config_path)
        .unwrap_or_else(|| format!("http://127.0.0.1:{TESTNET_RPC_PORT}"));
    let client = Client::builder()
        .timeout(Duration::from_millis(2_500))
        .build()
        .map_err(|error| format!("HTTP client error: {error}"))?;

    let public_chain_height = query_public_chain_height(&client).await.ok();
    let live = build_node_live_status(&client, &node, public_chain_height).await;
    let readiness =
        build_node_readiness_report(&client, &node, &live, &state.network_profile.seed_servers)
            .await;
    let log_bundle = build_node_log_bundle(&node, 240);
    let chain_blocks = if live.local_rpc_ready {
        fetch_recent_chain_blocks_for_endpoint(&client, &rpc_endpoint, 40).await
    } else {
        Ok(Vec::new())
    };
    let graph = chain_graph_from_blocks(chain_blocks.as_ref().ok());
    let mempool = if live.local_rpc_ready {
        fetch_mempool_snapshot(&client, &rpc_endpoint).await
    } else {
        json!({
            "available": false,
            "status": "offline",
            "detail": live.local_rpc_status,
            "transactions": [],
            "stats": empty_mempool_stats(),
        })
    };
    let dag = if live.local_rpc_ready {
        fetch_dag_snapshot(&client, &rpc_endpoint, chain_blocks.as_ref().ok()).await
    } else {
        json!({
            "available": false,
            "status": "offline",
            "detail": live.local_rpc_status,
            "graph": graph,
            "vertices": [],
            "certificates": [],
            "orderingCut": Value::Null,
        })
    };
    let rpc_probes = if live.local_rpc_ready {
        probe_feature_rpc_methods(
            &client,
            &rpc_endpoint,
            &input.screen_key,
            &node.node_address,
            chain_blocks.as_ref().ok(),
        )
        .await
    } else {
        vec![json!({
            "method": "local_rpc",
            "status": "fail",
            "latencyMs": 0,
            "detail": live.local_rpc_status,
        })]
    };
    let storage = workspace_storage_snapshot(&workspace);
    let config = workspace_config_snapshot(&workspace);
    let diagnostics = machine_diagnostics_snapshot(&workspace, &rpc_endpoint);

    Ok(json!({
        "screenKey": input.screen_key,
        "generatedAtUtc": generated_at_utc,
        "node": node,
        "network": {
            "environmentId": state.environment_id,
            "chainName": state.network_profile.chain_name,
            "chainId": state.network_profile.chain_id,
            "networkId": state.network_profile.network_id,
            "consensusFork": state.network_profile.consensus_fork,
            "configuredNodes": state.nodes.len(),
            "bootnodes": state.network_profile.bootnodes,
            "seedServers": state.network_profile.seed_servers,
        },
        "consensus": {
            "algorithm": TESTNET_CONSENSUS_ALGORITHM,
            "fork": state.consensus_fork,
            "parserMode": TESTNET_PARSER_MODE,
        },
        "live": live,
        "readiness": readiness,
        "logs": {
            "summary": log_bundle.summary,
            "sources": log_bundle.sources,
            "entries": log_bundle.entries.into_iter().rev().take(80).collect::<Vec<_>>(),
        },
        "chain": {
            "blocks": chain_blocks.unwrap_or_default(),
            "graph": graph,
        },
        "mempool": mempool,
        "dag": dag,
        "rpc": {
            "endpoint": rpc_endpoint,
            "probes": rpc_probes,
        },
        "storage": storage,
        "config": config,
        "diagnostics": diagnostics,
    }))
}

fn empty_mempool_stats() -> Value {
    json!({
        "pendingCount": 0,
        "totalFeeNwei": 0,
        "totalGasLimit": 0,
        "minGasPriceNwei": 0,
        "avgGasPriceNwei": 0,
        "maxGasPriceNwei": 0,
        "largestAmountNwei": 0,
    })
}

fn numeric_json_field(value: &Value, keys: &[&str]) -> u64 {
    for key in keys {
        let Some(candidate) = value.get(*key) else {
            continue;
        };
        if let Some(number) = candidate.as_u64() {
            return number;
        }
        if let Some(number) = candidate.as_i64() {
            return number.max(0) as u64;
        }
        if let Some(text) = candidate.as_str() {
            let trimmed = text.trim();
            if let Some(hex) = trimmed.strip_prefix("0x") {
                if let Ok(parsed) = u64::from_str_radix(hex, 16) {
                    return parsed;
                }
            }
            if let Ok(parsed) = trimmed.parse::<u64>() {
                return parsed;
            }
        }
    }
    0
}

fn mempool_stats(transactions: &[Value]) -> Value {
    if transactions.is_empty() {
        return empty_mempool_stats();
    }

    let mut gas_prices = Vec::new();
    let mut total_fee = 0u64;
    let mut total_gas = 0u64;
    let mut largest_amount = 0u64;

    for tx in transactions {
        let gas_price = numeric_json_field(
            tx,
            &[
                "gas_price",
                "gasPrice",
                "effectiveGasPrice",
                "gas_price_nwei",
            ],
        );
        let gas_limit = numeric_json_field(tx, &["gas", "gasLimit", "gas_limit"]);
        let fee = numeric_json_field(tx, &["fee", "fee_nwei", "feeNwei", "transaction_fee_nwei"]);
        let amount = numeric_json_field(tx, &["amount", "amount_nwei", "amountNwei", "value"]);
        if gas_price > 0 {
            gas_prices.push(gas_price);
        }
        total_gas = total_gas.saturating_add(gas_limit);
        total_fee = total_fee.saturating_add(if fee > 0 {
            fee
        } else {
            gas_price.saturating_mul(gas_limit)
        });
        largest_amount = largest_amount.max(amount);
    }

    gas_prices.sort_unstable();
    let min_gas = gas_prices.first().copied().unwrap_or(0);
    let max_gas = gas_prices.last().copied().unwrap_or(0);
    let avg_gas = if gas_prices.is_empty() {
        0
    } else {
        gas_prices.iter().sum::<u64>() / gas_prices.len() as u64
    };

    json!({
        "pendingCount": transactions.len(),
        "totalFeeNwei": total_fee,
        "totalGasLimit": total_gas,
        "minGasPriceNwei": min_gas,
        "avgGasPriceNwei": avg_gas,
        "maxGasPriceNwei": max_gas,
        "largestAmountNwei": largest_amount,
    })
}

async fn fetch_mempool_snapshot(client: &Client, rpc_endpoint: &str) -> Value {
    let primary = query_rpc_value(
        client,
        rpc_endpoint,
        "synergy_getPendingTransactions",
        json!([250, "gasPrice"]),
    )
    .await;
    let (source_method, value) = match primary {
        Ok(value) => ("synergy_getPendingTransactions", value),
        Err(primary_error) => match query_rpc_value(
            client,
            rpc_endpoint,
            "synergy_getTransactionPool",
            json!([]),
        )
        .await
        {
            Ok(value) => ("synergy_getTransactionPool", value),
            Err(fallback_error) => {
                return json!({
                    "available": false,
                    "status": "unavailable",
                    "sourceMethod": "synergy_getPendingTransactions",
                    "detail": format!("{primary_error}; fallback failed: {fallback_error}"),
                    "transactions": [],
                    "stats": empty_mempool_stats(),
                });
            }
        },
    };

    let transactions = value.as_array().cloned().unwrap_or_default();
    let stats = mempool_stats(&transactions);
    json!({
        "available": true,
        "status": "live",
        "sourceMethod": source_method,
        "transactions": transactions,
        "stats": stats,
    })
}

fn normalize_dag_graph(value: &Value, fallback_blocks: Option<&Vec<Value>>) -> Value {
    if let Some(graph) = value.get("graph").filter(|graph| graph.is_object()) {
        return graph.clone();
    }
    if value.get("nodes").is_some() || value.get("edges").is_some() {
        return json!({
            "nodes": value.get("nodes").cloned().unwrap_or_else(|| json!([])),
            "edges": value.get("edges").cloned().unwrap_or_else(|| json!([])),
        });
    }
    if let Some(vertices) = value
        .get("vertices")
        .and_then(Value::as_array)
        .or_else(|| value.as_array())
    {
        let nodes = vertices
            .iter()
            .enumerate()
            .map(|(index, vertex)| {
                json!({
                    "id": vertex
                        .get("id")
                        .or_else(|| vertex.get("vertex_id"))
                        .or_else(|| vertex.get("hash"))
                        .and_then(Value::as_str)
                        .map(ToString::to_string)
                        .unwrap_or_else(|| format!("vertex-{index}")),
                    "height": vertex
                        .get("round")
                        .or_else(|| vertex.get("height"))
                        .or_else(|| vertex.get("block_height"))
                        .cloned()
                        .unwrap_or_else(|| json!(index)),
                    "validator": vertex
                        .get("author")
                        .or_else(|| vertex.get("validator"))
                        .or_else(|| vertex.get("validator_id"))
                        .cloned()
                        .unwrap_or(Value::Null),
                    "certified": vertex
                        .get("certified")
                        .or_else(|| vertex.get("available"))
                        .cloned()
                        .unwrap_or_else(|| json!(false)),
                })
            })
            .collect::<Vec<_>>();
        return json!({
            "nodes": nodes,
            "edges": [],
        });
    }
    chain_graph_from_blocks(fallback_blocks)
}

fn dag_vertices_from_value(value: &Value) -> Vec<Value> {
    value
        .get("vertices")
        .and_then(Value::as_array)
        .or_else(|| value.as_array())
        .cloned()
        .unwrap_or_default()
}

async fn optional_rpc_value(
    client: &Client,
    rpc_endpoint: &str,
    method: &str,
    params: Value,
) -> Value {
    match query_rpc_value(client, rpc_endpoint, method, params).await {
        Ok(value) => value,
        Err(error) => json!({
            "available": false,
            "method": method,
            "detail": error,
        }),
    }
}

async fn fetch_dag_snapshot(
    client: &Client,
    rpc_endpoint: &str,
    fallback_blocks: Option<&Vec<Value>>,
) -> Value {
    for method in ["synergy_getDagGraph", "synergy_getDAGGraph"] {
        if let Ok(value) = query_rpc_value(client, rpc_endpoint, method, json!([])).await {
            let vertices = dag_vertices_from_value(&value);
            let certificates = optional_rpc_value(
                client,
                rpc_endpoint,
                "synergy_getDagCertificates",
                json!([128]),
            )
            .await;
            let ordering_cut =
                optional_rpc_value(client, rpc_endpoint, "synergy_getOrderingCut", json!([])).await;
            return json!({
                "available": true,
                "status": "live",
                "sourceMethod": method,
                "detail": "Dedicated DAG RPC returned graph evidence for the selected node.",
                "graph": normalize_dag_graph(&value, fallback_blocks),
                "vertices": vertices,
                "certificates": certificates,
                "orderingCut": ordering_cut,
            });
        }
    }

    json!({
        "available": false,
        "status": "posy-finality-fallback",
        "sourceMethod": "synergy_getBlockRange",
        "detail": "The selected node does not expose dedicated DAG RPC yet; showing live PoSy finalized block parent evidence instead of synthetic DAG vertices.",
        "graph": chain_graph_from_blocks(fallback_blocks),
        "vertices": [],
        "certificates": [],
        "orderingCut": Value::Null,
    })
}

async fn fetch_recent_chain_blocks_for_endpoint(
    client: &Client,
    rpc_endpoint: &str,
    count: u64,
) -> Result<Vec<Value>, String> {
    let height = query_local_chain_height(client, rpc_endpoint).await?;
    let start = height.saturating_sub(count.saturating_sub(1));
    let result = query_rpc_value(
        client,
        rpc_endpoint,
        "synergy_getBlockRange",
        json!([start, height]),
    )
    .await?;
    let mut blocks = result.as_array().cloned().unwrap_or_default();
    blocks.reverse();
    Ok(blocks)
}

fn chain_graph_from_blocks(blocks: Option<&Vec<Value>>) -> Value {
    let blocks = blocks.cloned().unwrap_or_default();
    let nodes = blocks
        .iter()
        .filter_map(|block| {
            let height = block
                .get("number")
                .or_else(|| block.get("block_index"))
                .or_else(|| block.get("blockNumber"))
                .and_then(Value::as_u64)?;
            Some(json!({
                "id": block.get("hash").and_then(Value::as_str).unwrap_or("").to_string(),
                "height": height,
                "validator": block.get("validator")
                    .or_else(|| block.get("validator_id"))
                    .and_then(Value::as_str)
                    .unwrap_or(""),
                "transactionCount": block.get("transactions")
                    .and_then(|value| value.as_array().map(Vec::len).or_else(|| value.as_u64().map(|n| n as usize)))
                    .unwrap_or(0),
                "timestamp": block.get("timestamp").cloned().unwrap_or(Value::Null),
            }))
        })
        .collect::<Vec<_>>();

    let edges = blocks
        .iter()
        .filter_map(|block| {
            let hash = block.get("hash").and_then(Value::as_str)?;
            let parent = block
                .get("parentHash")
                .or_else(|| block.get("parent_hash"))
                .or_else(|| block.get("previous_hash"))
                .and_then(Value::as_str)?;
            if parent.is_empty() {
                return None;
            }
            Some(json!({
                "from": parent,
                "to": hash,
            }))
        })
        .collect::<Vec<_>>();

    json!({
        "nodes": nodes,
        "edges": edges,
    })
}

fn feature_rpc_methods(
    screen_key: &str,
    address: &str,
    blocks: Option<&Vec<Value>>,
) -> Vec<(&'static str, Value)> {
    let latest_height = blocks
        .and_then(|items| items.first())
        .and_then(|block| {
            block
                .get("number")
                .or_else(|| block.get("block_index"))
                .or_else(|| block.get("blockNumber"))
                .and_then(Value::as_u64)
        })
        .unwrap_or(0);
    match screen_key {
        "alerts" => vec![
            ("synergy_getNodeStatus", json!([])),
            ("synergy_getSyncStatus", json!([])),
            ("synergy_getBlockValidationStatus", json!([])),
        ],
        "validator" => vec![
            ("synergy_getValidator", json!([address])),
            ("synergy_getValidatorPerformance", json!([address])),
            ("synergy_getValidatorQueue", json!([])),
            ("synergy_getValidatorActivity", json!([])),
        ],
        "security" | "identity" => vec![
            ("synergy_getValidator", json!([address])),
            ("synergy_getValidatorSlashingHistory", json!([address])),
            ("synergy_getSynergyScoreBreakdown", json!([address])),
        ],
        "consensus" => vec![
            ("synergy_getBlockValidationStatus", json!([])),
            ("synergy_getValidatorStats", json!([])),
            ("synergy_getValidatorActivity", json!([])),
            ("synergy_getLatestBlock", json!([])),
        ],
        "dag" => vec![
            ("synergy_getDagGraph", json!([])),
            ("synergy_getDagCertificates", json!([128])),
            ("synergy_getOrderingCut", json!([])),
            ("synergy_getLatestBlock", json!([])),
            ("synergy_getBlockByNumber", json!([latest_height])),
            ("synergy_getBlockValidationStatus", json!([])),
        ],
        "transactions" => vec![
            ("synergy_getTransactionPool", json!([])),
            ("synergy_getPendingTransactions", json!([])),
            ("synergy_gasPrice", json!([])),
            ("synergy_getTransactionsInBlock", json!([latest_height])),
        ],
        "storage" => vec![
            ("synergy_getBlockNumber", json!([])),
            ("synergy_getTokenStats", json!([])),
            ("synergy_getNetworkStats", json!([])),
        ],
        "api" => vec![
            ("synergy_getChainId", json!([])),
            ("synergy_getNodeStatus", json!([])),
            ("synergy_getPeerInfo", json!([])),
            ("synergy_getSyncStatus", json!([])),
            ("synergy_getNetworkStats", json!([])),
            ("synergy_getTransactionPool", json!([])),
        ],
        "maintenance" => vec![
            ("synergy_getNodeStatus", json!([])),
            ("synergy_getSyncStatus", json!([])),
            ("synergy_getPeerInfo", json!([])),
        ],
        "diagnostics" => vec![
            ("synergy_getNodeStatus", json!([])),
            ("synergy_getPeerInfo", json!([])),
            ("synergy_getSyncStatus", json!([])),
            ("synergy_blockNumber", json!([])),
        ],
        "config" => vec![
            ("synergy_getChainId", json!([])),
            ("synergy_nodeInfo", json!([])),
            ("synergy_getDeterminismDigest", json!([])),
        ],
        _ => vec![
            ("synergy_getNodeStatus", json!([])),
            ("synergy_getSyncStatus", json!([])),
        ],
    }
}

async fn probe_feature_rpc_methods(
    client: &Client,
    rpc_endpoint: &str,
    screen_key: &str,
    address: &str,
    blocks: Option<&Vec<Value>>,
) -> Vec<Value> {
    let mut probes = Vec::new();
    for (method, params) in feature_rpc_methods(screen_key, address, blocks) {
        let started = Instant::now();
        let result = query_rpc_value(client, rpc_endpoint, method, params).await;
        let latency_ms = started.elapsed().as_millis() as u64;
        match result {
            Ok(value) if rpc_result_contains_error(&value) => {
                probes.push(json!({
                    "method": method,
                    "status": "fail",
                    "latencyMs": latency_ms,
                    "detail": value,
                }));
            }
            Ok(value) => {
                probes.push(json!({
                    "method": method,
                    "status": "pass",
                    "latencyMs": latency_ms,
                    "summary": summarize_rpc_value(&value),
                    "result": value,
                }));
            }
            Err(error) => {
                probes.push(json!({
                    "method": method,
                    "status": "fail",
                    "latencyMs": latency_ms,
                    "detail": error,
                }));
            }
        }
    }
    probes
}

fn summarize_rpc_value(value: &Value) -> String {
    if let Some(array) = value.as_array() {
        return format!("{} row(s)", array.len());
    }
    if let Some(object) = value.as_object() {
        return format!(
            "{} field(s): {}",
            object.len(),
            object
                .keys()
                .take(5)
                .cloned()
                .collect::<Vec<_>>()
                .join(", ")
        );
    }
    if value.is_null() {
        return "null".to_string();
    }
    value.to_string()
}

fn directory_usage(path: &Path) -> (u64, u64) {
    let mut bytes = 0u64;
    let mut files = 0u64;
    let mut stack = vec![path.to_path_buf()];
    while let Some(current) = stack.pop() {
        let Ok(metadata) = fs::symlink_metadata(&current) else {
            continue;
        };
        if metadata.is_file() {
            bytes = bytes.saturating_add(metadata.len());
            files = files.saturating_add(1);
        } else if metadata.is_dir() {
            let Ok(entries) = fs::read_dir(&current) else {
                continue;
            };
            for entry in entries.flatten() {
                stack.push(entry.path());
            }
        }
    }
    (bytes, files)
}

fn workspace_storage_snapshot(workspace: &Path) -> Value {
    let sections = ["config", "data", "logs", "manifests", "keys"]
        .iter()
        .map(|section| {
            let path = workspace.join(section);
            let (bytes, files) = directory_usage(&path);
            json!({
                "label": section,
                "path": path.display().to_string(),
                "exists": path.exists(),
                "bytes": bytes,
                "files": files,
            })
        })
        .collect::<Vec<_>>();
    let (workspace_bytes, workspace_files) = directory_usage(workspace);
    let canonical_workspace = workspace
        .canonicalize()
        .unwrap_or_else(|_| workspace.to_path_buf());
    let disks = Disks::new_with_refreshed_list();
    let disk = disks
        .iter()
        .filter(|disk| canonical_workspace.starts_with(disk.mount_point()))
        .max_by_key(|disk| disk.mount_point().to_string_lossy().len())
        .map(|disk| {
            json!({
                "mountPoint": disk.mount_point().display().to_string(),
                "availableBytes": disk.available_space(),
                "totalBytes": disk.total_space(),
            })
        });

    json!({
        "workspacePath": workspace.display().to_string(),
        "workspaceExists": workspace.exists(),
        "workspaceBytes": workspace_bytes,
        "workspaceFiles": workspace_files,
        "sections": sections,
        "disk": disk,
    })
}

fn read_config_file(path: &Path, max_bytes: usize) -> Value {
    let metadata = fs::metadata(path).ok();
    let contents = fs::read_to_string(path).ok().map(|text| {
        if text.len() > max_bytes {
            let trimmed = text.chars().take(max_bytes).collect::<String>();
            format!("{trimmed}...")
        } else {
            text
        }
    });
    json!({
        "path": path.display().to_string(),
        "exists": metadata.is_some(),
        "bytes": metadata.as_ref().map(|item| item.len()),
        "modifiedAtUtc": source_modified_at_utc(path),
        "contents": contents,
    })
}

fn workspace_config_snapshot(workspace: &Path) -> Value {
    let config_dir = workspace.join("config");
    let files = [
        config_dir.join("node.toml"),
        config_dir.join("peers.toml"),
        config_dir.join("consensus-fork-migration.json"),
        workspace.join("node.env"),
        config_dir.join("genesis.json"),
        workspace.join("manifests").join("funding-manifest.json"),
    ]
    .into_iter()
    .map(|path| {
        read_config_file(
            &path,
            if path.file_name().and_then(|name| name.to_str()) == Some("genesis.json") {
                24_000
            } else {
                12_000
            },
        )
    })
    .collect::<Vec<_>>();

    json!({
        "workspacePath": workspace.display().to_string(),
        "files": files,
    })
}

fn capture_command(program: &str, args: &[&str]) -> Value {
    match ProcessCommand::new(program)
        .args(args)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .output()
    {
        Ok(output) => json!({
            "command": std::iter::once(program.to_string()).chain(args.iter().map(|arg| arg.to_string())).collect::<Vec<_>>().join(" "),
            "status": output.status.code(),
            "stdout": String::from_utf8_lossy(&output.stdout).to_string(),
            "stderr": String::from_utf8_lossy(&output.stderr).to_string(),
        }),
        Err(error) => json!({
            "command": std::iter::once(program.to_string()).chain(args.iter().map(|arg| arg.to_string())).collect::<Vec<_>>().join(" "),
            "status": Value::Null,
            "stdout": "",
            "stderr": error.to_string(),
        }),
    }
}

fn machine_diagnostics_snapshot(workspace: &Path, rpc_endpoint: &str) -> Value {
    let processes = running_processes_for_workspace(workspace)
        .into_iter()
        .map(|process| {
            json!({
                "pid": process.pid,
                "uptimeSecs": process.uptime_secs,
            })
        })
        .collect::<Vec<_>>();
    let listener_command = if cfg!(target_os = "windows") {
        capture_command("netstat", &["-ano"])
    } else {
        capture_command("lsof", &["-nP", "-iTCP:5620-5699", "-sTCP:LISTEN"])
    };
    let disk_command = if cfg!(target_os = "windows") {
        capture_command(
            "cmd",
            &["/C", "wmic logicaldisk get size,freespace,caption"],
        )
    } else {
        capture_command("df", &["-k", &workspace.display().to_string()])
    };

    json!({
        "workspacePath": workspace.display().to_string(),
        "rpcEndpoint": rpc_endpoint,
        "processes": processes,
        "listeners": listener_command,
        "disk": disk_command,
    })
}

/// Returns the last `lines` lines from a node's main log file.
/// Reads `{workspace_directory}/logs/synergy-testnet.log`.
pub async fn testnet_run_register_with_seeds(
    _app_context: &AppContext,
    node_id: String,
) -> Result<String, String> {
    let state = build_state()?;
    let node = state
        .nodes
        .iter()
        .find(|n| n.id == node_id)
        .cloned()
        .ok_or_else(|| format!("Node not found: {}", node_id))?;

    let workspace_directory = PathBuf::from(&node.workspace_directory);
    let vpn_enrollment_path =
        validator_onboarding_evidence_path(&node, "validator-vpn-enrollment.json");
    if role_supports_validator_registration(&node.role_id) && vpn_enrollment_path.is_file() {
        let alignment = align_enrolled_validator_vpn_config(&node, &workspace_directory)
            .await?
        .ok_or_else(|| {
            "Validator VPN enrollment exists but no coordinator-managed peer routes were refreshed."
                .to_string()
        })?;
        let peer_target_count = alignment
            .get("peer_target_count")
            .and_then(Value::as_u64)
            .unwrap_or(0);
        return Ok(format!(
            "Validator peer routes refreshed from coordinator-signed VPN evidence ({} targets).",
            peer_target_count
        ));
    }

    let registered_count = register_node_with_seeds_async(&state.network_profile, &node).await?;
    Ok(format!(
        "Node '{}' registered with {} reachable seed server(s).",
        node.display_label, registered_count
    ))
}

pub async fn testnet_get_node_readiness(node_id: String) -> Result<NodeReadinessReport, String> {
    let state = build_state()?;
    let node = state
        .nodes
        .iter()
        .find(|n| n.id == node_id)
        .cloned()
        .ok_or_else(|| format!("Node not found: {node_id}"))?;

    let client = Client::builder()
        .timeout(Duration::from_secs(8))
        .build()
        .map_err(|e| format!("HTTP client error: {e}"))?;

    let public_chain_height = query_public_chain_height(&client).await.ok();
    let live = build_node_live_status(&client, &node, public_chain_height).await;
    let report =
        build_node_readiness_report(&client, &node, &live, &state.network_profile.seed_servers)
            .await;

    Ok(report)
}

