pub async fn testnet_validator_vpn_status(
    app_context: &AppContext,
    input: TestnetValidatorVpnInput,
) -> Result<TestnetValidatorVpnResult, String> {
    reject_retired_static_validator_vpn("agent status")?;
    let state = build_state()?;
    let node = state
        .nodes
        .iter()
        .find(|entry| entry.id == input.node_id)
        .cloned()
        .ok_or_else(|| format!("Node not found: {}", input.node_id))?;
    let local_public_key_path = validator_vpn_public_key_path(&node)
        .to_string_lossy()
        .to_string();
    let status = run_local_validator_vpn_agent(app_context, &node, &["status"])?;
    Ok(TestnetValidatorVpnResult {
        node_id: node.id,
        status: if status.success {
            "status".to_string()
        } else {
            validator_vpn_agent_failure_status(&status.stderr)
        },
        message: if status.success {
            "Validator VPN agent status collected.".to_string()
        } else {
            format!(
                "Validator VPN agent status failed. {}",
                status.stderr.trim()
            )
        },
        vpn_node_id: None,
        vpn_ip: None,
        peer_snapshot_generation: None,
        public_key_path: validator_vpn_agent_field(&status.stdout, "public_key_path")
            .or(Some(local_public_key_path)),
        evidence_path: None,
        apply_status: None,
        detail: Some(validator_vpn_agent_detail(&status)),
    })
}

#[derive(Debug, Clone)]
struct ValidatorVpnAgentOutcome {
    success: bool,
    exit_code: i32,
    stdout: String,
    stderr: String,
}

fn run_local_validator_vpn_agent(
    app_context: &AppContext,
    node: &TestnetProvisionedNode,
    args: &[&str],
) -> Result<ValidatorVpnAgentOutcome, String> {
    let script = validator_vpn_agent_script_path(app_context)?;
    let workspace = ensure_monitor_workspace_with_context(app_context)?;
    let vpn_dir = validator_vpn_agent_directory(node);
    fs::create_dir_all(&vpn_dir).map_err(|error| {
        format!(
            "Failed to create validator VPN working directory {}: {error}",
            vpn_dir.display()
        )
    })?;
    let mut command = ProcessCommand::new("bash");
    command.arg(&script).args(args).current_dir(workspace);
    command.env("PATH", validator_vpn_tool_path());
    command.env("VALIDATOR_VPN_DIR", &vpn_dir);
    command.env("VALIDATOR_VPN_PRIVATE_KEY", vpn_dir.join("private.key"));
    command.env("VALIDATOR_VPN_PUBLIC_KEY", vpn_dir.join("public.key"));
    command.env("VALIDATOR_VPN_STATE_PATH", vpn_dir.join("agent-state.json"));
    command.env(
        "VALIDATOR_VPN_SNAPSHOT_PATH",
        vpn_dir.join("latest-snapshot.json"),
    );
    for (key, value) in validator_vpn_result_owner_env(&vpn_dir) {
        command.env(key, value);
    }
    command.env("VALIDATOR_VPN_ALLOW_ADMIN_PROMPT", "1");
    command.env(
        "VALIDATOR_VPN_COORDINATOR_URL",
        validator_vpn_coordinator_url(),
    );
    if let Some(public_key) = validator_vpn_coordinator_public_signing_key() {
        command.env("VALIDATOR_VPN_COORDINATOR_PUBLIC_KEY", public_key);
    }
    if let Some(token) = validator_vpn_coordinator_token() {
        command.env("VALIDATOR_VPN_COORDINATOR_TOKEN", token);
    }
    let output = command.output().map_err(|error| {
        format!(
            "Failed to run validator VPN agent helper {}: {error}",
            script.display()
        )
    })?;
    Ok(ValidatorVpnAgentOutcome {
        success: output.status.success(),
        exit_code: output.status.code().unwrap_or(-1),
        stdout: String::from_utf8_lossy(&output.stdout).to_string(),
        stderr: String::from_utf8_lossy(&output.stderr).to_string(),
    })
}

fn validator_vpn_agent_directory(node: &TestnetProvisionedNode) -> PathBuf {
    PathBuf::from(&node.workspace_directory).join("validator-vpn")
}

fn validator_vpn_public_key_path(node: &TestnetProvisionedNode) -> PathBuf {
    validator_vpn_agent_directory(node).join("public.key")
}

#[cfg(unix)]
fn validator_vpn_result_owner_env(path: &Path) -> Vec<(&'static str, String)> {
    use std::os::unix::fs::MetadataExt;

    fs::metadata(path)
        .map(|metadata| {
            vec![
                ("VALIDATOR_VPN_RESULT_OWNER_UID", metadata.uid().to_string()),
                ("VALIDATOR_VPN_RESULT_OWNER_GID", metadata.gid().to_string()),
            ]
        })
        .unwrap_or_default()
}

#[cfg(not(unix))]
fn validator_vpn_result_owner_env(_path: &Path) -> Vec<(&'static str, String)> {
    Vec::new()
}

fn validator_vpn_tool_path() -> String {
    let existing = std::env::var("PATH").unwrap_or_default();
    let preferred = "/opt/homebrew/bin:/usr/local/bin:/usr/sbin:/sbin:/usr/bin:/bin";
    if existing.trim().is_empty() {
        preferred.to_string()
    } else {
        format!("{preferred}:{existing}")
    }
}

fn validator_vpn_env(name: &str) -> Option<String> {
    std::env::var(name)
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

fn configured_validator_vpn_coordinator_url() -> Option<String> {
    validator_vpn_env("VALIDATOR_VPN_COORDINATOR_URL")
        .or_else(|| validator_vpn_env("SYNERGY_VALIDATOR_VPN_COORDINATOR_URL"))
}

fn validator_vpn_coordinator_url() -> String {
    configured_validator_vpn_coordinator_url()
        .unwrap_or_else(|| DEFAULT_VALIDATOR_VPN_COORDINATOR_URL.to_string())
}

fn validator_vpn_coordinator_token() -> Option<String> {
    validator_vpn_env("VALIDATOR_VPN_COORDINATOR_TOKEN")
        .or_else(|| validator_vpn_env("SYNERGY_VALIDATOR_VPN_COORDINATOR_TOKEN"))
}

fn local_validator_vpn_coordinator_signing_key_is_configured() -> bool {
    validator_vpn_env("SYNERGY_VALIDATOR_VPN_COORDINATOR_SIGNING_KEY").is_some()
}

fn add_validator_vpn_coordinator_auth(request: reqwest::RequestBuilder) -> reqwest::RequestBuilder {
    if let Some(token) = validator_vpn_coordinator_token() {
        request.header(header::AUTHORIZATION, format!("Bearer {token}"))
    } else {
        request
    }
}

async fn parse_validator_vpn_coordinator_response<T: for<'de> Deserialize<'de>>(
    response: reqwest::Response,
    action: &str,
) -> Result<T, String> {
    let status = response.status();
    let body = response.text().await.map_err(|error| {
        format!("Validator VPN coordinator {action} response read failed: {error}")
    })?;
    if !status.is_success() {
        return Err(format!(
            "Validator VPN coordinator {action} failed with HTTP {status}: {}",
            body.chars().take(500).collect::<String>()
        ));
    }
    serde_json::from_str::<T>(&body).map_err(|error| {
        format!(
            "Validator VPN coordinator {action} returned invalid JSON: {error}. Body: {}",
            body.chars().take(500).collect::<String>()
        )
    })
}

async fn remote_validator_vpn_challenge(
    client: &Client,
    coordinator_url: &str,
    request: &ValidatorVpnChallengeRequest,
) -> Result<ValidatorVpnChallengeResponse, String> {
    let url = format!(
        "{}/api/validator-vpn/enrollment/challenge",
        coordinator_url.trim_end_matches('/')
    );
    let response = add_validator_vpn_coordinator_auth(client.post(url).json(request))
        .send()
        .await
        .map_err(|error| format!("Validator VPN coordinator challenge request failed: {error}"))?;
    parse_validator_vpn_coordinator_response(response, "challenge").await
}

async fn remote_validator_vpn_enroll(
    client: &Client,
    coordinator_url: &str,
    request: &ValidatorVpnEnrollRequest,
) -> Result<ValidatorVpnEnrollResponse, String> {
    let url = format!(
        "{}/api/validator-vpn/enroll",
        coordinator_url.trim_end_matches('/')
    );
    let response = add_validator_vpn_coordinator_auth(client.post(url).json(request))
        .send()
        .await
        .map_err(|error| format!("Validator VPN coordinator enrollment request failed: {error}"))?;
    parse_validator_vpn_coordinator_response(response, "enrollment").await
}

fn validator_vpn_agent_script_path(app_context: &AppContext) -> Result<PathBuf, String> {
    for root in app_context.resource_roots() {
        for relative in [
            Path::new("scripts/testnet/validator-vpn-agent.sh"),
            Path::new("node-control-panel/scripts/testnet/validator-vpn-agent.sh"),
        ] {
            let candidate = root.join(relative);
            if candidate.is_file() {
                return Ok(candidate);
            }
        }
    }
    let workspace = ensure_monitor_workspace_with_context(app_context)?;
    let candidate = workspace
        .join("scripts")
        .join("testnet")
        .join("validator-vpn-agent.sh");
    if candidate.is_file() {
        return Ok(candidate);
    }
    Err(format!(
        "Validator VPN agent helper not found. Expected {}",
        candidate.display()
    ))
}

fn validator_vpn_agent_field(stdout: &str, field: &str) -> Option<String> {
    let prefix = format!("{field}=");
    stdout.lines().find_map(|line| {
        line.trim()
            .strip_prefix(&prefix)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToOwned::to_owned)
    })
}

fn validator_vpn_agent_ack_complete(stdout: &str) -> Option<bool> {
    validator_vpn_agent_field(stdout, "validator_vpn_agent_config_ack")
        .and_then(|value| serde_json::from_str::<Value>(&value).ok())
        .and_then(|value| value.get("complete").and_then(Value::as_bool))
}

fn validator_vpn_agent_failure_status(stderr: &str) -> String {
    let lower = stderr.to_ascii_lowercase();
    if lower.contains("wireguard wg command is missing") || lower.contains("wg command is missing")
    {
        "wireguard_missing".to_string()
    } else if lower.contains("must run as root")
        || lower.contains("password is required")
        || lower.contains("permission denied")
        || lower.contains("operation not permitted")
    {
        "privilege_required".to_string()
    } else {
        "failed".to_string()
    }
}

fn validator_vpn_agent_detail(outcome: &ValidatorVpnAgentOutcome) -> Value {
    json!({
        "success": outcome.success,
        "exit_code": outcome.exit_code,
        "stdout": outcome.stdout,
        "stderr": outcome.stderr,
    })
}

fn validator_vpn_node_name(node: &TestnetProvisionedNode) -> String {
    format!("validator-{}", node.id)
}

fn validator_vpn_challenge_signature(
    node_name: &str,
    operator_address: Option<&str>,
    validator_address: &str,
    wg_pubkey: &str,
    challenge: &str,
) -> String {
    let payload = format!(
        "{}|validator|{}|{}|{}|{}|{}",
        VALIDATOR_VPN_NETWORK,
        validator_address,
        operator_address.unwrap_or(""),
        wg_pubkey,
        challenge,
        node_name
    );
    let mut hasher = Sha256::new();
    hasher.update(payload.as_bytes());
    format!("challenge-sha256:{:x}", hasher.finalize())
}

fn align_validator_runtime_config_from_vpn_snapshot(
    node: &TestnetProvisionedNode,
    workspace_directory: &Path,
    snapshot: &ValidatorVpnPeerSnapshot,
    vpn_node_id: &str,
    vpn_ip: &str,
) -> Result<Value, String> {
    let local_vpn_host = validator_vpn_host(vpn_ip)?;
    if !snapshot.validators.iter().any(|peer| {
        peer.node_id == vpn_node_id
            || validator_vpn_host(&peer.vpn_ip)
                .map(|host| host == local_vpn_host)
                .unwrap_or(false)
    }) {
        return Err(format!(
            "Validator VPN snapshot generation {} does not include local node {} at {}.",
            snapshot.generation, vpn_node_id, vpn_ip
        ));
    }

    let local_public_address = node.node_address.trim().to_string();
    let local_discovery_address = node.node_address.trim().to_string();
    let (peer_targets, validator_transports) =
        validator_vpn_snapshot_p2p_targets(snapshot, vpn_node_id, vpn_ip, &node.node_address)?;

    let config_path = workspace_directory.join("config").join("node.toml");
    let created_base_config =
        ensure_validator_runtime_config_for_vpn_alignment(node, workspace_directory, &config_path)?;
    let mut value = read_toml_value(&config_path)?;
    let validator_allowlist =
        validator_vpn_snapshot_validator_allowlist(snapshot, &value, &node.node_address);
    let root = value
        .as_table_mut()
        .ok_or_else(|| format!("{} must parse into a TOML table.", config_path.display()))?;

    {
        let network = root
            .entry("network")
            .or_insert_with(|| toml::Value::Table(Default::default()))
            .as_table_mut()
            .ok_or_else(|| "[network] must be a TOML table.".to_string())?;
        let bootnodes = endpoint_socket_entries(&bootstrap_endpoints("bootnode"));
        let seed_servers = endpoint_http_entries(&bootstrap_endpoints("seed"));
        let bootstrap_dns_records = vec![TESTNET_BOOTSTRAP_DNS_RECORD.to_string()];
        network.insert(
            "public_p2p_address".to_string(),
            toml::Value::String(local_public_address.clone()),
        );
        network.insert("bootnodes".to_string(), toml_string_array_value(&bootnodes));
        network.insert(
            "seed_servers".to_string(),
            toml_string_array_value(&seed_servers),
        );
        network.insert(
            "bootstrap_dns_records".to_string(),
            toml_string_array_value(&bootstrap_dns_records),
        );
        network.insert(
            "additional_dial_targets".to_string(),
            toml_string_array_value(&peer_targets),
        );
        network.insert(
            "persistent_peers".to_string(),
            toml_string_array_value(&peer_targets),
        );
        network.insert(
            "validator_vpn_transports".to_string(),
            toml_validator_vpn_transport_array_value(&validator_transports),
        );
    }

    {
        let p2p = root
            .entry("p2p")
            .or_insert_with(|| toml::Value::Table(Default::default()))
            .as_table_mut()
            .ok_or_else(|| "[p2p] must be a TOML table.".to_string())?;
        p2p.insert(
            "public_address".to_string(),
            toml::Value::String(local_public_address.clone()),
        );
        p2p.insert(
            "public_p2p_address".to_string(),
            toml::Value::String(local_public_address.clone()),
        );
        p2p.insert(
            "discovery_public_address".to_string(),
            toml::Value::String(local_discovery_address.clone()),
        );
        p2p.insert("enable_discovery".to_string(), toml::Value::Boolean(false));
        p2p.insert(
            "enable_peer_exchange".to_string(),
            toml::Value::Boolean(false),
        );
        p2p.insert(
            "reject_private_advertise_addrs".to_string(),
            toml::Value::Boolean(false),
        );
    }

    {
        let node_table = root
            .entry("node")
            .or_insert_with(|| toml::Value::Table(Default::default()))
            .as_table_mut()
            .ok_or_else(|| "[node] must be a TOML table.".to_string())?;
        node_table.insert(
            "auto_register_validator".to_string(),
            toml::Value::Boolean(false),
        );
        if !validator_allowlist.is_empty() {
            node_table.insert(
                "strict_validator_allowlist".to_string(),
                toml::Value::Boolean(false),
            );
            node_table.insert(
                "allowed_validator_addresses".to_string(),
                toml_string_array_value(&validator_allowlist),
            );
        }
    }

    let rendered = toml::to_string_pretty(&value)
        .map_err(|error| format!("Failed to serialize {}: {error}", config_path.display()))?;
    let rendered = normalize_validator_vpn_transport_toml(&rendered, &validator_transports);
    write_file(&config_path, &rendered)?;

    let peers_path = workspace_directory.join("config").join("peers.toml");
    align_validator_peers_toml_from_vpn_snapshot(&peers_path, &peer_targets)?;

    Ok(json!({
        "network": VALIDATOR_VPN_NETWORK,
        "snapshot_generation": snapshot.generation,
        "vpn_node_id": vpn_node_id,
        "vpn_ip": vpn_ip,
        "public_p2p_address": local_public_address,
        "discovery_public_address": local_discovery_address,
        "peer_target_count": peer_targets.len(),
        "validator_transport_count": validator_transports.len(),
        "validator_transport_routes": validator_transports.iter().map(|(validator_address, dial_address)| {
            json!({
                "validator_address": validator_address,
                "dial_address": dial_address,
            })
        }).collect::<Vec<_>>(),
        "validator_allowlist_count": validator_allowlist.len(),
        "created_base_config": created_base_config,
        "config_path": config_path,
        "peers_path": peers_path,
        "node_id": node.id,
        "validator_address": node.node_address,
    }))
}

fn align_innernet_validator_runtime_config(
    node: &TestnetProvisionedNode,
    workspace_directory: &Path,
    receipt: &innernet::InnernetMembershipReceipt,
    transport_snapshot: Option<&innernet::InnernetValidatorTransportSnapshot>,
) -> Result<Value, String> {
    innernet::verify_membership_receipt(receipt)?;
    if receipt.node_id != node.id {
        return Err(
            "Innernet membership receipt belongs to a different provisioned node.".to_string(),
        );
    }

    let local_validator_address = node.node_address.trim().to_string();
    if local_validator_address.is_empty() {
        return Err(
            "Innernet runtime alignment requires the local synv1 validator address.".to_string(),
        );
    }
    let local_vpn_host = innernet_validator_host(&receipt.assigned_ip)?;
    let p2p_port = node.public_p2p_port.unwrap_or(TESTNET_P2P_PORT);
    let private_p2p_listen = format!("{local_vpn_host}:{p2p_port}");
    let private_discovery_listen = format!("{local_vpn_host}:{TESTNET_DISCOVERY_PORT}");

    let (mut peer_targets, mut validator_transports) = if let Some(snapshot) = transport_snapshot {
        innernet::verify_validator_transport_snapshot(snapshot)?;
        if snapshot.migration_id != receipt.migration_id
            || snapshot.configuration_version < receipt.configuration_version
        {
            return Err(
                "Innernet validator transport snapshot does not match the coordinator receipt."
                    .to_string(),
            );
        }
        if !snapshot.transports.iter().any(|transport| {
            transport
                .validator_address
                .eq_ignore_ascii_case(&local_validator_address)
        }) {
            return Err(
                "Innernet validator transport snapshot does not contain this validator."
                    .to_string(),
            );
        }

        let mut peer_targets = snapshot
            .transports
            .iter()
            .filter(|transport| {
                !transport
                    .validator_address
                    .eq_ignore_ascii_case(&local_validator_address)
            })
            .map(|transport| transport.validator_address.clone())
            .collect::<Vec<_>>();
        peer_targets.sort();
        peer_targets.dedup();
        let mut validator_transports = snapshot
            .transports
            .iter()
            .filter(|transport| {
                !transport
                    .validator_address
                    .eq_ignore_ascii_case(&local_validator_address)
            })
            .map(|transport| {
                (
                    transport.validator_address.clone(),
                    transport.dial_address.clone(),
                )
            })
            .collect::<Vec<_>>();
        validator_transports.sort();
        validator_transports.dedup();
        (Some(peer_targets), Some(validator_transports))
    } else {
        (None, None)
    };

    let config_path = workspace_directory.join("config").join("node.toml");
    let created_base_config =
        ensure_validator_runtime_config_for_vpn_alignment(node, workspace_directory, &config_path)?;
    let mut value = read_toml_value(&config_path)?;
    if validator_transports.is_none() {
        let mut recovered_transports = value
            .get("network")
            .and_then(|section| section.get("validator_vpn_transports"))
            .and_then(toml::Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(toml::Value::as_table)
            .filter_map(|transport| {
                let validator_address = transport
                    .get("validator_address")
                    .and_then(toml::Value::as_str)?
                    .trim();
                let dial_address = transport
                    .get("dial_address")
                    .and_then(toml::Value::as_str)?
                    .trim();
                (!validator_address.is_empty()
                    && validator_address != local_validator_address
                    && !dial_address.is_empty())
                .then(|| (validator_address.to_string(), dial_address.to_string()))
            })
            .collect::<Vec<_>>();
        recovered_transports.sort();
        recovered_transports.dedup();
        if recovered_transports.is_empty() {
            return Err(
                "Existing Innernet enrollment is missing its validator transport routes. Reconnect the secure validator network to refresh coordinator-signed transport evidence."
                    .to_string(),
            );
        }
        let mut recovered_peer_targets = recovered_transports
            .iter()
            .map(|(validator_address, _)| validator_address.clone())
            .collect::<Vec<_>>();
        recovered_peer_targets.sort();
        recovered_peer_targets.dedup();
        peer_targets = Some(recovered_peer_targets);
        validator_transports = Some(recovered_transports);
    }
    if let Some(peer_targets) = peer_targets.as_mut() {
        peer_targets.extend(
            TESTNET_INNERNET_RELAYER_P2P_TARGETS
                .iter()
                .map(|target| (*target).to_string()),
        );
        peer_targets.sort();
        peer_targets.dedup();
    }
    let root = value
        .as_table_mut()
        .ok_or_else(|| format!("{} must parse into a TOML table.", config_path.display()))?;

    {
        let identity = root
            .entry("identity")
            .or_insert_with(|| toml::Value::Table(Default::default()))
            .as_table_mut()
            .ok_or_else(|| "[identity] must be a TOML table.".to_string())?;
        identity.insert(
            "node_id".to_string(),
            toml::Value::String(local_validator_address.clone()),
        );
        identity.insert(
            "address".to_string(),
            toml::Value::String(local_validator_address.clone()),
        );
    }

    {
        let network = root
            .entry("network")
            .or_insert_with(|| toml::Value::Table(Default::default()))
            .as_table_mut()
            .ok_or_else(|| "[network] must be a TOML table.".to_string())?;
        network.insert(
            "public_p2p_address".to_string(),
            toml::Value::String(local_validator_address.clone()),
        );
        network.insert(
            "innernet_interface".to_string(),
            toml::Value::String(receipt.interface_name.clone()),
        );
        network.insert(
            "innernet_address".to_string(),
            toml::Value::String(receipt.assigned_ip.clone()),
        );
        network.insert(
            "p2p_listen".to_string(),
            toml::Value::String(private_p2p_listen.clone()),
        );
        network.insert(
            "listen_addr".to_string(),
            toml::Value::String(private_p2p_listen.clone()),
        );
        for key in ["bootnodes", "seed_servers", "bootstrap_dns_records"] {
            network.insert(key.to_string(), toml::Value::Array(Vec::new()));
        }
        let requested_configuration_version = transport_snapshot
            .map(|snapshot| snapshot.configuration_version)
            .unwrap_or(receipt.configuration_version);
        let aligned_configuration_version = network
            .get("innernet_configuration_version")
            .and_then(toml::Value::as_integer)
            .and_then(|value| u64::try_from(value).ok())
            .unwrap_or(0)
            .max(requested_configuration_version);
        network.insert(
            "innernet_configuration_version".to_string(),
            toml::Value::Integer(aligned_configuration_version as i64),
        );
        if let Some(peer_targets) = &peer_targets {
            network.insert(
                "additional_dial_targets".to_string(),
                toml_string_array_value(peer_targets),
            );
            network.insert(
                "persistent_peers".to_string(),
                toml_string_array_value(peer_targets),
            );
        }
        if let Some(validator_transports) = &validator_transports {
            network.insert(
                "validator_vpn_transports".to_string(),
                toml_validator_vpn_transport_array_value(validator_transports),
            );
        }
    }

    {
        let p2p = root
            .entry("p2p")
            .or_insert_with(|| toml::Value::Table(Default::default()))
            .as_table_mut()
            .ok_or_else(|| "[p2p] must be a TOML table.".to_string())?;
        for key in [
            "public_address",
            "public_p2p_address",
            "discovery_public_address",
        ] {
            p2p.insert(
                key.to_string(),
                toml::Value::String(local_validator_address.clone()),
            );
        }
        p2p.insert(
            "node_name".to_string(),
            toml::Value::String(local_validator_address.clone()),
        );
        p2p.insert(
            "listen_address".to_string(),
            toml::Value::String(private_p2p_listen.clone()),
        );
        p2p.insert(
            "discovery_listen_address".to_string(),
            toml::Value::String(private_discovery_listen.clone()),
        );
        p2p.insert("enable_discovery".to_string(), toml::Value::Boolean(false));
        p2p.insert(
            "enable_peer_exchange".to_string(),
            toml::Value::Boolean(false),
        );
        p2p.insert(
            "reject_private_advertise_addrs".to_string(),
            toml::Value::Boolean(false),
        );
    }

    let node_table = root
        .entry("node")
        .or_insert_with(|| toml::Value::Table(Default::default()))
        .as_table_mut()
        .ok_or_else(|| "[node] must be a TOML table.".to_string())?;
    node_table.insert(
        "auto_register_validator".to_string(),
        toml::Value::Boolean(false),
    );
    node_table.insert(
        "validator_address".to_string(),
        toml::Value::String(local_validator_address.clone()),
    );

    let wallet = root
        .entry("wallet")
        .or_insert_with(|| toml::Value::Table(Default::default()))
        .as_table_mut()
        .ok_or_else(|| "[wallet] must be a TOML table.".to_string())?;
    wallet.insert(
        "reward_address".to_string(),
        toml::Value::String(local_validator_address.clone()),
    );

    let transport_count = validator_vpn_transport_count(&value);
    let rendered = toml::to_string_pretty(&value)
        .map_err(|error| format!("Failed to serialize {}: {error}", config_path.display()))?;
    let rendered = if let Some(validator_transports) = &validator_transports {
        normalize_validator_vpn_transport_toml(&rendered, validator_transports)
    } else {
        rendered
    };
    write_file(&config_path, &rendered)?;

    if let Some(peer_targets) = &peer_targets {
        align_validator_peers_toml_from_vpn_snapshot(
            &workspace_directory.join("config").join("peers.toml"),
            peer_targets,
        )?;
    }

    Ok(json!({
        "transport": "innernet",
        "interface": receipt.interface_name,
        "innernet_address": receipt.assigned_ip,
        "private_p2p_listen": private_p2p_listen,
        "configuration_version": transport_snapshot
            .map(|snapshot| snapshot.configuration_version)
            .unwrap_or(receipt.configuration_version),
        "public_p2p_address": local_validator_address,
        "peer_target_count": peer_targets.as_ref().map(Vec::len),
        "validator_transport_count": transport_count,
        "created_base_config": created_base_config,
        "config_path": config_path,
    }))
}

fn ensure_validator_runtime_config_for_vpn_alignment(
    node: &TestnetProvisionedNode,
    workspace_directory: &Path,
    config_path: &Path,
) -> Result<bool, String> {
    if config_path.is_file() {
        return Ok(false);
    }
    if !role_supports_validator_registration(&node.role_id) {
        return Err(format!(
            "Runtime config bootstrap is only available for validator nodes, got {}.",
            node.role_id
        ));
    }

    let validator_address = node.node_address.trim();
    if validator_address.is_empty() {
        return Err(format!(
            "Cannot create {} because validator address is missing for node {}.",
            config_path.display(),
            node.id
        ));
    }

    let root = ensure_testnet_root()?;
    let network_profile = load_or_create_network_profile(&root)?;
    let role = find_role_profile(&node.role_id)?;
    let role_overlay = role_overlay_for(&role.id);
    let contents = build_node_toml(
        &node.id,
        &node.display_label,
        &role,
        validator_address,
        workspace_directory,
        node.public_host.as_deref(),
        &network_profile,
        role_overlay.as_str(),
        node.port_slot.unwrap_or(0),
        node.public_p2p_port,
        None,
    );
    write_file(config_path, &contents)?;
    Ok(true)
}

async fn refresh_innernet_validator_transport_snapshot(
    coordinator_url: &str,
    receipt: &innernet::InnernetMembershipReceipt,
) -> Result<innernet::InnernetValidatorTransportSnapshot, String> {
    let client = Client::builder()
        .timeout(Duration::from_secs(15))
        .connect_timeout(Duration::from_secs(5))
        .build()
        .map_err(|error| format!("Failed to create Innernet coordinator client: {error}"))?;
    let url = format!(
        "{}/v1/mesh/transports/refresh",
        coordinator_url.trim_end_matches('/')
    );
    let response = client
        .post(url)
        .json(&json!({ "receipt": receipt }))
        .send()
        .await
        .map_err(|error| format!("Innernet validator transport refresh request failed: {error}"))?;
    let snapshot = parse_validator_vpn_coordinator_response::<
        innernet::InnernetValidatorTransportSnapshot,
    >(response, "Innernet validator transport refresh")
    .await?;
    innernet::verify_validator_transport_snapshot(&snapshot)?;
    if snapshot.migration_id != receipt.migration_id
        || snapshot.configuration_version < receipt.configuration_version
    {
        return Err(
            "Refreshed Innernet validator transport snapshot does not match the coordinator receipt."
                .to_string(),
        );
    }
    Ok(snapshot)
}

async fn align_enrolled_validator_vpn_config(
    node: &TestnetProvisionedNode,
    workspace_directory: &Path,
) -> Result<Option<Value>, String> {
    if !role_supports_validator_registration(&node.role_id) {
        return Ok(None);
    }
    let enrollment_path = validator_onboarding_evidence_path(node, "validator-vpn-enrollment.json");
    if !enrollment_path.is_file() {
        return Ok(None);
    }
    let mut enrollment = read_json_value(&enrollment_path)?;
    if enrollment.get("transport").and_then(Value::as_str) == Some("innernet") {
        let receipt = serde_json::from_value::<innernet::InnernetMembershipReceipt>(
            enrollment
                .get("innernet_receipt")
                .cloned()
                .ok_or_else(|| {
                    "Coordinator-managed Innernet enrollment evidence is missing its membership receipt."
                        .to_string()
                })?,
        )
        .map_err(|error| format!("Innernet enrollment receipt is invalid: {error}"))?;
        let stored_transport_snapshot = enrollment
            .get("innernet_transport_snapshot")
            .cloned()
            .map(serde_json::from_value::<innernet::InnernetValidatorTransportSnapshot>)
            .transpose();
        let stored_transport_snapshot = match stored_transport_snapshot {
            Ok(Some(snapshot))
                if innernet::verify_validator_transport_snapshot(&snapshot).is_ok() =>
            {
                Some(snapshot)
            }
            _ => None,
        };
        let coordinator_url = json_string_at(&enrollment, &["coordinator_url", "coordinatorUrl"])
            .unwrap_or_else(validator_vpn_coordinator_url);
        let transport_snapshot = match refresh_innernet_validator_transport_snapshot(
            &coordinator_url,
            &receipt,
        )
        .await
        {
            Ok(refreshed) => {
                let selected = stored_transport_snapshot
                    .filter(|stored| stored.configuration_version > refreshed.configuration_version)
                    .unwrap_or(refreshed);
                if let Some(map) = enrollment.as_object_mut() {
                    map.insert(
                        "coordinator_url".to_string(),
                        Value::String(coordinator_url.clone()),
                    );
                    map.insert(
                        "peer_snapshot_generation".to_string(),
                        json!(selected.configuration_version),
                    );
                    map.insert(
                        "innernet_transport_snapshot".to_string(),
                        serde_json::to_value(&selected).map_err(|error| {
                            format!("Failed to serialize refreshed Innernet transports: {error}")
                        })?,
                    );
                    map.insert(
                        "transport_refreshed_at_utc".to_string(),
                        Value::String(Utc::now().to_rfc3339()),
                    );
                }
                write_json_file(&enrollment_path, &enrollment)?;
                Some(selected)
            }
            Err(refresh_error) => {
                if stored_transport_snapshot.is_none() {
                    return Err(format!(
                        "Existing Innernet enrollment could not refresh its coordinator-signed validator transport routes. {refresh_error}"
                    ));
                }
                append_workspace_control_log(
                    workspace_directory,
                    "WARN",
                    "Using cached signed Innernet validator transport map after refresh failure",
                    Some(json!({
                        "coordinator_url": coordinator_url,
                        "error": refresh_error,
                    })),
                );
                stored_transport_snapshot
            }
        };
        let detail = align_innernet_validator_runtime_config(
            node,
            workspace_directory,
            &receipt,
            transport_snapshot.as_ref(),
        )?;
        let config_path = workspace_directory.join("config").join("node.toml");
        let config_value = read_toml_value(&config_path)?;
        let gate =
            innernet_validator_route_gate(node, &config_value, &enrollment, &enrollment_path);
        if gate.status != "pass" {
            return Err(gate.detail);
        }
        append_workspace_control_log(
            workspace_directory,
            "INFO",
            "Coordinator-managed Innernet runtime config reconciled",
            Some(detail.clone()),
        );
        return Ok(Some(detail));
    }
    Err(
        "This workspace still contains retired static validator VPN enrollment evidence. Reconnect the secure validator network so the coordinator can replace it with signed Innernet transport evidence."
            .to_string(),
    )
}

fn propagate_validator_vpn_snapshot_to_enrolled_workspaces(
    nodes: &[TestnetProvisionedNode],
    snapshot: &ValidatorVpnPeerSnapshot,
    exclude_node_id: Option<&str>,
) -> Value {
    let mut aligned = Vec::new();
    let mut skipped = Vec::new();
    let mut failed = Vec::new();
    let mut validator_candidate_count = 0usize;
    let origin_validator_address = exclude_node_id.and_then(|node_id| {
        nodes
            .iter()
            .find(|node| node.id == node_id)
            .map(|node| node.node_address.trim().to_string())
            .filter(|address| !address.is_empty())
    });
    let mut inventory_validator_addresses = HashSet::new();

    for node in nodes
        .iter()
        .filter(|node| role_supports_validator_registration(&node.role_id))
    {
        validator_candidate_count += 1;
        let node_validator_address = node.node_address.trim().to_string();
        if !node_validator_address.is_empty() {
            inventory_validator_addresses.insert(node_validator_address);
        }
        if exclude_node_id == Some(node.id.as_str()) {
            skipped.push(json!({
                "node_id": node.id,
                "validator_address": node.node_address,
                "reason": "excluded_origin_node",
            }));
            continue;
        }

        let workspace_directory = PathBuf::from(&node.workspace_directory);
        let enrollment_path =
            validator_onboarding_evidence_path(node, "validator-vpn-enrollment.json");
        if !enrollment_path.is_file() {
            skipped.push(json!({
                "node_id": node.id,
                "reason": "missing_vpn_enrollment_evidence",
                "evidence_path": enrollment_path,
            }));
            continue;
        }

        match propagate_validator_vpn_snapshot_to_enrolled_workspace(
            node,
            &workspace_directory,
            snapshot,
            &enrollment_path,
        ) {
            Ok(detail) => {
                append_workspace_control_log(
                    &workspace_directory,
                    "INFO",
                    "Validator VPN runtime config refreshed from propagated signed snapshot",
                    Some(detail.clone()),
                );
                aligned.push(detail);
            }
            Err(error) => {
                let failure = json!({
                    "node_id": node.id,
                    "workspace_directory": workspace_directory,
                    "enrollment_path": enrollment_path,
                    "error": error,
                });
                append_workspace_control_log(
                    &workspace_directory,
                    "WARN",
                    "Validator VPN propagated snapshot alignment failed",
                    Some(failure.clone()),
                );
                failed.push(failure);
            }
        }
    }

    match validator_vpn_snapshot_validator_addresses(snapshot) {
        Ok(snapshot_validator_addresses) => {
            for validator_address in snapshot_validator_addresses {
                if origin_validator_address.as_deref() == Some(validator_address.as_str()) {
                    continue;
                }
                if !inventory_validator_addresses.contains(&validator_address) {
                    if is_testnet_bootstrap_validator_address(&validator_address) {
                        skipped.push(json!({
                            "validator_address": validator_address,
                            "reason": "bootstrap_validator_inventory_managed_by_coordinator",
                        }));
                        continue;
                    }
                    skipped.push(json!({
                        "validator_address": validator_address,
                        "reason": "missing_validator_workspace_inventory",
                    }));
                }
            }
        }
        Err(error) => {
            failed.push(json!({
                "reason": "invalid_validator_vpn_snapshot_validator_identity",
                "error": error,
            }));
        }
    }

    let incomplete_count = failed.len()
        + skipped
            .iter()
            .filter(|entry| {
                entry
                    .get("reason")
                    .and_then(Value::as_str)
                    .is_some_and(|reason| {
                        !matches!(
                            reason,
                            "excluded_origin_node"
                                | "bootstrap_validator_inventory_managed_by_coordinator"
                        )
                    })
            })
            .count();

    json!({
        "network": VALIDATOR_VPN_NETWORK,
        "snapshot_generation": snapshot.generation,
        "validator_candidate_count": validator_candidate_count,
        "aligned_count": aligned.len(),
        "skipped_count": skipped.len(),
        "failed_count": failed.len(),
        "incomplete_count": incomplete_count,
        "aligned": aligned,
        "skipped": skipped,
        "failed": failed,
    })
}

fn propagate_validator_vpn_snapshot_to_enrolled_workspace(
    node: &TestnetProvisionedNode,
    workspace_directory: &Path,
    snapshot: &ValidatorVpnPeerSnapshot,
    enrollment_path: &Path,
) -> Result<Value, String> {
    let enrollment = read_json_value(enrollment_path)?;
    let vpn_node_id = enrollment
        .get("vpn_node_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| format!("{} is missing vpn_node_id", enrollment_path.display()))?
        .to_string();
    let vpn_ip = enrollment
        .get("vpn_ip")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| format!("{} is missing vpn_ip", enrollment_path.display()))?
        .to_string();

    let snapshot_path =
        validator_onboarding_evidence_path(node, "validator-vpn-latest-snapshot.json");
    let snapshot_value = serde_json::to_value(snapshot)
        .map_err(|error| format!("Failed to serialize validator VPN snapshot: {error}"))?;
    write_json_file(&snapshot_path, &snapshot_value)?;

    let mut detail = align_validator_runtime_config_from_vpn_snapshot(
        node,
        workspace_directory,
        snapshot,
        &vpn_node_id,
        &vpn_ip,
    )?;
    if let Some(map) = detail.as_object_mut() {
        map.insert(
            "propagated_snapshot_path".to_string(),
            json!(snapshot_path.to_string_lossy().to_string()),
        );
    }
    Ok(detail)
}

fn validator_vpn_snapshot_validator_addresses(
    snapshot: &ValidatorVpnPeerSnapshot,
) -> Result<Vec<String>, String> {
    let mut addresses = Vec::new();
    for peer in &snapshot.validators {
        if let Some(address) = validator_vpn_peer_validator_address(peer)? {
            if !addresses.contains(&address) {
                addresses.push(address);
            }
        }
    }
    Ok(addresses)
}

fn validator_vpn_propagation_failed(propagation: &Value) -> bool {
    if propagation
        .get("incomplete_count")
        .and_then(Value::as_u64)
        .unwrap_or(0)
        > 0
    {
        return true;
    }
    propagation
        .get("failed_count")
        .and_then(Value::as_u64)
        .unwrap_or(0)
        > 0
}

fn validator_vpn_status_after_propagation(success_status: &str, propagation: &Value) -> String {
    if validator_vpn_propagation_failed(propagation) {
        "blocked_propagation_failed".to_string()
    } else {
        success_status.to_string()
    }
}

fn align_validator_peers_toml_from_vpn_snapshot(
    peers_path: &Path,
    peer_targets: &[String],
) -> Result<(), String> {
    let mut value = if peers_path.is_file() {
        read_toml_value(peers_path)?
    } else {
        toml::Value::Table(Default::default())
    };
    let root = value
        .as_table_mut()
        .ok_or_else(|| format!("{} must parse into a TOML table.", peers_path.display()))?;
    let global = root
        .entry("global")
        .or_insert_with(|| toml::Value::Table(Default::default()))
        .as_table_mut()
        .ok_or_else(|| "[global] must be a TOML table.".to_string())?;

    let bootnodes = endpoint_socket_entries(&bootstrap_endpoints("bootnode"));
    let seed_servers = endpoint_http_entries(&bootstrap_endpoints("seed"));
    let bootstrap_dns_records = vec![TESTNET_BOOTSTRAP_DNS_RECORD.to_string()];
    global.insert("bootnodes".to_string(), toml_string_array_value(&bootnodes));
    global.insert(
        "seed_servers".to_string(),
        toml_string_array_value(&seed_servers),
    );
    global.insert(
        "bootstrap_dns_records".to_string(),
        toml_string_array_value(&bootstrap_dns_records),
    );
    global.insert(
        "additional_dial_targets".to_string(),
        toml_string_array_value(peer_targets),
    );
    global.insert(
        "persistent_peers".to_string(),
        toml_string_array_value(peer_targets),
    );

    let rendered = toml::to_string_pretty(&value)
        .map_err(|error| format!("Failed to serialize {}: {error}", peers_path.display()))?;
    write_file(peers_path, &rendered)
}

fn validator_vpn_snapshot_p2p_targets(
    snapshot: &ValidatorVpnPeerSnapshot,
    local_vpn_node_id: &str,
    local_vpn_ip: &str,
    local_validator_address: &str,
) -> Result<(Vec<String>, Vec<(String, String)>), String> {
    let local_vpn_host = validator_vpn_host(local_vpn_ip)?;
    let mut targets = Vec::new();
    let mut validator_transports = Vec::new();
    for peer in snapshot
        .validators
        .iter()
        .filter(|peer| peer.node_id != local_vpn_node_id)
    {
        let host = validator_vpn_host(&peer.vpn_ip)?;
        if host != local_vpn_host {
            let validator_address =
                validator_vpn_peer_validator_address(peer)?.ok_or_else(|| {
                    format!(
                        "Validator VPN peer {} is missing its synv1 validator address.",
                        peer.node_id
                    )
                })?;
            if validator_address.eq_ignore_ascii_case(local_validator_address.trim()) {
                continue;
            }
            targets.push(validator_address.clone());
            validator_transports.push((validator_address, format!("{host}:{TESTNET_P2P_PORT}")));
        }
    }
    for peer in &snapshot.relayers {
        targets.push(validator_vpn_peer_p2p_target(peer)?);
    }
    targets.sort();
    targets.dedup();
    validator_transports.sort();
    validator_transports.dedup();
    Ok((targets, validator_transports))
}

fn validator_vpn_peer_validator_address(
    peer: &ValidatorVpnPeerRecord,
) -> Result<Option<String>, String> {
    let reserved_slot = validator_vpn_bootstrap_validator_text_slot(peer)
        .or_else(|| validator_vpn_reserved_bootstrap_ip_slot(peer));
    let reserved_address = reserved_slot.and_then(|slot| {
        TESTNET_BOOTSTRAP_VALIDATOR_ORDER
            .get(slot.saturating_sub(1))
            .copied()
    });

    if let Some(address) = peer
        .validator_pubkey
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        if !address.starts_with("synv1") {
            return Err(format!(
                "Validator VPN peer {} has invalid validator address {}.",
                peer.node_id, address
            ));
        }
        if let Some(expected) = reserved_address {
            if address != expected {
                return Err(format!(
                    "Validator VPN peer {} at reserved bootstrap slot advertises {}, expected {}.",
                    peer.node_id, address, expected
                ));
            }
        }
        return Ok(Some(address.to_string()));
    }

    Ok(reserved_address.map(str::to_string))
}

fn validator_vpn_bootstrap_validator_text_slot(peer: &ValidatorVpnPeerRecord) -> Option<usize> {
    [&peer.node_id, &peer.node_name].iter().find_map(|value| {
        value
            .trim()
            .strip_prefix("bootstrap-validator-")
            .and_then(|slot| slot.parse::<usize>().ok())
            .filter(|slot| *slot > 0)
    })
}

fn validator_vpn_reserved_bootstrap_ip_slot(peer: &ValidatorVpnPeerRecord) -> Option<usize> {
    let host = peer.vpn_ip.trim().split('/').next().unwrap_or_default();
    let octets = host.parse::<std::net::Ipv4Addr>().ok()?.octets();
    (octets[0] == 10 && octets[1] == 69 && octets[2] == 10)
        .then_some(octets[3] as usize)
        .filter(|slot| (1..=TESTNET_BOOTSTRAP_VALIDATOR_ORDER.len()).contains(slot))
}

fn validator_vpn_snapshot_validator_allowlist(
    snapshot: &ValidatorVpnPeerSnapshot,
    current_config: &toml::Value,
    local_validator_address: &str,
) -> Vec<String> {
    let mut allowlist = canonical_testnet_validator_addresses().unwrap_or_default();
    let canonical = allowlist.iter().cloned().collect::<HashSet<_>>();
    for address in extract_toml_string_array(current_config, "node", "allowed_validator_addresses")
        .into_iter()
        .chain(
            snapshot
                .validators
                .iter()
                .filter_map(|peer| validator_vpn_peer_validator_address(peer).ok().flatten()),
        )
        .chain(std::iter::once(local_validator_address.trim().to_string()))
    {
        if (canonical.contains(&address) || address.starts_with("synv1"))
            && !allowlist.contains(&address)
        {
            allowlist.push(address);
        }
    }
    allowlist
}

fn validator_vpn_peer_p2p_target(peer: &ValidatorVpnPeerRecord) -> Result<String, String> {
    let host = validator_vpn_host(&peer.vpn_ip)?;
    Ok(format!("{host}:{TESTNET_P2P_PORT}"))
}

fn validator_vpn_host(vpn_ip: &str) -> Result<String, String> {
    let trimmed = vpn_ip.trim();
    let (host, prefix) = trimmed
        .split_once('/')
        .map(|(host, prefix)| (host.trim(), Some(prefix.trim())))
        .unwrap_or((trimmed, None));
    if host.is_empty() {
        return Err("Validator VPN IP is empty".to_string());
    }
    if prefix.is_some_and(|value| value != "32") {
        return Err(format!("{vpn_ip} must use an exact /32 route"));
    }
    match host
        .parse::<IpAddr>()
        .map_err(|error| format!("Invalid validator VPN IP {vpn_ip}: {error}"))?
    {
        IpAddr::V4(ip) => {
            let octets = ip.octets();
            if (octets[..3] == [10, 70, 10] || octets[..3] == [10, 70, 20])
                && octets[3] != 0
                && octets[3] != 255
            {
                Ok(host.to_string())
            } else {
                Err(format!(
                    "{vpn_ip} is outside the canonical validator or relayer VPN ranges"
                ))
            }
        }
        IpAddr::V6(_) => Err(format!("{vpn_ip} must be an IPv4 validator VPN address")),
    }
}

fn innernet_validator_host(assigned_ip: &str) -> Result<String, String> {
    let host = assigned_ip
        .trim()
        .split_once('/')
        .map(|(host, _)| host)
        .unwrap_or_else(|| assigned_ip.trim());
    let parsed = host
        .parse::<std::net::Ipv4Addr>()
        .map_err(|_| format!("Invalid Innernet validator address: {assigned_ip}"))?;
    let octets = parsed.octets();
    if octets[..3] != [10, 70, 10] || octets[3] == 0 || octets[3] == 255 {
        return Err(format!(
            "{assigned_ip} is outside the canonical Innernet validator CIDR 10.70.10.0/24"
        ));
    }
    Ok(parsed.to_string())
}

fn toml_string_array_value(values: &[String]) -> toml::Value {
    toml::Value::Array(values.iter().cloned().map(toml::Value::String).collect())
}

fn toml_validator_vpn_transport_array_value(values: &[(String, String)]) -> toml::Value {
    toml::Value::Array(
        values
            .iter()
            .map(|(validator_address, dial_address)| {
                let mut table = toml::map::Map::new();
                table.insert(
                    "validator_address".to_string(),
                    toml::Value::String(validator_address.clone()),
                );
                table.insert(
                    "dial_address".to_string(),
                    toml::Value::String(dial_address.clone()),
                );
                toml::Value::Table(table)
            })
            .collect(),
    )
}

fn normalize_validator_vpn_transport_toml(rendered: &str, values: &[(String, String)]) -> String {
    let mut out = Vec::new();
    let mut skipping_transport = false;
    for line in rendered.lines() {
        let trimmed = line.trim();
        if trimmed == "[[network.validator_vpn_transports]]" {
            skipping_transport = true;
            continue;
        }
        if skipping_transport && trimmed.starts_with('[') {
            skipping_transport = false;
        }
        if !skipping_transport {
            out.push(line.to_string());
        }
    }

    while out.last().is_some_and(|line| line.trim().is_empty()) {
        out.pop();
    }
    if !values.is_empty() {
        out.push(String::new());
        for (validator_address, dial_address) in values {
            out.push("[[network.validator_vpn_transports]]".to_string());
            out.push(format!(
                "dial_address = \"{}\"",
                dial_address.replace('"', "\\\"")
            ));
            out.push(format!(
                "validator_address = \"{}\"",
                validator_address.replace('"', "\\\"")
            ));
            out.push(String::new());
        }
        while out.last().is_some_and(|line| line.trim().is_empty()) {
            out.pop();
        }
    }
    out.push(String::new());
    out.join("\n")
}

async fn build_validator_activation_preflight(
    state: &TestnetState,
    node: &TestnetProvisionedNode,
) -> Result<ValidatorActivationPreflightResult, String> {
    let required_stake_nwei = MINIMUM_STAKE_SNRG * TOKEN_SCALE;
    let required_funding_nwei = validator_funding_requirement_nwei();
    let fee_reserve_nwei = validator_fee_reserve_requirement_nwei();
    let client = Client::builder()
        .timeout(Duration::from_secs(8))
        .build()
        .map_err(|error| format!("HTTP client error: {error}"))?;
    let public_chain_height = query_public_chain_height(&client).await.ok();
    let live = build_node_live_status(&client, node, public_chain_height).await;
    let readiness =
        build_node_readiness_report(&client, node, &live, &state.network_profile.seed_servers)
            .await;
    let rpc_endpoint = rpc_endpoint_for_workspace(node)?;
    let owner_wallet_address = node
        .owner_wallet_address
        .as_deref()
        .map(str::trim)
        .filter(|address| {
            !address.is_empty()
                && !address.starts_with("synv")
                && address.len() == TARGET_ADDRESS_LEN
                && is_valid_address(address)
        })
        .map(str::to_string);
    let owner_wallet_ready = owner_wallet_address.is_some();
    let owner_balance_nwei = if let Some(owner_address) = owner_wallet_address.as_deref() {
        query_rpc_u64_or_none(
            &client,
            TESTNET_PUBLIC_RPC_ENDPOINT,
            "synergy_getTokenBalance",
            json!([owner_address, TOKEN_SYMBOL]),
        )
        .await
    } else {
        None
    };
    let local_validator_balance_nwei = query_rpc_u64_or_none(
        &client,
        &rpc_endpoint,
        "synergy_getTokenBalance",
        json!([node.node_address, TOKEN_SYMBOL]),
    )
    .await;
    let public_validator_balance_nwei = query_rpc_u64_or_none(
        &client,
        TESTNET_PUBLIC_RPC_ENDPOINT,
        "synergy_getTokenBalance",
        json!([node.node_address, TOKEN_SYMBOL]),
    )
    .await;
    let (local_validator_total_stake_nwei, local_validator_staking_entries) =
        query_account_stake_from_endpoint(&client, &rpc_endpoint, &node.node_address).await;
    let (public_validator_total_stake_nwei, public_validator_staking_entries) =
        query_account_stake_from_endpoint(&client, TESTNET_PUBLIC_RPC_ENDPOINT, &node.node_address)
            .await;
    let local_validator_stake_nwei = local_validator_total_stake_nwei.or_else(|| {
        Some(active_stake_total_for_validator(
            &local_validator_staking_entries,
            &node.node_address,
        ))
    });
    let public_validator_stake_nwei = public_validator_total_stake_nwei.or_else(|| {
        Some(active_stake_total_for_validator(
            &public_validator_staking_entries,
            &node.node_address,
        ))
    });
    let validator_account_state_parity = normal_sync_account_state_parity_proof(
        &node.node_address,
        local_validator_balance_nwei,
        public_validator_balance_nwei,
        local_validator_stake_nwei,
        public_validator_stake_nwei,
    );
    let validator_account_state_parity_ok = validator_account_state_parity.is_ok();
    let validator_account_state_parity_detail = validator_account_state_parity
        .as_ref()
        .map(|_| {
            "Local and canonical public RPC report identical validator SNRG balance and stake."
                .to_string()
        })
        .unwrap_or_else(|error| error.clone());
    let local_validator_stake_nwei = local_validator_stake_nwei.unwrap_or(0);
    let public_validator_stake_nwei = public_validator_stake_nwei.unwrap_or(0);
    let validator_self_stake_nwei = public_validator_stake_nwei.max(local_validator_stake_nwei);
    let validator_balance_nwei = public_validator_balance_nwei.or(local_validator_balance_nwei);
    let balance_nwei = validator_balance_nwei.or(owner_balance_nwei);
    let staked_balance_nwei = owner_wallet_ready.then_some(validator_self_stake_nwei);
    let key_inspection = inspect_validator_key_material(node);
    let local_signing_key_ready =
        key_inspection.address_matches && key_inspection.private_key_present;
    let runtime_wallet_ready =
        match query_runtime_wallet_ready(&client, &rpc_endpoint, &node.node_address).await {
            Ok(ready) => ready || local_signing_key_ready,
            Err(error) if rpc_error_is_method_not_found(&error) && local_signing_key_ready => true,
            Err(_) => false,
        };
    let _ = refresh_latest_epoch_validator_set(&client, node).await;
    let workspace_directory = PathBuf::from(&node.workspace_directory);
    if let Err(error) = align_enrolled_validator_vpn_config(node, &workspace_directory).await {
        append_workspace_control_log(
            &workspace_directory,
            "WARN",
            "Innernet runtime config refresh did not complete",
            Some(json!({ "error": error })),
        );
    }
    let node_config_path = workspace_directory.join("config").join("node.toml");
    let onboarding_policy = build_validator_onboarding_policy_evidence(node);
    let validator_vpn_ok = onboarding_policy.validator_vpn.status == "pass";
    let epoch_validator_set_ok = onboarding_policy.epoch_validator_set.status == "pass";
    let epoch_boundary_ok = onboarding_policy.epoch_boundary.status == "pass";
    let fork_metadata_ok = node_config_fork_metadata_ready(&node_config_path).unwrap_or(false);
    let fndsa_key_ok = key_inspection.algorithm == TESTNET_VALIDATOR_IDENTITY_ALGORITHM
        && key_inspection.public_key_bytes == Some(1793);
    let workspace_genesis_ok = match (
        workspace_genesis_hash(&workspace_directory),
        canonical_testnet_genesis_hash(),
    ) {
        (Ok(actual), Ok(expected)) => actual.eq_ignore_ascii_case(&expected),
        _ => false,
    };
    let chain_state_genesis_ok =
        !workspace_chain_state_requires_canonical_reset(&workspace_directory).unwrap_or(true);

    let role_ok = role_supports_validator_registration(&node.role_id);
    let validator_mesh_only = provisioned_node_uses_private_validator_mesh(node);
    let public_host_ok = validator_mesh_only || validator_vpn_ok;
    let sync_gap_ok = live
        .sync_gap
        .map(|gap| gap <= TESTNET_ACTIVATION_MAX_SYNC_GAP)
        .unwrap_or(false);
    let rpc_ok = live.is_running && live.local_rpc_ready;
    let required_peer_count = if validator_mesh_only {
        1
    } else {
        TESTNET_ACTIVATION_MIN_PUBLIC_PEERS
    };
    let peer_ok = live.local_peer_count.unwrap_or(0) >= required_peer_count;
    let seed_ok = readiness
        .checks
        .iter()
        .any(|check| check.id == "seed_registered" && check.status == "pass");
    let liquid = balance_nwei.unwrap_or(0);
    let staked = staked_balance_nwei.unwrap_or(0);
    let funding_ready_to_bond = liquid >= required_funding_nwei;
    let funding_status = validator_funding_status(liquid, staked);
    let seed_or_peer_visibility_ok = seed_ok || peer_ok;
    let validator_address_ok = node.node_address.starts_with("synv")
        && node.node_address.len() == TARGET_ADDRESS_LEN
        && is_valid_address(&node.node_address);

    let mut checks = readiness.checks;
    checks.push(preflight_check(
        "validator-role",
        "Validator role",
        role_ok,
        "This workspace is configured as a validator.",
        "Select or provision a validator workspace before staking.",
    ));
    checks.push(preflight_check(
        "canonical-validator-address",
        "Canonical validator address",
        validator_address_ok,
        "The validator address is a canonical 41-character Synergy Bech32m validator address.",
        "Remove this workspace and rerun setup with the updated Control Panel so the address engine generates a full canonical validator identity.",
    ));
    checks.push(preflight_check(
        "validator-owner-wallet",
        "Operator owner wallet",
        owner_wallet_ready,
        "A regular Synergy wallet is registered as the owner of this validator.",
        "Connect the operator Synergy Wallet before staking or activation.",
    ));
    checks.push(preflight_check(
        "public-endpoint",
        "Validator transport",
        public_host_ok,
        "The validator has a private validator VPN route or canonical private mesh transport.",
        "Enroll and apply the validator VPN snapshot before activation. Validators should not require public endpoints.",
    ));
    checks.push(NodeReadinessCheck {
        id: "validator-vpn-route".to_string(),
        label: "Validator VPN route".to_string(),
        status: onboarding_policy.validator_vpn.status.clone(),
        detail: onboarding_policy.validator_vpn.detail.clone(),
        suggestion: onboarding_policy.validator_vpn.next_action.clone(),
    });
    checks.push(NodeReadinessCheck {
        id: "epoch-validator-set".to_string(),
        label: "Epoch validator set".to_string(),
        status: onboarding_policy.epoch_validator_set.status.clone(),
        detail: onboarding_policy.epoch_validator_set.detail.clone(),
        suggestion: onboarding_policy.epoch_validator_set.next_action.clone(),
    });
    checks.push(NodeReadinessCheck {
        id: "epoch-boundary".to_string(),
        label: "Epoch boundary activation gate".to_string(),
        status: onboarding_policy.epoch_boundary.status.clone(),
        detail: onboarding_policy.epoch_boundary.detail.clone(),
        suggestion: onboarding_policy.epoch_boundary.next_action.clone(),
    });
    checks.push(preflight_check(
        "canonical-workspace-genesis",
        "Canonical workspace genesis",
        workspace_genesis_ok,
        "The validator workspace has the canonical chain 1266 genesis hash.",
        "Re-provision this workspace with the canonical Testnet bundle before staking or activation.",
    ));
    checks.push(preflight_check(
        "canonical-chain-state",
        "Canonical chain state",
        chain_state_genesis_ok,
        "Existing local chain data belongs to the canonical chain 1266 genesis.",
        "Stop the node and reset stale local chain data before staking or activation.",
    ));
    checks.push(preflight_check(
        "testnet-v3-consensus-metadata",
        "Testnet-v3 genesis consensus metadata",
        fork_metadata_ok,
        "node.toml declares chain_id 1266, network_id synergy-testnet-v3, genesis-height ML-DSA-65 consensus keys, and fail_closed parsing.",
        "Re-provision or repair node.toml with the current Control Panel before staking or activation.",
    ));
    checks.push(preflight_check(
        "validator-primary-identity-key",
        "FN-DSA-1024 validator primary identity",
        fndsa_key_ok,
        &format!(
            "identity.json reports algorithm {} and public key size {} bytes.",
            key_inspection.algorithm,
            key_inspection
                .public_key_bytes
                .map(|value| value.to_string())
                .unwrap_or_else(|| "unknown".to_string())
        ),
        "Install the assigned five-role validator bundle. Its primary identity must be FN-DSA-1024 and its consensus role must be ML-DSA-65.",
    ));
    checks.push(preflight_check(
        "local-rpc",
        "Local RPC ready",
        rpc_ok,
        "The local validator RPC is running and reachable.",
        "Start or rejoin the validator and wait for RPC readiness.",
    ));
    checks.push(preflight_check(
        "sync-gap",
        "Synced near chain head",
        sync_gap_ok,
        "The validator is within two blocks of the public chain head for activation.",
        "Run Sync Catch Up before activating.",
    ));
    checks.push(preflight_check(
        "peers-visible",
        "Relayer peers visible",
        peer_ok,
        "The validator has enough live peer visibility for safe activation.",
        "Check relayer reachability, firewall/P2P access, and peer bootstrap before activation.",
    ));
    checks.push(NodeReadinessCheck {
        id: "seed-registration".to_string(),
        label: "Seed registration".to_string(),
        status: if seed_ok {
            "pass"
        } else if peer_ok {
            "warn"
        } else {
            "fail"
        }
        .to_string(),
        detail: if seed_ok {
            "Seed servers have a registration for this validator.".to_string()
        } else if peer_ok {
            "Seed registration is not reporting this validator, but the validator already has live peer visibility."
                .to_string()
        } else {
            "Seed servers do not currently expose this validator.".to_string()
        },
        suggestion: if seed_ok {
            None
        } else if peer_ok {
            Some("Run Re-register before activation so public discovery matches the validator identity.".to_string())
        } else {
            Some("Run Re-register or fix bootstrap peers so public validators can discover this node.".to_string())
        },
    });
    let stake_detail = if !owner_wallet_ready {
        "No operator owner wallet is registered for this validator yet."
    } else if public_validator_stake_nwei > local_validator_stake_nwei {
        "Canonical public RPC confirms this validator's self-bond; the local validator RPC stake index is still catching up."
    } else {
        "The validator has a protocol-locked self-bond backed by its funded balance."
    };
    let funding_detail = if funding_status == FEE_RESERVE_REQUIRED_STATUS {
        validator_fee_reserve_required_message()
    } else if staked >= required_stake_nwei && liquid < fee_reserve_nwei {
        format!(
            "The validator has the {MINIMUM_STAKE_SNRG} SNRG self-bond but no {VALIDATOR_FEE_RESERVE_SNRG} SNRG fee reserve remains in its account."
        )
    } else {
        format!(
            "The validator requires {VALIDATOR_FUNDING_SNRG} SNRG before bonding: {MINIMUM_STAKE_SNRG} SNRG bond plus {VALIDATOR_FEE_RESERVE_SNRG} SNRG fee reserve."
        )
    };
    let funding_suggestion = if funding_status == FEE_RESERVE_REQUIRED_STATUS {
        validator_fee_reserve_required_message()
    } else {
        format!(
            "Fund this validator with {VALIDATOR_FUNDING_SNRG} SNRG from the operator wallet, then complete the exact {MINIMUM_STAKE_SNRG} SNRG local self-bond."
        )
    };
    checks.push(NodeReadinessCheck {
        id: "liquid-balance".to_string(),
        label: "Validator funding".to_string(),
        status: if owner_wallet_ready {
            funding_status.to_string()
        } else {
            "fail".to_string()
        },
        detail: funding_detail,
        suggestion: Some(funding_suggestion),
    });
    checks.push(preflight_check(
        "local-signing-key",
        "Local signing key",
        local_signing_key_ready,
        "The validator workspace has the local private signing key for this validator address.",
        "Re-run setup with the validator address engine or import the correct validator identity before staking.",
    ));
    checks.push(preflight_check(
        "runtime-wallet-loaded",
        "Runtime wallet loaded",
        runtime_wallet_ready,
        "The validator has verified local signing key material available for stake transactions.",
        "Restart or resume chain sync after updating the Control Panel so the runtime imports keys/identity.json and keys/private.key.",
    ));
    checks.push(preflight_check(
        "bonded-stake",
        "Bonded stake",
        owner_wallet_ready && staked >= required_stake_nwei,
        stake_detail,
        &format!(
            "Fund this validator with {VALIDATOR_FUNDING_SNRG} SNRG, then complete its exact {MINIMUM_STAKE_SNRG} SNRG local self-bond from the setup panel."
        ),
    ));
    checks.push(NodeReadinessCheck {
        id: "normal-sync-account-state-parity".to_string(),
        label: "Validator account-state parity".to_string(),
        status: if validator_account_state_parity_ok {
            "pass".to_string()
        } else {
            "fail".to_string()
        },
        detail: validator_account_state_parity_detail,
        suggestion: (!validator_account_state_parity_ok).then(|| {
            "Restore verified validator state and catch up before staking or activation; local and canonical public SNRG balance and stake must match exactly.".to_string()
        }),
    });

    let can_stake = role_ok
        && owner_wallet_ready
        && validator_address_ok
        && workspace_genesis_ok
        && chain_state_genesis_ok
        && fork_metadata_ok
        && fndsa_key_ok
        && rpc_ok
        && local_signing_key_ready
        && runtime_wallet_ready
        && sync_gap_ok
        && peer_ok
        && seed_or_peer_visibility_ok
        && validator_account_state_parity_ok
        && funding_ready_to_bond;
    let can_activate = role_ok
        && owner_wallet_ready
        && validator_address_ok
        && workspace_genesis_ok
        && chain_state_genesis_ok
        && fork_metadata_ok
        && fndsa_key_ok
        && public_host_ok
        && rpc_ok
        && local_signing_key_ready
        && runtime_wallet_ready
        && sync_gap_ok
        && peer_ok
        && seed_or_peer_visibility_ok
        && staked >= required_stake_nwei
        && liquid >= fee_reserve_nwei
        && validator_account_state_parity_ok
        && validator_vpn_ok
        && epoch_validator_set_ok
        && epoch_boundary_ok
        && onboarding_policy.activation_allowed;

    Ok(ValidatorActivationPreflightResult {
        node_id: node.id.clone(),
        generated_at_utc: Utc::now().to_rfc3339(),
        can_stake,
        can_activate,
        onboarding_policy: Some(onboarding_policy),
        balance_nwei,
        staked_balance_nwei,
        required_stake_snrg: MINIMUM_STAKE_SNRG,
        required_stake_nwei,
        required_funding_snrg: VALIDATOR_FUNDING_SNRG,
        required_funding_nwei,
        funding_ready_to_bond,
        checks,
    })
}

fn local_validator_signing_key_ready(node: &TestnetProvisionedNode) -> bool {
    let identity_dir = node_identity_directory(node);
    let identity_path = identity_dir.join("identity.json");
    let private_key_path = identity_dir.join("private.key");

    let identity_address_matches = fs::read_to_string(identity_path)
        .ok()
        .and_then(|contents| serde_json::from_str::<Value>(&contents).ok())
        .and_then(|identity| {
            identity
                .get("address")
                .and_then(Value::as_str)
                .map(str::to_string)
        })
        .map(|address| address == node.node_address)
        .unwrap_or(false);

    let private_key_present = fs::read_to_string(private_key_path)
        .map(|contents| !contents.trim().is_empty())
        .unwrap_or(false);

    identity_address_matches && private_key_present
}

#[derive(Debug, Clone)]
struct ValidatorKeyInspection {
    algorithm: String,
    public_key_bytes: Option<usize>,
    address_matches: bool,
    private_key_present: bool,
}

fn inspect_validator_key_material(node: &TestnetProvisionedNode) -> ValidatorKeyInspection {
    let identity_dir = node_identity_directory(node);
    let identity_path = identity_dir.join("identity.json");
    let private_key_path = identity_dir.join("private.key");
    let identity = read_json_value(&identity_path).ok();
    let algorithm = identity
        .as_ref()
        .and_then(|value| value.get("algorithm"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("missing")
        .to_string();
    let public_key_bytes = identity
        .as_ref()
        .and_then(|value| value.get("public_key"))
        .and_then(Value::as_str)
        .and_then(|value| general_purpose::STANDARD.decode(value).ok())
        .map(|bytes| bytes.len());
    let address_matches = identity
        .as_ref()
        .and_then(|value| value.get("address"))
        .and_then(Value::as_str)
        .map(|address| address == node.node_address)
        .unwrap_or(false);
    let private_key_present = fs::read_to_string(private_key_path)
        .map(|contents| !contents.trim().is_empty())
        .unwrap_or(false);

    ValidatorKeyInspection {
        algorithm,
        public_key_bytes,
        address_matches,
        private_key_present,
    }
}

fn node_config_fork_metadata_ready(config_path: &Path) -> Result<bool, String> {
    let contents = fs::read_to_string(config_path)
        .map_err(|error| format!("Failed to read {}: {error}", config_path.display()))?;
    let value: toml::Value = toml::from_str(&contents)
        .map_err(|error| format!("Failed to parse {}: {error}", config_path.display()))?;
    let consensus = value
        .get("consensus")
        .and_then(toml::Value::as_table)
        .ok_or_else(|| "node.toml is missing [consensus].".to_string())?;
    let fork = consensus
        .get("fork")
        .and_then(toml::Value::as_table)
        .ok_or_else(|| "node.toml is missing [consensus.fork].".to_string())?;
    let policy = value
        .get("policy")
        .and_then(toml::Value::as_table)
        .ok_or_else(|| "node.toml is missing [policy].".to_string())?;

    let chain_id_ok =
        fork.get("chain_id").and_then(toml::Value::as_integer) == Some(TESTNET_CHAIN_ID as i64);
    let network_id_ok =
        fork.get("network_id").and_then(toml::Value::as_str) == Some(TESTNET_NETWORK_ID_V2);
    let height_ok = fork.get("fork_height").and_then(toml::Value::as_integer)
        == Some(TESTNET_FORK_HEIGHT as i64);
    let parent_height_ok = fork
        .get("fork_parent_height")
        .and_then(toml::Value::as_integer)
        == Some(TESTNET_FORK_PARENT_HEIGHT as i64);
    let parent_hash_ok = fork
        .get("parent_hash")
        .and_then(toml::Value::as_str)
        .map(|value| value.eq_ignore_ascii_case(TESTNET_FORK_PARENT_HASH))
        .unwrap_or(false);
    let consensus_algorithm_ok = consensus
        .get("new_consensus_algorithm")
        .and_then(toml::Value::as_str)
        == Some(TESTNET_CONSENSUS_ALGORITHM)
        && fork
            .get("new_consensus_algorithm")
            .and_then(toml::Value::as_str)
            == Some(TESTNET_CONSENSUS_ALGORITHM);
    let validator_key_algorithm_ok = consensus
        .get("validator_key_algorithm")
        .and_then(toml::Value::as_str)
        == Some(TESTNET_VALIDATOR_KEY_ALGORITHM)
        && fork
            .get("validator_key_algorithm")
            .and_then(toml::Value::as_str)
            == Some(TESTNET_VALIDATOR_KEY_ALGORITHM);
    let parser_mode_ok = policy.get("parser_mode").and_then(toml::Value::as_str)
        == Some(TESTNET_PARSER_MODE)
        && fork.get("parser_mode").and_then(toml::Value::as_str) == Some(TESTNET_PARSER_MODE);
    let no_legacy_algorithm = !contents.to_ascii_lowercase().contains("fn-dsa")
        && !contents.to_ascii_lowercase().contains("falcon")
        && !contents.to_ascii_lowercase().contains("dilithium");
    let fork_file_ok = config_path
        .parent()
        .map(|directory| directory.join("consensus-fork-migration.json"))
        .map(|path| consensus_fork_migration_file_ready(&path))
        .transpose()?
        .unwrap_or(false);

    Ok(chain_id_ok
        && network_id_ok
        && height_ok
        && parent_height_ok
        && parent_hash_ok
        && consensus_algorithm_ok
        && validator_key_algorithm_ok
        && parser_mode_ok
        && no_legacy_algorithm
        && fork_file_ok)
}

fn consensus_fork_migration_file_ready(path: &Path) -> Result<bool, String> {
    let value = read_json_value(path)?;
    let chain_id_ok = value
        .get("chain_id")
        .and_then(Value::as_u64)
        .map(|chain_id| chain_id == TESTNET_CHAIN_ID)
        .unwrap_or(true);
    let network_id_ok = value
        .get("network_id")
        .and_then(Value::as_str)
        .map(|network_id| network_id == TESTNET_NETWORK_ID_V2)
        .unwrap_or(true);
    let fork_height_ok =
        value.get("fork_height").and_then(Value::as_u64) == Some(TESTNET_FORK_HEIGHT);
    let parent_height_ok =
        value.get("parent_height").and_then(Value::as_u64) == Some(TESTNET_FORK_PARENT_HEIGHT);
    let parent_hash_ok = value
        .get("parent_hash")
        .and_then(Value::as_str)
        .map(|hash| hash.eq_ignore_ascii_case(TESTNET_FORK_PARENT_HASH))
        .unwrap_or(false);
    let new_algorithm_ok = value.get("new_consensus_algorithm").and_then(Value::as_str)
        == Some(TESTNET_CONSENSUS_ALGORITHM);
    let parser_mode_ok =
        value.get("parser_mode").and_then(Value::as_str) == Some(TESTNET_PARSER_MODE);
    let validator_count = value
        .get("new_validator_registry")
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or(0);

    Ok(chain_id_ok
        && network_id_ok
        && fork_height_ok
        && parent_height_ok
        && parent_hash_ok
        && new_algorithm_ok
        && parser_mode_ok
        && validator_count >= TESTNET_GENESIS_SETUP_PACKAGE_VALIDATOR_COUNT)
}

async fn query_runtime_wallet_ready(
    client: &Client,
    rpc_endpoint: &str,
    address: &str,
) -> Result<bool, String> {
    let value =
        query_rpc_value(client, rpc_endpoint, "synergy_getWallet", json!([address])).await?;
    Ok(value
        .get("address")
        .and_then(Value::as_str)
        .map(|wallet_address| wallet_address == address)
        .unwrap_or(false))
}

fn rpc_endpoint_for_workspace(node: &TestnetProvisionedNode) -> Result<String, String> {
    let config_path = PathBuf::from(&node.workspace_directory)
        .join("config")
        .join("node.toml");
    parse_testnet_rpc_endpoint(&config_path).ok_or_else(|| {
        format!(
            "Could not resolve local RPC endpoint from {}",
            config_path.display()
        )
    })
}

fn catch_up_step(id: &str, label: &str, status: &str, detail: &str) -> ValidatorCatchUpStep {
    ValidatorCatchUpStep {
        id: id.to_string(),
        label: label.to_string(),
        status: status.to_string(),
        detail: detail.to_string(),
    }
}

fn push_unique_repair_action(
    actions: &mut Vec<PreflightRepairAction>,
    id: &str,
    label: &str,
    detail: &str,
    action: &str,
) {
    if actions.iter().any(|entry| entry.id == id) {
        return;
    }

    actions.push(PreflightRepairAction {
        id: id.to_string(),
        label: label.to_string(),
        detail: detail.to_string(),
        action: action.to_string(),
    });
}

fn repair_actions_for_preflight(
    preflight: &ValidatorActivationPreflightResult,
) -> Vec<PreflightRepairAction> {
    let mut actions = Vec::new();
    for check in preflight
        .checks
        .iter()
        .filter(|check| check.status != "pass")
    {
        match check.id.as_str() {
            "process-running" | "local-rpc" => push_unique_repair_action(
                &mut actions,
                "start-node",
                "Start Node",
                "Start or restart the runtime, then rerun preflight.",
                "start",
            ),
            "sync-gap" => push_unique_repair_action(
                &mut actions,
                "sync-catch-up",
                "Sync Catch Up",
                "Run the catch-up workflow again after peers are reachable.",
                "sync-catch-up",
            ),
            "peers-visible" | "seed-registration" => push_unique_repair_action(
                &mut actions,
                "register-seeds",
                "Refresh Peers",
                "Refresh seed registration and peer targets.",
                "register-seeds",
            ),
            "liquid-balance" if check.status == FEE_RESERVE_REQUIRED_STATUS => push_unique_repair_action(
                &mut actions,
                "approve-mobile-wallet-stake",
                "Add Validator Fee Reserve",
                &validator_fee_reserve_required_message(),
                "setup-wallet-stake",
            ),
            "liquid-balance" => push_unique_repair_action(
                &mut actions,
                "approve-mobile-wallet-stake",
                "Approve Mobile Wallet Stake",
                "Connect the operator Synergy Wallet and fund this validator with 50,001 SNRG before creating its exact 50,000 SNRG self-bond.",
                "setup-wallet-stake",
            ),
            "bonded-stake" if preflight.balance_nwei.unwrap_or(0) >= preflight.required_funding_nwei => push_unique_repair_action(
                &mut actions,
                "complete-validator-self-bond",
                "Complete Validator Self-Bond",
                "Confirmed operator funding is already in the validator balance. Start the local runtime, then create the protocol-locked self-bond without sending another transfer.",
                "setup-validator-self-bond",
            ),
            "bonded-stake" => push_unique_repair_action(
                &mut actions,
                "approve-mobile-wallet-stake",
                "Fund Validator",
                "Connect the operator Synergy Wallet and fund this validator with 50,001 SNRG before creating its exact 50,000 SNRG local self-bond.",
                "setup-wallet-stake",
            ),
            "post-fork-fndsa-metadata" => push_unique_repair_action(
                &mut actions,
                "repair-fork-config",
                "Repair Fork Config",
                "Regenerate node.toml from the current Control Panel so Testnet-v3 chain 1266 genesis consensus, ML-DSA-65, and fail_closed parser metadata are explicit.",
                "config",
            ),
            "fndsa-consensus-key" => push_unique_repair_action(
                &mut actions,
                "regenerate-fndsa-identity",
                "Regenerate FN-DSA Identity",
                "Install the assigned validator key bundle with its FN-DSA-1024 primary identity and ML-DSA-65 consensus role before staking.",
                "identity",
            ),
            "local-signing-key" | "runtime-wallet-loaded" => push_unique_repair_action(
                &mut actions,
                "restart-node",
                "Restart Node",
                "Reload runtime identity and wallet files.",
                "restart",
            ),
            _ => push_unique_repair_action(
                &mut actions,
                "open-diagnostics",
                "Open Diagnostics",
                "Inspect machine diagnostics and runtime configuration.",
                "diagnostics",
            ),
        }
    }

    actions
}

async fn validator_consensus_active(node: &TestnetProvisionedNode) -> bool {
    let Ok(endpoint) = rpc_endpoint_for_workspace(node) else {
        return false;
    };
    let Ok(client) = Client::builder().timeout(Duration::from_secs(8)).build() else {
        return false;
    };
    canonical_validator_consensus_active(&client, &endpoint, &node.node_address).await
}

fn write_activation_confirmation_proof(node: &TestnetProvisionedNode) -> Result<(), String> {
    let proof = json!({
        "status": "pass",
        "canonical_status": "Active",
        "validator_address": node.node_address,
        "node_id": node.id,
        "source": "canonical-validator-registry",
        "detail": "Canonical validator registry reports this validator as active.",
        "generated_at_utc": Utc::now().to_rfc3339(),
    });
    write_json_file(
        &validator_onboarding_evidence_path(node, "activation-confirmation.json"),
        &proof,
    )
}

