fn reusable_innernet_enrollment_evidence(node: &TestnetProvisionedNode) -> Option<Value> {
    let path = validator_onboarding_evidence_path(node, "validator-vpn-enrollment.json");
    let evidence = read_json_value(&path).ok()?;
    if evidence.get("status").and_then(Value::as_str) != Some("confirmed")
        || evidence.get("transport").and_then(Value::as_str) != Some("innernet")
        || evidence.get("node_id").and_then(Value::as_str) != Some(node.id.as_str())
        || evidence.get("validator_address").and_then(Value::as_str)
            != Some(node.node_address.as_str())
    {
        return None;
    }
    let receipt = serde_json::from_value::<innernet::InnernetMembershipReceipt>(
        evidence.get("innernet_receipt")?.clone(),
    )
    .ok()?;
    if receipt.node_id != node.id || innernet::verify_membership_receipt(&receipt).is_err() {
        return None;
    }
    let snapshot = serde_json::from_value::<innernet::InnernetValidatorTransportSnapshot>(
        evidence.get("innernet_transport_snapshot")?.clone(),
    )
    .ok()?;
    if innernet::verify_validator_transport_snapshot(&snapshot).is_err()
        || snapshot.migration_id != receipt.migration_id
        || snapshot.configuration_version < receipt.configuration_version
    {
        return None;
    }
    Some(evidence)
}

fn validator_onboarding_shadow_state_path(node: &TestnetProvisionedNode) -> PathBuf {
    validator_onboarding_evidence_path(node, "validator-onboarding-shadow-observation-state.json")
}

fn read_validator_onboarding_shadow_state(node: &TestnetProvisionedNode) -> Option<Value> {
    fs::read_to_string(validator_onboarding_shadow_state_path(node))
        .ok()
        .and_then(|contents| serde_json::from_str::<Value>(&contents).ok())
}

fn read_latest_validator_funding_evidence_nwei(node: &TestnetProvisionedNode) -> Option<u64> {
    let evidence_dir = PathBuf::from(&node.workspace_directory)
        .join("logs")
        .join("evidence");
    let mut candidates: Vec<PathBuf> = fs::read_dir(evidence_dir)
        .ok()?
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .filter(|path| {
            path.file_name()
                .and_then(|name| name.to_str())
                .map(|name| name.starts_with("validator-funding-") && name.ends_with(".json"))
                .unwrap_or(false)
        })
        .collect();
    candidates.sort();
    candidates.reverse();

    candidates.into_iter().find_map(|path| {
        let value = fs::read_to_string(path)
            .ok()
            .and_then(|contents| serde_json::from_str::<Value>(&contents).ok())?;
        let status_ok = value
            .get("status")
            .and_then(Value::as_str)
            .map(|status| status.eq_ignore_ascii_case("ok"))
            .unwrap_or(false);
        let receipt_ok = value
            .get("receipt")
            .and_then(|receipt| receipt.get("status"))
            .and_then(Value::as_str)
            .map(|status| status == "0x1" || status.eq_ignore_ascii_case("ok"))
            .unwrap_or(false);
        if !status_ok || !receipt_ok {
            return None;
        }
        json_u64(&value, "amount_nwei").or_else(|| {
            value
                .get("public_balance_after")
                .and_then(|balance| json_u64(balance, "nwei"))
        })
    })
}

