fn evidence_generated_at_utc(value: &Value) -> Option<DateTime<Utc>> {
    ["generated_at_utc", "generatedAtUtc"]
        .iter()
        .find_map(|key| {
            value
                .get(*key)
                .and_then(Value::as_str)
                .and_then(|timestamp| DateTime::parse_from_rfc3339(timestamp).ok())
                .map(|timestamp| timestamp.with_timezone(&Utc))
        })
}

fn onboarding_evidence_freshness_failure(
    value: &Value,
    max_age_secs: i64,
    label: &str,
) -> Option<String> {
    let Some(generated_at) = evidence_generated_at_utc(value) else {
        return Some(format!(
            "{label} evidence is missing generated_at_utc. Regenerate it before activation."
        ));
    };
    let age_secs = Utc::now().signed_duration_since(generated_at).num_seconds();
    if age_secs < -TESTNET_ONBOARDING_EVIDENCE_FUTURE_SKEW_SECS {
        return Some(format!(
            "{label} evidence timestamp is in the future: generated_at_utc={}, clock_skew_secs={}. Resync time and regenerate it before activation.",
            generated_at.to_rfc3339(),
            -age_secs
        ));
    }
    if age_secs > max_age_secs {
        return Some(format!(
            "{label} evidence is stale: generated_at_utc={}, age_secs={}, max_age_secs={}. Regenerate it before activation.",
            generated_at.to_rfc3339(),
            age_secs,
            max_age_secs
        ));
    }
    None
}

fn json_truthy(value: &Value, keys: &[&str]) -> bool {
    keys.iter().any(|key| {
        value.get(*key).and_then(Value::as_bool).unwrap_or(false)
            || value
                .get(*key)
                .and_then(Value::as_str)
                .map(|status| {
                    matches!(
                        status.to_ascii_lowercase().as_str(),
                        "pass" | "passed" | "ok" | "true" | "complete" | "completed"
                    )
                })
                .unwrap_or(false)
    })
}

fn json_u64_at(value: &Value, keys: &[&str]) -> Option<u64> {
    keys.iter().find_map(|key| {
        value
            .get(*key)
            .and_then(Value::as_u64)
            .or_else(|| value.get(*key).and_then(Value::as_str)?.parse::<u64>().ok())
    })
}

fn json_u64(value: &Value, key: &str) -> Option<u64> {
    value
        .get(key)
        .and_then(Value::as_u64)
        .or_else(|| value.get(key).and_then(Value::as_str)?.parse::<u64>().ok())
}

fn json_string_at(value: &Value, keys: &[&str]) -> Option<String> {
    keys.iter().find_map(|key| {
        value
            .get(*key)
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|text| !text.is_empty())
            .map(str::to_string)
    })
}

fn json_bool_at(value: &Value, keys: &[&str]) -> Option<bool> {
    keys.iter().find_map(|key| {
        value.get(*key).and_then(Value::as_bool).or_else(|| {
            value.get(*key).and_then(Value::as_str).and_then(|text| {
                match text.trim().to_ascii_lowercase().as_str() {
                    "true" | "yes" | "latest" | "pass" | "ok" => Some(true),
                    "false" | "no" | "stale" | "failed" | "blocked" => Some(false),
                    _ => None,
                }
            })
        })
    })
}

fn epoch_validator_set_snapshot_paths(node: &TestnetProvisionedNode) -> Vec<PathBuf> {
    let workspace = PathBuf::from(&node.workspace_directory);
    vec![
        validator_onboarding_evidence_path(node, "epoch-validator-set-latest.json"),
        validator_onboarding_evidence_path(node, "validator-set-latest-snapshot.json"),
        validator_onboarding_evidence_path(node, "epoch-validator-sets.json"),
        workspace
            .join("config")
            .join("epoch-validator-set-latest.json"),
        workspace.join("config").join("epoch-validator-sets.json"),
    ]
}

#[derive(Debug, Clone)]
struct ValidatorSetRpcObservation {
    label: String,
    role: String,
    endpoint: String,
    public_rpc: bool,
    validator_set_hash: String,
    cluster_map_hash: String,
    membership_bundle_hash: String,
    effective_from_height: u64,
    snapshot: Value,
}

#[derive(Debug, Clone)]
struct ValidatedClusterMembershipSnapshot {
    cluster_count: u64,
    assignment_epoch: u64,
    assignment_effective_height: u64,
    randomness_source: String,
    cluster_map_hash: String,
    membership_bundle_hash: String,
    assignments: Vec<ValidatorClusterAssignmentSummary>,
}

fn local_validator_bundle_matches_canonical(
    local: &ValidatorSetRpcObservation,
    canonical: &ValidatorSetRpcObservation,
    local_validator_address: &str,
) -> Result<bool, String> {
    let bundle_matches = local.cluster_map_hash == canonical.cluster_map_hash
        && local.membership_bundle_hash == canonical.membership_bundle_hash;
    if bundle_matches {
        return Ok(true);
    }
    let network_active_validators = validator_members_at(
        &canonical.snapshot,
        &["active_validators", "activeValidators"],
    );
    if validator_set_contains(&network_active_validators, local_validator_address.trim()) {
        return Err(format!(
            "Active validator {local_validator_address} reports cluster bundle {} locally, but the canonical network reports {}. Active validators must match the canonical membership bundle exactly.",
            local.membership_bundle_hash,
            canonical.membership_bundle_hash,
        ));
    }
    Ok(false)
}

fn validator_snapshot_hash(value: &Value, keys: &[&str], label: &str) -> Result<String, String> {
    let hash = json_string_at(value, keys)
        .filter(|hash| hash.len() == 64 && hash.bytes().all(|byte| byte.is_ascii_hexdigit()))
        .ok_or_else(|| format!("Validator-set snapshot has an invalid or missing {label}."))?;
    Ok(hash.to_ascii_lowercase())
}

fn validate_cluster_membership_snapshot(
    snapshot: &Value,
    active_validators: &[String],
) -> Result<ValidatedClusterMembershipSnapshot, String> {
    if json_bool_at(
        snapshot,
        &["cluster_assignments_complete", "clusterAssignmentsComplete"],
    ) != Some(true)
    {
        return Err(
            "Validator-set snapshot does not contain complete persisted cluster assignments."
                .to_string(),
        );
    }
    let epoch_id = json_u64_at(snapshot, &["epoch_id", "epochId", "epoch"])
        .ok_or_else(|| "Validator-set snapshot is missing epoch_id.".to_string())?;
    let cluster_count = json_u64_at(snapshot, &["cluster_count", "clusterCount"])
        .ok_or_else(|| "Validator-set snapshot is missing cluster_count.".to_string())?;
    let expected_cluster_count = testnet_validator_cluster_count(active_validators.len()) as u64;
    if cluster_count != expected_cluster_count || cluster_count == 0 {
        return Err(format!(
            "Validator-set snapshot cluster_count={cluster_count}, expected {expected_cluster_count} for {} active validators.",
            active_validators.len()
        ));
    }
    let assignment_epoch = json_u64_at(
        snapshot,
        &["cluster_assignment_epoch", "clusterAssignmentEpoch"],
    )
    .ok_or_else(|| "Validator-set snapshot is missing cluster_assignment_epoch.".to_string())?;
    if assignment_epoch != epoch_id {
        return Err(format!(
            "Cluster assignment epoch {assignment_epoch} does not match validator-set epoch {epoch_id}."
        ));
    }
    let assignment_effective_height = json_u64_at(
        snapshot,
        &[
            "cluster_assignment_effective_height",
            "clusterAssignmentEffectiveHeight",
        ],
    )
    .ok_or_else(|| {
        "Validator-set snapshot is missing cluster_assignment_effective_height.".to_string()
    })?;
    let epoch_start_height = testnet_epoch_start_height(assignment_epoch);
    let epoch_end_height = testnet_epoch_end_height(assignment_epoch);
    if assignment_effective_height < epoch_start_height
        || assignment_effective_height > epoch_end_height
    {
        return Err(format!(
            "Cluster assignment effective height {assignment_effective_height} is outside epoch {assignment_epoch} ({epoch_start_height}..={epoch_end_height})."
        ));
    }
    let randomness_source = json_string_at(
        snapshot,
        &["cluster_randomness_source", "clusterRandomnessSource"],
    )
    .filter(|value| !value.trim().is_empty())
    .ok_or_else(|| {
        "Validator-set snapshot is missing its finalized-QC cluster seed.".to_string()
    })?;
    let cluster_map_hash = validator_snapshot_hash(
        snapshot,
        &["cluster_map_hash", "clusterMapHash"],
        "cluster_map_hash",
    )?;
    let membership_bundle_hash = validator_snapshot_hash(
        snapshot,
        &["membership_bundle_hash", "membershipBundleHash"],
        "membership_bundle_hash",
    )?;
    let entries = snapshot
        .get("cluster_assignments")
        .or_else(|| snapshot.get("clusterAssignments"))
        .and_then(Value::as_array)
        .ok_or_else(|| "Validator-set snapshot is missing cluster_assignments.".to_string())?;
    if entries.len() != cluster_count as usize {
        return Err(format!(
            "Validator-set snapshot contains {} cluster assignments, expected {cluster_count}.",
            entries.len()
        ));
    }

    let active_set = active_validators.iter().cloned().collect::<HashSet<_>>();
    let mut seen_cluster_ids = HashSet::new();
    let mut seen_validators = HashSet::new();
    let mut assignments = Vec::with_capacity(entries.len());
    let mut cluster_sizes = Vec::with_capacity(entries.len());
    for entry in entries {
        let cluster_id = json_u64_at(entry, &["cluster_id", "clusterId"])
            .ok_or_else(|| "Cluster assignment is missing cluster_id.".to_string())?;
        if cluster_id >= cluster_count || !seen_cluster_ids.insert(cluster_id) {
            return Err(format!(
                "Cluster assignment contains invalid or duplicate cluster_id {cluster_id}."
            ));
        }
        let cluster_address = json_string_at(entry, &["cluster_address", "clusterAddress"])
            .filter(|value| !value.trim().is_empty())
            .ok_or_else(|| format!("Cluster {cluster_id} is missing cluster_address."))?;
        let validator_entries = entry
            .get("validator_ids")
            .or_else(|| entry.get("validatorIds"))
            .and_then(Value::as_array)
            .ok_or_else(|| format!("Cluster {cluster_id} is missing validator_ids."))?;
        let validator_ids = validator_entries
            .iter()
            .map(|member| {
                validator_member_address(member).ok_or_else(|| {
                    format!("Cluster {cluster_id} contains an invalid validator identity.")
                })
            })
            .collect::<Result<Vec<_>, _>>()?;
        if validator_ids.is_empty() {
            return Err(format!("Cluster {cluster_id} has no validator_ids."));
        }
        if validator_ids.iter().collect::<HashSet<_>>().len() != validator_ids.len() {
            return Err(format!(
                "Cluster {cluster_id} contains duplicate validator_ids."
            ));
        }
        for validator_id in &validator_ids {
            if !active_set.contains(validator_id) {
                return Err(format!(
                    "Cluster {cluster_id} contains validator {validator_id} outside the active validator set."
                ));
            }
            if !seen_validators.insert(validator_id.clone()) {
                return Err(format!(
                    "Validator {validator_id} appears in more than one cluster."
                ));
            }
        }
        let quorum_threshold = json_u64_at(entry, &["quorum_threshold", "quorumThreshold"])
            .ok_or_else(|| format!("Cluster {cluster_id} is missing quorum_threshold."))?;
        let expected_quorum = testnet_validator_cluster_quorum(validator_ids.len()) as u64;
        if quorum_threshold != expected_quorum {
            return Err(format!(
                "Cluster {cluster_id} quorum_threshold={quorum_threshold}, expected {expected_quorum} for {} validators.",
                validator_ids.len()
            ));
        }
        let fault_tolerance_f = json_u64_at(entry, &["fault_tolerance_f", "faultToleranceF"])
            .ok_or_else(|| format!("Cluster {cluster_id} is missing fault_tolerance_f."))?;
        let expected_fault_tolerance = validator_ids.len().saturating_sub(1) as u64 / 3;
        if fault_tolerance_f != expected_fault_tolerance {
            return Err(format!(
                "Cluster {cluster_id} fault_tolerance_f={fault_tolerance_f}, expected {expected_fault_tolerance} for {} validators.",
                validator_ids.len()
            ));
        }
        let entry_epoch = json_u64_at(entry, &["assignment_epoch", "assignmentEpoch"])
            .ok_or_else(|| format!("Cluster {cluster_id} is missing assignment_epoch."))?;
        let entry_effective_height = json_u64_at(
            entry,
            &["assignment_effective_height", "assignmentEffectiveHeight"],
        )
        .ok_or_else(|| format!("Cluster {cluster_id} is missing assignment_effective_height."))?;
        if entry_epoch != assignment_epoch || entry_effective_height != assignment_effective_height
        {
            return Err(format!(
                "Cluster {cluster_id} assignment metadata does not match the membership bundle."
            ));
        }
        cluster_sizes.push(validator_ids.len());
        assignments.push(ValidatorClusterAssignmentSummary {
            cluster_id,
            cluster_address,
            validator_ids,
            quorum_threshold,
            fault_tolerance_f,
            assignment_epoch: entry_epoch,
            assignment_effective_height: entry_effective_height,
        });
    }
    if seen_validators != active_set {
        return Err(
            "Cluster assignments do not cover the active validator set exactly once.".to_string(),
        );
    }
    let minimum_size = cluster_sizes.iter().copied().min().unwrap_or_default();
    let maximum_size = cluster_sizes.iter().copied().max().unwrap_or_default();
    if maximum_size.saturating_sub(minimum_size) > 1 {
        return Err(
            "Cluster assignments are not balanced across the active validator set.".to_string(),
        );
    }
    assignments.sort_by_key(|assignment| assignment.cluster_id);
    Ok(ValidatedClusterMembershipSnapshot {
        cluster_count,
        assignment_epoch,
        assignment_effective_height,
        randomness_source,
        cluster_map_hash,
        membership_bundle_hash,
        assignments,
    })
}

fn validate_validator_set_rpc_snapshot(
    source: &OnboardingRpcSource,
    value: Value,
) -> Result<ValidatorSetRpcObservation, String> {
    let snapshot = select_epoch_validator_set_snapshot(&value);
    if !snapshot.is_object() {
        return Err(format!(
            "{} returned a validator-set snapshot that is not an object.",
            source.label
        ));
    }

    let chain_id = json_u64_at(&snapshot, &["chain_id", "chainId"]);
    if chain_id != Some(TESTNET_CHAIN_ID) {
        return Err(format!(
            "{} returned chain_id={}, expected {}.",
            source.label,
            chain_id
                .map(|value| value.to_string())
                .unwrap_or_else(|| "missing".to_string()),
            TESTNET_CHAIN_ID
        ));
    }
    if json_u64_at(
        &snapshot,
        &["snapshot_format_version", "snapshotFormatVersion"],
    ) != Some(TESTNET_VALIDATOR_SET_SNAPSHOT_FORMAT_VERSION)
    {
        return Err(format!(
            "{} returned an unsupported validator-set snapshot format.",
            source.label
        ));
    }
    if json_string_at(
        &snapshot,
        &[
            "protocol_version",
            "protocolVersion",
            "required_protocol_version",
            "requiredProtocolVersion",
        ],
    )
    .as_deref()
        != Some(TESTNET_VALIDATOR_PROTOCOL_VERSION)
    {
        return Err(format!(
            "{} returned an incompatible validator-set protocol version.",
            source.label
        ));
    }
    let binary_version = json_string_at(
        &snapshot,
        &[
            "binary_version",
            "binaryVersion",
            "runtime_version",
            "runtimeVersion",
            "required_binary_version",
            "requiredBinaryVersion",
        ],
    );
    if binary_version.as_deref() != Some(env!("CARGO_PKG_VERSION")) {
        return Err(format!(
            "{} returned runtime version {}, but this Control Panel requires {}.",
            source.label,
            binary_version.as_deref().unwrap_or("missing"),
            env!("CARGO_PKG_VERSION")
        ));
    }

    let validator_set_hash = json_string_at(
        &snapshot,
        &[
            "validator_set_hash",
            "validatorSetHash",
            "set_hash",
            "setHash",
        ],
    )
    .ok_or_else(|| {
        format!(
            "{} returned a validator-set snapshot without a hash.",
            source.label
        )
    })?;
    for candidate in [
        json_string_at(
            &snapshot,
            &["local_validator_set_hash", "localValidatorSetHash"],
        ),
        json_string_at(
            &snapshot,
            &["network_validator_set_hash", "networkValidatorSetHash"],
        ),
    ]
    .into_iter()
    .flatten()
    {
        if !candidate.eq_ignore_ascii_case(&validator_set_hash) {
            return Err(format!(
                "{} returned internally inconsistent validator-set hashes.",
                source.label
            ));
        }
    }

    let effective_from_height = json_u64_at(
        &snapshot,
        &[
            "effective_from_height",
            "effectiveFromHeight",
            "effective_height",
            "effectiveHeight",
        ],
    )
    .ok_or_else(|| {
        format!(
            "{} returned a validator-set snapshot without an effective height.",
            source.label
        )
    })?;
    let active_validators =
        validator_members_at(&snapshot, &["active_validators", "activeValidators"]);
    if json_u64_at(&snapshot, &["epoch_id", "epochId", "epoch"]).is_none()
        || json_u64_at(
            &snapshot,
            &["validator_set_version", "validatorSetVersion", "version"],
        )
        .is_none()
        || json_u64_at(&snapshot, &["quorum_threshold", "quorumThreshold"]).is_none()
        || active_validators.is_empty()
    {
        return Err(format!(
            "{} returned an incomplete validator-set snapshot.",
            source.label
        ));
    }
    let cluster_membership = validate_cluster_membership_snapshot(&snapshot, &active_validators)
        .map_err(|error| {
            format!(
                "{} returned invalid cluster membership: {error}",
                source.label
            )
        })?;

    Ok(ValidatorSetRpcObservation {
        label: source.label.clone(),
        role: source.role.clone(),
        endpoint: source.endpoint.clone(),
        public_rpc: source.public_rpc,
        validator_set_hash: validator_set_hash.to_ascii_lowercase(),
        cluster_map_hash: cluster_membership.cluster_map_hash,
        membership_bundle_hash: cluster_membership.membership_bundle_hash,
        effective_from_height,
        snapshot,
    })
}

fn write_json_file_atomically(path: &Path, value: &Value) -> Result<(), String> {
    let parent = path
        .parent()
        .ok_or_else(|| format!("{} has no parent directory.", path.display()))?;
    fs::create_dir_all(parent)
        .map_err(|error| format!("Failed to create {}: {error}", parent.display()))?;
    let mut temporary = tempfile::NamedTempFile::new_in(parent)
        .map_err(|error| format!("Failed to stage {}: {error}", path.display()))?;
    serde_json::to_writer_pretty(&mut temporary, value)
        .map_err(|error| format!("Failed to serialize {}: {error}", path.display()))?;
    temporary
        .write_all(b"\n")
        .map_err(|error| format!("Failed to finish {}: {error}", path.display()))?;
    temporary
        .as_file()
        .sync_all()
        .map_err(|error| format!("Failed to sync {}: {error}", path.display()))?;
    temporary.persist(path).map_err(|error| {
        format!(
            "Failed to atomically replace {}: {}",
            path.display(),
            error.error
        )
    })?;
    #[cfg(unix)]
    File::open(parent)
        .and_then(|directory| directory.sync_all())
        .map_err(|error| format!("Failed to sync {}: {error}", parent.display()))?;
    Ok(())
}

async fn sync_latest_epoch_validator_set(
    client: &Client,
    node: &TestnetProvisionedNode,
) -> Result<PathBuf, String> {
    let sources = onboarding_rpc_sources(node)?;
    let results = join_all(sources.iter().map(|source| async move {
        let value = query_rpc_value(
            client,
            &source.endpoint,
            "synergy_getValidatorSetSnapshot",
            json!([]),
        )
        .await
        .map_err(|error| format!("{} validator-set RPC failed: {error}", source.label))?;
        validate_validator_set_rpc_snapshot(source, value)
    }))
    .await;
    let mut observations = Vec::new();
    let mut failures = Vec::new();
    for (source, result) in sources.iter().zip(results) {
        match result {
            Ok(observation) => observations.push(observation),
            Err(error) => failures.push((source.role.clone(), error)),
        }
    }

    let local = observations
        .iter()
        .find(|observation| observation.role == "local_validator")
        .ok_or_else(|| {
            let detail = failures
                .iter()
                .find(|(role, _)| role == "local_validator")
                .map(|(_, error)| error.as_str())
                .unwrap_or("The local validator source returned no observation.");
            format!(
                "The local validator runtime did not provide a valid live validator-set snapshot: {detail}"
            )
        })?;
    let https_core = observations.iter().find(|observation| {
        observation.public_rpc
            && observation.endpoint.starts_with("https://")
            && observation.validator_set_hash == local.validator_set_hash
    });
    let corroborated_network = if let Some(observation) = https_core {
        Some(observation)
    } else {
        observations.iter().find_map(|candidate| {
            if candidate.role != "relayer" || candidate.validator_set_hash != local.validator_set_hash
            {
                return None;
            }
            let matching_relayer_count = observations
                .iter()
                .filter(|observation| {
                    observation.role == "relayer"
                        && observation.validator_set_hash == candidate.validator_set_hash
                        && observation.cluster_map_hash == candidate.cluster_map_hash
                        && observation.membership_bundle_hash == candidate.membership_bundle_hash
                })
                .count();
            (matching_relayer_count >= 2).then_some(candidate)
        })
    }
    .ok_or_else(|| {
        format!(
            "Local validator set {} was not corroborated by the HTTPS core RPC or two independent relayers.",
            local.validator_set_hash
        )
    })?;
    let matching = observations
        .iter()
        .filter(|observation| {
            observation.validator_set_hash == corroborated_network.validator_set_hash
                && observation.cluster_map_hash == corroborated_network.cluster_map_hash
                && observation.membership_bundle_hash == corroborated_network.membership_bundle_hash
        })
        .collect::<Vec<_>>();
    let local_bundle_matches =
        local_validator_bundle_matches_canonical(local, corroborated_network, &node.node_address)?;

    let mut document = corroborated_network.snapshot.clone();
    let object = document
        .as_object_mut()
        .ok_or_else(|| "The selected live validator-set snapshot is not an object.".to_string())?;
    let now = Utc::now().to_rfc3339();
    object.insert("generated_at_utc".to_string(), json!(now));
    object.insert("is_latest".to_string(), json!(true));
    object.insert("source_majority_verified".to_string(), json!(true));
    object.insert(
        "pre_activation_local_cluster_divergence".to_string(),
        json!(!local_bundle_matches),
    );
    object.insert(
        "local_validator_set_hash".to_string(),
        json!(local.validator_set_hash),
    );
    object.insert(
        "network_validator_set_hash".to_string(),
        json!(local.validator_set_hash),
    );
    object.insert(
        "sources".to_string(),
        Value::Array(
            std::iter::once(local)
                .chain(matching.iter().copied().filter(|observation| {
                    observation.role != "local_validator"
                }))
                .map(|observation| {
                    json!({
                        "label": observation.label,
                        "role": observation.role,
                        "endpoint": observation.endpoint,
                        "public_rpc": observation.public_rpc,
                        "effective_from_height": observation.effective_from_height,
                        "validator_set_hash": observation.validator_set_hash,
                        "cluster_map_hash": observation.cluster_map_hash,
                        "membership_bundle_hash": observation.membership_bundle_hash,
                        "bundle_matches_selected": observation.cluster_map_hash == corroborated_network.cluster_map_hash
                            && observation.membership_bundle_hash == corroborated_network.membership_bundle_hash,
                    })
                })
                .collect(),
        ),
    );

    let path = validator_onboarding_evidence_path(node, "epoch-validator-set-latest.json");
    write_json_file_atomically(&path, &document)?;
    Ok(path)
}

fn validator_runtime_binary_version(value: &Value) -> Option<String> {
    let snapshot = select_epoch_validator_set_snapshot(value);
    json_string_at(
        &snapshot,
        &[
            "binary_version",
            "binaryVersion",
            "runtime_version",
            "runtimeVersion",
            "required_binary_version",
            "requiredBinaryVersion",
        ],
    )
}

async fn query_local_validator_runtime_version(
    client: &Client,
    node: &TestnetProvisionedNode,
) -> Result<String, String> {
    let endpoint = rpc_endpoint_for_workspace(node)?;
    let value = query_rpc_value(
        client,
        &endpoint,
        "synergy_getValidatorSetSnapshot",
        json!([]),
    )
    .await
    .map_err(|error| format!("Local validator runtime version query failed: {error}"))?;
    validator_runtime_binary_version(&value).ok_or_else(|| {
        "Local validator runtime did not report a binary version in its validator-set snapshot."
            .to_string()
    })
}

async fn ensure_matching_validator_runtime(
    app_context: &AppContext,
    node: &TestnetProvisionedNode,
) -> Result<Option<String>, String> {
    let workspace_directory = PathBuf::from(&node.workspace_directory);
    if running_pid_for_workspace(&workspace_directory).is_none() {
        return Ok(None);
    }

    let client = Client::builder()
        .timeout(Duration::from_secs(8))
        .connect_timeout(Duration::from_secs(2))
        .build()
        .map_err(|error| format!("HTTP client error: {error}"))?;
    let reported_version = match query_local_validator_runtime_version(&client, node).await {
        Ok(version) => version,
        Err(_) => return Ok(None),
    };
    let required_version = env!("CARGO_PKG_VERSION");
    if reported_version == required_version {
        return Ok(None);
    }

    append_workspace_control_log(
        &workspace_directory,
        "WARN",
        "Restarting validator to align its running runtime with the Control Panel release",
        Some(json!({
            "reported_runtime_version": reported_version.clone(),
            "required_runtime_version": required_version,
        })),
    );
    let restart = testnet_node_control(
        app_context,
        None,
        TestnetNodeControlInput {
            node_id: node.id.clone(),
            action: "restart".to_string(),
        },
    )
    .await
    .map_err(|error| {
        format!(
            "Control Panel {required_version} could not restart validator runtime {reported_version} with the matching bundled binary: {error}"
        )
    })?;

    let restarted_version = query_local_validator_runtime_version(&client, node).await?;
    if restarted_version != required_version {
        return Err(format!(
            "Validator runtime version alignment failed closed: restarted runtime reported {restarted_version}, but Control Panel requires {required_version}."
        ));
    }

    Ok(Some(format!(
        "Restarted validator runtime {reported_version} with the bundled {restarted_version} binary. {}",
        restart.message
    )))
}

fn epoch_validator_set_refresh_status_path(node: &TestnetProvisionedNode) -> PathBuf {
    validator_onboarding_evidence_path(node, "epoch-validator-set-refresh-status.json")
}

async fn refresh_latest_epoch_validator_set(
    client: &Client,
    node: &TestnetProvisionedNode,
) -> Result<PathBuf, String> {
    let result = sync_latest_epoch_validator_set(client, node).await;
    let (status, detail, evidence_path) = match &result {
        Ok(path) => (
            "pass",
            "The local validator set was corroborated by independent network RPC evidence.",
            Some(path.to_string_lossy().to_string()),
        ),
        Err(error) => ("failed", error.as_str(), None),
    };
    let refresh_status = json!({
        "status": status,
        "detail": detail,
        "evidence_path": evidence_path,
        "generated_at_utc": Utc::now().to_rfc3339(),
    });
    if let Err(error) = write_json_file_atomically(
        &epoch_validator_set_refresh_status_path(node),
        &refresh_status,
    ) {
        return Err(format!(
            "Validator-set refresh finished with status {status}, but its durable status could not be recorded: {error}"
        ));
    }
    result
}

fn select_epoch_validator_set_snapshot(value: &Value) -> Value {
    for key in [
        "epoch_validator_set",
        "epochValidatorSet",
        "validator_set",
        "validatorSet",
        "snapshot",
    ] {
        if let Some(snapshot) = value.get(key).filter(|snapshot| snapshot.is_object()) {
            return snapshot.clone();
        }
    }

    for key in [
        "epoch_validator_sets",
        "epochValidatorSets",
        "validator_sets",
        "validatorSets",
        "sets",
    ] {
        if let Some(snapshot) = value.get(key).and_then(Value::as_array).and_then(|sets| {
            sets.iter()
                .filter(|entry| entry.is_object())
                .max_by_key(|entry| {
                    (
                        json_u64_at(
                            entry,
                            &[
                                "epoch_id",
                                "epochId",
                                "epoch",
                                "validator_set_version",
                                "validatorSetVersion",
                            ],
                        )
                        .unwrap_or(0),
                        json_u64_at(
                            entry,
                            &[
                                "effective_from_height",
                                "effectiveFromHeight",
                                "effective_height",
                                "height",
                            ],
                        )
                        .unwrap_or(0),
                    )
                })
        }) {
            return snapshot.clone();
        }
    }

    value.clone()
}

fn validator_member_address(value: &Value) -> Option<String> {
    if let Some(address) = value.as_str() {
        let address = address.trim();
        return address.starts_with("synv1").then(|| address.to_string());
    }
    let object = value.as_object()?;
    [
        "validator_address",
        "validatorAddress",
        "address",
        "operator_address",
        "operatorAddress",
        "validator",
    ]
    .iter()
    .find_map(|key| {
        object
            .get(*key)
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|address| address.starts_with("synv1"))
            .map(str::to_string)
    })
}

fn validator_members_at(value: &Value, keys: &[&str]) -> Vec<String> {
    keys.iter()
        .find_map(|key| value.get(*key).and_then(Value::as_array))
        .map(|members| {
            let mut addresses = members
                .iter()
                .filter_map(validator_member_address)
                .collect::<Vec<_>>();
            addresses.sort();
            addresses.dedup();
            addresses
        })
        .unwrap_or_default()
}

fn validator_set_contains(addresses: &[String], validator_address: &str) -> bool {
    addresses
        .iter()
        .any(|address| address.eq_ignore_ascii_case(validator_address))
}

fn proof_source_count(value: &Value) -> usize {
    value
        .get("sources")
        .or_else(|| value.get("source_nodes"))
        .or_else(|| value.get("source_majority_sources"))
        .and_then(Value::as_array)
        .map(|sources| {
            sources
                .iter()
                .filter(|source| !proof_source_is_public_rpc(source))
                .count()
        })
        .unwrap_or(0)
}

fn proof_source_text(source: &Value) -> String {
    if let Some(text) = source.as_str() {
        return text.to_ascii_lowercase();
    }
    if let Some(object) = source.as_object() {
        return [
            "source",
            "url",
            "endpoint",
            "source_url_or_path",
            "label",
            "name",
            "role",
            "type",
            "proof_mode",
            "source_mode",
            "mode",
        ]
        .iter()
        .filter_map(|key| object.get(*key).and_then(Value::as_str))
        .collect::<Vec<_>>()
        .join(" ")
        .to_ascii_lowercase();
    }
    String::new()
}

fn proof_source_is_public_rpc(source: &Value) -> bool {
    let text = proof_source_text(source);
    source
        .get("public_rpc_only")
        .and_then(Value::as_bool)
        .unwrap_or(false)
        || source
            .get("public_rpc")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        || text.contains("public_rpc")
        || text.contains("public-rpc")
        || text.contains("testnet-core-rpc.synergy-network.io")
        || text.contains("synergy-network.io")
}

fn proof_declares_public_rpc_only(value: &Value) -> bool {
    value
        .get("proof_mode")
        .or_else(|| value.get("source_mode"))
        .or_else(|| value.get("mode"))
        .and_then(Value::as_str)
        .map(|mode| mode.eq_ignore_ascii_case("public_rpc_only"))
        .unwrap_or(false)
        || value
            .get("public_rpc_only")
            .and_then(Value::as_bool)
            .unwrap_or(false)
}

fn source_majority_proof_gate(node: &TestnetProvisionedNode) -> ValidatorOnboardingEvidenceGate {
    let candidates = [
        "source-majority-proof.json",
        "head-match-proof.json",
        "validator-onboarding-source-majority-proof.json",
    ];
    let Some(path) = candidates
        .iter()
        .map(|file| validator_onboarding_evidence_path(node, file))
        .find(|path| path.is_file())
    else {
        return evidence_gate(
            "source-majority-proof",
            "blocked",
            "Missing source-majority proof. Public RPC alone cannot satisfy validator activation.",
            Some(validator_onboarding_evidence_path(
                node,
                "source-majority-proof.json",
            )),
            Some("prove_source_majority_head_match"),
        );
    };
    let Ok(value) = read_json_value(&path) else {
        return evidence_gate(
            "source-majority-proof",
            "failed",
            "Source-majority proof exists but cannot be parsed.",
            Some(path),
            Some("regenerate_source_majority_proof"),
        );
    };
    if proof_declares_public_rpc_only(&value) {
        return evidence_gate(
            "source-majority-proof",
            "failed",
            "Source-majority proof explicitly used public RPC only, which is forbidden for activation.",
            Some(path),
            Some("prove_source_majority_with_validator_relayers_or_archive"),
        );
    }
    if let Some(detail) = onboarding_evidence_freshness_failure(
        &value,
        TESTNET_ONBOARDING_HEAD_PROOF_MAX_AGE_SECS,
        "Source-majority proof",
    ) {
        return evidence_gate(
            "source-majority-proof",
            "blocked",
            &detail,
            Some(path),
            Some("regenerate_source_majority_proof"),
        );
    }
    let source_count = proof_source_count(&value);
    let passed = json_truthy(
        &value,
        &[
            "source_majority_verified",
            "fixed_height_hash_agreement",
            "head_matched",
            "pass",
            "passed",
        ],
    );
    if passed && source_count >= 3 {
        evidence_gate(
            "source-majority-proof",
            "pass",
            &format!("Source-majority head match verified with {source_count} sources."),
            Some(path),
            None,
        )
    } else {
        evidence_gate(
            "source-majority-proof",
            "blocked",
            &format!(
                "Source-majority proof is incomplete: passed={passed}, source_count={source_count}, required=3."
            ),
            Some(path),
            Some("regenerate_source_majority_proof"),
        )
    }
}

fn verified_normal_sync_head_evidence(
    node: &TestnetProvisionedNode,
) -> Result<(PathBuf, u64, String), String> {
    let gate = source_majority_proof_gate(node);
    if gate.status != "pass" {
        return Err(format!(
            "Normal peer sync cannot complete setup sync: {}",
            gate.detail
        ));
    }
    let evidence_path = gate
        .evidence_path
        .map(PathBuf::from)
        .ok_or_else(|| "Normal peer sync head evidence path is missing.".to_string())?;
    let evidence = read_json_value(&evidence_path).map_err(|error| {
        format!(
            "Normal peer sync head evidence could not be read from {}: {error}",
            evidence_path.display()
        )
    })?;
    for key in [
        "source_majority_verified",
        "fixed_height_hash_agreement",
        "head_matched",
    ] {
        if evidence.get(key).and_then(Value::as_bool) != Some(true) {
            return Err(format!(
                "Normal peer sync head evidence is not verified: {key} is not true."
            ));
        }
    }

    let common_height = json_u64_at(&evidence, &["common_height"])
        .filter(|height| *height > 0)
        .ok_or_else(|| {
            "Normal peer sync head evidence is missing a positive canonical height.".to_string()
        })?;
    let common_hash = snapshot_string_field(&evidence, "common_hash")
        .ok_or_else(|| "Normal peer sync head evidence is missing common_hash.".to_string())?;
    let local_hash = snapshot_string_field(&evidence, "local_hash")
        .ok_or_else(|| "Normal peer sync head evidence is missing local_hash.".to_string())?;
    if !common_hash.eq_ignore_ascii_case(&local_hash) {
        return Err(
            "Normal peer sync head evidence does not match the local validator hash to the canonical hash."
                .to_string(),
        );
    }

    let fixed_height_sources = evidence
        .get("fixed_height_sources")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            "Normal peer sync head evidence is missing fixed-height source records.".to_string()
        })?;
    let verified_source_count = fixed_height_sources
        .iter()
        .filter(|source| {
            source.get("status").and_then(Value::as_str) == Some("ok")
                && json_u64_at(source, &["height"]) == Some(common_height)
                && snapshot_string_field(source, "hash").is_some()
        })
        .count();
    if verified_source_count < 3 {
        return Err(format!(
            "Normal peer sync head evidence has only {verified_source_count} verified fixed-height sources; required=3."
        ));
    }
    if !fixed_height_sources.iter().any(|source| {
        source.get("label").and_then(Value::as_str) == Some("local-validator")
            && source.get("status").and_then(Value::as_str) == Some("ok")
            && json_u64_at(source, &["height"]) == Some(common_height)
            && snapshot_string_field(source, "hash")
                .is_some_and(|hash| hash.eq_ignore_ascii_case(&local_hash))
    }) {
        return Err(
            "Normal peer sync head evidence does not contain a verified local-validator record at the canonical height."
                .to_string(),
        );
    }

    Ok((evidence_path, common_height, common_hash))
}

fn normal_sync_public_rpc_endpoint() -> String {
    #[cfg(test)]
    {
        return std::env::var("SYNERGY_TEST_NORMAL_SYNC_PUBLIC_RPC_ENDPOINT")
            .unwrap_or_else(|_| TESTNET_PUBLIC_RPC_ENDPOINT.to_string());
    }

    #[cfg(not(test))]
    {
        TESTNET_PUBLIC_RPC_ENDPOINT.to_string()
    }
}

fn normal_sync_account_state_parity_proof(
    validator_address: &str,
    local_balance_nwei: Option<u64>,
    canonical_public_balance_nwei: Option<u64>,
    local_stake_nwei: Option<u64>,
    canonical_public_stake_nwei: Option<u64>,
) -> Result<Value, String> {
    let local_balance_nwei = local_balance_nwei.ok_or_else(|| {
        "Normal peer sync account-state parity cannot be verified: local validator SNRG balance is missing."
            .to_string()
    })?;
    let canonical_public_balance_nwei = canonical_public_balance_nwei.ok_or_else(|| {
        "Normal peer sync account-state parity cannot be verified: canonical public validator SNRG balance is missing."
            .to_string()
    })?;
    let local_stake_nwei = local_stake_nwei.ok_or_else(|| {
        "Normal peer sync account-state parity cannot be verified: local validator SNRG stake is missing."
            .to_string()
    })?;
    let canonical_public_stake_nwei = canonical_public_stake_nwei.ok_or_else(|| {
        "Normal peer sync account-state parity cannot be verified: canonical public validator SNRG stake is missing."
            .to_string()
    })?;

    if local_balance_nwei != canonical_public_balance_nwei {
        return Err(format!(
            "Normal peer sync account-state parity rejected: local validator SNRG balance {local_balance_nwei} does not match canonical public balance {canonical_public_balance_nwei}."
        ));
    }
    if local_stake_nwei != canonical_public_stake_nwei {
        return Err(format!(
            "Normal peer sync account-state parity rejected: local validator SNRG stake {local_stake_nwei} does not match canonical public stake {canonical_public_stake_nwei}."
        ));
    }

    Ok(json!({
        "status": "pass",
        "proof_version": 1,
        "validator_address": validator_address,
        "token": TOKEN_SYMBOL,
        "local_balance_nwei": local_balance_nwei,
        "canonical_public_balance_nwei": canonical_public_balance_nwei,
        "local_stake_nwei": local_stake_nwei,
        "canonical_public_stake_nwei": canonical_public_stake_nwei,
        "balance_match": true,
        "stake_match": true,
        "verified_at_utc": Utc::now().to_rfc3339(),
    }))
}

async fn verified_normal_sync_account_state_parity(
    client: &Client,
    node: &TestnetProvisionedNode,
) -> Result<Value, String> {
    let local_endpoint = rpc_endpoint_for_workspace(node)?;
    let public_endpoint = normal_sync_public_rpc_endpoint();
    let local_balance_nwei = query_rpc_u64_or_none(
        client,
        &local_endpoint,
        "synergy_getTokenBalance",
        json!([node.node_address, TOKEN_SYMBOL]),
    )
    .await;
    let canonical_public_balance_nwei = query_rpc_u64_or_none(
        client,
        &public_endpoint,
        "synergy_getTokenBalance",
        json!([node.node_address, TOKEN_SYMBOL]),
    )
    .await;
    let (local_stake_nwei, _) =
        query_account_stake_from_endpoint(client, &local_endpoint, &node.node_address).await;
    let (canonical_public_stake_nwei, _) =
        query_account_stake_from_endpoint(client, &public_endpoint, &node.node_address).await;

    normal_sync_account_state_parity_proof(
        &node.node_address,
        local_balance_nwei,
        canonical_public_balance_nwei,
        local_stake_nwei,
        canonical_public_stake_nwei,
    )
}

fn validate_normal_sync_resume_identity(node: &TestnetProvisionedNode) -> Result<Value, String> {
    let workspace = Path::new(&node.workspace_directory);
    let config_path = workspace.join("config").join("node.toml");
    if !config_path.is_file() {
        return Err(format!(
            "Local validator config is missing at {}.",
            config_path.display()
        ));
    }
    let genesis_hash = workspace_genesis_hash(workspace)?;
    let expected_genesis_hash = canonical_testnet_genesis_hash()?;
    if !genesis_hash.eq_ignore_ascii_case(&expected_genesis_hash) {
        return Err(
            "Local validator genesis identity does not match the canonical Testnet genesis."
                .to_string(),
        );
    }
    if !node_config_fork_metadata_ready(&config_path)? {
        return Err("Local validator fork identity is not canonical and fail-closed.".to_string());
    }
    if let Some(config_address) = parse_testnet_validator_address(&config_path) {
        if !config_address.eq_ignore_ascii_case(&node.node_address) {
            return Err(
                "Local validator config identity does not match the preserved workspace identity."
                    .to_string(),
            );
        }
    } else {
        return Err("Local validator config is missing its validator identity.".to_string());
    }
    Ok(json!({
        "chain_id": TESTNET_CHAIN_ID,
        "network_id": TESTNET_NETWORK_ID_V2,
        "genesis_hash": genesis_hash,
        "validator_address": node.node_address,
        "fork_metadata_verified": true,
    }))
}

fn normal_sync_resume_height_proof(
    local_height: u64,
    public_head: &VerifiedPublicChainHead,
    requested_target_height: Option<u64>,
) -> Result<(u64, u64), String> {
    if local_height == 0 {
        return Err("Local validator height must be positive.".to_string());
    }
    if public_head.chain_id != TESTNET_CHAIN_ID || public_head.network_id != TESTNET_NETWORK_ID_V2 {
        return Err("Public normal-sync head identity is not canonical.".to_string());
    }
    if let Some(requested_target_height) = requested_target_height {
        if requested_target_height.abs_diff(public_head.height) > TESTNET_ACTIVATION_MAX_SYNC_GAP {
            return Err(format!(
                "Requested normal-sync target h{requested_target_height} is not within the verified public head h{} safe threshold.",
                public_head.height
            ));
        }
    }
    let gap = local_height.abs_diff(public_head.height);
    if gap > TESTNET_ACTIVATION_MAX_SYNC_GAP {
        return Err(format!(
            "Local normal-sync height h{local_height} is {gap} blocks from verified public head h{}, exceeding the safe {}-block threshold.",
            public_head.height, TESTNET_ACTIVATION_MAX_SYNC_GAP
        ));
    }
    Ok((public_head.height, gap))
}

async fn verified_normal_sync_resume_head_evidence(
    client: &Client,
    node: &TestnetProvisionedNode,
    local_height: u64,
    requested_target_height: Option<u64>,
) -> Result<(PathBuf, u64, String), String> {
    let local_identity = validate_normal_sync_resume_identity(node)?;
    let public_head = query_public_chain_head(client).await?;
    let (canonical_height, gap) =
        normal_sync_resume_height_proof(local_height, &public_head, requested_target_height)?;
    let canonical_hash = public_head.latest_hash.clone().ok_or_else(|| {
        "Public normal-sync head is missing its canonical block hash.".to_string()
    })?;
    let evidence = json!({
        "status": "pass",
        "proof_mode": "canonical_local_public_identity",
        "source_majority_verified": false,
        "fixed_height_hash_agreement": false,
        "head_matched": true,
        "chain_identity_verified": true,
        "local_identity": local_identity,
        "public_identity": {
            "chain_id": public_head.chain_id,
            "network_id": public_head.network_id,
            "genesis_hash": public_head.genesis_hash,
        },
        "common_height": canonical_height,
        "common_hash": canonical_hash,
        "local_height": local_height,
        "height_gap": gap,
        "local_public_identity_verified": true,
        "generated_at_utc": Utc::now().to_rfc3339(),
    });
    let path = validator_onboarding_evidence_path(node, "normal-sync-resume-proof.json");
    write_json_file(&path, &evidence)?;
    Ok((path, canonical_height, canonical_hash))
}

fn normal_sync_account_state_parity_proof_is_verified(
    proof: &Value,
    validator_address: &str,
) -> bool {
    let balances = (
        proof.get("local_balance_nwei").and_then(Value::as_u64),
        proof
            .get("canonical_public_balance_nwei")
            .and_then(Value::as_u64),
    );
    let stakes = (
        proof.get("local_stake_nwei").and_then(Value::as_u64),
        proof
            .get("canonical_public_stake_nwei")
            .and_then(Value::as_u64),
    );

    proof.get("status").and_then(Value::as_str) == Some("pass")
        && proof.get("proof_version").and_then(Value::as_u64) == Some(1)
        && proof.get("validator_address").and_then(Value::as_str) == Some(validator_address)
        && proof.get("token").and_then(Value::as_str) == Some(TOKEN_SYMBOL)
        && proof.get("balance_match").and_then(Value::as_bool) == Some(true)
        && proof.get("stake_match").and_then(Value::as_bool) == Some(true)
        && proof
            .get("verified_at_utc")
            .and_then(Value::as_str)
            .is_some_and(|value| !value.trim().is_empty())
        && matches!(balances, (Some(local), Some(public)) if local == public)
        && matches!(stakes, (Some(local), Some(public)) if local == public)
}

fn normal_sync_account_state_parity_evidence_is_verified(
    evidence: &Value,
    node: &TestnetProvisionedNode,
) -> bool {
    evidence
        .get("account_state_parity_verified")
        .and_then(Value::as_bool)
        == Some(true)
        && evidence
            .get("account_state_parity_proof")
            .is_some_and(|proof| {
                normal_sync_account_state_parity_proof_is_verified(proof, &node.node_address)
            })
}

fn shadow_epoch_proof_gate(node: &TestnetProvisionedNode) -> ValidatorOnboardingEvidenceGate {
    let candidates = [
        "validator-shadow-epoch-1-proof.json",
        "validator-onboarding-shadow-epoch-1.json",
        "shadow-epoch-1.json",
    ];
    let Some(path) = candidates
        .iter()
        .map(|file| validator_onboarding_evidence_path(node, file))
        .find(|path| path.is_file())
    else {
        return evidence_gate(
            "shadow-epoch-proof",
            "blocked",
            "Missing full shadow epoch proof. Activation remains blocked until the validator observes a complete epoch with zero mismatches.",
            Some(validator_onboarding_evidence_path(node, "validator-onboarding-shadow-epoch-1.json")),
            Some("run_full_shadow_epoch"),
        );
    };
    let Ok(value) = read_json_value(&path) else {
        return evidence_gate(
            "shadow-epoch-proof",
            "failed",
            "Shadow proof exists but cannot be parsed.",
            Some(path),
            Some("regenerate_shadow_epoch_proof"),
        );
    };
    if let Some(detail) = onboarding_evidence_freshness_failure(
        &value,
        TESTNET_ONBOARDING_SHADOW_PROOF_MAX_AGE_SECS,
        "Shadow epoch proof",
    ) {
        return evidence_gate(
            "shadow-epoch-proof",
            "blocked",
            &detail,
            Some(path),
            Some("continue_full_shadow_epoch"),
        );
    }
    let status = value.get("shadow_status").unwrap_or(&value);
    let completed = json_truthy(
        status,
        &["full_epoch_shadow_completed", "completed", "shadow_passed"],
    ) || status
        .get("computed_state")
        .or_else(|| status.get("state"))
        .or_else(|| status.get("status"))
        .and_then(Value::as_str)
        .map(|state| state.eq_ignore_ascii_case("SHADOW_PASSED"))
        .unwrap_or(false);
    let observed = json_u64_at(
        status,
        &[
            "observed_count",
            "observed_blocks",
            "observed_shadow_blocks",
        ],
    )
    .unwrap_or(0);
    let mismatches = json_u64_at(status, &["mismatch_count", "mismatches"]).unwrap_or(0);
    let missed =
        json_u64_at(status, &["missed_block_count", "missed_observation_count"]).unwrap_or(0);
    let epoch_start = json_u64_at(
        status,
        &[
            "required_full_shadow_epoch_start",
            "shadow_epoch_start",
            "epoch_start_height",
        ],
    );
    let epoch_end = json_u64_at(
        status,
        &[
            "required_full_shadow_epoch_end",
            "shadow_epoch_end",
            "epoch_end_height",
        ],
    );
    let canonical_epoch_range = epoch_start.zip(epoch_end).is_some_and(|(start, end)| {
        testnet_is_epoch_start_height(start)
            && testnet_is_epoch_end_height(end)
            && testnet_epoch_for_block_height(start) == testnet_epoch_for_block_height(end)
            && end.saturating_sub(start).saturating_add(1) == TESTNET_EPOCH_LENGTH as u64
    });
    if completed
        && observed >= TESTNET_EPOCH_LENGTH as u64
        && mismatches == 0
        && missed == 0
        && canonical_epoch_range
    {
        evidence_gate(
            "shadow-epoch-proof",
            "pass",
            &format!("Full shadow epoch passed: observed={observed}, mismatches=0, missed=0."),
            Some(path),
            None,
        )
    } else {
        evidence_gate(
            "shadow-epoch-proof",
            "blocked",
            &format!(
                "Shadow proof is incomplete: completed={completed}, observed={observed}, mismatches={mismatches}, missed={missed}, canonical_epoch_range={canonical_epoch_range}."
            ),
            Some(path),
            Some("continue_full_shadow_epoch"),
        )
    }
}

fn duty_gate_proof_gate(node: &TestnetProvisionedNode) -> ValidatorOnboardingEvidenceGate {
    let candidates = [
        "duty-gate-proof-before.json",
        "validator-onboarding-duty-gates.json",
        "validator-shadow-epoch-1-proof.json",
    ];
    let Some(path) = candidates
        .iter()
        .map(|file| validator_onboarding_evidence_path(node, file))
        .find(|path| path.is_file())
    else {
        return evidence_gate(
            "duty-gates-closed",
            "blocked",
            "Missing duty-gate proof. Onboarding validators must prove can_vote/can_propose/can_aggregate_qc all remained false before activation.",
            Some(validator_onboarding_evidence_path(node, "duty-gate-proof-before.json")),
            Some("prove_onboarding_duty_gates_closed"),
        );
    };
    let Ok(value) = read_json_value(&path) else {
        return evidence_gate(
            "duty-gates-closed",
            "failed",
            "Duty-gate proof exists but cannot be parsed.",
            Some(path),
            Some("regenerate_duty_gate_proof"),
        );
    };
    let duty_gate = value
        .pointer("/shadow_status/duty_gate")
        .or_else(|| value.pointer("/duty_gate"))
        .or_else(|| value.pointer("/quarantine/duty_gate"))
        .unwrap_or(&value);
    let required_closed_flags = [
        "can_vote",
        "can_propose",
        "can_aggregate_qc",
        "can_count_toward_quorum",
        "can_enter_proposer_schedule",
        "can_serve_as_canonical_source",
        "shadow_signs_real_votes",
    ];
    let missing_flags = required_closed_flags
        .iter()
        .filter(|key| duty_gate.get(**key).and_then(Value::as_bool).is_none())
        .copied()
        .collect::<Vec<_>>();
    if !missing_flags.is_empty() {
        return evidence_gate(
            "duty-gates-closed",
            "failed",
            &format!(
                "Onboarding duty-gate proof is missing required fail-closed flags: {}.",
                missing_flags.join(", ")
            ),
            Some(path),
            Some("regenerate_duty_gate_proof"),
        );
    }
    if let Some(detail) = onboarding_evidence_freshness_failure(
        &value,
        TESTNET_ONBOARDING_DUTY_PROOF_MAX_AGE_SECS,
        "Duty-gate proof",
    ) {
        return evidence_gate(
            "duty-gates-closed",
            "blocked",
            &detail,
            Some(path),
            Some("regenerate_duty_gate_proof"),
        );
    }
    let closed = required_closed_flags
        .iter()
        .all(|key| duty_gate.get(*key).and_then(Value::as_bool) == Some(false));
    if closed {
        evidence_gate(
            "duty-gates-closed",
            "pass",
            "Onboarding consensus duty gates are closed.",
            Some(path),
            None,
        )
    } else {
        evidence_gate(
            "duty-gates-closed",
            "failed",
            "Onboarding duty gates are not proven closed.",
            Some(path),
            Some("emergency_quarantine_and_reprove_duty_gates"),
        )
    }
}

fn validator_vpn_route_gate(node: &TestnetProvisionedNode) -> ValidatorOnboardingEvidenceGate {
    let workspace_directory = PathBuf::from(&node.workspace_directory);
    let config_path = workspace_directory.join("config").join("node.toml");
    let enrollment_path = validator_onboarding_evidence_path(node, "validator-vpn-enrollment.json");
    let snapshot_path =
        validator_onboarding_evidence_path(node, "validator-vpn-latest-snapshot.json");

    let Ok(config_value) = read_toml_value(&config_path) else {
        return evidence_gate(
            "validator-vpn-route",
            "blocked",
            "Validator runtime config is missing or invalid; VPN transport routes cannot be verified.",
            Some(config_path),
            Some("repair_validator_vpn_config"),
        );
    };
    if let Ok(enrollment) = read_json_value(&enrollment_path) {
        if enrollment.get("transport").and_then(Value::as_str) == Some("innernet") {
            return innernet_validator_route_gate(
                node,
                &config_value,
                &enrollment,
                &enrollment_path,
            );
        }
    }
    if !validator_workspace_uses_validator_vpn(&config_value) {
        return evidence_gate(
            "validator-vpn-route",
            "blocked",
            "Validator config does not use the validator VPN identity/transport model.",
            Some(config_path),
            Some("apply_validator_vpn_snapshot"),
        );
    }

    let public_address = config_value
        .get("p2p")
        .and_then(|section| section.get("public_address"))
        .and_then(toml::Value::as_str)
        .map(str::trim)
        .unwrap_or_default();
    if public_address != node.node_address.trim() {
        return evidence_gate(
            "validator-vpn-route",
            "failed",
            "Validator config public P2P identity does not match the local synv1 validator address.",
            Some(config_path),
            Some("repair_validator_vpn_config"),
        );
    }

    let mut peer_targets = extract_toml_string_array(&config_value, "network", "persistent_peers");
    peer_targets.extend(extract_toml_string_array(
        &config_value,
        "network",
        "additional_dial_targets",
    ));
    peer_targets.sort();
    peer_targets.dedup();
    if peer_targets
        .iter()
        .any(is_private_validator_transport_target)
    {
        return evidence_gate(
            "validator-vpn-route",
            "failed",
            "Validator peer targets include raw private validator transport addresses. Peer identities must be synv1 addresses; VPN IPs belong only in validator_vpn_transports.",
            Some(config_path),
            Some("repair_validator_vpn_config"),
        );
    }
    if !peer_targets
        .iter()
        .any(|target| target.trim().starts_with("synv1"))
    {
        return evidence_gate(
            "validator-vpn-route",
            "blocked",
            "Validator peer targets do not include any canonical synv1 validator identities.",
            Some(config_path),
            Some("repair_validator_vpn_config"),
        );
    }

    let Ok(enrollment) = read_json_value(&enrollment_path) else {
        return evidence_gate(
            "validator-vpn-route",
            "blocked",
            "Validator VPN enrollment evidence is missing or invalid.",
            Some(enrollment_path),
            Some("enroll_validator_vpn"),
        );
    };
    let Some(vpn_node_id) = enrollment
        .get("vpn_node_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return evidence_gate(
            "validator-vpn-route",
            "failed",
            "Validator VPN enrollment evidence is missing vpn_node_id.",
            Some(enrollment_path),
            Some("reenroll_validator_vpn"),
        );
    };
    let Some(vpn_ip) = enrollment
        .get("vpn_ip")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return evidence_gate(
            "validator-vpn-route",
            "failed",
            "Validator VPN enrollment evidence is missing vpn_ip.",
            Some(enrollment_path),
            Some("reenroll_validator_vpn"),
        );
    };

    let Ok(snapshot_value) = read_json_value(&snapshot_path) else {
        return evidence_gate(
            "validator-vpn-route",
            "blocked",
            "Latest signed validator VPN snapshot evidence is missing.",
            Some(snapshot_path),
            Some("apply_validator_vpn_snapshot"),
        );
    };
    let Ok(snapshot) = serde_json::from_value::<ValidatorVpnPeerSnapshot>(snapshot_value) else {
        return evidence_gate(
            "validator-vpn-route",
            "failed",
            "Latest validator VPN snapshot evidence is not a valid signed peer snapshot.",
            Some(snapshot_path),
            Some("apply_validator_vpn_snapshot"),
        );
    };
    if let Err(error) = validate_peer_snapshot_with_configured_signature(&snapshot) {
        let status = if error.contains("not configured") || error.contains("require") {
            "blocked"
        } else {
            "failed"
        };
        return evidence_gate(
            "validator-vpn-route",
            status,
            &format!("Latest validator VPN snapshot signature could not be verified: {error}."),
            Some(snapshot_path),
            Some("apply_validator_vpn_snapshot"),
        );
    }
    if snapshot.network != VALIDATOR_VPN_NETWORK {
        return evidence_gate(
            "validator-vpn-route",
            "failed",
            &format!(
                "Validator VPN snapshot is for network {}, expected {}.",
                snapshot.network, VALIDATOR_VPN_NETWORK
            ),
            Some(snapshot_path),
            Some("apply_validator_vpn_snapshot"),
        );
    }
    let created_at = match DateTime::parse_from_rfc3339(&snapshot.created_at) {
        Ok(timestamp) => timestamp.with_timezone(&Utc),
        Err(error) => {
            return evidence_gate(
                "validator-vpn-route",
                "failed",
                &format!(
                    "Latest validator VPN snapshot has an invalid created_at timestamp: {error}."
                ),
                Some(snapshot_path),
                Some("apply_validator_vpn_snapshot"),
            );
        }
    };
    let snapshot_age_secs = Utc::now().signed_duration_since(created_at).num_seconds();
    if snapshot_age_secs < -TESTNET_ONBOARDING_EVIDENCE_FUTURE_SKEW_SECS {
        return evidence_gate(
            "validator-vpn-route",
            "blocked",
            &format!(
                "Latest validator VPN snapshot timestamp is in the future: created_at={}, clock_skew_secs={}.",
                created_at.to_rfc3339(),
                -snapshot_age_secs
            ),
            Some(snapshot_path),
            Some("resync_time_and_apply_validator_vpn_snapshot"),
        );
    }
    if snapshot_age_secs > TESTNET_VALIDATOR_VPN_SNAPSHOT_MAX_AGE_SECS {
        return evidence_gate(
            "validator-vpn-route",
            "blocked",
            &format!(
                "Latest validator VPN snapshot evidence is stale: created_at={}, age_secs={}, max_age_secs={}.",
                created_at.to_rfc3339(),
                snapshot_age_secs,
                TESTNET_VALIDATOR_VPN_SNAPSHOT_MAX_AGE_SECS
            ),
            Some(snapshot_path),
            Some("apply_validator_vpn_snapshot"),
        );
    }
    if let Some(enrollment_generation) = json_u64_at(
        &enrollment,
        &["peer_snapshot_generation", "peerSnapshotGeneration"],
    ) {
        if snapshot.generation < enrollment_generation {
            return evidence_gate(
                "validator-vpn-route",
                "blocked",
                &format!(
                    "Validator VPN snapshot generation {} is older than enrollment generation {}.",
                    snapshot.generation, enrollment_generation
                ),
                Some(snapshot_path),
                Some("apply_validator_vpn_snapshot"),
            );
        }
    }

    let local_validator_address = node.node_address.trim();
    let local_vpn_host = match validator_vpn_host(vpn_ip) {
        Ok(host) => host,
        Err(error) => {
            return evidence_gate(
                "validator-vpn-route",
                "failed",
                &format!("Validator VPN enrollment has an invalid local vpn_ip: {error}."),
                Some(enrollment_path),
                Some("reenroll_validator_vpn"),
            );
        }
    };
    let local_peer = snapshot.validators.iter().find(|peer| {
        peer.node_id == vpn_node_id
            || peer.validator_pubkey.as_deref() == Some(local_validator_address)
    });
    let Some(local_peer) = local_peer else {
        return evidence_gate(
            "validator-vpn-route",
            "failed",
            "Latest validator VPN snapshot does not include this validator identity.",
            Some(snapshot_path),
            Some("apply_validator_vpn_snapshot"),
        );
    };
    if local_peer.validator_pubkey.as_deref() != Some(local_validator_address) {
        return evidence_gate(
            "validator-vpn-route",
            "failed",
            "Latest validator VPN snapshot local peer does not match the local synv1 validator identity.",
            Some(snapshot_path),
            Some("reenroll_validator_vpn"),
        );
    }
    if validator_vpn_host(&local_peer.vpn_ip).ok().as_deref() != Some(local_vpn_host.as_str()) {
        return evidence_gate(
            "validator-vpn-route",
            "failed",
            "Latest validator VPN snapshot local peer has a different VPN route than enrollment evidence.",
            Some(snapshot_path),
            Some("apply_validator_vpn_snapshot"),
        );
    }

    evidence_gate(
        "validator-vpn-route",
        "pass",
        &format!(
            "Validator VPN route verified from signed snapshot generation {} with {} validator transport mapping(s).",
            snapshot.generation,
            validator_vpn_transport_count(&config_value)
        ),
        Some(snapshot_path),
        None,
    )
}

fn innernet_validator_route_gate(
    node: &TestnetProvisionedNode,
    config_value: &toml::Value,
    enrollment: &Value,
    enrollment_path: &Path,
) -> ValidatorOnboardingEvidenceGate {
    let receipt_value = enrollment
        .get("innernet_receipt")
        .cloned()
        .unwrap_or(Value::Null);
    let Ok(receipt) = serde_json::from_value::<innernet::InnernetMembershipReceipt>(receipt_value)
    else {
        return evidence_gate(
            "validator-vpn-route",
            "failed",
            "Coordinator-managed Innernet enrollment evidence is missing a valid membership receipt.",
            Some(enrollment_path.to_path_buf()),
            Some("reenroll_innernet"),
        );
    };
    if let Err(error) = innernet::verify_membership_receipt(&receipt) {
        return evidence_gate(
            "validator-vpn-route",
            "failed",
            &format!("Innernet membership receipt signature could not be verified: {error}."),
            Some(enrollment_path.to_path_buf()),
            Some("reenroll_innernet"),
        );
    }
    if receipt.node_id != node.id {
        return evidence_gate(
            "validator-vpn-route",
            "failed",
            "Innernet membership receipt belongs to a different provisioned node.",
            Some(enrollment_path.to_path_buf()),
            Some("reenroll_innernet"),
        );
    }
    if !enrollment
        .pointer("/local_interface_evidence/handshakeConfirmed")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        return evidence_gate(
            "validator-vpn-route",
            "blocked",
            "Innernet enrollment lacks verified local coordinator handshake evidence.",
            Some(enrollment_path.to_path_buf()),
            Some("repair_innernet"),
        );
    }
    let network = config_value.get("network").and_then(toml::Value::as_table);
    let interface_matches = network
        .and_then(|network| network.get("innernet_interface"))
        .and_then(toml::Value::as_str)
        .map(str::trim)
        == Some(receipt.interface_name.as_str());
    let address_matches = network
        .and_then(|network| network.get("innernet_address"))
        .and_then(toml::Value::as_str)
        .map(str::trim)
        == Some(receipt.assigned_ip.as_str());
    let generation_matches = network
        .and_then(|network| network.get("innernet_configuration_version"))
        .and_then(toml::Value::as_integer)
        .is_some_and(|version| version >= receipt.configuration_version as i64);
    if !interface_matches || !address_matches || !generation_matches {
        return evidence_gate(
            "validator-vpn-route",
            "failed",
            "Validator runtime config does not match the signed coordinator Innernet assignment.",
            Some(enrollment_path.to_path_buf()),
            Some("repair_innernet"),
        );
    }
    let transport_count = validator_vpn_transport_count(config_value);
    if transport_count == 0 {
        return evidence_gate(
            "validator-vpn-route",
            "failed",
            "Coordinator-managed Innernet enrollment is missing its signed validator transport map.",
            Some(enrollment_path.to_path_buf()),
            Some("repair_innernet"),
        );
    }
    let public_address = config_value
        .get("p2p")
        .and_then(|section| section.get("public_address"))
        .and_then(toml::Value::as_str)
        .map(str::trim)
        .unwrap_or_default();
    if public_address != node.node_address.trim() {
        return evidence_gate(
            "validator-vpn-route",
            "failed",
            "Validator config public P2P identity does not match the local synv1 validator address.",
            Some(enrollment_path.to_path_buf()),
            Some("repair_innernet"),
        );
    }
    let mut peer_targets = extract_toml_string_array(config_value, "network", "persistent_peers");
    peer_targets.extend(extract_toml_string_array(
        config_value,
        "network",
        "additional_dial_targets",
    ));
    peer_targets.sort();
    peer_targets.dedup();
    if peer_targets
        .iter()
        .any(is_private_validator_transport_target)
    {
        return evidence_gate(
            "validator-vpn-route",
            "failed",
            "Innernet validator peer targets must use synv1 identities, not private transport addresses.",
            Some(enrollment_path.to_path_buf()),
            Some("repair_innernet"),
        );
    }
    if !peer_targets
        .iter()
        .any(|target| target.trim().starts_with("synv1"))
    {
        return evidence_gate(
            "validator-vpn-route",
            "blocked",
            "Innernet validator config does not include canonical synv1 validator identities.",
            Some(enrollment_path.to_path_buf()),
            Some("repair_innernet"),
        );
    }
    let transport_failures =
        validator_vpn_transport_validation_failures(config_value, &peer_targets);
    if !transport_failures.is_empty() {
        return evidence_gate(
            "validator-vpn-route",
            "failed",
            &format!(
                "Coordinator-signed Innernet transport map is invalid: {}",
                transport_failures.join("; ")
            ),
            Some(enrollment_path.to_path_buf()),
            Some("repair_innernet"),
        );
    }
    evidence_gate(
        "validator-vpn-route",
        "pass",
        &format!(
            "Coordinator-managed Innernet route verified at configuration version {} for interface {} with {} validator transport mapping(s).",
            receipt.configuration_version, receipt.interface_name, transport_count
        ),
        Some(enrollment_path.to_path_buf()),
        None,
    )
}

fn epoch_validator_set_gate(
    node: &TestnetProvisionedNode,
) -> (
    ValidatorOnboardingEvidenceGate,
    Option<ValidatorSetSnapshotSummary>,
) {
    let refresh_status_path = epoch_validator_set_refresh_status_path(node);
    let Ok(refresh_status) = read_json_value(&refresh_status_path) else {
        return (
            evidence_gate(
                "epoch-validator-set",
                "blocked",
                "Live validator-set evidence has not been synchronized by this Control Panel yet.",
                Some(refresh_status_path),
                Some("sync_latest_epoch_validator_set"),
            ),
            None,
        );
    };
    if let Some(detail) = onboarding_evidence_freshness_failure(
        &refresh_status,
        TESTNET_VALIDATOR_SET_SNAPSHOT_MAX_AGE_SECS,
        "Validator-set refresh status",
    ) {
        return (
            evidence_gate(
                "epoch-validator-set",
                "blocked",
                &detail,
                Some(refresh_status_path),
                Some("sync_latest_epoch_validator_set"),
            ),
            None,
        );
    }
    if refresh_status.get("status").and_then(Value::as_str) != Some("pass") {
        let detail = refresh_status
            .get("detail")
            .and_then(Value::as_str)
            .unwrap_or("Live validator-set synchronization failed.");
        return (
            evidence_gate(
                "epoch-validator-set",
                "blocked",
                detail,
                Some(refresh_status_path),
                Some("sync_latest_epoch_validator_set"),
            ),
            None,
        );
    }

    let Some(path) = epoch_validator_set_snapshot_paths(node)
        .into_iter()
        .find(|path| path.is_file())
    else {
        let expected_path =
            validator_onboarding_evidence_path(node, "epoch-validator-set-latest.json");
        return (
            evidence_gate(
                "epoch-validator-set",
                "blocked",
                "Missing latest EpochValidatorSet snapshot. Activation cannot use VPN/config/peer state as membership authority.",
                Some(expected_path),
                Some("sync_latest_epoch_validator_set"),
            ),
            None,
        );
    };

    let Ok(document) = read_json_value(&path) else {
        return (
            evidence_gate(
                "epoch-validator-set",
                "failed",
                "EpochValidatorSet evidence exists but cannot be parsed.",
                Some(path),
                Some("sync_latest_epoch_validator_set"),
            ),
            None,
        );
    };
    let snapshot = select_epoch_validator_set_snapshot(&document);
    if !snapshot.is_object() {
        return (
            evidence_gate(
                "epoch-validator-set",
                "failed",
                "EpochValidatorSet evidence does not contain an object snapshot.",
                Some(path),
                Some("sync_latest_epoch_validator_set"),
            ),
            None,
        );
    }

    let source_majority_verified = json_truthy(
        &document,
        &["source_majority_verified", "sourceMajorityVerified"],
    ) || json_truthy(
        &snapshot,
        &["source_majority_verified", "sourceMajorityVerified"],
    );
    let sources = document
        .get("sources")
        .or_else(|| snapshot.get("sources"))
        .and_then(Value::as_array);
    let local_source_verified = sources.is_some_and(|entries| {
        entries
            .iter()
            .any(|entry| entry.get("role").and_then(Value::as_str) == Some("local_validator"))
    });
    let network_source_verified = sources.is_some_and(|entries| {
        let https_core = entries.iter().any(|entry| {
            entry.get("public_rpc").and_then(Value::as_bool) == Some(true)
                && entry
                    .get("endpoint")
                    .and_then(Value::as_str)
                    .is_some_and(|endpoint| endpoint.starts_with("https://"))
        });
        let relayer_count = entries
            .iter()
            .filter(|entry| entry.get("role").and_then(Value::as_str) == Some("relayer"))
            .count();
        https_core || relayer_count >= 2
    });
    if !source_majority_verified || !local_source_verified || !network_source_verified {
        return (
            evidence_gate(
                "epoch-validator-set",
                "failed",
                "EpochValidatorSet evidence is not corroborated by the local validator and an independent network authority.",
                Some(path),
                Some("sync_latest_epoch_validator_set"),
            ),
            None,
        );
    }

    let freshness_subject = if evidence_generated_at_utc(&document).is_some() {
        &document
    } else {
        &snapshot
    };
    if let Some(detail) = onboarding_evidence_freshness_failure(
        freshness_subject,
        TESTNET_VALIDATOR_SET_SNAPSHOT_MAX_AGE_SECS,
        "EpochValidatorSet snapshot",
    ) {
        return (
            evidence_gate(
                "epoch-validator-set",
                "blocked",
                &detail,
                Some(path),
                Some("sync_latest_epoch_validator_set"),
            ),
            None,
        );
    }

    let chain_id = json_u64_at(&snapshot, &["chain_id", "chainId"]);
    if chain_id != Some(TESTNET_CHAIN_ID) {
        return (
            evidence_gate(
                "epoch-validator-set",
                "failed",
                &format!(
                    "EpochValidatorSet chain_id mismatch: actual={}, expected={}.",
                    chain_id
                        .map(|value| value.to_string())
                        .unwrap_or_else(|| "missing".to_string()),
                    TESTNET_CHAIN_ID
                ),
                Some(path),
                Some("sync_latest_epoch_validator_set"),
            ),
            None,
        );
    }

    let snapshot_format_version = json_u64_at(
        &snapshot,
        &["snapshot_format_version", "snapshotFormatVersion"],
    );
    if snapshot_format_version != Some(TESTNET_VALIDATOR_SET_SNAPSHOT_FORMAT_VERSION) {
        return (
            evidence_gate(
                "epoch-validator-set",
                "failed",
                &format!(
                    "EpochValidatorSet snapshot format version is incompatible: actual={}, expected={}.",
                    snapshot_format_version
                        .map(|value| value.to_string())
                        .unwrap_or_else(|| "missing".to_string()),
                    TESTNET_VALIDATOR_SET_SNAPSHOT_FORMAT_VERSION
                ),
                Some(path),
                Some("upgrade_validator_binary_or_snapshot_format"),
            ),
            None,
        );
    }

    let protocol_version = json_string_at(
        &snapshot,
        &[
            "protocol_version",
            "protocolVersion",
            "required_protocol_version",
            "requiredProtocolVersion",
            "consensus_protocol_version",
            "consensusProtocolVersion",
        ],
    );
    if protocol_version.as_deref() != Some(TESTNET_VALIDATOR_PROTOCOL_VERSION) {
        return (
            evidence_gate(
                "epoch-validator-set",
                "failed",
                &format!(
                    "EpochValidatorSet protocol version is incompatible: actual={}, expected={}.",
                    protocol_version.as_deref().unwrap_or("missing"),
                    TESTNET_VALIDATOR_PROTOCOL_VERSION
                ),
                Some(path),
                Some("upgrade_validator_binary_or_protocol"),
            ),
            None,
        );
    }
    let binary_version = json_string_at(
        &snapshot,
        &[
            "binary_version",
            "binaryVersion",
            "runtime_version",
            "runtimeVersion",
            "required_binary_version",
            "requiredBinaryVersion",
        ],
    );
    if binary_version.as_deref() != Some(env!("CARGO_PKG_VERSION")) {
        return (
            evidence_gate(
                "epoch-validator-set",
                "failed",
                &format!(
                    "EpochValidatorSet runtime version is incompatible: actual={}, expected={}.",
                    binary_version.as_deref().unwrap_or("missing"),
                    env!("CARGO_PKG_VERSION")
                ),
                Some(path),
                Some("upgrade_validator_binary_or_control_panel"),
            ),
            None,
        );
    }

    if json_bool_at(&snapshot, &["is_latest", "isLatest", "latest"]) == Some(false) {
        return (
            evidence_gate(
                "epoch-validator-set",
                "blocked",
                "EpochValidatorSet evidence is explicitly marked non-latest.",
                Some(path),
                Some("sync_latest_epoch_validator_set"),
            ),
            None,
        );
    }

    let validator_set_hash = json_string_at(
        &snapshot,
        &[
            "validator_set_hash",
            "validatorSetHash",
            "set_hash",
            "setHash",
        ],
    );
    let Some(validator_set_hash_value) = validator_set_hash.clone() else {
        return (
            evidence_gate(
                "epoch-validator-set",
                "failed",
                "EpochValidatorSet is missing validator_set_hash.",
                Some(path),
                Some("sync_latest_epoch_validator_set"),
            ),
            None,
        );
    };
    let local_validator_set_hash = json_string_at(
        &snapshot,
        &[
            "local_validator_set_hash",
            "localValidatorSetHash",
            "local_set_hash",
            "localSetHash",
        ],
    )
    .or_else(|| Some(validator_set_hash_value.clone()));
    let network_validator_set_hash = json_string_at(
        &snapshot,
        &[
            "network_validator_set_hash",
            "networkValidatorSetHash",
            "expected_validator_set_hash",
            "expectedValidatorSetHash",
        ],
    )
    .or_else(|| Some(validator_set_hash_value.clone()));
    if local_validator_set_hash
        .as_deref()
        .zip(network_validator_set_hash.as_deref())
        .is_some_and(|(local, network)| !local.eq_ignore_ascii_case(network))
    {
        return (
            evidence_gate(
                "epoch-validator-set",
                "failed",
                "Local validator-set hash does not match the network validator-set hash.",
                Some(path),
                Some("sync_latest_epoch_validator_set"),
            ),
            None,
        );
    }

    let active_validators =
        validator_members_at(&snapshot, &["active_validators", "activeValidators"]);
    let pending_validators =
        validator_members_at(&snapshot, &["pending_validators", "pendingValidators"]);
    let syncing_validators =
        validator_members_at(&snapshot, &["syncing_validators", "syncingValidators"]);
    let eligible_validators =
        validator_members_at(&snapshot, &["eligible_validators", "eligibleValidators"]);
    let jailed_validators =
        validator_members_at(&snapshot, &["jailed_validators", "jailedValidators"]);
    let removed_validators =
        validator_members_at(&snapshot, &["removed_validators", "removedValidators"]);
    let cluster_membership =
        match validate_cluster_membership_snapshot(&snapshot, &active_validators) {
            Ok(cluster_membership) => cluster_membership,
            Err(error) => {
                return (
                    evidence_gate(
                        "epoch-validator-set",
                        "failed",
                        &format!("EpochValidatorSet cluster membership is invalid: {error}"),
                        Some(path),
                        Some("sync_latest_epoch_validator_set"),
                    ),
                    None,
                );
            }
        };
    let local_address = node.node_address.trim();
    let local_validator_status = if validator_set_contains(&active_validators, local_address) {
        "Active"
    } else if validator_set_contains(&eligible_validators, local_address) {
        "Eligible"
    } else if validator_set_contains(&syncing_validators, local_address) {
        "Syncing"
    } else if validator_set_contains(&pending_validators, local_address) {
        "Pending"
    } else if validator_set_contains(&jailed_validators, local_address) {
        "Jailed"
    } else if validator_set_contains(&removed_validators, local_address) {
        "Removed"
    } else {
        "Unknown"
    }
    .to_string();

    let summary = ValidatorSetSnapshotSummary {
        epoch_id: json_u64_at(&snapshot, &["epoch_id", "epochId", "epoch"]),
        validator_set_version: json_u64_at(
            &snapshot,
            &["validator_set_version", "validatorSetVersion", "version"],
        ),
        effective_from_height: json_u64_at(
            &snapshot,
            &[
                "effective_from_height",
                "effectiveFromHeight",
                "effective_height",
                "effectiveHeight",
            ],
        ),
        effective_to_height: json_u64_at(&snapshot, &["effective_to_height", "effectiveToHeight"]),
        active_validators,
        pending_validators,
        jailed_validators,
        removed_validators,
        quorum_threshold: json_u64_at(&snapshot, &["quorum_threshold", "quorumThreshold"]),
        cluster_count: Some(cluster_membership.cluster_count),
        cluster_assignment_epoch: Some(cluster_membership.assignment_epoch),
        cluster_assignment_effective_height: Some(cluster_membership.assignment_effective_height),
        cluster_randomness_source: Some(cluster_membership.randomness_source),
        cluster_map_hash: Some(cluster_membership.cluster_map_hash),
        membership_bundle_hash: Some(cluster_membership.membership_bundle_hash),
        cluster_assignments: cluster_membership.assignments,
        local_validator_status: local_validator_status.clone(),
        local_validator_set_hash,
        network_validator_set_hash,
        validator_set_hash,
        protocol_version,
        binary_version,
        snapshot_format_version,
        evidence_path: path.to_string_lossy().to_string(),
    };

    if summary.epoch_id.is_none()
        || summary.validator_set_version.is_none()
        || summary.effective_from_height.is_none()
        || summary.quorum_threshold.is_none()
    {
        return (
            evidence_gate(
                "epoch-validator-set",
                "failed",
                "EpochValidatorSet is missing epoch/version/effective height/quorum metadata.",
                Some(PathBuf::from(&summary.evidence_path)),
                Some("sync_latest_epoch_validator_set"),
            ),
            Some(summary),
        );
    }

    match local_validator_status.as_str() {
        "Jailed" => (
            evidence_gate(
                "epoch-validator-set",
                "failed",
                "Local validator is Jailed in the latest EpochValidatorSet and cannot activate.",
                Some(PathBuf::from(&summary.evidence_path)),
                Some("wait_for_unjail_epoch_validator_set"),
            ),
            Some(summary),
        ),
        "Removed" => (
            evidence_gate(
                "epoch-validator-set",
                "failed",
                "Local validator is Removed in the latest EpochValidatorSet and cannot activate.",
                Some(PathBuf::from(&summary.evidence_path)),
                Some("restart_validator_onboarding"),
            ),
            Some(summary),
        ),
        "Unknown" => (
            evidence_gate(
                "epoch-validator-set",
                "pass",
                "The current validator set is live and independently corroborated. This validator is not present yet, which is the expected state before its activation transaction is finalized.",
                Some(PathBuf::from(&summary.evidence_path)),
                None,
            ),
            Some(summary),
        ),
        _ => (
            evidence_gate(
                "epoch-validator-set",
                "pass",
                &format!(
                    "Latest EpochValidatorSet verified: epoch={}, version={}, local_status={}, quorum_threshold={}, hash={}.",
                    summary
                        .epoch_id
                        .map(|value| value.to_string())
                        .unwrap_or_else(|| "unknown".to_string()),
                    summary
                        .validator_set_version
                        .map(|value| value.to_string())
                        .unwrap_or_else(|| "unknown".to_string()),
                    summary.local_validator_status,
                    summary
                        .quorum_threshold
                        .map(|value| value.to_string())
                        .unwrap_or_else(|| "unknown".to_string()),
                    summary
                        .validator_set_hash
                        .as_deref()
                        .unwrap_or("unknown")
                ),
                Some(PathBuf::from(&summary.evidence_path)),
                None,
            ),
            Some(summary),
        ),
    }
}

fn epoch_boundary_activation_gate(
    node: &TestnetProvisionedNode,
) -> ValidatorOnboardingEvidenceGate {
    let candidates = [
        "validator-shadow-epoch-1-proof.json",
        "validator-onboarding-shadow-epoch-1.json",
        "shadow-epoch-1.json",
    ];
    let Some(path) = candidates
        .iter()
        .map(|file| validator_onboarding_evidence_path(node, file))
        .find(|path| path.is_file())
    else {
        return evidence_gate(
            "epoch-boundary",
            "blocked",
            "Activation must wait for a full shadow epoch and the next eligible epoch boundary.",
            Some(validator_onboarding_evidence_path(
                node,
                "validator-onboarding-shadow-epoch-1.json",
            )),
            Some("run_full_shadow_epoch"),
        );
    };
    let Ok(value) = read_json_value(&path) else {
        return evidence_gate(
            "epoch-boundary",
            "failed",
            "Shadow epoch evidence exists but cannot be parsed for the epoch-boundary gate.",
            Some(path),
            Some("regenerate_shadow_epoch_proof"),
        );
    };
    if let Some(detail) = onboarding_evidence_freshness_failure(
        &value,
        TESTNET_ONBOARDING_SHADOW_PROOF_MAX_AGE_SECS,
        "Shadow epoch proof",
    ) {
        return evidence_gate(
            "epoch-boundary",
            "blocked",
            &detail,
            Some(path),
            Some("continue_full_shadow_epoch"),
        );
    }
    let status = value.get("shadow_status").unwrap_or(&value);
    let completed = json_truthy(
        status,
        &["full_epoch_shadow_completed", "completed", "shadow_passed"],
    ) || status
        .get("computed_state")
        .or_else(|| status.get("state"))
        .or_else(|| status.get("status"))
        .and_then(Value::as_str)
        .map(|state| state.eq_ignore_ascii_case("SHADOW_PASSED"))
        .unwrap_or(false);
    if !completed {
        return evidence_gate(
            "epoch-boundary",
            "blocked",
            "Full shadow epoch is not complete, so the activation epoch boundary is not reachable.",
            Some(path),
            Some("continue_full_shadow_epoch"),
        );
    }

    let explicit_boundary_reached = json_truthy(
        status,
        &[
            "activation_epoch_boundary_reached",
            "epoch_boundary_reached",
            "eligible_epoch_boundary_reached",
        ],
    ) || json_truthy(
        &value,
        &[
            "activation_epoch_boundary_reached",
            "epoch_boundary_reached",
            "eligible_epoch_boundary_reached",
        ],
    );
    let end_height = json_u64_at(
        status,
        &[
            "required_full_shadow_epoch_end",
            "shadow_epoch_end",
            "epoch_end_height",
        ],
    )
    .or_else(|| {
        json_u64_at(
            &value,
            &[
                "required_full_shadow_epoch_end",
                "shadow_epoch_end",
                "epoch_end_height",
            ],
        )
    });
    let latest_height = json_u64_at(
        status,
        &[
            "latest_height",
            "current_height",
            "verified_height",
            "last_observed_height",
        ],
    )
    .or_else(|| {
        json_u64_at(
            &value,
            &[
                "latest_height",
                "current_height",
                "verified_height",
                "last_observed_height",
            ],
        )
    });
    let boundary_height = end_height.map(|height| height.saturating_add(1));
    if end_height.is_some_and(|height| !testnet_is_epoch_end_height(height)) {
        return evidence_gate(
            "epoch-boundary",
            "failed",
            "Shadow epoch evidence does not end at a canonical epoch boundary.",
            Some(path),
            Some("regenerate_shadow_epoch_proof"),
        );
    }
    let boundary_reached = explicit_boundary_reached
        || boundary_height
            .zip(latest_height)
            .is_some_and(|(boundary, latest)| latest >= boundary);
    if boundary_reached {
        evidence_gate(
            "epoch-boundary",
            "pass",
            &format!(
                "Activation epoch boundary reached: boundary_height={}, latest_height={}.",
                boundary_height
                    .map(|height| height.to_string())
                    .unwrap_or_else(|| "explicit".to_string()),
                latest_height
                    .map(|height| height.to_string())
                    .unwrap_or_else(|| "explicit".to_string())
            ),
            Some(path),
            None,
        )
    } else {
        evidence_gate(
            "epoch-boundary",
            "blocked",
            &format!(
                "Activation is waiting for the next eligible epoch boundary: boundary_height={}, latest_height={}.",
                boundary_height
                    .map(|height| height.to_string())
                    .unwrap_or_else(|| "unknown".to_string()),
                latest_height
                    .map(|height| height.to_string())
                    .unwrap_or_else(|| "unknown".to_string())
            ),
            Some(path),
            Some("wait_for_epoch_boundary"),
        )
    }
}

fn activation_confirmation_gate(node: &TestnetProvisionedNode) -> ValidatorOnboardingEvidenceGate {
    let path = validator_onboarding_evidence_path(node, "activation-confirmation.json");
    let Ok(contents) = fs::read_to_string(&path) else {
        return evidence_gate(
            "activation-confirmation",
            "pending",
            "Activation confirmation is required after submission before duty gates may open.",
            Some(path),
            Some("wait_for_registry_activation_confirmation"),
        );
    };
    let Ok(value) = serde_json::from_str::<Value>(&contents) else {
        return evidence_gate(
            "activation-confirmation",
            "failed",
            "Activation confirmation evidence is not valid JSON.",
            Some(path),
            Some("regenerate_activation_confirmation"),
        );
    };
    let active = value
        .get("canonical_status")
        .or_else(|| value.get("status"))
        .and_then(Value::as_str)
        .map(|status| status.eq_ignore_ascii_case("active") || status.eq_ignore_ascii_case("pass"))
        .unwrap_or(false);
    let address_matches = value
        .get("validator_address")
        .and_then(Value::as_str)
        .map(|address| address == node.node_address)
        .unwrap_or(false);

    if active && address_matches {
        if let Some(detail) = onboarding_evidence_freshness_failure(
            &value,
            TESTNET_ONBOARDING_ACTIVATION_CONFIRMATION_MAX_AGE_SECS,
            "Activation confirmation",
        ) {
            return evidence_gate(
                "activation-confirmation",
                "pending",
                &detail,
                Some(path),
                Some("wait_for_registry_activation_confirmation"),
            );
        }
        evidence_gate(
            "activation-confirmation",
            "pass",
            "Canonical validator registry confirms this validator is active.",
            Some(path),
            None,
        )
    } else {
        evidence_gate(
            "activation-confirmation",
            "pending",
            "Activation confirmation evidence exists, but it does not yet prove this validator active.",
            Some(path),
            Some("wait_for_registry_activation_confirmation"),
        )
    }
}

fn build_validator_onboarding_policy_evidence(
    node: &TestnetProvisionedNode,
) -> ValidatorOnboardingPolicyEvidence {
    let source_majority = source_majority_proof_gate(node);
    let shadow_epoch = shadow_epoch_proof_gate(node);
    let duty_gates = duty_gate_proof_gate(node);
    let validator_vpn = validator_vpn_route_gate(node);
    let (epoch_validator_set, validator_set_snapshot) = epoch_validator_set_gate(node);
    let epoch_boundary = epoch_boundary_activation_gate(node);
    let activation_confirmation = activation_confirmation_gate(node);
    let activation_allowed = source_majority.status == "pass"
        && shadow_epoch.status == "pass"
        && duty_gates.status == "pass"
        && validator_vpn.status == "pass"
        && epoch_validator_set.status == "pass"
        && epoch_boundary.status == "pass";

    ValidatorOnboardingPolicyEvidence {
        activation_allowed,
        required_state_machine: validator_onboarding_required_state_machine(),
        source_majority,
        shadow_epoch,
        duty_gates,
        validator_vpn,
        epoch_validator_set,
        epoch_boundary,
        activation_confirmation,
        validator_set_snapshot,
    }
}

fn validator_activation_policy_error(policy: &ValidatorOnboardingPolicyEvidence) -> Option<String> {
    if policy.activation_allowed {
        return None;
    }
    let next_action = policy
        .source_majority
        .next_action
        .clone()
        .or_else(|| policy.shadow_epoch.next_action.clone())
        .or_else(|| policy.duty_gates.next_action.clone())
        .or_else(|| policy.validator_vpn.next_action.clone())
        .or_else(|| policy.epoch_validator_set.next_action.clone())
        .or_else(|| policy.epoch_boundary.next_action.clone())
        .unwrap_or_else(|| "prove_activation_evidence".to_string());
    Some(format!(
        "Validator activation is blocked until source-majority, full shadow epoch, duty-gate, validator VPN route, latest EpochValidatorSet, and epoch-boundary evidence all pass. source_majority={}; shadow_epoch={}; duty_gates={}; validator_vpn={}; epoch_validator_set={}; epoch_boundary={}; next_action={next_action}",
        policy.source_majority.detail,
        policy.shadow_epoch.detail,
        policy.duty_gates.detail,
        policy.validator_vpn.detail,
        policy.epoch_validator_set.detail,
        policy.epoch_boundary.detail
    ))
}

#[derive(Debug, Clone)]
struct OnboardingRpcSource {
    label: String,
    role: String,
    endpoint: String,
    public_rpc: bool,
}

#[derive(Debug, Clone)]
struct OnboardingBlockSummary {
    height: u64,
    hash: String,
}

#[derive(Debug)]
struct ShadowHeightVerification {
    height: u64,
    observed: bool,
    mismatch: bool,
    missed: bool,
    sample: Option<Value>,
}

fn onboarding_rpc_sources(
    node: &TestnetProvisionedNode,
) -> Result<Vec<OnboardingRpcSource>, String> {
    Ok(vec![
        OnboardingRpcSource {
            label: "local-validator".to_string(),
            role: "local_validator".to_string(),
            endpoint: rpc_endpoint_for_workspace(node)?,
            public_rpc: false,
        },
        OnboardingRpcSource {
            label: "relayer-1".to_string(),
            role: "relayer".to_string(),
            endpoint: "http://10.70.20.1:5640".to_string(),
            public_rpc: false,
        },
        OnboardingRpcSource {
            label: "relayer-2".to_string(),
            role: "relayer".to_string(),
            endpoint: "http://10.70.20.2:5640".to_string(),
            public_rpc: false,
        },
        OnboardingRpcSource {
            label: "relayer-3".to_string(),
            role: "relayer".to_string(),
            endpoint: "http://10.70.20.3:5640".to_string(),
            public_rpc: false,
        },
        OnboardingRpcSource {
            label: "public-core-rpc".to_string(),
            role: "public_rpc_diagnostic".to_string(),
            endpoint: TESTNET_PUBLIC_RPC_ENDPOINT.to_string(),
            public_rpc: true,
        },
    ])
}

fn read_existing_activation_tx_hash(node: &TestnetProvisionedNode) -> Option<String> {
    let contents = fs::read_to_string(validator_onboarding_state_path(node)).ok()?;
    let value = serde_json::from_str::<Value>(&contents).ok()?;
    value
        .get("activation")
        .and_then(|activation| {
            activation
                .get("tx_hash")
                .or_else(|| activation.get("txHash"))
        })
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|tx_hash| !tx_hash.is_empty())
        .map(str::to_string)
}

fn activation_transaction_known(status: &Value) -> bool {
    status.get("found").and_then(Value::as_bool) == Some(true)
        || status
            .get("status")
            .and_then(Value::as_str)
            .map(|status| {
                matches!(
                    status.to_ascii_lowercase().as_str(),
                    "pending" | "queued" | "confirmed" | "committed" | "included"
                )
            })
            .unwrap_or(false)
}

fn activation_transaction_committed(status: &Value) -> bool {
    status
        .get("dag")
        .and_then(|dag| dag.get("found"))
        .and_then(Value::as_bool)
        == Some(true)
        || status
            .get("transaction")
            .and_then(|tx| tx.get("block_number").or_else(|| tx.get("blockNumber")))
            .and_then(Value::as_u64)
            .is_some()
        || status
            .get("status")
            .and_then(Value::as_str)
            .map(|status| {
                matches!(
                    status.to_ascii_lowercase().as_str(),
                    "confirmed" | "committed" | "included"
                )
            })
            .unwrap_or(false)
}

fn activation_transaction_public_key_bytes(transaction: &Value) -> Option<Vec<u8>> {
    let payload = transaction
        .get("data")
        .and_then(Value::as_str)?
        .strip_prefix("validator_activation:")?;
    let payload = serde_json::from_str::<Value>(payload).ok()?;
    let public_key = payload.get("public_key").and_then(Value::as_str)?;
    general_purpose::STANDARD.decode(public_key).ok()
}

fn hydrate_activation_transaction_payload(mut transaction: Value) -> Option<Value> {
    let signer_public_key_hex = if transaction
        .get("signerPublicKey")
        .or_else(|| transaction.get("signer_public_key"))
        .is_some()
    {
        None
    } else {
        Some(encode_hex_bytes(&activation_transaction_public_key_bytes(
            &transaction,
        )?))
    };

    if transaction
        .get("signer_public_key")
        .or_else(|| transaction.get("signerPublicKey"))
        .is_none()
    {
        if let Some(object) = transaction.as_object_mut() {
            let signer_public_key = signer_public_key_hex.as_deref()?;
            object.insert("signerPublicKey".to_string(), json!(signer_public_key));
            object.insert("signer_public_key".to_string(), json!(signer_public_key));
        } else {
            return None;
        }
    }

    if let Some(object) = transaction.as_object_mut() {
        if !object.contains_key("chainId") {
            if let Some(value) = object.get("chain_id").cloned() {
                object.insert("chainId".to_string(), value);
            }
        }
        if !object.contains_key("networkId") {
            if let Some(value) = object.get("network_id").cloned() {
                object.insert("networkId".to_string(), value);
            }
        }
        if !object.contains_key("gasPrice") {
            if let Some(value) = object.get("gas_price").cloned() {
                object.insert("gasPrice".to_string(), value);
            }
        }
        if !object.contains_key("gasLimit") {
            if let Some(value) = object.get("gas_limit").cloned() {
                object.insert("gasLimit".to_string(), value);
            }
        }
        if !object.contains_key("signatureAlgorithm") {
            if let Some(value) = object.get("signature_algorithm").cloned() {
                object.insert("signatureAlgorithm".to_string(), value);
            }
        }
        if !object.contains_key("value") {
            if let Some(value) = object.get("amount").cloned() {
                object.insert("value".to_string(), value);
            }
        }
    } else {
        return None;
    }

    Some(transaction)
}

fn activation_transaction_payload_from_status(source_status: &Value) -> Option<Value> {
    source_status
        .get("response")
        .and_then(|response| response.get("transaction"))
        .cloned()
        .and_then(hydrate_activation_transaction_payload)
}

async fn query_activation_transaction_status(
    client: &Client,
    source: &OnboardingRpcSource,
    tx_hash: &str,
) -> Value {
    match query_rpc_value(
        client,
        &source.endpoint,
        "synergy_getTransactionStatus",
        json!([tx_hash]),
    )
    .await
    {
        Ok(value) => json!({
            "label": source.label,
            "role": source.role,
            "endpoint": source.endpoint,
            "public_rpc": source.public_rpc,
            "ok": true,
            "found": activation_transaction_known(&value),
            "committed": activation_transaction_committed(&value),
            "status": value.get("status").cloned().unwrap_or_else(|| json!("unknown")),
            "response": value,
        }),
        Err(error) => json!({
            "label": source.label,
            "role": source.role,
            "endpoint": source.endpoint,
            "public_rpc": source.public_rpc,
            "ok": false,
            "found": false,
            "committed": false,
            "status": "rpc_error",
            "error": error,
        }),
    }
}

async fn rebroadcast_activation_transaction_to_source(
    client: &Client,
    source: &OnboardingRpcSource,
    transaction: &Value,
) -> Value {
    match query_rpc_value(
        client,
        &source.endpoint,
        "synergy_sendTransaction",
        json!([transaction]),
    )
    .await
    {
        Ok(value) => {
            let accepted = value
                .get("success")
                .and_then(Value::as_bool)
                .unwrap_or(false)
                || value
                    .get("mempool_status")
                    .and_then(Value::as_str)
                    .map(|status| status.eq_ignore_ascii_case("queued"))
                    .unwrap_or(false);
            json!({
                "label": source.label,
                "role": source.role,
                "endpoint": source.endpoint,
                "ok": accepted,
                "response": value,
            })
        }
        Err(error) => json!({
            "label": source.label,
            "role": source.role,
            "endpoint": source.endpoint,
            "ok": false,
            "error": error,
        }),
    }
}

async fn ensure_activation_transaction_propagated(
    client: &Client,
    node: &TestnetProvisionedNode,
    tx_hash: &str,
    submitted_transaction: Option<Value>,
) -> Result<Value, String> {
    let sources = onboarding_rpc_sources(node)?;
    let before = join_all(
        sources
            .iter()
            .map(|source| query_activation_transaction_status(client, source, tx_hash)),
    )
    .await;
    let trusted_found_before = before.iter().any(|status| {
        status.get("role").and_then(Value::as_str) != Some("local_validator")
            && status.get("found").and_then(Value::as_bool) == Some(true)
    });
    let committed_before = before
        .iter()
        .any(|status| status.get("committed").and_then(Value::as_bool) == Some(true));

    let mut rebroadcasts = Vec::new();
    let mut payload_source = "none";
    let mut transaction_payload =
        submitted_transaction.and_then(hydrate_activation_transaction_payload);
    if transaction_payload.is_some() {
        payload_source = "activation_submit_response";
    }
    if transaction_payload.is_none() {
        transaction_payload = before
            .iter()
            .find_map(activation_transaction_payload_from_status);
        if transaction_payload.is_some() {
            payload_source = "local_transaction_status";
        }
    }

    if !trusted_found_before && !committed_before {
        if let Some(transaction) = transaction_payload.as_ref() {
            for source in sources.iter().filter(|source| source.public_rpc) {
                rebroadcasts.push(
                    rebroadcast_activation_transaction_to_source(client, source, transaction).await,
                );
            }
        }
    }

    let after = join_all(
        sources
            .iter()
            .map(|source| query_activation_transaction_status(client, source, tx_hash)),
    )
    .await;
    let trusted_found_after = after.iter().any(|status| {
        status.get("role").and_then(Value::as_str) != Some("local_validator")
            && status.get("found").and_then(Value::as_bool) == Some(true)
    });
    let local_found_after = after.iter().any(|status| {
        status.get("role").and_then(Value::as_str) == Some("local_validator")
            && status.get("found").and_then(Value::as_bool) == Some(true)
    });
    let committed_after = after
        .iter()
        .any(|status| status.get("committed").and_then(Value::as_bool) == Some(true));
    let accepted_rebroadcasts = rebroadcasts
        .iter()
        .filter(|result| result.get("ok").and_then(Value::as_bool) == Some(true))
        .count();
    let status = if committed_after {
        "committed"
    } else if trusted_found_after || accepted_rebroadcasts > 0 {
        "propagated"
    } else if local_found_after {
        "local_only_pending"
    } else {
        "not_found"
    };
    let detail = match status {
        "committed" => "Activation transaction is committed in canonical transaction status.",
        "propagated" => "Activation transaction is visible outside the local validator.",
        "local_only_pending" => {
            if transaction_payload.is_some() {
                "Activation transaction is still only visible in the local validator pool after rebroadcast attempts."
            } else {
                "Activation transaction is only visible locally and Jarvis could not reconstruct a signed transaction payload for rebroadcast."
            }
        }
        _ => "Activation transaction is not visible on local or trusted RPC sources.",
    };
    let proof = json!({
        "status": status,
        "detail": detail,
        "tx_hash": tx_hash,
        "node_id": node.id,
        "validator_address": node.node_address,
        "trusted_found_before": trusted_found_before,
        "trusted_found_after": trusted_found_after,
        "local_found_after": local_found_after,
        "committed_after": committed_after,
        "payload_source": payload_source,
        "rebroadcast_attempted": !rebroadcasts.is_empty(),
        "accepted_rebroadcasts": accepted_rebroadcasts,
        "sources_before": before,
        "rebroadcasts": rebroadcasts,
        "sources_after": after,
        "generated_at_utc": Utc::now().to_rfc3339(),
    });
    write_json_file(
        &validator_onboarding_evidence_path(node, "activation-transaction-propagation.json"),
        &proof,
    )?;
    Ok(proof)
}

async fn query_rpc_latest_block_summary(
    client: &Client,
    source: &OnboardingRpcSource,
) -> Result<OnboardingBlockSummary, String> {
    let value = query_rpc_value(
        client,
        &source.endpoint,
        "synergy_getLatestBlock",
        json!([]),
    )
    .await?;
    let height = parse_rpc_block_height(value.clone())?;
    let hash = block_hash_from_value(&value)
        .ok_or_else(|| format!("{} latest block did not include a hash", source.label))?;
    Ok(OnboardingBlockSummary { height, hash })
}

async fn query_rpc_block_summary(
    client: &Client,
    source: &OnboardingRpcSource,
    height: u64,
) -> Result<OnboardingBlockSummary, String> {
    let value = query_rpc_value(
        client,
        &source.endpoint,
        "synergy_getBlockByNumber",
        json!([height]),
    )
    .await?;
    if value.is_null() {
        return Err(format!(
            "{} returned no block at height {height}",
            source.label
        ));
    }
    let block_height = parse_rpc_block_height(value.clone())?;
    if block_height != height {
        return Err(format!(
            "{} returned height {block_height} for requested height {height}",
            source.label
        ));
    }
    let hash = block_hash_from_value(&value)
        .ok_or_else(|| format!("{} block {height} did not include a hash", source.label))?;
    Ok(OnboardingBlockSummary { height, hash })
}

async fn write_source_majority_head_match_proof(
    node: &TestnetProvisionedNode,
) -> Result<Value, String> {
    let client = Client::builder()
        .timeout(Duration::from_secs(8))
        .build()
        .map_err(|error| format!("HTTP client error: {error}"))?;
    let sources = onboarding_rpc_sources(node)?;
    let mut latest_records = Vec::new();
    let mut usable_latest = Vec::<(OnboardingRpcSource, OnboardingBlockSummary)>::new();

    for source in sources {
        match query_rpc_latest_block_summary(&client, &source).await {
            Ok(summary) => {
                if !source.public_rpc {
                    usable_latest.push((source.clone(), summary.clone()));
                }
                latest_records.push(json!({
                    "label": source.label,
                    "role": source.role,
                    "endpoint": source.endpoint,
                    "public_rpc": source.public_rpc,
                    "status": "ok",
                    "height": summary.height,
                    "hash": summary.hash,
                }));
            }
            Err(error) => latest_records.push(json!({
                "label": source.label,
                "role": source.role,
                "endpoint": source.endpoint,
                "public_rpc": source.public_rpc,
                "status": "error",
                "error": error,
            })),
        }
    }

    let fixed_height = usable_latest
        .iter()
        .map(|(_, summary)| summary.height)
        .min()
        .unwrap_or(0);
    let mut block_records = Vec::new();
    let mut hash_counts = HashMap::<String, usize>::new();
    let mut local_hash = None::<String>;

    if usable_latest.len() >= 3 && fixed_height > 0 {
        for (source, _) in &usable_latest {
            match query_rpc_block_summary(&client, source, fixed_height).await {
                Ok(summary) => {
                    if source.label == "local-validator" {
                        local_hash = Some(summary.hash.clone());
                    }
                    *hash_counts.entry(summary.hash.clone()).or_insert(0) += 1;
                    block_records.push(json!({
                        "label": source.label,
                        "role": source.role,
                        "endpoint": source.endpoint,
                        "public_rpc": source.public_rpc,
                        "status": "ok",
                        "height": summary.height,
                        "hash": summary.hash,
                    }));
                }
                Err(error) => block_records.push(json!({
                    "label": source.label,
                    "role": source.role,
                    "endpoint": source.endpoint,
                    "public_rpc": source.public_rpc,
                    "status": "error",
                    "height": fixed_height,
                    "error": error,
                })),
            }
        }
    }

    let (majority_hash, majority_count) = hash_counts
        .iter()
        .max_by_key(|(_, count)| *count)
        .map(|(hash, count)| (Some(hash.clone()), *count))
        .unwrap_or((None, 0));
    let source_majority_verified =
        majority_count >= 3 && majority_hash.as_ref() == local_hash.as_ref();
    let evidence = json!({
        "proof_mode": "trusted_local_plus_relayers",
        "source_majority_verified": source_majority_verified,
        "fixed_height_hash_agreement": source_majority_verified,
        "head_matched": source_majority_verified,
        "common_height": if fixed_height > 0 { json!(fixed_height) } else { Value::Null },
        "common_hash": majority_hash,
        "local_hash": local_hash,
        "source_count": usable_latest.len(),
        "majority_count": majority_count,
        "required_source_count": 3,
        "sources": latest_records,
        "fixed_height_sources": block_records,
        "generated_at_utc": Utc::now().to_rfc3339(),
    });
    write_json_file(
        &validator_onboarding_evidence_path(node, "source-majority-proof.json"),
        &evidence,
    )?;
    Ok(evidence)
}

fn node_config_auto_register_disabled(node: &TestnetProvisionedNode) -> Result<bool, String> {
    let config_path = PathBuf::from(&node.workspace_directory)
        .join("config")
        .join("node.toml");
    let config = read_toml_value(&config_path)?;
    Ok(config
        .get("node")
        .and_then(|section| section.get("auto_register_validator"))
        .and_then(toml::Value::as_bool)
        == Some(false))
}

async fn write_onboarding_duty_gate_proof(node: &TestnetProvisionedNode) -> Result<Value, String> {
    let auto_register_disabled = node_config_auto_register_disabled(node)?;
    let consensus_active = validator_consensus_active(node).await;
    let duties_closed = auto_register_disabled && !consensus_active;
    let open = !duties_closed;
    let evidence = json!({
        "node_id": node.id,
        "validator_address": node.node_address,
        "auto_register_validator_disabled": auto_register_disabled,
        "consensus_active": consensus_active,
        "duties_closed": duties_closed,
        "duty_gate": {
            "state": if duties_closed { "ONBOARDING_DUTIES_CLOSED" } else { "DUTIES_NOT_PROVEN_CLOSED" },
            "can_vote": open,
            "can_propose": open,
            "can_aggregate_qc": open,
            "can_count_toward_quorum": open,
            "can_enter_proposer_schedule": open,
            "can_serve_as_canonical_source": open,
            "shadow_signs_real_votes": false
        },
        "generated_at_utc": Utc::now().to_rfc3339(),
    });
    write_json_file(
        &validator_onboarding_evidence_path(node, "duty-gate-proof-before.json"),
        &evidence,
    )?;
    Ok(evidence)
}

fn next_onboarding_shadow_epoch_start(height: u64) -> u64 {
    let first_observed_height = height.saturating_add(1);
    let first_observed_epoch = testnet_epoch_for_block_height(first_observed_height);
    if testnet_is_epoch_start_height(first_observed_height) {
        first_observed_height
    } else {
        testnet_epoch_start_height(first_observed_epoch.saturating_add(1))
    }
}

fn new_onboarding_shadow_state(
    node: &TestnetProvisionedNode,
    latest: &OnboardingBlockSummary,
) -> Value {
    let required_full_shadow_epoch_start = next_onboarding_shadow_epoch_start(latest.height);
    let required_full_shadow_epoch_end = testnet_epoch_end_height(testnet_epoch_for_block_height(
        required_full_shadow_epoch_start,
    ));
    json!({
        "status": "started",
        "node_id": node.id,
        "validator_address": node.node_address,
        "start_height": latest.height,
        "start_hash": latest.hash,
        "required_full_shadow_epoch_start": required_full_shadow_epoch_start,
        "required_full_shadow_epoch_end": required_full_shadow_epoch_end,
        "epoch_length": TESTNET_EPOCH_LENGTH,
        "started_at_utc": Utc::now().to_rfc3339(),
    })
}

fn unfinished_shadow_state_is_stale(state: &Value, latest_height: u64) -> bool {
    let status_passed = state
        .get("status")
        .and_then(Value::as_str)
        .map(|status| matches!(status, "pass" | "passed" | "complete" | "completed"))
        .unwrap_or(false);
    if status_passed {
        return false;
    }
    let Some(end) = state
        .get("required_full_shadow_epoch_end")
        .and_then(Value::as_u64)
    else {
        return false;
    };
    latest_height > end.saturating_add(TESTNET_EPOCH_LENGTH as u64)
}

async fn verify_shadow_epoch_range(
    client: &Client,
    node: &TestnetProvisionedNode,
    start_height: u64,
    end_height: u64,
) -> Result<(u64, u64, u64, Vec<Value>), String> {
    let sources = onboarding_rpc_sources(node)?
        .into_iter()
        .filter(|source| !source.public_rpc)
        .collect::<Vec<_>>();
    let mut observed = 0_u64;
    let mut mismatches = 0_u64;
    let mut missed = 0_u64;
    let mut samples = Vec::new();

    let heights = (start_height..=end_height).collect::<Vec<_>>();
    for chunk in heights.chunks(TESTNET_ONBOARDING_SHADOW_VERIFY_BATCH_SIZE) {
        let results = join_all(
            chunk
                .iter()
                .map(|height| verify_shadow_epoch_height(client, &sources, *height)),
        )
        .await;

        let mut last_verified_height = start_height;
        for result in results {
            last_verified_height = result.height;
            if result.observed {
                observed = observed.saturating_add(1);
            }
            if result.mismatch {
                mismatches = mismatches.saturating_add(1);
            }
            if result.missed {
                missed = missed.saturating_add(1);
            }
            if let Some(sample) = result.sample {
                if samples.len() < 10
                    || result.height == start_height
                    || result.height == end_height
                    || result.height % 100 == 0
                {
                    samples.push(sample);
                }
            }
        }

        write_shadow_epoch_progress_proof(
            node,
            start_height,
            end_height,
            last_verified_height,
            observed,
            mismatches,
            missed,
            &samples,
        )?;
    }

    Ok((observed, mismatches, missed, samples))
}

async fn verify_shadow_epoch_height(
    client: &Client,
    sources: &[OnboardingRpcSource],
    height: u64,
) -> ShadowHeightVerification {
    let query_results = join_all(sources.iter().map(|source| async move {
        (
            source.clone(),
            query_shadow_rpc_block_summary(client, source, height).await,
        )
    }))
    .await;

    evaluate_shadow_epoch_height(height, query_results)
}

async fn query_shadow_rpc_block_summary(
    client: &Client,
    source: &OnboardingRpcSource,
    height: u64,
) -> Result<OnboardingBlockSummary, String> {
    let mut last_error = None;
    for attempt in 1..=TESTNET_ONBOARDING_SHADOW_RPC_ATTEMPTS {
        match query_rpc_block_summary(client, source, height).await {
            Ok(summary) => return Ok(summary),
            Err(error) => last_error = Some(error),
        }
        if attempt < TESTNET_ONBOARDING_SHADOW_RPC_ATTEMPTS {
            tokio::time::sleep(Duration::from_millis(
                TESTNET_ONBOARDING_SHADOW_RPC_RETRY_DELAY_MS,
            ))
            .await;
        }
    }
    Err(last_error.unwrap_or_else(|| {
        format!(
            "{} block {height} query failed without an RPC error",
            source.label
        )
    }))
}

fn evaluate_shadow_epoch_height(
    height: u64,
    query_results: Vec<(OnboardingRpcSource, Result<OnboardingBlockSummary, String>)>,
) -> ShadowHeightVerification {
    let mut records = Vec::<(OnboardingRpcSource, OnboardingBlockSummary)>::new();
    let mut errors = Vec::<Value>::new();
    for (source, result) in query_results {
        match result {
            Ok(summary) => records.push((source, summary)),
            Err(error) => errors.push(json!({
                "label": source.label,
                "endpoint": source.endpoint,
                "height": height,
                "error": error,
            })),
        }
    }

    let Some((_, local)) = records
        .iter()
        .find(|(source, _)| source.label == "local-validator")
    else {
        return ShadowHeightVerification {
            height,
            observed: false,
            mismatch: false,
            missed: true,
            sample: Some(json!({
                "height": height,
                "local_hash": Value::Null,
                "errors": errors,
                "missed_reason": "local_validator_block_missing",
            })),
        };
    };

    let responding_relayers = records
        .iter()
        .filter(|(source, _)| source.role == "relayer")
        .count();
    let mismatch_sources = records
        .iter()
        .filter(|(source, summary)| source.label != "local-validator" && summary.hash != local.hash)
        .map(|(source, summary)| {
            json!({
                "label": source.label,
                "endpoint": source.endpoint,
                "hash": summary.hash,
            })
        })
        .collect::<Vec<_>>();
    let mismatch = !mismatch_sources.is_empty();

    if responding_relayers < 2 {
        return ShadowHeightVerification {
            height,
            observed: false,
            mismatch,
            missed: true,
            sample: Some(json!({
                "height": height,
                "local_hash": local.hash,
                "responding_relayers": responding_relayers,
                "required_relayers": 2,
                "mismatch_sources": mismatch_sources,
                "errors": errors,
                "missed_reason": "insufficient_relayer_sources",
            })),
        };
    }

    ShadowHeightVerification {
        height,
        observed: true,
        mismatch,
        missed: false,
        sample: Some(json!({
            "height": height,
            "local_hash": local.hash,
            "responding_relayers": responding_relayers,
            "mismatch_sources": mismatch_sources,
            "errors": errors,
        })),
    }
}

fn write_shadow_epoch_progress_proof(
    node: &TestnetProvisionedNode,
    start: u64,
    end: u64,
    latest_verified_height: u64,
    observed: u64,
    mismatches: u64,
    missed: u64,
    samples: &[Value],
) -> Result<(), String> {
    let proof = json!({
        "node_id": node.id,
        "validator_address": node.node_address,
        "shadow_status": {
            "computed_state": "SHADOW_VERIFYING",
            "full_epoch_shadow_completed": false,
            "shadow_passed": false,
            "observed_shadow_blocks": observed,
            "observed_count": observed,
            "mismatch_count": mismatches,
            "missed_observation_count": missed,
            "missed_block_count": missed,
            "required_full_shadow_epoch_start": start,
            "required_full_shadow_epoch_end": end,
            "latest_verified_height": latest_verified_height,
            "latest_height": latest_verified_height,
            "epoch_length": TESTNET_EPOCH_LENGTH,
            "shadow_signs_real_votes": false,
            "source_mode": "trusted_local_plus_relayers",
            "sample_records": samples,
        },
        "generated_at_utc": Utc::now().to_rfc3339(),
    });
    write_json_file(
        &validator_onboarding_evidence_path(node, "validator-onboarding-shadow-epoch-1.json"),
        &proof,
    )
}

async fn write_or_update_onboarding_shadow_epoch_proof(
    node: &TestnetProvisionedNode,
) -> Result<Value, String> {
    let client = Client::builder()
        .timeout(Duration::from_secs(8))
        .build()
        .map_err(|error| format!("HTTP client error: {error}"))?;
    let local_source = onboarding_rpc_sources(node)?
        .into_iter()
        .find(|source| source.label == "local-validator")
        .ok_or_else(|| "Missing local validator RPC source.".to_string())?;
    let latest = query_rpc_latest_block_summary(&client, &local_source).await?;
    let state_path = validator_onboarding_shadow_state_path(node);
    let mut state =
        read_json_value(&state_path).unwrap_or_else(|_| new_onboarding_shadow_state(node, &latest));
    if unfinished_shadow_state_is_stale(&state, latest.height) {
        let previous_start = state
            .get("required_full_shadow_epoch_start")
            .and_then(Value::as_u64);
        let previous_end = state
            .get("required_full_shadow_epoch_end")
            .and_then(Value::as_u64);
        state = new_onboarding_shadow_state(node, &latest);
        if let Some(object) = state.as_object_mut() {
            object.insert("reset_reason".to_string(), json!("stale_unfinished_window"));
            object.insert("previous_shadow_start".to_string(), json!(previous_start));
            object.insert("previous_shadow_end".to_string(), json!(previous_end));
        }
    }

    let start = state
        .get("required_full_shadow_epoch_start")
        .and_then(Value::as_u64)
        .unwrap_or_else(|| next_onboarding_shadow_epoch_start(latest.height));
    let end = state
        .get("required_full_shadow_epoch_end")
        .and_then(Value::as_u64)
        .unwrap_or_else(|| start.saturating_add(TESTNET_EPOCH_LENGTH as u64 - 1));
    let observed_so_far = if latest.height >= start {
        latest
            .height
            .min(end)
            .saturating_sub(start)
            .saturating_add(1)
    } else {
        0
    };

    let (completed, observed, mismatches, missed, samples) = if latest.height >= end {
        let (observed, mismatches, missed, samples) =
            verify_shadow_epoch_range(&client, node, start, end).await?;
        (
            mismatches == 0 && missed == 0 && observed >= TESTNET_EPOCH_LENGTH as u64,
            observed,
            mismatches,
            missed,
            samples,
        )
    } else {
        (false, observed_so_far, 0, 0, Vec::new())
    };

    if let Some(object) = state.as_object_mut() {
        object.insert(
            "status".to_string(),
            json!(if completed { "pass" } else { "observing" }),
        );
        object.insert("latest_height".to_string(), json!(latest.height));
        object.insert("latest_hash".to_string(), json!(latest.hash));
        object.insert("updated_at_utc".to_string(), json!(Utc::now().to_rfc3339()));
    }
    write_json_file(&state_path, &state)?;

    let proof = json!({
        "node_id": node.id,
        "validator_address": node.node_address,
        "shadow_status": {
            "computed_state": if completed { "SHADOW_PASSED" } else { "SHADOW_OBSERVING" },
            "full_epoch_shadow_completed": completed,
            "shadow_passed": completed,
            "observed_shadow_blocks": observed,
            "observed_count": observed,
            "mismatch_count": mismatches,
            "missed_observation_count": missed,
            "missed_block_count": missed,
            "required_full_shadow_epoch_start": start,
            "required_full_shadow_epoch_end": end,
            "latest_height": latest.height,
            "epoch_length": TESTNET_EPOCH_LENGTH,
            "shadow_signs_real_votes": false,
            "source_mode": "trusted_local_plus_relayers",
            "sample_records": samples,
        },
        "generated_at_utc": Utc::now().to_rfc3339(),
    });
    write_json_file(
        &validator_onboarding_evidence_path(node, "validator-onboarding-shadow-epoch-1.json"),
        &proof,
    )?;
    Ok(proof)
}

fn preflight_has_required_stake(preflight: &ValidatorActivationPreflightResult) -> bool {
    preflight.staked_balance_nwei.unwrap_or(0) >= preflight.required_stake_nwei
}

fn validator_rejoin_request_path(node: &TestnetProvisionedNode) -> PathBuf {
    node_state_store_directory(node)
        .join("realignment-controller")
        .join("validator-rejoin-request.json")
}

fn validator_rejoin_request_evidence_path(node: &TestnetProvisionedNode) -> PathBuf {
    validator_onboarding_evidence_path(node, "validator-rejoin-request.json")
}

pub async fn testnet_request_validator_rejoin(
    input: TestnetValidatorRejoinRequestInput,
) -> Result<ValidatorRejoinRequestResult, String> {
    let state = build_state()?;
    let node = state
        .nodes
        .iter()
        .find(|n| n.id == input.node_id)
        .cloned()
        .ok_or_else(|| format!("Node not found: {}", input.node_id))?;
    if !role_supports_validator_registration(&node.role_id) {
        return Err(
            "Validator rejoin requests are only available for validator nodes.".to_string(),
        );
    }

    let client = Client::builder()
        .timeout(Duration::from_secs(5))
        .build()
        .map_err(|error| format!("HTTP client error: {error}"))?;
    let rpc_endpoint = rpc_endpoint_for_workspace(&node).ok();
    let current_height = if let Some(endpoint) = rpc_endpoint.as_deref() {
        query_rpc_value(&client, endpoint, "synergy_getLatestBlock", json!([]))
            .await
            .ok()
            .and_then(|value| {
                value
                    .get("block_index")
                    .or_else(|| value.get("height"))
                    .and_then(Value::as_u64)
            })
    } else {
        None
    };
    let target_boundary = current_height.map(|height| {
        testnet_epoch_start_height(testnet_epoch_for_block_height(height).saturating_add(1))
    });
    let entry_window_start = target_boundary;
    let entry_window_blocks = 10u64;
    let entry_window_end = target_boundary.map(|height| height + entry_window_blocks - 1);
    let requested_at_utc = Utc::now().to_rfc3339();
    let request_path = validator_rejoin_request_path(&node);
    let evidence_path = validator_rejoin_request_evidence_path(&node);
    let payload = json!({
        "requested": true,
        "status": "armed",
        "requested_at_utc": requested_at_utc,
        "requested_by": "node-control-panel",
        "node_id": node.id,
        "validator_address": node.node_address,
        "current_height": current_height,
        "target_boundary": target_boundary,
        "entry_window_start": entry_window_start,
        "entry_window_end": entry_window_end,
        "entry_window_blocks": entry_window_blocks,
        "epoch_length": TESTNET_EPOCH_LENGTH,
        "policy": "The realignment controller may execute request-rejoin only inside the first 10 blocks of the target epoch. If that window is missed, it must roll forward to the next epoch.",
    });
    write_json_file(&request_path, &payload)?;
    write_json_file(&evidence_path, &payload)?;

    Ok(ValidatorRejoinRequestResult {
        node_id: input.node_id,
        status: "armed".to_string(),
        message: target_boundary
            .map(|boundary| {
                format!(
                    "Validator rejoin is armed for epoch boundary {boundary}; the controller may join only through block {}.",
                    boundary + entry_window_blocks - 1
                )
            })
            .unwrap_or_else(|| {
                "Validator rejoin request is armed; the controller will calculate the next epoch boundary when local RPC is available.".to_string()
            }),
        requested_at_utc,
        current_height,
        target_boundary,
        entry_window_start,
        entry_window_end,
        request_path: request_path.to_string_lossy().to_string(),
        evidence_path: evidence_path.to_string_lossy().to_string(),
    })
}

fn preflight_check_is_pass(preflight: &ValidatorActivationPreflightResult, id: &str) -> bool {
    preflight
        .checks
        .iter()
        .any(|check| check.id == id && check.status == "pass")
}

fn validator_onboarding_sync_needed(preflight: &ValidatorActivationPreflightResult) -> bool {
    // Seed registration is an activation requirement, but shadow onboarding can
    // begin once the validator has live relayer visibility. Otherwise local
    // validators behind NAT can never produce the pre-activation evidence that
    // activation is meant to require.
    ["local-rpc", "sync-gap", "peers-visible"]
        .iter()
        .any(|id| !preflight_check_is_pass(preflight, id))
}

fn normalized_validator_sync_mode(value: Option<&str>) -> Option<String> {
    value
        .map(|value| value.trim().replace('-', "_").to_ascii_lowercase())
        .filter(|value| !value.is_empty())
}

fn validator_sync_mode_is_normal(value: Option<&str>) -> bool {
    matches!(
        normalized_validator_sync_mode(value).as_deref(),
        Some("normal") | Some("normal_sync")
    )
}

fn validator_onboarding_requests_normal_sync(input: &TestnetValidatorOnboardingInput) -> bool {
    validator_sync_mode_is_normal(input.sync_mode.as_deref())
}

fn setup_sync_normal_mode_selected(
    node: &TestnetProvisionedNode,
    requested_sync_mode: Option<&str>,
) -> bool {
    if validator_sync_mode_is_normal(requested_sync_mode) {
        return true;
    }
    read_json_value(&validator_onboarding_state_path(node))
        .ok()
        .and_then(|value| {
            value
                .get("sync_mode")
                .and_then(Value::as_str)
                .map(str::to_string)
        })
        .is_some_and(|mode| validator_sync_mode_is_normal(Some(&mode)))
}

fn validator_onboarding_can_mutate_sync_state(node: &TestnetProvisionedNode) -> bool {
    !validator_setup_sync_complete_evidence_is_verified(node)
}

