pub fn testnet_import_config(
    input: TestnetFilesystemTargetInput,
) -> Result<TestnetFilesystemActionResult, String> {
    let node = provisioned_node_by_id(&input.node_id)?;
    let source = source_file(input.source.as_deref())?;
    let workspace = PathBuf::from(&node.workspace_directory);
    let config_dir = workspace.join("config");
    fs::create_dir_all(&config_dir)
        .map_err(|error| format!("Failed to create config directory: {error}"))?;
    let current = config_dir.join("node.toml");
    if current.exists() {
        let backup = config_dir.join(format!("node.toml.pre-import-{}.bak", utc_file_stamp()));
        fs::copy(&current, &backup).map_err(|error| {
            format!("Failed to back up existing node.toml before import: {error}")
        })?;
    }
    let target = config_dir.join("node.toml");
    fs::copy(&source, &target)
        .map_err(|error| format!("Failed to import validator configuration: {error}"))?;
    Ok(TestnetFilesystemActionResult {
        node_id: node.id,
        status: "imported".to_string(),
        path: target.to_string_lossy().to_string(),
        message: "Imported validator node.toml configuration.".to_string(),
    })
}

pub fn testnet_verify_backup(
    input: TestnetFilesystemTargetInput,
) -> Result<TestnetFilesystemActionResult, String> {
    let node = provisioned_node_by_id(&input.node_id)?;
    let source = source_file(input.source.as_deref())?;
    let digest = sha256_file_hex(&source)?;
    Ok(TestnetFilesystemActionResult {
        node_id: node.id,
        status: "verified".to_string(),
        path: source.to_string_lossy().to_string(),
        message: format!("Verified backup readability and SHA-256 digest {digest}."),
    })
}

pub fn testnet_restore_backup(
    input: TestnetFilesystemTargetInput,
) -> Result<TestnetFilesystemActionResult, String> {
    let node = provisioned_node_by_id(&input.node_id)?;
    let source = source_file(input.source.as_deref())?;
    let workspace = PathBuf::from(&node.workspace_directory);
    let file =
        File::open(&source).map_err(|error| format!("Failed to open backup archive: {error}"))?;
    let decoder = GzDecoder::new(file);
    let mut archive = Archive::new(decoder);
    archive
        .unpack(&workspace)
        .map_err(|error| format!("Failed to restore backup archive: {error}"))?;
    Ok(TestnetFilesystemActionResult {
        node_id: node.id,
        status: "restored".to_string(),
        path: workspace.to_string_lossy().to_string(),
        message: "Restored backup archive into validator workspace.".to_string(),
    })
}

pub fn testnet_clear_cache(
    input: TestnetFilesystemTargetInput,
) -> Result<TestnetFilesystemActionResult, String> {
    let node = provisioned_node_by_id(&input.node_id)?;
    let workspace = PathBuf::from(&node.workspace_directory);
    let cache_root = workspace.join("cache");
    let mut removed = Vec::new();
    for relative in ["cache", "tmp", "temp", "logs/cache"] {
        let candidate = workspace.join(relative);
        if candidate.exists() {
            remove_path_if_exists(&candidate, &mut removed)?;
        }
    }
    fs::create_dir_all(&cache_root)
        .map_err(|error| format!("Failed to recreate cache directory: {error}"))?;
    Ok(TestnetFilesystemActionResult {
        node_id: node.id,
        status: "cleared".to_string(),
        path: workspace.to_string_lossy().to_string(),
        message: format!("Cleared {} cache path(s).", removed.len()),
    })
}

pub fn testnet_apply_log_retention(
    input: TestnetLogRetentionInput,
) -> Result<TestnetFilesystemActionResult, String> {
    let node = provisioned_node_by_id(&input.node_id)?;
    let workspace = PathBuf::from(&node.workspace_directory);
    let logs_dir = workspace.join("logs");
    let mut removed = 0usize;
    if logs_dir.exists() {
        let cutoff = std::time::SystemTime::now()
            .checked_sub(std::time::Duration::from_secs(
                input.retention_days.saturating_mul(86_400),
            ))
            .ok_or_else(|| "Invalid log retention window.".to_string())?;
        remove_old_files(&logs_dir, cutoff, &mut removed)?;
    }
    Ok(TestnetFilesystemActionResult {
        node_id: node.id,
        status: "applied".to_string(),
        path: logs_dir.to_string_lossy().to_string(),
        message: format!(
            "Applied {} day log retention; removed {} old file(s).",
            input.retention_days, removed
        ),
    })
}

pub async fn testnet_verify_validator_eligibility(
    input: TestnetValidatorEligibilityInput,
) -> Result<TestnetValidatorEligibilityResult, String> {
    let wallet_address = input.wallet_address.trim().to_string();
    if !is_valid_address(&wallet_address) {
        return Err("Wallet address is not a canonical Synergy address.".to_string());
    }
    if wallet_address.starts_with("synv") {
        return Err(
            "Connect a regular Synergy wallet address, not a validator address.".to_string(),
        );
    }
    let required_stake = input.required_stake.unwrap_or(MINIMUM_STAKE_SNRG);
    let required_stake_nwei = required_stake.saturating_mul(TOKEN_SCALE);
    let required_funding = required_stake.max(VALIDATOR_FUNDING_SNRG);
    let required_funding_nwei = required_funding.saturating_mul(TOKEN_SCALE);
    let provisioned_node = input
        .node_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(provisioned_node_by_id)
        .transpose()?;
    let validator_address = if let Some(address) = input
        .validator_address
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        Some(address.to_string())
    } else if let Some(node) = provisioned_node.as_ref() {
        Some(node.node_address.clone())
    } else {
        None
    };
    if let Some(address) = validator_address.as_deref() {
        if !is_valid_address(address) || !address.starts_with("synv") {
            return Err(
                "Validator stake assignment requires a canonical synv validator address."
                    .to_string(),
            );
        }
    }
    let client = Client::builder()
        .timeout(Duration::from_secs(12))
        .build()
        .map_err(|error| format!("HTTP client error: {error}"))?;
    let provided_stake_tx_hash = input
        .stake_tx_hash
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    let persisted_funding = {
        let _guard = VALIDATOR_FUNDING_LOCK
            .lock()
            .map_err(|_| "Validator funding replay lock is unavailable.".to_string())?;
        match (provisioned_node.as_ref(), validator_address.as_deref()) {
            (Some(node), Some(address)) => read_validator_funding_pending(
                &validator_funding_pending_path(node),
            )?
            .filter(|record| {
                record.node_id == node.id
                    && record.validator_address.eq_ignore_ascii_case(address)
                    && record
                        .owner_wallet_address
                        .eq_ignore_ascii_case(&wallet_address)
                    && record.expected_amount_nwei == required_funding_nwei.to_string()
            }),
            _ => None,
        }
    };
    let stake_tx_hash = provided_stake_tx_hash.or_else(|| {
        persisted_funding
            .as_ref()
            .map(|record| record.tx_hash.clone())
    });
    let wallet_balance = query_rpc_u64_or_none(
        &client,
        TESTNET_PUBLIC_RPC_ENDPOINT,
        "synergy_getTokenBalance",
        json!([wallet_address, TOKEN_SYMBOL]),
    );
    let validator_account = async {
        let Some(address) = validator_address.as_deref() else {
            return (0, 0);
        };
        let (funding_nwei, (_validator_staked_balance_nwei, validator_staking_entries)) = tokio::join!(
            query_rpc_u64_or_none(
                &client,
                TESTNET_PUBLIC_RPC_ENDPOINT,
                "synergy_getTokenBalance",
                json!([address, TOKEN_SYMBOL]),
            ),
            query_account_stake_from_endpoint(&client, TESTNET_PUBLIC_RPC_ENDPOINT, address),
        );
        (
            funding_nwei.unwrap_or(0),
            active_stake_total_for_validator(&validator_staking_entries, address),
        )
    };
    let stake_evidence = async {
        match (stake_tx_hash.as_deref(), validator_address.as_deref()) {
            (Some(tx_hash), Some(address)) => Some(
                query_stake_transaction_evidence(
                    &client,
                    tx_hash,
                    &wallet_address,
                    address,
                    required_stake_nwei,
                    required_funding_nwei,
                )
                .await,
            ),
            _ => None,
        }
    };
    let (balance_nwei, (validator_funding_nwei, indexed_active_stake_nwei), stake_evidence) =
        tokio::join!(wallet_balance, validator_account, stake_evidence);
    let balance_nwei = balance_nwei.unwrap_or(0);
    let active_stake_nwei = match stake_evidence.as_ref() {
        Some(StakeTransactionEvidence {
            kind: ValidatorTransactionKind::ProtocolStake,
            status: StakeTransactionStatus::Confirmed,
            amount_nwei,
            ..
        }) => indexed_active_stake_nwei.max(*amount_nwei),
        _ => indexed_active_stake_nwei,
    };
    let fee_reserve_ready = validator_funding_nwei >= validator_fee_reserve_requirement_nwei();
    let pending_stake_nwei = match stake_evidence.as_ref() {
        Some(StakeTransactionEvidence {
            kind: ValidatorTransactionKind::ProtocolStake,
            status: StakeTransactionStatus::Pending,
            amount_nwei,
            ..
        }) => *amount_nwei,
        _ => 0,
    };
    let missing_stake_nwei = required_stake_nwei.saturating_sub(active_stake_nwei);
    let eligible = active_stake_nwei >= required_stake_nwei && fee_reserve_ready;
    let eligibility_status = if eligible {
        "eligible"
    } else if active_stake_nwei >= required_stake_nwei && !fee_reserve_ready {
        FEE_RESERVE_REQUIRED_STATUS
    } else if validator_funding_nwei >= required_funding_nwei {
        "stake_ready_to_bond"
    } else if required_stake == MINIMUM_STAKE_SNRG && validator_funding_nwei == required_stake_nwei
    {
        FEE_RESERVE_REQUIRED_STATUS
    } else if matches!(
        stake_evidence.as_ref(),
        Some(StakeTransactionEvidence {
            kind: ValidatorTransactionKind::ValidatorFunding,
            status: StakeTransactionStatus::Confirmed,
            ..
        })
    ) {
        "stake_pending"
    } else if matches!(
        stake_evidence.as_ref().map(|evidence| &evidence.status),
        Some(StakeTransactionStatus::Pending)
            | Some(StakeTransactionStatus::NotFound)
            | Some(StakeTransactionStatus::Unavailable)
    ) {
        "stake_pending"
    } else if matches!(
        stake_evidence.as_ref().map(|evidence| &evidence.status),
        Some(StakeTransactionStatus::Invalid)
    ) {
        "stake_invalid"
    } else if active_stake_nwei > 0 {
        "stake_insufficient"
    } else if balance_nwei >= required_stake_nwei {
        "not_staked"
    } else {
        "not_enough_balance"
    };
    if let (Some(node), Some(tx_hash)) = (provisioned_node.as_ref(), stake_tx_hash.as_deref()) {
        let transaction_resolved = eligible
            || validator_funding_nwei >= required_funding_nwei
            || matches!(
                stake_evidence.as_ref().map(|evidence| &evidence.status),
                Some(StakeTransactionStatus::Invalid)
            );
        if transaction_resolved {
            clear_validator_funding_pending(&validator_funding_pending_path(node), tx_hash)?;
        }
    }
    Ok(TestnetValidatorEligibilityResult {
        wallet_address,
        snrg_balance: nwei_to_whole_snrg(balance_nwei),
        required_stake,
        required_funding,
        active_stake_amount: nwei_to_whole_snrg(active_stake_nwei),
        pending_stake_amount: nwei_to_whole_snrg(pending_stake_nwei),
        missing_stake_amount: nwei_to_whole_snrg(missing_stake_nwei),
        eligibility_status: eligibility_status.to_string(),
        eligible,
        stake_tx_hash,
        stake_tx_status: stake_evidence
            .as_ref()
            .map(|evidence| evidence.status.as_str().to_string())
            .unwrap_or_else(|| StakeTransactionStatus::NotProvided.as_str().to_string()),
        validator_funding_amount: nwei_to_whole_snrg(validator_funding_nwei),
        funding_ready_to_bond: validator_funding_nwei >= required_funding_nwei && !eligible,
        last_verified_at: Utc::now().to_rfc3339(),
        error_message: if eligibility_status == FEE_RESERVE_REQUIRED_STATUS {
            validator_fee_reserve_required_message()
        } else {
            stake_evidence
                .as_ref()
                .map(|evidence| evidence.message.clone())
                .unwrap_or_default()
        },
    })
}

fn provisioned_node_by_id(node_id: &str) -> Result<TestnetProvisionedNode, String> {
    let root = ensure_testnet_root()?;
    let registry = load_registry(&root)?;
    registry
        .nodes
        .iter()
        .find(|node| node.id == node_id)
        .cloned()
        .ok_or_else(|| format!("Node not found: {node_id}"))
}

fn utc_file_stamp() -> String {
    Utc::now().format("%Y%m%dT%H%M%SZ").to_string()
}

fn resolve_output_path(requested: Option<&str>, default_path: &Path) -> Result<PathBuf, String> {
    let path = requested
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(PathBuf::from)
        .unwrap_or_else(|| default_path.to_path_buf());
    let final_path = if path.extension().is_none() || path.is_dir() {
        let file_name = default_path
            .file_name()
            .ok_or_else(|| "Default output path has no file name.".to_string())?;
        path.join(file_name)
    } else {
        path
    };
    if let Some(parent) = final_path.parent() {
        fs::create_dir_all(parent).map_err(|error| {
            format!(
                "Failed to create output directory {}: {error}",
                parent.display()
            )
        })?;
    }
    Ok(final_path)
}

fn source_file(requested: Option<&str>) -> Result<PathBuf, String> {
    let source = requested
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(PathBuf::from)
        .ok_or_else(|| "Source file is required.".to_string())?;
    if !source.is_file() {
        return Err(format!("Source file does not exist: {}", source.display()));
    }
    Ok(source)
}

fn create_workspace_archive(
    workspace: &Path,
    target: &Path,
    relative_paths: &[&str],
) -> Result<(), String> {
    let paths = relative_paths
        .iter()
        .map(|relative| workspace.join(relative))
        .filter(|path| path.exists())
        .collect::<Vec<_>>();
    if paths.is_empty() {
        return Err("No workspace paths were available to archive.".to_string());
    }
    create_paths_archive(workspace, target, &paths)
}

fn create_paths_archive(workspace: &Path, target: &Path, paths: &[PathBuf]) -> Result<(), String> {
    if let Some(parent) = target.parent() {
        fs::create_dir_all(parent).map_err(|error| {
            format!(
                "Failed to create archive directory {}: {error}",
                parent.display()
            )
        })?;
    }
    let output = File::create(target)
        .map_err(|error| format!("Failed to create archive {}: {error}", target.display()))?;
    let encoder = GzEncoder::new(output, Compression::default());
    let mut builder = Builder::new(encoder);
    for path in paths {
        if !path.exists() {
            continue;
        }
        let archive_name = path
            .strip_prefix(workspace)
            .unwrap_or(path.as_path())
            .to_path_buf();
        if path.is_dir() {
            builder
                .append_dir_all(&archive_name, path)
                .map_err(|error| {
                    format!("Failed to append {} to archive: {error}", path.display())
                })?;
        } else {
            builder
                .append_path_with_name(path, &archive_name)
                .map_err(|error| {
                    format!("Failed to append {} to archive: {error}", path.display())
                })?;
        }
    }
    builder
        .finish()
        .map_err(|error| format!("Failed to finish archive {}: {error}", target.display()))?;
    Ok(())
}

fn sha256_file_hex(path: &Path) -> Result<String, String> {
    let mut file = File::open(path)
        .map_err(|error| format!("Failed to open {} for hashing: {error}", path.display()))?;
    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 64 * 1024];
    loop {
        let read = file
            .read(&mut buffer)
            .map_err(|error| format!("Failed to read {} for hashing: {error}", path.display()))?;
        if read == 0 {
            break;
        }
        hasher.update(&buffer[..read]);
    }
    Ok(format!("{:x}", hasher.finalize()))
}

fn remove_old_files(
    directory: &Path,
    cutoff: std::time::SystemTime,
    removed: &mut usize,
) -> Result<(), String> {
    for entry in fs::read_dir(directory).map_err(|error| {
        format!(
            "Failed to read log directory {}: {error}",
            directory.display()
        )
    })? {
        let entry =
            entry.map_err(|error| format!("Failed to inspect log directory entry: {error}"))?;
        let path = entry.path();
        if path.is_dir() {
            remove_old_files(&path, cutoff, removed)?;
            continue;
        }
        let metadata = entry
            .metadata()
            .map_err(|error| format!("Failed to inspect {}: {error}", path.display()))?;
        if metadata
            .modified()
            .map(|modified| modified < cutoff)
            .unwrap_or(false)
        {
            fs::remove_file(&path).map_err(|error| {
                format!("Failed to remove old log file {}: {error}", path.display())
            })?;
            *removed += 1;
        }
    }
    Ok(())
}

pub async fn testnet_setup_node(input: TestnetSetupInput) -> Result<TestnetSetupResult, String> {
    let root = ensure_testnet_root()?;
    let role = find_role_profile(&input.role_id)?;
    let device_profile = detect_device_profile();
    let mut network_profile = load_or_create_network_profile(&root)?;
    let mut registry = load_registry(&root)?;

    if let Some(existing_node) = registry.nodes.first() {
        return Err(format!(
            "This machine already has a local Testnet node workspace for {} at {}. Restart Setup must erase local node data before provisioning another node.",
            existing_node.display_label,
            existing_node.workspace_directory
        ));
    }

    let role_slug = sanitize_slug(&role.id);
    let label = input
        .display_label
        .as_deref()
        .filter(|value| !value.trim().is_empty())
        .map(str::trim)
        .unwrap_or(role.display_name.as_str())
        .to_string();
    let node_id = format!("testnet-{}", Uuid::new_v4().simple());
    let default_directory = default_node_directory(&root, &role.id, &role_slug, &node_id);
    let workspace_directory =
        resolve_node_directory(input.intended_directory.as_deref(), &default_directory)?;
    let layout = provisioning_layout_for_role(&role.id, &workspace_directory);

    let identity_passphrase = input
        .identity_passphrase
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty());
    if role.id == "validator"
        && input.packaged_validator_identity.is_none()
        && identity_passphrase.map(str::len).unwrap_or(0) < 8
    {
        return Err(
            "Validator setup requires an identity encryption passphrase with at least 8 characters."
                .to_string(),
        );
    }

    for directory in layout.provisioning_directories(&role.id) {
        fs::create_dir_all(directory)
            .map_err(|error| format!("Failed to create {}: {error}", directory.display()))?;
    }

    let node_identity = match input.packaged_validator_identity.as_ref() {
        Some(identity) if role.id == "validator" => {
            import_packaged_validator_identity(&layout, identity)?
        }
        Some(_) => {
            return Err(
                "Packaged validator identities may only be installed for the validator role."
                    .to_string(),
            )
        }
        None => generate_node_wallet(&role, &layout.identity, identity_passphrase)?,
    };
    let effective_node_address = input
        .node_address_override
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .unwrap_or_else(|| node_identity.wallet.address.clone());
    validate_node_address_for_role(&role, &effective_node_address)?;
    // Use a caller-supplied public host only when it is usable. Invalid,
    // private, or reserved overrides are ignored without falling back to
    // auto-detection so generated public validator config cannot accidentally
    // preserve a bad advertised endpoint.
    let public_host_override = input
        .public_host
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let detected_public_host = match public_host_override {
        Some(raw_host) => {
            normalize_public_host_candidate(raw_host).filter(|host| is_publicly_routable_host(host))
        }
        None => detect_public_host().await,
    };
    if role.id == "validator" && detected_public_host.is_none() && public_host_override.is_none() {
        return Err(
            "Validator setup requires a public P2P IP address or DNS host before config generation."
                .to_string(),
        );
    }
    let public_p2p_port = match input.public_p2p_port {
        Some(0) => return Err("Validator public P2P port must be between 1 and 65535.".to_string()),
        Some(port) => port,
        None => TESTNET_P2P_PORT,
    };
    let nat_mode = input
        .nat_mode
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("router_port_forward");
    let nat_mode = match nat_mode {
        "direct_public_ip" | "router_port_forward" | "custom_public_port" => nat_mode.to_string(),
        other => {
            return Err(format!(
                "Invalid validator NAT mode '{other}'. Expected direct_public_ip, router_port_forward, or custom_public_port."
            ))
        }
    };
    let validator_mesh_only = validator_uses_private_mesh(&role.id, &effective_node_address);
    let funding_manifest = TestnetFundingManifest {
        id: format!("fund-{}", Uuid::new_v4().simple()),
        source_wallet: network_profile.treasury_wallet.address.clone(),
        destination_wallet: effective_node_address.clone(),
        destination_role: role.display_name.clone(),
        amount_snrg: format_amount(VALIDATOR_FUNDING_SNRG),
        amount_nwei: amount_to_nwei_string(VALIDATOR_FUNDING_SNRG),
        stake_vault_wallet: network_profile.stake_vault_wallet.address.clone(),
        status: "planned".to_string(),
        note: if validator_mesh_only {
            "Provisioning does not block on bootstrap reachability. Generated operational validator appliances are wired for the private WireGuard validator mesh immediately.".to_string()
        } else if role.id == "validator" {
            "Provisioning keeps validator P2P loopback-only until coordinator-signed Innernet enrollment installs private validator routes.".to_string()
        } else if role_uses_sentry_upstreams(&role.id) {
            "Provisioning does not block on bootstrap reachability. Generated public-edge workspaces are pinned to the sentry upstreams instead of dialing validators directly.".to_string()
        } else {
            "Provisioning does not block on bootstrap reachability. Generated workspaces are configured to use DNS bootnodes and DNS seed services immediately.".to_string()
        },
        created_at_utc: Utc::now().to_rfc3339(),
    };
    network_profile
        .funding_manifests
        .push(funding_manifest.clone());
    network_profile.updated_at_utc = Utc::now().to_rfc3339();

    let role_overlay = role_overlay_for(&role.id);
    let port_slot = if role.id == "validator" {
        0
    } else {
        next_available_port_slot(&registry.nodes)
    };
    let use_static_validator_vpn =
        role.id == "validator" && is_canonical_initial_validator_address(&effective_node_address);
    let peers_contents = if validator_mesh_only {
        build_peers_toml_with_additional(
            &network_profile,
            &canonical_validator_dial_targets(&effective_node_address),
        )
    } else if use_static_validator_vpn {
        build_validator_vpn_peers_toml_with_additional(
            &canonical_foundation_validator_dial_targets(
                &canonical_testnet_validator_peers(),
                &effective_node_address,
            ),
        )
    } else if role.id == "validator" {
        build_validator_vpn_peers_toml_with_additional(&[])
    } else if role_uses_sentry_upstreams(&role.id) {
        build_peers_toml_with_additional(
            &network_profile,
            &canonical_sentry_public_dial_targets_for_role(&role.id),
        )
    } else {
        build_peers_toml(&network_profile)
    };
    let public_host_for_generated_artifacts = detected_public_host.as_deref();
    let public_p2p_port_override = if role.id == "validator" {
        Some(public_p2p_port)
    } else {
        None
    };
    let aegis_contents = build_aegis_toml();
    let node_contents = build_node_toml(
        &node_id,
        &label,
        &role,
        &effective_node_address,
        &workspace_directory,
        public_host_for_generated_artifacts,
        &network_profile,
        role_overlay.as_str(),
        port_slot,
        public_p2p_port_override,
        None,
    );
    let manifest_contents = build_bootstrap_manifest_contents(
        &node_id,
        &label,
        &role,
        &effective_node_address,
        public_host_for_generated_artifacts,
        &funding_manifest,
        &device_profile,
        &network_profile.bootstrap_policy,
    )?;
    let readme_contents = build_node_readme(
        &label,
        &role,
        &effective_node_address,
        &workspace_directory,
        &network_profile,
        None,
    );

    let node_toml_path = layout.config.join("node.toml");
    let peers_toml_path = layout.config.join("peers.toml");
    let aegis_toml_path = layout.config.join("aegis.toml");
    let consensus_fork_migration_path = layout.config.join("consensus-fork-migration.json");
    let manifest_path = layout.evidence.join("bootstrap.json");
    let readme_path = workspace_directory.join("README.md");

    write_file(&node_toml_path, &node_contents)?;
    write_file(&peers_toml_path, &peers_contents)?;
    write_file(&aegis_toml_path, &aegis_contents)?;
    write_file(&manifest_path, &manifest_contents)?;
    write_file(&readme_path, &readme_contents)?;
    if role.id == "validator" {
        // Keep the historical bootstrap receipt as a compatibility copy; all
        // onboarding reads and writes use logs/evidence.
        let legacy_bootstrap = workspace_directory.join("evidence").join("bootstrap.json");
        copy_file(&manifest_path, &legacy_bootstrap)?;
    }
    if !input.skip_canonical_manifests {
        write_canonical_workspace_manifests(&workspace_directory)?;
    }

    // Generate an nginx reverse-proxy config for roles that expose a public RPC surface.
    if matches!(role.id.as_str(), "rpc_gateway" | "indexer") {
        let p2p_port_val = TESTNET_P2P_PORT.saturating_add(port_slot);
        let rpc_port_val = TESTNET_RPC_PORT.saturating_add(port_slot);
        let ws_port_val = TESTNET_WS_PORT.saturating_add(port_slot);
        let public_host_val = detected_public_host.as_deref().unwrap_or("YOUR_SERVER_IP");
        let nginx_contents = if role.id == "rpc_gateway" {
            let rpc_subdomain = "testnet-core-rpc.synergy-network.io";
            let ws_subdomain = "testnet-core-ws.synergy-network.io";
            let certbot_domains = format!("-d {rpc_subdomain} -d {ws_subdomain}");
            format!(
                "# Nginx reverse proxy for {role_display} ({node_id})\n\
                 # Generated by Synergy Node Control Panel during provisioning.\n\
                 #\n\
                 # DEPLOY STEPS (run on the server as root / sudo):\n\
                 #   1. sudo mkdir -p /var/www/letsencrypt\n\
                 #   2. sudo cp this-file /etc/nginx/sites-available/{rpc_subdomain}.conf\n\
                 #      sudo ln -sf /etc/nginx/sites-available/{rpc_subdomain}.conf /etc/nginx/sites-enabled/\n\
                 #   3. Deploy HTTP-only first so certbot can complete the ACME challenge:\n\
                 #      sudo nginx -t && sudo systemctl reload nginx\n\
                 #   4. Obtain SSL certificate (certbot will update this file automatically):\n\
                 #      sudo certbot --nginx {certbot_domains}\n\
                 #   5. sudo nginx -t && sudo systemctl reload nginx\n\
                 #\n\
                 # NOTE: certbot names the cert after the first domain.  Cert paths after\n\
                 # certbot runs will be /etc/letsencrypt/live/{rpc_subdomain}/...\n\
                 # Server public IP: {public_host} | P2P port {p2p_port} must be open in firewall.\n\n\
                 upstream {node_id}_rpc {{\n\
                 \tserver 127.0.0.1:{rpc_port};\n\
                 }}\n\
                 upstream {node_id}_ws {{\n\
                 \tserver 127.0.0.1:{ws_port};\n\
                 }}\n\n\
                 server {{\n\
                 \tlisten 80;\n\
                 \tserver_name {rpc_subdomain} {ws_subdomain};\n\
                 \tlocation ^~ /.well-known/acme-challenge/ {{\n\
                 \t\troot /var/www/letsencrypt;\n\
                 \t\tdefault_type \"text/plain\";\n\
                 \t\ttry_files $uri =404;\n\
                 \t}}\n\
                 \treturn 301 https://$host$request_uri;\n\
                 }}\n\n\
                 server {{\n\
                 \tlisten 443 ssl http2;\n\
                 \tserver_name {rpc_subdomain};\n\
                 \tssl_certificate /etc/letsencrypt/live/{rpc_subdomain}/fullchain.pem;\n\
                 \tssl_certificate_key /etc/letsencrypt/live/{rpc_subdomain}/privkey.pem;\n\
                 \tinclude /etc/letsencrypt/options-ssl-nginx.conf;\n\
                 \tssl_dhparam /etc/letsencrypt/ssl-dhparams.pem;\n\
                 \tlocation = /healthz {{ return 200 \"ok\\n\"; }}\n\
                 \tlocation / {{\n\
                 \t\tproxy_pass http://{node_id}_rpc;\n\
                 \t\tproxy_http_version 1.1;\n\
                 \t\tproxy_set_header Host $host;\n\
                 \t\tproxy_set_header X-Real-IP $remote_addr;\n\
                 \t\tproxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n\
                 \t\tproxy_set_header X-Forwarded-Proto $scheme;\n\
                 \t\tproxy_read_timeout 60s;\n\
                 \t\tadd_header Access-Control-Allow-Origin *;\n\
                 \t\tadd_header Access-Control-Allow-Methods \"GET, POST, OPTIONS\";\n\
                 \t\tadd_header Access-Control-Allow-Headers \"Content-Type\";\n\
                 \t}}\n\
                 }}\n\n\
                 server {{\n\
                 \tlisten 443 ssl http2;\n\
                 \tserver_name {ws_subdomain};\n\
                 \tssl_certificate /etc/letsencrypt/live/{rpc_subdomain}/fullchain.pem;\n\
                 \tssl_certificate_key /etc/letsencrypt/live/{rpc_subdomain}/privkey.pem;\n\
                 \tinclude /etc/letsencrypt/options-ssl-nginx.conf;\n\
                 \tssl_dhparam /etc/letsencrypt/ssl-dhparams.pem;\n\
                 \tlocation / {{\n\
                 \t\tproxy_pass http://{node_id}_ws;\n\
                 \t\tproxy_http_version 1.1;\n\
                 \t\tproxy_set_header Upgrade $http_upgrade;\n\
                 \t\tproxy_set_header Connection \"upgrade\";\n\
                 \t\tproxy_set_header Host $host;\n\
                 \t\tproxy_read_timeout 3600s;\n\
                 \t}}\n\
                 }}\n",
                role_display = role.display_name,
                node_id = node_id,
                rpc_subdomain = rpc_subdomain,
                ws_subdomain = ws_subdomain,
                rpc_port = rpc_port_val,
                ws_port = ws_port_val,
                p2p_port = p2p_port_val,
                public_host = public_host_val,
            )
        } else {
            let explorer_host = "testnet-explorer.synergy-network.io";
            let atlas_api_host = "testnet-atlas-api.synergy-network.io";
            let indexer_ws_host = "testnet-indexer.synergy-network.io";
            let explorer_static_root = "/var/www/explorer/dist";
            let atlas_api_port = 3020_u16;
            let certbot_domains =
                format!("-d {explorer_host} -d {atlas_api_host} -d {indexer_ws_host}");
            format!(
                "# Nginx reverse proxy for {role_display} ({node_id})\n\
                 # Generated by Synergy Node Control Panel during provisioning.\n\
                 #\n\
                 # DEPLOY STEPS (run on the server as root / sudo):\n\
                 #   1. sudo mkdir -p /var/www/letsencrypt\n\
                 #   2. sudo cp this-file /etc/nginx/sites-available/{explorer_host}.conf\n\
                 #      sudo ln -sf /etc/nginx/sites-available/{explorer_host}.conf /etc/nginx/sites-enabled/\n\
                 #   3. Deploy HTTP-only first so certbot can complete the ACME challenge:\n\
                 #      sudo nginx -t && sudo systemctl reload nginx\n\
                 #   4. Obtain SSL certificate (certbot will update this file automatically):\n\
                 #      sudo certbot --nginx {certbot_domains}\n\
                 #   5. sudo nginx -t && sudo systemctl reload nginx\n\
                 #\n\
                 # NOTE: certbot names the cert after the first domain.  Cert paths after\n\
                 # certbot runs will be /etc/letsencrypt/live/{explorer_host}/...\n\
                 # Explorer UI root on the server: {explorer_static_root}\n\
                 # Server public IP: {public_host} | P2P port {p2p_port} must be open in firewall.\n\n\
                 upstream {node_id}_atlas_api {{\n\
                 \tserver 127.0.0.1:{atlas_api_port};\n\
                 }}\n\
                 upstream {node_id}_indexer_ws {{\n\
                 \tserver 127.0.0.1:{ws_port};\n\
                 }}\n\n\
                 server {{\n\
                 \tlisten 80;\n\
                 \tserver_name {explorer_host} {atlas_api_host} {indexer_ws_host};\n\
                 \tlocation ^~ /.well-known/acme-challenge/ {{\n\
                 \t\troot /var/www/letsencrypt;\n\
                 \t\tdefault_type \"text/plain\";\n\
                 \t\ttry_files $uri =404;\n\
                 \t}}\n\
                 \treturn 301 https://$host$request_uri;\n\
                 }}\n\n\
                 server {{\n\
                 \tlisten 443 ssl http2;\n\
                 \tserver_name {explorer_host};\n\
                 \tssl_certificate /etc/letsencrypt/live/{explorer_host}/fullchain.pem;\n\
                 \tssl_certificate_key /etc/letsencrypt/live/{explorer_host}/privkey.pem;\n\
                 \tinclude /etc/letsencrypt/options-ssl-nginx.conf;\n\
                 \tssl_dhparam /etc/letsencrypt/ssl-dhparams.pem;\n\
                 \troot {explorer_static_root};\n\
                 \tindex index.html;\n\
                 \tlocation /api/ {{\n\
                 \t\tproxy_pass http://{node_id}_atlas_api;\n\
                 \t\tproxy_http_version 1.1;\n\
                 \t\tproxy_set_header Host $host;\n\
                 \t\tproxy_set_header X-Real-IP $remote_addr;\n\
                 \t\tproxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n\
                 \t\tproxy_set_header X-Forwarded-Proto $scheme;\n\
                 \t\tproxy_read_timeout 60s;\n\
                 \t}}\n\
                 \tlocation = /healthz {{\n\
                 \t\tproxy_pass http://{node_id}_atlas_api/healthz;\n\
                 \t}}\n\
                 \tlocation = /readyz {{\n\
                 \t\tproxy_pass http://{node_id}_atlas_api/readyz;\n\
                 \t}}\n\
                 \tlocation / {{\n\
                 \t\ttry_files $uri $uri/ /index.html;\n\
                 \t}}\n\
                 }}\n\n\
                 server {{\n\
                 \tlisten 443 ssl http2;\n\
                 \tserver_name {atlas_api_host};\n\
                 \tssl_certificate /etc/letsencrypt/live/{explorer_host}/fullchain.pem;\n\
                 \tssl_certificate_key /etc/letsencrypt/live/{explorer_host}/privkey.pem;\n\
                 \tinclude /etc/letsencrypt/options-ssl-nginx.conf;\n\
                 \tssl_dhparam /etc/letsencrypt/ssl-dhparams.pem;\n\
                 \tlocation / {{\n\
                 \t\tproxy_pass http://{node_id}_atlas_api;\n\
                 \t\tproxy_http_version 1.1;\n\
                 \t\tproxy_set_header Host $host;\n\
                 \t\tproxy_set_header X-Real-IP $remote_addr;\n\
                 \t\tproxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n\
                 \t\tproxy_set_header X-Forwarded-Proto $scheme;\n\
                 \t\tproxy_read_timeout 60s;\n\
                 \t}}\n\
                 }}\n\n\
                 server {{\n\
                 \tlisten 443 ssl http2;\n\
                 \tserver_name {indexer_ws_host};\n\
                 \tssl_certificate /etc/letsencrypt/live/{explorer_host}/fullchain.pem;\n\
                 \tssl_certificate_key /etc/letsencrypt/live/{explorer_host}/privkey.pem;\n\
                 \tinclude /etc/letsencrypt/options-ssl-nginx.conf;\n\
                 \tssl_dhparam /etc/letsencrypt/ssl-dhparams.pem;\n\
                 \tlocation / {{\n\
                 \t\tproxy_pass http://{node_id}_indexer_ws;\n\
                 \t\tproxy_http_version 1.1;\n\
                 \t\tproxy_set_header Upgrade $http_upgrade;\n\
                 \t\tproxy_set_header Connection \"upgrade\";\n\
                 \t\tproxy_set_header Host $host;\n\
                 \t\tproxy_read_timeout 3600s;\n\
                 \t}}\n\
                 }}\n",
                role_display = role.display_name,
                node_id = node_id,
                explorer_host = explorer_host,
                atlas_api_host = atlas_api_host,
                indexer_ws_host = indexer_ws_host,
                atlas_api_port = atlas_api_port,
                ws_port = ws_port_val,
                p2p_port = p2p_port_val,
                public_host = public_host_val,
                explorer_static_root = explorer_static_root,
            )
        };
        let nginx_path = workspace_directory.join("nginx.conf");
        let _ = write_file(&nginx_path, &nginx_contents);
    }

    let mut node_record = TestnetProvisionedNode {
        id: node_id.clone(),
        role_id: role.id.clone(),
        role_display_name: role.display_name.clone(),
        class_name: role.class_name.clone(),
        display_label: label.clone(),
        node_address: effective_node_address,
        public_key_path: node_identity.wallet.public_key_path.clone(),
        private_key_path: node_identity.wallet.private_key_path.clone(),
        encrypted_private_key_path: node_identity.wallet.encrypted_private_key_path.clone(),
        workspace_directory: workspace_directory.to_string_lossy().to_string(),
        config_paths: {
            let mut paths = vec![
                node_toml_path.to_string_lossy().to_string(),
                peers_toml_path.to_string_lossy().to_string(),
                aegis_toml_path.to_string_lossy().to_string(),
                consensus_fork_migration_path.to_string_lossy().to_string(),
                manifest_path.to_string_lossy().to_string(),
            ];
            if matches!(role.id.as_str(), "rpc_gateway" | "indexer") {
                paths.push(
                    workspace_directory
                        .join("nginx.conf")
                        .to_string_lossy()
                        .to_string(),
                );
            }
            paths
        },
        public_host: detected_public_host.clone(),
        public_p2p_port: if role.id == "validator" {
            Some(public_p2p_port)
        } else {
            None
        },
        nat_mode: if role.id == "validator" {
            Some(nat_mode)
        } else {
            None
        },
        reward_payout_address: None,
        owner_wallet_address: None,
        connectivity_status: if validator_mesh_only {
            "Private validator mesh configured.".to_string()
        } else if role.id == "validator" {
            "Secure network enrollment required. Validator P2P remains loopback-only until coordinator-signed Innernet routes are installed.".to_string()
        } else {
            "Bootstrap configured. Node will use DNS bootnodes and DNS seed services on startup."
                .to_string()
        },
        role_certificate_status: "Pending Aegis role certificate binding.".to_string(),
        funding_manifest_id: funding_manifest.id.clone(),
        created_at_utc: Utc::now().to_rfc3339(),
        port_slot: Some(port_slot),
        setup_sync_required: role.id == "validator" && !validator_mesh_only,
        setup_sync_reason: if role.id == "validator" && !validator_mesh_only {
            Some(
                "Jarvis must restore the latest archive-validator-produced validator-pruned snapshot, catch up, fund, stake, and confirm activation before opening the dashboard."
                    .to_string(),
            )
        } else {
            None
        },
    };
    let monitoring = write_onboarding_monitoring_artifacts(&node_record, &device_profile)
        .unwrap_or_else(|error| monitoring_error_result(&node_record, error));
    node_record
        .config_paths
        .extend(monitoring.generated_paths.clone());

    registry.nodes.push(node_record.clone());
    registry
        .nodes
        .sort_by(|left, right| left.created_at_utc.cmp(&right.created_at_utc));
    save_registry(&root, &registry)?;
    save_network_profile(&root, &network_profile)?;

    // Refresh the canonical launch manifests everywhere so each managed workspace
    // carries the same Testnet genesis and operational manifest data.
    for n in &registry.nodes {
        if input.skip_canonical_manifests && n.id == node_record.id {
            continue;
        }
        let ws = PathBuf::from(&n.workspace_directory);
        if ws.is_dir() {
            if let Err(e) = write_canonical_workspace_manifests(&ws) {
                eprintln!(
                    "Warning: could not refresh launch manifests for {}: {e}",
                    n.display_label
                );
            }
        }
    }

    #[cfg(not(test))]
    register_node_with_seeds_best_effort(&network_profile, &node_record).await;

    Ok(TestnetSetupResult {
        node: node_record,
        network_profile,
        device_profile,
        monitoring,
        next_steps: {
            let mut steps = vec![
                "Review the generated node.toml, peers.toml, and aegis.toml overlays in the isolated workspace.".to_string(),
                "Submit the generated monitoring-registration.json to Synergy monitoring; runtime metrics stay on 6030/tcp and host metrics use node_exporter on 9100/tcp while qRPC remains loopback-only.".to_string(),
                "Ask the Synergy Core team to send 50,001 SNRG to this validator synv1... address, then use Stake Validator to submit the exact 50,000 SNRG bond; the app will resume autonomous onboarding and activation checks.".to_string(),
                format!(
                    "Public host detection: {}.",
                    detected_public_host
                        .as_deref()
                        .unwrap_or("not detected automatically")
                ),
                if validator_mesh_only {
                    "Start the node with the generated workspace; it will dial the private WireGuard validator mesh immediately.".to_string()
                } else if role.id == "validator" {
                    "Run Safe Onboarding from the control panel. The app must restore the latest archive-validator-produced validator-pruned snapshot first, then speed-sync only the remaining blocks before funding, stake, shadow, and activation.".to_string()
                } else {
                    "Start the node with the generated workspace; multi-source peer discovery is configured from DNS bootnodes and DNS seed services.".to_string()
                },
            ];
            if role.id == "rpc_gateway" {
                steps.push(
                    "RPC Gateway: deploy the generated nginx.conf to /etc/nginx/sites-available/, \
                     obtain an SSL cert with certbot --nginx --expand, then reload nginx. \
                     The node binds JSON-RPC and WS to 127.0.0.1; nginx is the only public JSON-RPC surface. \
                     Keep rpc.synergynode.xyz:5623 reserved for P2P only."
                        .to_string(),
                );
            } else if role.id == "indexer" {
                steps.push(
                    "Indexer: deploy the generated nginx.conf to /etc/nginx/sites-available/, \
                     obtain an SSL cert with certbot --nginx --expand, then reload nginx. \
                     The node binds RPC to 0.0.0.0 with CORS enabled — no manual node.toml edits required.".to_string()
                );
            }
            steps
        },
    })
}

pub fn testnet_sign_packaged_validator_enrollment_proof(
    input: TestnetValidatorEnrollmentProofInput,
) -> Result<TestnetValidatorEnrollmentProofResult, String> {
    let root = ensure_testnet_root()?;
    let registry = load_registry(&root)?;
    let node_id = input.node_id.trim();
    let assignment_id = input.assignment_id.trim();
    let peer_name = input.peer_name.trim();
    if node_id.is_empty() || assignment_id.is_empty() || peer_name.is_empty() {
        return Err(
            "Packaged validator enrollment proof requires nodeId, assignmentId, and peerName."
                .to_string(),
        );
    }
    let node = registry
        .nodes
        .iter()
        .find(|candidate| candidate.id == node_id)
        .ok_or_else(|| format!("Validator node not found: {node_id}"))?;
    if node.role_id != "validator" {
        return Err("Enrollment proofs may only be created by validator nodes.".to_string());
    }
    let identity_directory = node_identity_directory(node);
    let package_assignment: Value = serde_json::from_str(
        &fs::read_to_string(identity_directory.join("package-assignment.json")).map_err(|_| {
            "This validator was not installed from a validator-specific package.".to_string()
        })?,
    )
    .map_err(|_| "The installed validator package assignment is invalid.".to_string())?;
    if package_assignment
        .get("assignment_id")
        .and_then(Value::as_str)
        .map(str::trim)
        != Some(assignment_id)
        || package_assignment
            .get("validator_address")
            .and_then(Value::as_str)
            .map(str::trim)
            != Some(node.node_address.trim())
    {
        return Err(
            "The requested VPN token assignment does not match the installed validator package."
                .to_string(),
        );
    }
    let private_key = fs::read_to_string(&node.private_key_path)
        .map_err(|error| format!("Failed to open the installed validator identity: {error}"))?;
    let public_key = fs::read_to_string(&node.public_key_path)
        .map_err(|error| format!("Failed to open the installed validator public key: {error}"))?;
    let message = format!(
        "synergy-validator-enrollment-proof-v1|{}|{}|{}|{}",
        assignment_id,
        node.node_address.trim(),
        peer_name,
        node_id,
    );
    let signature = sign_identity_proof(private_key.trim(), message.as_bytes())?;
    if !verify_identity_proof(
        node.node_address.trim(),
        public_key.trim(),
        message.as_bytes(),
        &signature,
    )? {
        return Err(
            "The installed validator identity proof failed local verification.".to_string(),
        );
    }
    Ok(TestnetValidatorEnrollmentProofResult {
        assignment_id: assignment_id.to_string(),
        validator_address: node.node_address.clone(),
        validator_public_key: public_key.trim().to_string(),
        identity_proof: signature,
    })
}

fn build_state() -> Result<TestnetState, String> {
    let root = ensure_testnet_root()?;
    let mut network_profile = load_or_create_network_profile(&root)?;
    let mut registry = load_registry(&root)?;
    let registry_reconstructed =
        reconstruct_validator_registry_from_workspace_identity(&mut registry)?;
    let evidence_migrated = registry
        .nodes
        .iter()
        .filter(|node| role_supports_validator_registration(&node.role_id))
        .map(|node| migrate_legacy_validator_evidence(&node.workspace_directory))
        .collect::<Result<Vec<_>, _>>()?
        .into_iter()
        .any(|changed| changed);
    let registry_repaired = reconcile_validator_registry_from_workspace_identity(&mut registry)?;
    let network_profile_repaired =
        reconcile_network_profile_validator_funding(&mut network_profile, &registry);
    if registry_reconstructed || registry_repaired || evidence_migrated {
        save_registry(&root, &registry)?;
    }
    if network_profile_repaired {
        save_network_profile(&root, &network_profile)?;
    }
    let node_catalog = node_catalog();
    let device_profile = detect_device_profile();
    let total_nodes = registry.nodes.len();
    let mut nodes = registry.nodes;
    apply_setup_sync_gate_state(&mut nodes);
    let local_validator_setup = local_validator_setup_summary(&nodes);
    let total_sponsored_stake_nwei = network_profile
        .funding_manifests
        .iter()
        .filter_map(|manifest| manifest.amount_nwei.parse::<u64>().ok())
        .fold(0_u64, |sum, amount| sum.saturating_add(amount));
    let total_sponsored_stake = if total_sponsored_stake_nwei > 0 {
        total_sponsored_stake_nwei / TOKEN_SCALE
    } else {
        total_nodes as u64 * MINIMUM_STAKE_SNRG
    };

    Ok(TestnetState {
        environment_id: TESTNET_ENVIRONMENT_ID.to_string(),
        display_name: TESTNET_DISPLAY_NAME.to_string(),
        chain_id: TESTNET_CHAIN_ID,
        network_id: TESTNET_NETWORK_ID_V2.to_string(),
        consensus_fork: testnet_fork_metadata(),
        device_profile,
        network_profile: network_profile.clone(),
        node_catalog: node_catalog.clone(),
        nodes,
        local_validator_setup,
        summary: TestnetDashboardSummary {
            total_nodes,
            active_role_profiles: node_catalog.len(),
            total_sponsored_stake_snrg: format_amount(total_sponsored_stake),
            total_sponsored_stake_nwei: if total_sponsored_stake_nwei > 0 {
                total_sponsored_stake_nwei.to_string()
            } else {
                amount_to_nwei_string(total_sponsored_stake)
            },
            connectivity_policy: network_profile.bootstrap_policy.note,
        },
    })
}

fn valid_validator_address_candidate(value: &str) -> Option<String> {
    let candidate = value.trim();
    if candidate.starts_with("synv")
        && candidate.len() == TARGET_ADDRESS_LEN
        && is_valid_address(candidate)
    {
        Some(candidate.to_string())
    } else {
        None
    }
}

fn json_validator_address_at(path: &Path, key: &str) -> Option<String> {
    read_json_value(path)
        .ok()
        .and_then(|value| value.get(key).and_then(Value::as_str).map(str::to_string))
        .and_then(|value| valid_validator_address_candidate(&value))
}

fn activation_status_is_confirmed(value: &Value) -> bool {
    value
        .get("canonical_status")
        .or_else(|| value.get("status"))
        .and_then(Value::as_str)
        .map(|status| status.eq_ignore_ascii_case("active") || status.eq_ignore_ascii_case("pass"))
        .unwrap_or(false)
}

fn activated_validator_address_from_evidence(node: &TestnetProvisionedNode) -> Option<String> {
    let path = validator_onboarding_evidence_path(node, "activation-confirmation.json");
    let value = read_json_value(&path).ok()?;
    if !activation_status_is_confirmed(&value) {
        return None;
    }
    let node_matches = value
        .get("node_id")
        .and_then(Value::as_str)
        .map(|node_id| node_id == node.id)
        .unwrap_or(true);
    if !node_matches {
        return None;
    }
    value
        .get("validator_address")
        .and_then(Value::as_str)
        .and_then(valid_validator_address_candidate)
}

fn workspace_validator_identity_address(node: &TestnetProvisionedNode) -> Option<String> {
    let workspace = Path::new(&node.workspace_directory);
    let identity_dir = node_identity_directory(node);
    [
        activated_validator_address_from_evidence(node),
        json_validator_address_at(&identity_dir.join("private.key.enc"), "address"),
        json_validator_address_at(&workspace.join("data").join("role-runtime.json"), "node_id"),
        json_validator_address_at(
            &workspace
                .join("state")
                .join("store")
                .join("role-runtime.json"),
            "node_id",
        ),
        json_validator_address_at(&identity_dir.join("identity.json"), "address"),
    ]
    .into_iter()
    .flatten()
    .next()
}

fn validator_evidence_directories(workspace_directory: &Path) -> (PathBuf, PathBuf) {
    (
        workspace_directory.join("logs").join("evidence"),
        workspace_directory.join("evidence"),
    )
}

fn migrate_legacy_validator_evidence(workspace_directory: &str) -> Result<bool, String> {
    let workspace = Path::new(workspace_directory);
    let (canonical, legacy) = validator_evidence_directories(workspace);
    if !legacy.is_dir() {
        return Ok(false);
    }
    fs::create_dir_all(&canonical)
        .map_err(|error| format!("Failed to create {}: {error}", canonical.display()))?;

    let mut changed = false;
    for entry in fs::read_dir(&legacy)
        .map_err(|error| format!("Failed to read {}: {error}", legacy.display()))?
    {
        let entry = entry.map_err(|error| {
            format!(
                "Failed to inspect legacy evidence in {}: {error}",
                legacy.display()
            )
        })?;
        let source = entry.path();
        if !source.is_file() {
            continue;
        }
        let destination = canonical.join(entry.file_name());
        if destination.exists() {
            continue;
        }
        copy_file(&source, &destination)?;
        changed = true;
    }
    Ok(changed)
}

fn workspace_toml_string(value: &toml::Value, section: &str, key: &str) -> Option<String> {
    value
        .get(section)
        .and_then(|section| section.get(key))
        .and_then(toml::Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
}

fn canonical_validator_workspace_identity(
    workspace_directory: &Path,
) -> Result<Option<(String, String, PathBuf)>, String> {
    let config_path = workspace_directory.join("config").join("node.toml");
    let identity_directory = if workspace_directory.join("identity").is_dir() {
        workspace_directory.join("identity")
    } else {
        workspace_directory.join("keys")
    };
    if !config_path.is_file() || !identity_directory.is_dir() {
        return Ok(None);
    }

    let identity_path = identity_directory.join("identity.json");
    let identity_value = read_json_value(&identity_path).map_err(|error| {
        format!(
            "Preserved validator workspace {} has invalid canonical identity metadata: {error}",
            workspace_directory.display()
        )
    })?;
    let address_from_identity = identity_value
        .get("address")
        .and_then(Value::as_str)
        .and_then(valid_validator_address_candidate)
        .ok_or_else(|| {
            format!(
                "Preserved validator workspace {} is missing a valid synv1 identity address.",
                workspace_directory.display()
            )
        })?;
    let address_from_file = fs::read_to_string(identity_directory.join("address.txt"))
        .ok()
        .and_then(|value| valid_validator_address_candidate(&value));
    if let Some(address) = address_from_file.as_deref() {
        if address != address_from_identity {
            return Err(format!(
                "Preserved validator workspace {} has conflicting identity addresses.",
                workspace_directory.display()
            ));
        }
    }

    let config = read_toml_value(&config_path)?;
    for (section, key) in [
        ("identity", "address"),
        ("node", "validator_address"),
        ("wallet", "reward_address"),
    ] {
        if let Some(value) = workspace_toml_string(&config, section, key) {
            if value != address_from_identity {
                return Err(format!(
                    "Preserved validator workspace {} has {section}.{key} that does not match its canonical identity.",
                    workspace_directory.display()
                ));
            }
        }
    }
    validate_node_address_for_role(&find_role_profile("validator")?, &address_from_identity)?;

    let expected_genesis = canonical_testnet_genesis_hash()?;
    let workspace_genesis = workspace_genesis_hash(workspace_directory)?;
    if !workspace_genesis.eq_ignore_ascii_case(&expected_genesis) {
        return Err(format!(
            "Preserved validator workspace {} has a non-canonical genesis hash.",
            workspace_directory.display()
        ));
    }
    if !node_config_fork_metadata_ready(&config_path)? {
        return Err(format!(
            "Preserved validator workspace {} has incomplete canonical fork metadata.",
            workspace_directory.display()
        ));
    }

    let node_id = workspace_directory
        .join("logs")
        .join("evidence")
        .join("bootstrap.json");
    let node_id = read_json_value(&node_id)
        .ok()
        .and_then(|value| {
            value
                .get("node_id")
                .and_then(Value::as_str)
                .map(str::to_string)
        })
        .or_else(|| workspace_toml_string(&config, "identity", "node_id"))
        .unwrap_or_else(|| {
            format!(
                "testnet-recovered-{}",
                &address_from_identity[address_from_identity.len().saturating_sub(12)..]
            )
        });
    let display_label = workspace_toml_string(&config, "identity", "label")
        .or_else(|| workspace_toml_string(&config, "identity", "role_display"))
        .unwrap_or_else(|| "Recovered Validator Node".to_string());
    Ok(Some((node_id, display_label, identity_directory)))
}

fn validator_workspace_candidates(root: &Path) -> Result<Vec<PathBuf>, String> {
    let mut candidates = vec![default_validator_appliance_root()];
    let nodes_root = root.join("nodes");
    if nodes_root.is_dir() {
        for entry in fs::read_dir(&nodes_root)
            .map_err(|error| format!("Failed to read {}: {error}", nodes_root.display()))?
        {
            let path = entry
                .map_err(|error| format!("Failed to inspect {}: {error}", nodes_root.display()))?
                .path();
            if path.is_dir() {
                candidates.push(path);
            }
        }
    }
    candidates.sort();
    candidates.dedup();
    Ok(candidates)
}

fn recovered_validator_funding_manifest(
    workspace: &Path,
    node_id: &str,
    address: &str,
) -> Option<TestnetFundingManifest> {
    let (canonical, legacy) = validator_evidence_directories(workspace);
    [canonical.join("bootstrap.json"), legacy.join("bootstrap.json")]
        .into_iter()
        .find_map(|path| {
            let value = read_json_value(&path).ok()?;
            serde_json::from_value::<TestnetFundingManifest>(
                value.get("funding_manifest")?.clone(),
            )
            .ok()
            .filter(|manifest| {
                manifest.destination_wallet.eq_ignore_ascii_case(address)
                    && !manifest.id.trim().is_empty()
            })
            .or_else(|| {
                Some(TestnetFundingManifest {
                    id: format!("fund-recovered-{node_id}"),
                    source_wallet: String::new(),
                    destination_wallet: address.to_string(),
                    destination_role: "Validator Node".to_string(),
                    amount_snrg: format_amount(VALIDATOR_FUNDING_SNRG),
                    amount_nwei: amount_to_nwei_string(VALIDATOR_FUNDING_SNRG),
                    stake_vault_wallet: String::new(),
                    status: "recovered-from-workspace".to_string(),
                    note: "Recovered from preserved validator workspace metadata; no chain or funding state was modified.".to_string(),
                    created_at_utc: Utc::now().to_rfc3339(),
                })
            })
        })
}

fn reconstruct_validator_registry_from_workspace_identity(
    registry: &mut TestnetRegistryFile,
) -> Result<bool, String> {
    if registry
        .nodes
        .iter()
        .any(|node| role_supports_validator_registration(&node.role_id))
    {
        return Ok(false);
    }
    let root = testnet_root_path()?;
    for workspace in validator_workspace_candidates(&root)? {
        migrate_legacy_validator_evidence(&workspace.to_string_lossy())?;
        let Some((node_id, display_label, identity_directory)) =
            canonical_validator_workspace_identity(&workspace)?
        else {
            continue;
        };
        let address = fs::read_to_string(identity_directory.join("address.txt"))
            .ok()
            .and_then(|value| valid_validator_address_candidate(&value))
            .or_else(|| {
                read_json_value(&identity_directory.join("identity.json"))
                    .ok()
                    .and_then(|value| {
                        value
                            .get("address")
                            .and_then(Value::as_str)
                            .and_then(valid_validator_address_candidate)
                    })
            })
            .ok_or_else(|| {
                "Preserved validator identity disappeared during reconstruction.".to_string()
            })?;
        let role = find_role_profile("validator")?;
        let encrypted_path = identity_directory.join("private.key.enc");
        let funding_manifest_id =
            recovered_validator_funding_manifest(&workspace, &node_id, &address)
                .map(|manifest| manifest.id)
                .unwrap_or_else(|| format!("fund-recovered-{node_id}"));
        registry.nodes.push(TestnetProvisionedNode {
            id: node_id,
            role_id: role.id,
            role_display_name: role.display_name,
            class_name: role.class_name,
            display_label,
            node_address: address.clone(),
            public_key_path: identity_directory.join("public.key").to_string_lossy().to_string(),
            private_key_path: identity_directory.join("private.key").to_string_lossy().to_string(),
            encrypted_private_key_path: encrypted_path.is_file().then(|| encrypted_path.to_string_lossy().to_string()),
            workspace_directory: workspace.to_string_lossy().to_string(),
            config_paths: vec![workspace.join("config").join("node.toml").to_string_lossy().to_string()],
            public_host: None,
            public_p2p_port: Some(TESTNET_P2P_PORT),
            nat_mode: None,
            reward_payout_address: Some(address),
            owner_wallet_address: None,
            connectivity_status: "Recovered from preserved validator workspace identity.".to_string(),
            role_certificate_status: "Control Panel validator identity is authoritative.".to_string(),
            funding_manifest_id,
            created_at_utc: Utc::now().to_rfc3339(),
            port_slot: Some(0),
            setup_sync_required: true,
            setup_sync_reason: Some("Recovered validator metadata; resume onboarding after validating preserved chain and evidence state.".to_string()),
        });
        return Ok(true);
    }
    Ok(false)
}

fn replace_toml_string_key(contents: &str, key: &str, value: &str) -> String {
    contents
        .lines()
        .map(|line| {
            let trimmed = line.trim_start();
            let prefix = format!("{key} = \"");
            if trimmed.starts_with(&prefix) {
                let indent_len = line.len().saturating_sub(trimmed.len());
                let indent = &line[..indent_len];
                format!("{indent}{key} = \"{value}\"")
            } else {
                line.to_string()
            }
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn ensure_validator_allowlist_contains(contents: String, validator_address: &str) -> String {
    contents
        .lines()
        .map(|line| {
            let trimmed = line.trim_start();
            if !trimmed.starts_with("allowed_validator_addresses = [")
                || line.contains(validator_address)
            {
                return line.to_string();
            }
            let Some(close_index) = line.rfind(']') else {
                return line.to_string();
            };
            let (before_close, after_close) = line.split_at(close_index);
            let separator = if before_close.trim_end().ends_with('[') {
                ""
            } else {
                ", "
            };
            format!("{before_close}{separator}\"{validator_address}\"{after_close}")
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn repair_validator_node_toml_identity(
    node: &TestnetProvisionedNode,
    validator_address: &str,
) -> Result<bool, String> {
    let config_path = Path::new(&node.workspace_directory)
        .join("config")
        .join("node.toml");
    if !config_path.is_file() {
        return Ok(false);
    }
    let original = fs::read_to_string(&config_path)
        .map_err(|error| format!("Failed to read {}: {error}", config_path.display()))?;
    let mut updated = original.clone();
    for key in [
        "node_id",
        "address",
        "node_name",
        "validator_address",
        "reward_address",
    ] {
        updated = replace_toml_string_key(&updated, key, validator_address);
    }
    updated = ensure_validator_allowlist_contains(updated, validator_address);
    if updated == original {
        return Ok(false);
    }
    write_file(&config_path, &(updated + "\n"))?;
    Ok(true)
}

fn repair_validator_workspace_identity_metadata(
    node: &TestnetProvisionedNode,
    validator_address: &str,
) -> Result<bool, String> {
    let mut changed = repair_validator_node_toml_identity(node, validator_address)?;
    let identity_dir = node_identity_directory(node);

    let address_path = identity_dir.join("address.txt");
    if identity_dir.is_dir()
        && fs::read_to_string(&address_path)
            .map(|contents| contents.trim() != validator_address)
            .unwrap_or(true)
    {
        write_file(&address_path, validator_address)?;
        changed = true;
    }

    let identity_path = identity_dir.join("identity.json");
    if identity_path.is_file() {
        if let Ok(mut identity) = read_json_value(&identity_path) {
            if identity.get("address").and_then(Value::as_str) != Some(validator_address) {
                identity["address"] = json!(validator_address);
                write_json_file(&identity_path, &identity)?;
                changed = true;
            }
        }
    }

    for (relative_path, key) in [
        ("config/atlas-validator-profile.json", "validatorAddress"),
        ("logs/evidence/bootstrap.json", "node_address"),
        (
            "logs/evidence/validator-pruned-snapshot-restore.json",
            "validator_address",
        ),
    ] {
        let path = Path::new(&node.workspace_directory).join(relative_path);
        if !path.is_file() {
            continue;
        }
        if let Ok(mut value) = read_json_value(&path) {
            if value.get(key).and_then(Value::as_str) != Some(validator_address) {
                value[key] = json!(validator_address);
                if relative_path == "evidence/bootstrap.json" {
                    if let Some(manifest) = value
                        .get_mut("funding_manifest")
                        .and_then(Value::as_object_mut)
                    {
                        manifest.insert("destination_wallet".to_string(), json!(validator_address));
                    }
                }
                if relative_path == "config/atlas-validator-profile.json" {
                    value["updatedAtUtc"] = json!(Utc::now().to_rfc3339());
                }
                write_json_file(&path, &value)?;
                changed = true;
            }
        }
    }

    Ok(changed)
}

fn reconcile_validator_registry_from_workspace_identity(
    registry: &mut TestnetRegistryFile,
) -> Result<bool, String> {
    let mut changed = false;
    for node in &mut registry.nodes {
        if !role_supports_validator_registration(&node.role_id) {
            continue;
        }
        let Some(validator_address) = workspace_validator_identity_address(node) else {
            continue;
        };
        if node.node_address != validator_address {
            node.node_address = validator_address.clone();
            node.reward_payout_address = Some(validator_address.clone());
            let identity_directory = node_identity_directory(node);
            node.public_key_path = identity_directory
                .join("public.key")
                .to_string_lossy()
                .to_string();
            node.private_key_path = identity_directory
                .join("private.key")
                .to_string_lossy()
                .to_string();
            let encrypted_path = identity_directory.join("private.key.enc");
            node.encrypted_private_key_path = encrypted_path
                .is_file()
                .then(|| encrypted_path.to_string_lossy().to_string());
            changed = true;
        }
        if !validator_uses_private_mesh(&node.role_id, &validator_address)
            && node.public_host.is_some()
        {
            node.public_host = None;
            changed = true;
        }
        if node.role_certificate_status.contains("ceremony package") {
            node.role_certificate_status =
                "Control Panel validator identity is authoritative.".to_string();
            changed = true;
        }
        if repair_validator_workspace_identity_metadata(node, &validator_address)? {
            changed = true;
        }
    }
    Ok(changed)
}

fn reconcile_network_profile_validator_funding(
    network_profile: &mut TestnetNetworkProfile,
    registry: &TestnetRegistryFile,
) -> bool {
    let Some(validator_node) = registry
        .nodes
        .iter()
        .find(|node| role_supports_validator_registration(&node.role_id))
    else {
        return false;
    };
    let validator_address = validator_node.node_address.clone();

    let mut changed = false;
    if !network_profile
        .funding_manifests
        .iter()
        .any(|manifest| manifest.id == validator_node.funding_manifest_id)
    {
        if let Some(manifest) = recovered_validator_funding_manifest(
            Path::new(&validator_node.workspace_directory),
            &validator_node.id,
            &validator_address,
        ) {
            network_profile.funding_manifests.push(manifest);
            changed = true;
        }
    }
    for manifest in &mut network_profile.funding_manifests {
        if manifest.destination_role == "Validator Node"
            && manifest.destination_wallet != validator_address
        {
            manifest.destination_wallet = validator_address.clone();
            changed = true;
        }
    }
    if changed {
        network_profile.updated_at_utc = Utc::now().to_rfc3339();
    }
    changed
}

fn local_validator_setup_summary(nodes: &[TestnetProvisionedNode]) -> TestnetLocalValidatorSetup {
    let registered_node = nodes
        .iter()
        .filter(|node| role_supports_validator_registration(&node.role_id))
        .max_by(|left, right| left.created_at_utc.cmp(&right.created_at_utc));
    let workspace_directory = registered_node
        .map(|node| PathBuf::from(&node.workspace_directory))
        .unwrap_or_else(default_validator_appliance_root);
    let identity_directory = workspace_directory.join("identity");
    let evidence_directory = workspace_directory.join("logs").join("evidence");
    let identity_present = identity_directory.join("identity.json").is_file()
        || identity_directory.join("private.key").is_file();
    let config_present = workspace_directory
        .join("config")
        .join("node.toml")
        .is_file();
    let state_present = workspace_directory.join("state").is_dir()
        || workspace_directory.join("state").join("store").is_dir();
    let snapshot_restore_present = evidence_directory
        .join("validator-pruned-snapshot-restore.json")
        .is_file();
    let setup_sync_complete_present = evidence_directory
        .join("validator-pruned-snapshot-sync-complete.json")
        .is_file();
    let activation_confirmation_present = evidence_directory
        .join("activation-confirmation.json")
        .is_file();
    let registered = registered_node.is_some();
    let file_evidence_present = workspace_directory.is_dir()
        && (identity_present
            || config_present
            || state_present
            || snapshot_restore_present
            || setup_sync_complete_present
            || activation_confirmation_present);
    let exists = registered || file_evidence_present;

    TestnetLocalValidatorSetup {
        exists,
        registered,
        orphaned: exists && !registered,
        workspace_directory: workspace_directory.to_string_lossy().to_string(),
        node_id: registered_node.map(|node| node.id.clone()),
        node_address: registered_node.map(|node| node.node_address.clone()),
        setup_sync_required: registered_node
            .map(|node| node.setup_sync_required)
            .unwrap_or(false),
        setup_sync_reason: registered_node.and_then(|node| node.setup_sync_reason.clone()),
        identity_present,
        config_present,
        state_present,
        snapshot_restore_present,
        setup_sync_complete_present,
        activation_confirmation_present,
    }
}

fn discovery_summary(
    healthy_bootnodes: usize,
    total_bootnodes: usize,
    _healthy_seed_servers: usize,
    _total_seed_servers: usize,
) -> (String, String) {
    if total_bootnodes > 0 && healthy_bootnodes == total_bootnodes {
        return (
            "Online".to_string(),
            format!("{healthy_bootnodes}/{total_bootnodes} bootnodes are responding."),
        );
    }

    if healthy_bootnodes > 0 {
        return (
            "Degraded".to_string(),
            format!("Only {healthy_bootnodes}/{total_bootnodes} bootnodes are reachable."),
        );
    }

    (
        "Offline".to_string(),
        "No bootnodes responded to the control panel health check.".to_string(),
    )
}

fn chain_summary(
    public_rpc_online: bool,
    public_chain_height: Option<u64>,
    public_peer_count: Option<usize>,
    healthy_bootnodes: usize,
    _healthy_seed_servers: usize,
) -> (String, String) {
    if public_rpc_online {
        let height = public_chain_height
            .map(|value| value.to_string())
            .unwrap_or_else(|| "unknown".to_string());
        let peers = public_peer_count
            .map(|value| value.to_string())
            .unwrap_or_else(|| "unknown".to_string());
        return (
            "Live".to_string(),
            format!("Public RPC is responding at block {height} with {peers} peers visible."),
        );
    }

    if healthy_bootnodes > 0 {
        return (
            "Bootstrap Only".to_string(),
            "Bootstrap endpoints are reachable, but the public RPC is not answering yet."
                .to_string(),
        );
    }

    (
        "Offline".to_string(),
        "Neither the public RPC nor the bootstrap endpoints are responding yet.".to_string(),
    )
}

async fn check_bootstrap_endpoint(endpoint: TestnetBootstrapEndpoint) -> TestnetEndpointLiveStatus {
    let started = Instant::now();
    let mut attempts = Vec::new();

    for host in endpoint_host_candidates(&endpoint, false) {
        match timeout(
            Duration::from_secs(3),
            TcpStream::connect((host.as_str(), endpoint.port)),
        )
        .await
        {
            Ok(Ok(_stream)) => {
                return TestnetEndpointLiveStatus {
                    kind: endpoint.kind,
                    host: endpoint.host,
                    ip_address: endpoint.ip_address,
                    port: endpoint.port,
                    status: "online".to_string(),
                    detail: format!("TCP handshake completed via {host}."),
                    reachable: true,
                    latency_ms: Some(started.elapsed().as_millis().min(u128::from(u64::MAX)) as u64),
                };
            }
            Ok(Err(error)) => {
                attempts.push(format!("{host}: TCP connection failed: {error}"));
            }
            Err(_) => {
                attempts.push(format!("{host}: timed out during TCP connection"));
            }
        }
    }

    TestnetEndpointLiveStatus {
        kind: endpoint.kind,
        host: endpoint.host,
        ip_address: endpoint.ip_address,
        port: endpoint.port,
        status: "offline".to_string(),
        detail: if attempts.is_empty() {
            "No usable bootstrap endpoints were available.".to_string()
        } else {
            attempts.join(" | ")
        },
        reachable: false,
        latency_ms: None,
    }
}

async fn check_seed_endpoint(
    client: &Client,
    endpoint: TestnetBootstrapEndpoint,
) -> TestnetEndpointLiveStatus {
    let started = Instant::now();
    let mut attempts = Vec::new();

    for url in seed_service_urls(&endpoint, "/healthz") {
        match client.get(&url).send().await {
            Ok(response) if response.status().is_success() => {
                return TestnetEndpointLiveStatus {
                    kind: endpoint.kind,
                    host: endpoint.host,
                    ip_address: endpoint.ip_address,
                    port: endpoint.port,
                    status: "online".to_string(),
                    detail: format!("Seed health endpoint responded via {url}."),
                    reachable: true,
                    latency_ms: Some(started.elapsed().as_millis().min(u128::from(u64::MAX)) as u64),
                };
            }
            Ok(response) => {
                attempts.push(format!("{url}: HTTP {}", response.status()));
            }
            Err(error) => {
                attempts.push(format!("{url}: {error}"));
            }
        }
    }

    TestnetEndpointLiveStatus {
        kind: endpoint.kind,
        host: endpoint.host,
        ip_address: endpoint.ip_address,
        port: endpoint.port,
        status: "offline".to_string(),
        detail: if attempts.is_empty() {
            "No usable seed endpoints were available.".to_string()
        } else {
            attempts.join(" | ")
        },
        reachable: false,
        latency_ms: None,
    }
}

#[derive(Debug, Clone)]
struct SyncTargetSelection {
    height: Option<u64>,
    source: String,
    verified: bool,
    error: Option<String>,
}

#[derive(Debug, Clone)]
struct VerifiedPublicChainHead {
    height: u64,
    latest_hash: Option<String>,
    genesis_hash: String,
    chain_id: u64,
    network_id: String,
}

fn height_source_record(
    source: &str,
    source_url_or_path: impl Into<String>,
    height: Option<u64>,
    verification_status: &str,
    usable_for_sync_target: bool,
    detail: impl Into<String>,
) -> TestnetHeightSourceRecord {
    TestnetHeightSourceRecord {
        source: source.to_string(),
        source_url_or_path: source_url_or_path.into(),
        height,
        chain_id: usable_for_sync_target.then_some(TESTNET_CHAIN_ID),
        network_id: usable_for_sync_target.then(|| TESTNET_NETWORK_ID_V2.to_string()),
        genesis_hash: None,
        latest_hash: None,
        latest_qc_hash: None,
        verification_status: verification_status.to_string(),
        usable_for_sync_target,
        detail: detail.into(),
    }
}

fn select_verified_sync_target(
    public_chain_height: Option<u64>,
    trusted_relayer_height: Option<u64>,
    best_observed_peer_height: Option<u64>,
) -> SyncTargetSelection {
    if let Some(relayer_height) = trusted_relayer_height {
        if let Some(public_height) = public_chain_height {
            if public_height.saturating_add(TESTNET_ACTIVATION_MAX_SYNC_GAP) < relayer_height {
                return SyncTargetSelection {
                    height: Some(relayer_height),
                    source: "trusted-relayer-rpc:verified-chain-1266".to_string(),
                    verified: true,
                    error: Some(format!(
                        "Public RPC head {public_height} is stale behind trusted relayer head {relayer_height}."
                    )),
                };
            }
        }

        return SyncTargetSelection {
            height: Some(relayer_height),
            source: "trusted-relayer-rpc:verified-chain-1266".to_string(),
            verified: true,
            error: None,
        };
    }

    if let Some(public_height) = public_chain_height {
        let error = best_observed_peer_height
            .filter(|peer_height| {
                *peer_height > public_height.saturating_add(TESTNET_ACTIVATION_MAX_SYNC_GAP)
            })
            .map(|peer_height| {
                format!(
                    "Rejected unverified peer/log height {peer_height}; verified public RPC head is {public_height}."
                )
            });
        return SyncTargetSelection {
            height: Some(public_height),
            source: "public-rpc:verified-chain-1266".to_string(),
            verified: true,
            error,
        };
    }

    if let Some(peer_height) = best_observed_peer_height {
        return SyncTargetSelection {
            height: None,
            source: "unavailable".to_string(),
            verified: false,
            error: Some(format!(
                "Only unverified peer/log height {peer_height} is available; refusing to use it as the onboarding sync target."
            )),
        };
    }

    SyncTargetSelection {
        height: None,
        source: "unavailable".to_string(),
        verified: false,
        error: Some("No verified sync target source is available.".to_string()),
    }
}

async fn query_trusted_relayer_chain_height(client: &Client) -> Option<u64> {
    let mut heights = Vec::new();

    for endpoint in ["http://195.26.241.95:5640", "http://94.72.117.108:5640"] {
        let chain_id = query_rpc_value(client, endpoint, "synergy_getChainId", json!([]))
            .await
            .and_then(parse_rpc_u64)
            .ok();
        if chain_id != Some(TESTNET_CHAIN_ID) {
            continue;
        }

        if let Ok(value) =
            query_rpc_value(client, endpoint, "synergy_getLatestBlock", json!([])).await
        {
            if let Ok(height) = parse_rpc_block_height(value) {
                heights.push(height);
            }
        }
    }

    heights.into_iter().max()
}

async fn build_node_live_status(
    client: &Client,
    node: &TestnetProvisionedNode,
    public_chain_height: Option<u64>,
) -> TestnetNodeLiveStatus {
    build_node_live_status_with_remote_details(client, node, public_chain_height, true).await
}

async fn build_node_live_status_for_dashboard(
    client: &Client,
    node: &TestnetProvisionedNode,
    public_chain_height: Option<u64>,
) -> TestnetNodeLiveStatus {
    build_node_live_status_with_remote_details(client, node, public_chain_height, false).await
}

async fn build_node_live_status_with_remote_details(
    client: &Client,
    node: &TestnetProvisionedNode,
    public_chain_height: Option<u64>,
    include_remote_details: bool,
) -> TestnetNodeLiveStatus {
    let workspace_directory = PathBuf::from(&node.workspace_directory);
    let config_path = workspace_directory.join("config").join("node.toml");
    let runtime_report_path = node_state_store_directory(node).join("role-runtime.json");
    let rpc_endpoint = parse_testnet_rpc_endpoint(&config_path)
        .unwrap_or_else(|| format!("http://127.0.0.1:{TESTNET_RPC_PORT}"));
    let process_info = running_process_for_workspace(&workspace_directory);
    let pid = process_info.as_ref().map(|info| info.pid);
    let process_uptime_secs = process_info.as_ref().map(|info| info.uptime_secs);
    let resource_snapshot = node_resource_snapshot(&workspace_directory, pid);
    let is_running = process_info.is_some();
    let (log_local_chain_height, best_observed_peer_height) =
        recent_chain_hints_from_log(&workspace_directory);
    let store_local_chain_height = workspace_store_chain_height(&workspace_directory);
    let local_validator_address =
        role_supports_validator_registration(&node.role_id).then_some(node.node_address.as_str());
    let (
        trusted_relayer_chain_height,
        fresh_local_chain_height,
        local_chain_error,
        fresh_peer_summary,
        local_peer_error,
    ) = if is_running {
        let relayer_height = async {
            if include_remote_details {
                query_trusted_relayer_chain_height(client).await
            } else {
                None
            }
        };
        let (relayer_height, local_height, peer_info) = tokio::join!(
            relayer_height,
            query_local_chain_height(client, &rpc_endpoint),
            query_rpc_value(client, &rpc_endpoint, "synergy_getPeerInfo", json!([])),
        );
        let (fresh_local_chain_height, local_chain_error) = match local_height {
            Ok(height) => (Some(height), None),
            Err(error) => (None, Some(error)),
        };
        let (fresh_peer_summary, local_peer_error) = match peer_info {
            Ok(value) => match parse_rpc_peer_summary(&value, local_validator_address) {
                Ok(summary) => (Some(summary), None),
                Err(error) => (None, Some(error)),
            },
            Err(error) => (None, Some(error)),
        };
        (
            relayer_height,
            fresh_local_chain_height,
            local_chain_error,
            fresh_peer_summary,
            local_peer_error,
        )
    } else {
        (
            if include_remote_details {
                query_trusted_relayer_chain_height(client).await
            } else {
                None
            },
            None,
            None,
            None,
            None,
        )
    };
    let fresh_local_peer_count = fresh_peer_summary
        .as_ref()
        .map(|summary| summary.peer_count);
    let connected_validator_count = fresh_peer_summary
        .as_ref()
        .map(|summary| summary.connected_validator_count);
    let status_ready_validator_count = fresh_peer_summary
        .as_ref()
        .map(|summary| summary.status_ready_validator_count);
    let cached_snapshot = {
        let cache = NODE_LIVE_CACHE.lock().unwrap();
        cache.get(&node.id).cloned()
    };
    let cached_local_chain_height = cached_snapshot
        .as_ref()
        .and_then(|entry| entry.local_chain_height);
    let local_chain_height = fresh_local_chain_height.or(store_local_chain_height);
    let local_chain_height_verified = fresh_local_chain_height.is_some();
    let local_chain_height_source = if fresh_local_chain_height.is_some() {
        "local-rpc:verified-live".to_string()
    } else if store_local_chain_height.is_some() {
        "local-store:diagnostic".to_string()
    } else if cached_local_chain_height.is_some() || log_local_chain_height.is_some() {
        "unverified-diagnostic-only".to_string()
    } else {
        "unavailable".to_string()
    };
    let local_peer_count = fresh_local_peer_count.or_else(|| {
        cached_snapshot
            .as_ref()
            .and_then(|entry| entry.local_peer_count)
    });
    let using_cached_snapshot = is_running
        && ((fresh_local_chain_height.is_none() && cached_local_chain_height.is_some())
            || (fresh_local_peer_count.is_none() && local_peer_count.is_some()));
    let using_log_height =
        is_running && fresh_local_chain_height.is_none() && log_local_chain_height.is_some();
    let local_rpc_ready =
        is_running && (fresh_local_chain_height.is_some() || fresh_local_peer_count.is_some());
    let local_rpc_status = if !is_running {
        let mut cache = NODE_LIVE_CACHE.lock().unwrap();
        cache.remove(&node.id);
        "Local runtime is offline.".to_string()
    } else if local_rpc_ready {
        let mut cache = NODE_LIVE_CACHE.lock().unwrap();
        let previous = cache.get(&node.id).cloned();
        cache.insert(
            node.id.clone(),
            CachedNodeLiveSnapshot {
                local_chain_height: fresh_local_chain_height,
                local_peer_count,
                previous_chain_height: previous.as_ref().and_then(|s| s.local_chain_height),
                height_sampled_at: Some(Instant::now()),
                previous_sampled_at: previous.as_ref().and_then(|s| s.height_sampled_at),
            },
        );
        format!("Local RPC responding on {rpc_endpoint}.")
    } else {
        let mut details = Vec::new();
        if let Some(error) = local_chain_error.as_ref() {
            details.push(error.clone());
        }
        if let Some(error) = local_peer_error.as_ref() {
            details.push(format!("synergy_getPeerInfo: {error}"));
        }
        if using_cached_snapshot {
            details.push(
                "last successful local snapshot is available for diagnostics only".to_string(),
            );
        }
        if using_log_height {
            details.push(
                "last committed height from node log is diagnostic only and not used as the sync target"
                    .to_string(),
            );
        }
        if details.is_empty() {
            format!("Local RPC is not responding on {rpc_endpoint}.")
        } else {
            format!(
                "Local RPC is not responding on {rpc_endpoint}. {}",
                details.join(" | ")
            )
        }
    };
    let sync_target = select_verified_sync_target(
        public_chain_height,
        trusted_relayer_chain_height,
        best_observed_peer_height,
    );
    let best_network_height = sync_target.height;
    let sync_gap = match (best_network_height, local_chain_height) {
        (Some(network_height), Some(local_height)) => {
            Some(network_height.saturating_sub(local_height))
        }
        (Some(network_height), None) => Some(network_height),
        _ => None,
    };
    let log_path = workspace_directory.join("logs").join("synergy-testnet.log");
    let mut height_sources = Vec::new();
    height_sources.push(height_source_record(
        "local-rpc",
        rpc_endpoint.clone(),
        fresh_local_chain_height,
        if fresh_local_chain_height.is_some() {
            "verified-live"
        } else {
            "unavailable"
        },
        fresh_local_chain_height.is_some(),
        local_chain_error
            .as_deref()
            .unwrap_or("Local RPC height is current for this workspace."),
    ));
    if cached_local_chain_height.is_some() {
        height_sources.push(height_source_record(
            "cached-local-rpc",
            "control-service memory cache",
            cached_local_chain_height,
            "rejected-stale-cache",
            false,
            "Cached heights are diagnostics only and never define onboarding sync targets.",
        ));
    }
    if log_local_chain_height.is_some() {
        height_sources.push(height_source_record(
            "local-log-commit",
            log_path.to_string_lossy().to_string(),
            log_local_chain_height,
            "rejected-unverified-log",
            false,
            "Log-derived local heights can survive resets and are never canonical progress targets.",
        ));
    }
    if store_local_chain_height.is_some() {
        height_sources.push(height_source_record(
            "local-store",
            workspace_state_store_directory(&workspace_directory)
                .join("chain.json")
                .to_string_lossy()
                .to_string(),
            store_local_chain_height,
            "diagnostic-local-state",
            false,
            "Local store height reflects restored workspace state for display only; verified RPC/relayer heads still define sync targets.",
        ));
    }
    if best_observed_peer_height.is_some() {
        height_sources.push(height_source_record(
            "local-log-peer-status",
            log_path.to_string_lossy().to_string(),
            best_observed_peer_height,
            "rejected-unverified-peer-log",
            false,
            "Peer heights parsed from logs are not chain/genesis verified and cannot override public RPC.",
        ));
    }
    if trusted_relayer_chain_height.is_some() {
        height_sources.push(height_source_record(
            "trusted-relayer-rpc",
            "relayer-1/relayer-2",
            trusted_relayer_chain_height,
            "verified-chain-1266",
            true,
            "Trusted Testnet relayer RPC head verified against chain_id 1266.",
        ));
    }
    let mut public_rpc_source = height_source_record(
        "public-rpc",
        TESTNET_PUBLIC_RPC_ENDPOINT,
        public_chain_height,
        if public_chain_height.is_some() {
            "verified-chain-1266"
        } else {
            "unavailable"
        },
        public_chain_height.is_some(),
        "Canonical public RPC head for Synergy Testnet chain 1266.",
    );
    if public_chain_height.is_some() {
        public_rpc_source.chain_id = Some(TESTNET_CHAIN_ID);
        public_rpc_source.network_id = Some(TESTNET_NETWORK_ID_V2.to_string());
        public_rpc_source.genesis_hash = canonical_testnet_genesis_hash().ok();
    }
    height_sources.push(public_rpc_source);

    let (synergy_score, synergy_score_status) = if include_remote_details {
        resolve_synergy_score_status(
            client,
            &node.role_id,
            &rpc_endpoint,
            &node.node_address,
            is_running,
            local_rpc_ready,
        )
        .await
    } else {
        (
            None,
            "Live score refresh is deferred to detailed telemetry checks.".to_string(),
        )
    };

    // Compute sync trending from cached snapshots.
    let (sync_trending, blocks_per_second, estimated_sync_eta_secs) = {
        let cache = NODE_LIVE_CACHE.lock().unwrap();
        if let Some(snapshot) = cache.get(&node.id) {
            compute_sync_trending(snapshot, sync_gap)
        } else {
            ("unknown".to_string(), None, None)
        }
    };

    let wallet_ready = node_identity_directory(node)
        .join("identity.json")
        .is_file();

    TestnetNodeLiveStatus {
        node_id: node.id.clone(),
        rpc_endpoint,
        workspace_ready: workspace_directory.is_dir(),
        config_ready: config_path.is_file(),
        runtime_report_present: runtime_report_path.is_file(),
        is_running,
        local_rpc_ready,
        local_rpc_status,
        pid,
        process_uptime_secs,
        cpu_percent: resource_snapshot.cpu_percent,
        memory_percent: resource_snapshot.memory_percent,
        memory_mb: resource_snapshot.memory_mb,
        disk_percent: resource_snapshot.disk_percent,
        local_chain_height,
        local_chain_height_verified,
        local_chain_height_source,
        local_peer_count,
        connected_validator_count,
        status_ready_validator_count,
        sync_gap,
        log_local_chain_height,
        best_observed_peer_height,
        best_network_height,
        sync_target_height: sync_target.height,
        sync_target_source: sync_target.source,
        sync_target_verified: sync_target.verified,
        sync_target_error: sync_target.error,
        height_sources,
        synergy_score,
        synergy_score_status,
        wallet_ready,
        seed_registered: false,
        seed_registration_count: 0,
        sync_trending,
        blocks_per_second,
        estimated_sync_eta_secs,
        readiness: None,
        consensus_fork: testnet_fork_metadata(),
    }
}

fn compute_sync_trending(
    snapshot: &CachedNodeLiveSnapshot,
    sync_gap: Option<u64>,
) -> (String, Option<f64>, Option<u64>) {
    if let Some(gap) = sync_gap {
        if gap <= 5 {
            return ("synced".to_string(), None, None);
        }
    }
    let (current, prev, now_ts, prev_ts) = match (
        snapshot.local_chain_height,
        snapshot.previous_chain_height,
        snapshot.height_sampled_at,
        snapshot.previous_sampled_at,
    ) {
        (Some(c), Some(p), Some(n), Some(pt)) => (c, p, n, pt),
        _ => return ("unknown".to_string(), None, None),
    };
    let elapsed = now_ts.duration_since(prev_ts).as_secs_f64();
    if elapsed < 0.5 {
        return ("unknown".to_string(), None, None);
    }
    let gained = current.saturating_sub(prev) as f64;
    let bps = gained / elapsed;
    if bps < 0.01 {
        return ("stalled".to_string(), Some(0.0), None);
    }
    let eta = sync_gap.map(|gap| (gap as f64 / bps).ceil() as u64);
    ("improving".to_string(), Some(bps), eta)
}

struct RunningProcessInfo {
    pid: u32,
    uptime_secs: u64,
}

#[derive(Debug, Clone, Default, PartialEq)]
struct NodeResourceSnapshot {
    cpu_percent: Option<f64>,
    memory_percent: Option<f64>,
    memory_mb: Option<f64>,
    disk_percent: Option<f64>,
}

fn node_resource_snapshot(workspace_directory: &Path, pid: Option<u32>) -> NodeResourceSnapshot {
    let disk_percent = filesystem_disk_percent(workspace_directory);
    let (cpu_percent, memory_percent, memory_mb) = match pid {
        Some(pid) => {
            let mut system = NODE_RESOURCE_SYSTEM.lock().unwrap();
            system.refresh_all();
            let Some(process) = system
                .process(Pid::from_u32(pid))
                .filter(|process| process_matches_workspace(process, workspace_directory))
            else {
                return NodeResourceSnapshot {
                    disk_percent,
                    ..NodeResourceSnapshot::default()
                };
            };

            let cpu_percent = finite_resource_value(process.cpu_usage() as f64);
            let memory_mb = finite_resource_value(process.memory() as f64 / (1024.0 * 1024.0));
            let memory_percent = if system.total_memory() > 0 {
                finite_resource_value(
                    (process.memory() as f64 / system.total_memory() as f64) * 100.0,
                )
            } else {
                None
            };
            (cpu_percent, memory_percent, memory_mb)
        }
        None => (None, None, None),
    };

    NodeResourceSnapshot {
        cpu_percent,
        memory_percent,
        memory_mb,
        disk_percent,
    }
}

fn finite_resource_value(value: f64) -> Option<f64> {
    value.is_finite().then_some(value)
}

fn filesystem_disk_percent(workspace_directory: &Path) -> Option<f64> {
    let canonical_workspace = workspace_directory.canonicalize().ok()?;
    let disks = Disks::new_with_refreshed_list();
    let disk = disks
        .iter()
        .filter(|disk| canonical_workspace.starts_with(disk.mount_point()))
        .max_by_key(|disk| disk.mount_point().to_string_lossy().len())?;
    let total_bytes = disk.total_space();
    if total_bytes == 0 {
        return None;
    }
    let used_bytes = total_bytes.saturating_sub(disk.available_space());
    finite_resource_value((used_bytes as f64 / total_bytes as f64) * 100.0)
}

fn pid_file_candidates(workspace_directory: &Path) -> Vec<PathBuf> {
    let primary = workspace_state_store_directory(workspace_directory);
    let legacy = workspace_directory.join("data");
    let mut candidates = vec![
        primary.join("synergy-testnet.pid"),
        primary.join("node.pid"),
    ];
    if primary != legacy {
        candidates.extend([legacy.join("synergy-testnet.pid"), legacy.join("node.pid")]);
    }
    candidates
}

fn process_is_live(process: &sysinfo::Process) -> bool {
    let status = format!("{:?}", process.status()).to_ascii_lowercase();
    !status.contains("zombie") && !status.contains("dead")
}

fn process_matches_workspace(process: &sysinfo::Process, workspace_directory: &Path) -> bool {
    if !process_is_live(process) {
        return false;
    }
    let workspace = workspace_directory.to_string_lossy();
    let config_path = workspace_directory.join("config").join("node.toml");
    let config_path = config_path.to_string_lossy();
    let binary_directory = workspace_directory.join("bin");
    let command_line = process
        .cmd()
        .iter()
        .map(|part| part.to_string_lossy())
        .collect::<Vec<_>>()
        .join(" ");
    let command_lower = command_line.to_ascii_lowercase();
    let looks_like_validator_runtime = command_lower.contains("synergy-testnet")
        && (command_lower.contains(" start")
            || command_lower.contains("--config")
            || command_line.contains(config_path.as_ref()));

    if looks_like_validator_runtime
        && (command_line.contains(workspace.as_ref())
            || command_line.contains(config_path.as_ref()))
    {
        return true;
    }

    if looks_like_validator_runtime
        && process
            .exe()
            .is_some_and(|exe| exe.starts_with(&binary_directory))
    {
        return true;
    }

    // Validators are often started from the workspace with a relative binary
    // path and `--config config/node.toml`, so the full workspace path never
    // appears in the command line.
    process.cwd().is_some_and(|cwd| cwd == workspace_directory)
        && command_line.contains("config/node.toml")
        && command_line.contains("synergy-testnet")
}

fn persist_workspace_pid(workspace_directory: &Path, pid: u32) {
    let pid_path = workspace_state_store_directory(workspace_directory).join("synergy-testnet.pid");
    if let Some(parent) = pid_path.parent() {
        let _ = fs::create_dir_all(parent);
    }
    let _ = fs::write(pid_path, format!("{pid}\n"));
}

fn running_processes_for_workspace(workspace_directory: &Path) -> Vec<RunningProcessInfo> {
    let mut system = System::new_all();
    system.refresh_all();

    for pid_path in pid_file_candidates(workspace_directory) {
        let Some(pid_text) = fs::read_to_string(&pid_path).ok() else {
            continue;
        };
        let Some(pid) = pid_text.trim().parse::<u32>().ok() else {
            continue;
        };
        let Some(process) = system.process(Pid::from_u32(pid)) else {
            continue;
        };
        if process_matches_workspace(process, workspace_directory) {
            persist_workspace_pid(workspace_directory, pid);
            return vec![RunningProcessInfo {
                pid,
                uptime_secs: process.run_time(),
            }];
        }
    }

    let mut matches = system
        .processes()
        .iter()
        .filter_map(|(pid, process)| {
            if process_matches_workspace(process, workspace_directory) {
                Some(RunningProcessInfo {
                    pid: pid.as_u32(),
                    uptime_secs: process.run_time(),
                })
            } else {
                None
            }
        })
        .collect::<Vec<_>>();
    matches.sort_by_key(|info| std::cmp::Reverse(info.uptime_secs));
    if let Some(primary) = matches.first() {
        persist_workspace_pid(workspace_directory, primary.pid);
    }
    matches
}

fn running_process_for_workspace(workspace_directory: &Path) -> Option<RunningProcessInfo> {
    running_processes_for_workspace(workspace_directory)
        .into_iter()
        .next()
}

fn force_kill_workspace_processes(workspace_directory: &Path) -> Result<usize, String> {
    let processes = running_processes_for_workspace(workspace_directory);
    if processes.is_empty() {
        return Ok(0);
    }

    #[cfg(not(target_os = "windows"))]
    {
        for info in &processes {
            let _ = ProcessCommand::new("kill")
                .args(["-TERM", &info.pid.to_string()])
                .status();
        }
        std::thread::sleep(Duration::from_millis(500));

        let remaining = running_processes_for_workspace(workspace_directory);
        for info in &remaining {
            let _ = ProcessCommand::new("kill")
                .args(["-KILL", &info.pid.to_string()])
                .status();
        }
        std::thread::sleep(Duration::from_millis(500));
    }

    #[cfg(target_os = "windows")]
    {
        for info in &processes {
            let _ = ProcessCommand::new("taskkill")
                .args(["/PID", &info.pid.to_string(), "/F", "/T"])
                .status();
        }
        std::thread::sleep(Duration::from_millis(500));
    }

    for pid_path in pid_file_candidates(workspace_directory) {
        let _ = fs::remove_file(pid_path);
    }

    Ok(processes.len())
}

fn running_pid_for_workspace(workspace_directory: &Path) -> Option<u32> {
    running_process_for_workspace(workspace_directory).map(|info| info.pid)
}

fn repair_workspace_config_if_needed(role_id: &str, config_path: &Path) -> Result<(), String> {
    if !role_supports_validator_registration(role_id) {
        return Ok(());
    }

    let workspace_directory = match config_path.parent().and_then(Path::parent) {
        Some(path) => path,
        None => return Ok(()),
    };
    repair_workspace_consensus_timing_if_needed(config_path)?;
    repair_workspace_validator_allowlist_policy_if_needed(config_path)?;
    write_consensus_fork_migration_for_workspace(workspace_directory)?;
    let ceremony_package_path = workspace_manifest_directory_for_role(role_id, workspace_directory)
        .join("ceremony-package.json");

    if ceremony_package_path.is_file() {
        if let Ok(package) = load_ceremony_package(&ceremony_package_path) {
            repair_imported_validator_ports_if_needed(workspace_directory, config_path, &package)?;
        }
        return Ok(());
    }

    if config_path
        .parent()
        .and_then(Path::parent)
        .map(|workspace| {
            workspace_manifest_directory_for_role(role_id, workspace)
                .join("ceremony-package.json")
                .is_file()
        })
        .unwrap_or(false)
    {
        return Ok(());
    }

    Ok(())
}

fn repair_workspace_validator_allowlist_policy_if_needed(config_path: &Path) -> Result<(), String> {
    let mut value = read_toml_value(config_path)?;
    let root = value
        .as_table_mut()
        .ok_or_else(|| format!("{} must parse into a TOML table.", config_path.display()))?;
    let node = root
        .entry("node")
        .or_insert_with(|| toml::Value::Table(Default::default()))
        .as_table_mut()
        .ok_or_else(|| "[node] must be a TOML table.".to_string())?;
    let changed = set_toml_bool_if_changed(node, "strict_validator_allowlist", false);

    if changed {
        let rendered = toml::to_string_pretty(&value)
            .map_err(|error| format!("Failed to serialize {}: {error}", config_path.display()))?;
        write_file(config_path, &rendered)?;
    }

    Ok(())
}

fn repair_workspace_consensus_timing_if_needed(config_path: &Path) -> Result<(), String> {
    let mut value = read_toml_value(config_path)?;
    let root = value
        .as_table_mut()
        .ok_or_else(|| format!("{} must parse into a TOML table.", config_path.display()))?;
    let mut changed = false;

    let blockchain = root
        .entry("blockchain")
        .or_insert_with(|| toml::Value::Table(Default::default()))
        .as_table_mut()
        .ok_or_else(|| "[blockchain] must be a TOML table.".to_string())?;
    changed |= set_toml_int_if_changed(blockchain, "block_time", TESTNET_BLOCK_TIME_SECS as i64);

    let consensus = root
        .entry("consensus")
        .or_insert_with(|| toml::Value::Table(Default::default()))
        .as_table_mut()
        .ok_or_else(|| "[consensus] must be a TOML table.".to_string())?;
    let dynamic_validator_count = current_testnet_validator_count();
    let dynamic_validator_cluster_size = testnet_validator_cluster_size(dynamic_validator_count);
    for (key, expected) in [
        ("block_time_secs", TESTNET_BLOCK_TIME_SECS as i64),
        ("min_validators", TESTNET_STATIC_MIN_VALIDATORS as i64),
        (
            "validator_cluster_size",
            dynamic_validator_cluster_size as i64,
        ),
        ("validator_vote_threshold", 0),
        ("max_validators", 0),
        ("mesh_settle_secs", TESTNET_MESH_SETTLE_SECS as i64),
        ("leader_timeout_secs", TESTNET_LEADER_TIMEOUT_SECS as i64),
        ("vote_timeout_secs", TESTNET_VOTE_TIMEOUT_SECS as i64),
        ("block_timeout_secs", TESTNET_BLOCK_TIMEOUT_SECS as i64),
    ] {
        changed |= set_toml_int_if_changed(consensus, key, expected);
    }
    changed |= set_toml_bool_if_changed(
        consensus,
        "status_ready_gate_enabled",
        TESTNET_STATUS_READY_GATE_ENABLED,
    );
    changed |= set_toml_int_if_changed(
        consensus,
        "status_ready_min_validators",
        TESTNET_STATIC_STATUS_READY_MIN_VALIDATORS as i64,
    );
    changed |= set_toml_int_if_changed(
        consensus,
        "status_ready_genesis_grace_secs",
        TESTNET_STATUS_READY_GENESIS_GRACE_SECS as i64,
    );
    changed |= set_toml_bool_if_changed(
        consensus,
        "allow_genesis_status_bypass",
        TESTNET_ALLOW_GENESIS_STATUS_BYPASS,
    );
    changed |= set_toml_bool_if_changed(
        consensus,
        "penalization_enabled",
        TESTNET_CONSENSUS_PENALIZATION_ENABLED,
    );
    for key in [
        "emergency_stable_committee_mode",
        "freeze_validator_set",
        "freeze_score_weighted_proposer_order",
    ] {
        changed |= set_toml_bool_if_changed(consensus, key, false);
    }

    if changed {
        let rendered = toml::to_string_pretty(&value)
            .map_err(|error| format!("Failed to serialize {}: {error}", config_path.display()))?;
        write_file(config_path, &rendered)?;
    }

    Ok(())
}

fn set_toml_int_if_changed(
    table: &mut toml::map::Map<String, toml::Value>,
    key: &str,
    expected: i64,
) -> bool {
    if table.get(key).and_then(toml::Value::as_integer) == Some(expected) {
        return false;
    }
    table.insert(key.to_string(), toml::Value::Integer(expected));
    true
}

fn set_toml_bool_if_changed(
    table: &mut toml::map::Map<String, toml::Value>,
    key: &str,
    expected: bool,
) -> bool {
    if table.get(key).and_then(toml::Value::as_bool) == Some(expected) {
        return false;
    }
    table.insert(key.to_string(), toml::Value::Boolean(expected));
    true
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TestnetRuntimePorts {
    p2p_port: u16,
    public_p2p_port: u16,
    rpc_port: u16,
    ws_port: u16,
    discovery_port: u16,
    public_discovery_port: u16,
    metrics_port: u16,
}

fn runtime_ports_for_slot(slot: u16) -> TestnetRuntimePorts {
    let p2p_port = TESTNET_P2P_PORT.saturating_add(slot);
    let discovery_port = TESTNET_DISCOVERY_PORT.saturating_add(slot);
    TestnetRuntimePorts {
        p2p_port,
        public_p2p_port: p2p_port,
        rpc_port: TESTNET_RPC_PORT.saturating_add(slot),
        ws_port: TESTNET_WS_PORT.saturating_add(slot),
        discovery_port,
        public_discovery_port: discovery_port,
        metrics_port: TESTNET_METRICS_PORT.saturating_add(slot),
    }
}

fn validator_runtime_ports() -> TestnetRuntimePorts {
    TestnetRuntimePorts {
        p2p_port: TESTNET_P2P_PORT,
        public_p2p_port: TESTNET_P2P_PORT,
        rpc_port: TESTNET_RPC_PORT,
        ws_port: TESTNET_WS_PORT,
        discovery_port: TESTNET_DISCOVERY_PORT,
        public_discovery_port: TESTNET_DISCOVERY_PORT,
        metrics_port: TESTNET_METRICS_PORT,
    }
}

fn default_runtime_ports_for_role(role_id: &str, slot: u16) -> TestnetRuntimePorts {
    if role_id.eq_ignore_ascii_case("validator") {
        validator_runtime_ports()
    } else {
        runtime_ports_for_slot(slot)
    }
}

fn default_runtime_ports_for_node(node: &TestnetProvisionedNode) -> TestnetRuntimePorts {
    default_runtime_ports_for_role(&node.role_id, node.port_slot.unwrap_or(0))
}

fn runtime_ports_for_assigned_ports(
    assigned_ports: &TestnetCeremonyAssignedPorts,
) -> TestnetRuntimePorts {
    TestnetRuntimePorts {
        p2p_port: assigned_ports.p2p_port,
        public_p2p_port: assigned_ports
            .public_p2p_port
            .unwrap_or(assigned_ports.p2p_port),
        rpc_port: assigned_ports.rpc_port,
        ws_port: assigned_ports.ws_port,
        discovery_port: assigned_ports.discovery_port,
        public_discovery_port: assigned_ports
            .public_discovery_port
            .unwrap_or(assigned_ports.discovery_port),
        metrics_port: assigned_ports.metrics_port,
    }
}

fn parse_runtime_ports_from_config(config_path: &Path) -> Option<TestnetRuntimePorts> {
    let contents = fs::read_to_string(config_path).ok()?;
    let value: toml::Value = toml::from_str(&contents).ok()?;

    let read_u16 = |section: &str, key: &str| -> Option<u16> {
        value
            .get(section)
            .and_then(|section| section.get(key))
            .and_then(toml::Value::as_integer)
            .and_then(|value| u16::try_from(value).ok())
    };

    let metrics_port = value
        .get("telemetry")
        .and_then(|section| section.get("metrics_bind"))
        .and_then(toml::Value::as_str)
        .and_then(|bind| bind.rsplit(':').next())
        .and_then(|port| port.parse::<u16>().ok())?;
    let public_p2p_port = value
        .get("p2p")
        .and_then(|section| section.get("public_address"))
        .and_then(toml::Value::as_str)
        .and_then(|address| address.rsplit(':').next())
        .and_then(|port| port.parse::<u16>().ok())
        .unwrap_or_else(|| read_u16("network", "p2p_port").unwrap_or(TESTNET_P2P_PORT));

    Some(TestnetRuntimePorts {
        p2p_port: read_u16("network", "p2p_port")?,
        public_p2p_port,
        rpc_port: read_u16("rpc", "http_port")?,
        ws_port: read_u16("rpc", "ws_port")?,
        discovery_port: read_u16("p2p", "discovery_port")?,
        public_discovery_port: read_u16("p2p", "discovery_port")?,
        metrics_port,
    })
}

fn config_path_for_node(node: &TestnetProvisionedNode, file_name: &str) -> Option<PathBuf> {
    node.config_paths
        .iter()
        .map(PathBuf::from)
        .find(|path| path.file_name().and_then(|value| value.to_str()) == Some(file_name))
}

fn read_runtime_ports_for_node(node: &TestnetProvisionedNode) -> Option<TestnetRuntimePorts> {
    let config_path = config_path_for_node(node, "node.toml")?;
    parse_runtime_ports_from_config(&config_path)
}

fn repair_imported_validator_ports_if_needed(
    workspace_directory: &Path,
    config_path: &Path,
    package: &TestnetCeremonyPackage,
) -> Result<(), String> {
    let current_ports = match parse_runtime_ports_from_config(config_path) {
        Some(ports) => ports,
        None => return Ok(()),
    };
    let expected_ports = validator_runtime_ports();

    let root = ensure_testnet_root()?;
    let mut registry = load_registry(&root)?;
    let Some(node_index) = registry
        .nodes
        .iter()
        .position(|entry| Path::new(&entry.workspace_directory) == workspace_directory)
    else {
        return Ok(());
    };

    let mut registry_changed = false;
    if registry.nodes[node_index].port_slot != Some(0) {
        registry.nodes[node_index].port_slot = Some(0);
        registry_changed = true;
    }

    if current_ports == expected_ports {
        if registry_changed {
            save_registry(&root, &registry)?;
        }
        return Ok(());
    }

    let node_record = registry.nodes[node_index].clone();
    let network_profile = load_or_create_network_profile(&root)?;
    let role = find_role_profile(&node_record.role_id)?;
    let public_host = node_record.public_host.clone();
    let role_overlay = role_overlay_for(&role.id);

    let mut node_contents = build_node_toml(
        &node_record.id,
        &node_record.display_label,
        &role,
        &node_record.node_address,
        workspace_directory,
        public_host.as_deref(),
        &network_profile,
        role_overlay.as_str(),
        0,
        node_record.public_p2p_port,
        package.assigned_ports.as_ref(),
    );
    if role.id == "validator" {
        node_contents = apply_ceremony_validator_config_overrides(node_contents, package);
    }

    write_file(config_path, &node_contents)?;

    if registry_changed {
        save_registry(&root, &registry)?;
    }

    Ok(())
}

enum TestnetRunner {
    Binary(PathBuf),
    Cargo {
        manifest_path: PathBuf,
        binary_name: &'static str,
    },
}

fn resolve_testnet_runner(
    app_context: &AppContext,
    role_id: &str,
) -> Result<TestnetRunner, String> {
    for root in app_context.resource_roots() {
        if let Some(binary_name) = binary_name_for_role(role_id) {
            for candidate in runner_binary_candidates(root, binary_name) {
                if candidate.is_file() {
                    return Ok(TestnetRunner::Binary(candidate));
                }
            }
        }
    }

    for root in app_context.resource_roots() {
        for manifest in [root.join("synergy-testnet").join("src").join("Cargo.toml")] {
            if manifest.is_file() {
                return Ok(TestnetRunner::Cargo {
                    manifest_path: manifest,
                    binary_name: "synergy-testnet",
                });
            }
        }
    }

    for root in app_context.resource_roots() {
        for binary_name in current_platform_testnet_binary_names() {
            for candidate in runner_binary_candidates(root, binary_name) {
                if candidate.is_file() {
                    return Ok(TestnetRunner::Binary(candidate));
                }
            }
        }
    }

    Err(format!(
        "Could not find a runnable Testnet binary or source manifest for role {}.",
        role_id
    ))
}

fn runner_binary_candidates(root: &Path, binary_name: &str) -> [PathBuf; 4] {
    [
        root.join("binaries").join(binary_name),
        root.join("bin").join(binary_name),
        root.join(binary_name),
        root.join("synergy-testnet")
            .join("target")
            .join("release")
            .join(binary_name),
    ]
}

fn current_platform_testnet_binary_names() -> &'static [&'static str] {
    #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
    return &[
        "synergy-testnet-darwin-arm64",
        "synergy-testnet-macos-arm64",
        "synergy-testnet",
    ];

    #[cfg(all(target_os = "macos", target_arch = "x86_64"))]
    return &["synergy-testnet-macos-amd64", "synergy-testnet"];

    #[cfg(all(target_os = "linux", target_arch = "x86_64"))]
    return &["synergy-testnet-linux-amd64", "synergy-testnet"];

    #[cfg(all(target_os = "linux", target_arch = "aarch64"))]
    return &["synergy-testnet-linux-arm64", "synergy-testnet"];

    #[cfg(all(target_os = "windows", target_arch = "x86_64"))]
    return &["synergy-testnet-windows-amd64.exe", "synergy-testnet.exe"];

    #[allow(unreachable_code)]
    &["synergy-testnet"]
}

fn binary_name_for_role(role_id: &str) -> Option<&'static str> {
    match role_id {
        "validator" => Some("synergy-validator-node"),
        "committee" => Some("synergy-committee-node"),
        "archive_validator" => Some("synergy-archive-validator-node"),
        "audit_validator" => Some("synergy-audit-validator-node"),
        "relayer" => Some("synergy-relayer-node"),
        "witness" => Some("synergy-witness-node"),
        "oracle" => Some("synergy-oracle-node"),
        "uma_coordinator" => Some("synergy-uma-coordinator-node"),
        "cross_chain_verifier" => Some("synergy-cross-chain-verifier-node"),
        "compute" => Some("synergy-synq-execution-node"),
        "ai_inference" => Some("synergy-analytics-and-simulation-node"),
        "pqc_crypto" => Some("synergy-aegis-cryptography-node"),
        "data_availability" => Some("synergy-data-availability-node"),
        "governance_auditor" => Some("synergy-governance-auditor-node"),
        "treasury_controller" => Some("synergy-treasury-controller-node"),
        "security_council" => Some("synergy-security-council-node"),
        "rpc_gateway" => Some("synergy-rpc-gateway-node"),
        "indexer" => Some("synergy-indexer-and-explorer-node"),
        "observer" => Some("synergy-observer-light-node"),
        _ => None,
    }
}

async fn launch_runner_detached(
    runner: &TestnetRunner,
    subcommand: &str,
    config_path: &Path,
    workspace_directory: &Path,
) -> Result<(), String> {
    let runner = runner_to_owned(runner);
    let config_path = config_path.to_path_buf();
    let workspace_directory = workspace_directory.to_path_buf();
    let subcommand = subcommand.to_string();

    tokio::task::spawn_blocking(move || -> Result<(), String> {
        let logs_directory = workspace_directory.join("logs");
        fs::create_dir_all(&logs_directory)
            .map_err(|error| format!("Failed to create {}: {error}", logs_directory.display()))?;
        let stdout_path = control_action_log_path(&workspace_directory, &subcommand, "stdout");
        let stderr_path = control_action_log_path(&workspace_directory, &subcommand, "stderr");
        let stdout = fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&stdout_path)
            .map_err(|error| format!("Failed to open {}: {error}", stdout_path.display()))?;
        let stderr = fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&stderr_path)
            .map_err(|error| format!("Failed to open {}: {error}", stderr_path.display()))?;

        let mut command = command_for_runner(&runner);
        command.arg(&subcommand).arg("--config").arg(&config_path);
        apply_workspace_runtime_env(&mut command, &config_path, &workspace_directory)
            .current_dir(&workspace_directory)
            .stdout(Stdio::from(stdout))
            .stderr(Stdio::from(stderr));
        #[cfg(unix)]
        command.process_group(0);

        append_workspace_control_log(
            &workspace_directory,
            "INFO",
            "Launching detached node runner",
            Some(json!({
                "subcommand": subcommand.clone(),
                "config_path": config_path.display().to_string(),
                "stdout_log": stdout_path.display().to_string(),
                "stderr_log": stderr_path.display().to_string(),
            })),
        );

        let child = command
            .spawn()
            .map_err(|error| format!("Failed to launch {}: {}", subcommand, error))?;
        append_workspace_control_log(
            &workspace_directory,
            "INFO",
            "Detached node runner launched",
            Some(json!({
                "subcommand": subcommand.clone(),
                "pid": child.id(),
            })),
        );
        Ok(())
    })
    .await
    .map_err(|error| format!("Failed to run detached node command: {error}"))?
}

fn control_action_log_path(workspace_directory: &Path, subcommand: &str, stream: &str) -> PathBuf {
    workspace_directory
        .join("logs")
        .join(format!("control-{subcommand}.{stream}.log"))
}

fn control_service_log_path(workspace_directory: &Path) -> PathBuf {
    workspace_directory.join("logs").join("control-service.log")
}

fn append_control_action_output(path: &Path, bytes: &[u8]) -> Result<(), String> {
    if bytes.is_empty() {
        return Ok(());
    }

    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)
            .map_err(|error| format!("Failed to create {}: {error}", parent.display()))?;
    }

    let mut file = fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)
        .map_err(|error| format!("Failed to open {}: {error}", path.display()))?;
    file.write_all(bytes)
        .map_err(|error| format!("Failed to write {}: {error}", path.display()))?;
    if !bytes.ends_with(b"\n") {
        file.write_all(b"\n")
            .map_err(|error| format!("Failed to finalize {}: {error}", path.display()))?;
    }
    Ok(())
}

fn append_workspace_control_log(
    workspace_directory: &Path,
    level: &str,
    message: &str,
    metadata: Option<Value>,
) {
    let log_path = control_service_log_path(workspace_directory);
    if let Some(parent) = log_path.parent() {
        if fs::create_dir_all(parent).is_err() {
            return;
        }
    }

    let timestamp = Utc::now().format("%Y-%m-%d %H:%M:%S UTC");
    let mut contents = format!(
        "[{}] [{}] [control-service] {}\n",
        timestamp,
        level.trim().to_ascii_uppercase(),
        message
    );
    if let Some(metadata) = metadata {
        contents.push_str(&format!("  Metadata: {}\n", metadata));
    }

    if let Ok(mut file) = fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&log_path)
    {
        let _ = file.write_all(contents.as_bytes());
    }
}

fn time_resync_command_plan() -> Vec<(&'static str, Vec<&'static str>)> {
    match std::env::consts::OS {
        "macos" => vec![
            ("/usr/bin/sntp", vec!["-sS", "time.apple.com"]),
            ("/usr/sbin/systemsetup", vec!["-setusingnetworktime", "on"]),
            ("/usr/sbin/systemsetup", vec!["-getnetworktimeserver"]),
        ],
        "linux" => vec![
            ("timedatectl", vec!["set-ntp", "true"]),
            ("chronyc", vec!["-a", "makestep"]),
            ("ntpdate", vec!["-u", "pool.ntp.org"]),
        ],
        "windows" => vec![("w32tm", vec!["/resync", "/force"])],
        _ => Vec::new(),
    }
}

fn run_time_resync_command(program: &str, args: &[&str]) -> Value {
    let started_at = Utc::now().to_rfc3339();
    match ProcessCommand::new(program).args(args).output() {
        Ok(output) => json!({
            "program": program,
            "args": args,
            "started_at_utc": started_at,
            "finished_at_utc": Utc::now().to_rfc3339(),
            "exit_code": output.status.code(),
            "success": output.status.success(),
            "stdout": String::from_utf8_lossy(&output.stdout).trim(),
            "stderr": String::from_utf8_lossy(&output.stderr).trim(),
        }),
        Err(error) => json!({
            "program": program,
            "args": args,
            "started_at_utc": started_at,
            "finished_at_utc": Utc::now().to_rfc3339(),
            "exit_code": Value::Null,
            "success": false,
            "stdout": "",
            "stderr": error.to_string(),
        }),
    }
}

fn time_resync_command_succeeded(entry: &Value) -> bool {
    if !entry
        .get("success")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        return false;
    }
    let args = entry
        .get("args")
        .and_then(Value::as_array)
        .map(|values| {
            values
                .iter()
                .filter_map(Value::as_str)
                .collect::<Vec<_>>()
                .join(" ")
        })
        .unwrap_or_default();
    if args.contains("-getnetworktimeserver") {
        return false;
    }
    let combined_output = format!(
        "{}\n{}",
        entry.get("stdout").and_then(Value::as_str).unwrap_or(""),
        entry.get("stderr").and_then(Value::as_str).unwrap_or("")
    )
    .to_lowercase();
    !combined_output.contains("administrator access")
        && !combined_output.contains("permission denied")
        && !combined_output.contains("operation not permitted")
}

fn resync_machine_time(
    workspace_directory: &Path,
    node: &TestnetProvisionedNode,
) -> (String, String, String) {
    let commands = time_resync_command_plan();
    let attempted = commands
        .iter()
        .map(|(program, args)| run_time_resync_command(program, args))
        .collect::<Vec<_>>();
    let any_success = attempted.iter().any(time_resync_command_succeeded);
    let status = if any_success { "ok" } else { "warn" }.to_string();
    let evidence_dir = workspace_directory.join("logs").join("evidence");
    let evidence_name = format!("time-resync-{}.json", Utc::now().format("%Y%m%dT%H%M%SZ"));
    let evidence_path = evidence_dir.join(evidence_name);
    let evidence = json!({
        "action": "resync-time",
        "node_id": node.id,
        "node_label": node.display_label,
        "machine_os": std::env::consts::OS,
        "generated_at_utc": Utc::now().to_rfc3339(),
        "status": status,
        "commands": attempted,
        "note": if any_success {
            "At least one local time synchronization command completed successfully."
        } else if commands.is_empty() {
            "No supported local time synchronization command is configured for this platform."
        } else {
            "All local time synchronization commands failed; the machine may require administrator privileges or an installed NTP client."
        },
    });
    let _ = write_json_file(&evidence_path, &evidence);
    let message = if any_success {
        format!(
            "Machine time resync completed. Evidence: {}",
            evidence_path.display()
        )
    } else {
        format!(
            "Machine time resync attempted but needs attention. Evidence: {}",
            evidence_path.display()
        )
    };
    (status, message, evidence_path.to_string_lossy().to_string())
}

fn normalize_log_timestamp(raw: &str) -> Option<String> {
    let raw = raw.trim();
    if raw.is_empty() {
        return None;
    }

    DateTime::parse_from_rfc3339(raw)
        .map(|value| value.with_timezone(&Utc).to_rfc3339())
        .ok()
        .or_else(|| {
            NaiveDateTime::parse_from_str(raw, "%Y-%m-%d %H:%M:%S UTC")
                .ok()
                .map(|value| DateTime::<Utc>::from_naive_utc_and_offset(value, Utc).to_rfc3339())
        })
}

fn source_modified_at_utc(path: &Path) -> Option<String> {
    let modified = fs::metadata(path).ok()?.modified().ok()?;
    Some(DateTime::<Utc>::from(modified).to_rfc3339())
}

