fn node_identity_directory(node: &TestnetProvisionedNode) -> PathBuf {
    workspace_identity_directory_for_role(&node.role_id, Path::new(&node.workspace_directory))
}

fn node_state_store_directory(node: &TestnetProvisionedNode) -> PathBuf {
    workspace_state_store_directory_for_role(&node.role_id, Path::new(&node.workspace_directory))
}

fn node_manifest_directory(node: &TestnetProvisionedNode) -> PathBuf {
    workspace_manifest_directory_for_role(&node.role_id, Path::new(&node.workspace_directory))
}

fn normalize_optional(value: Option<&str>) -> Option<String> {
    value
        .map(str::trim)
        .filter(|value| !value.is_empty() && !value.eq_ignore_ascii_case("skip"))
        .map(str::to_string)
}

fn format_amount(amount_snrg: u64) -> String {
    format!("{amount_snrg}.{:09}", 0)
}

fn amount_to_nwei_string(amount_snrg: u64) -> String {
    (amount_snrg * TOKEN_SCALE).to_string()
}

fn sanitize_slug(value: &str) -> String {
    let sanitized = value
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() {
                character.to_ascii_lowercase()
            } else {
                '-'
            }
        })
        .collect::<String>();
    sanitized
        .split('-')
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>()
        .join("-")
}

fn find_role_profile(role_id: &str) -> Result<TestnetRoleProfile, String> {
    node_catalog()
        .into_iter()
        .find(|entry| entry.id == role_id)
        .ok_or_else(|| format!("Unknown Testnet role: {role_id}"))
}

fn build_node_toml(
    node_id: &str,
    display_label: &str,
    role: &TestnetRoleProfile,
    node_address: &str,
    workspace_directory: &Path,
    public_host: Option<&str>,
    network_profile: &TestnetNetworkProfile,
    role_overlay: &str,
    port_slot: u16,
    public_p2p_port_override: Option<u16>,
    assigned_ports: Option<&TestnetCeremonyAssignedPorts>,
) -> String {
    let canonical_validator_peers = canonical_testnet_validator_peers();
    let use_static_validator_mesh = role.id == "validator"
        && canonical_validator_peers
            .iter()
            .any(|entry| entry.address.eq_ignore_ascii_case(node_address.trim()));
    let runtime_ports = if role.id == "validator" {
        validator_runtime_ports()
    } else {
        assigned_ports
            .map(runtime_ports_for_assigned_ports)
            .unwrap_or_else(|| runtime_ports_for_slot(port_slot))
    };
    let p2p_port = runtime_ports.p2p_port;
    let rpc_port = runtime_ports.rpc_port;
    let ws_port = runtime_ports.ws_port;
    let discovery_port = runtime_ports.discovery_port;
    let metrics_port = runtime_ports.metrics_port;
    let config_node_id = if role.id == "validator" {
        node_address.to_string()
    } else {
        node_id.to_string()
    };
    let dynamic_validator_count = if canonical_validator_peers.is_empty() {
        TESTNET_GENESIS_SETUP_PACKAGE_VALIDATOR_COUNT
    } else {
        canonical_validator_peers.len()
    };
    let dynamic_validator_cluster_size = testnet_validator_cluster_size(dynamic_validator_count);
    let public_validator_upstreams = Vec::<String>::new();
    let sentry_upstreams = if role_uses_sentry_upstreams(&role.id) {
        canonical_sentry_public_dial_targets_for_role(&role.id)
    } else {
        Vec::new()
    };
    let use_sentry_upstreams = !use_static_validator_mesh && !sentry_upstreams.is_empty();
    let runtime_public_host = if use_static_validator_mesh {
        None
    } else if !public_validator_upstreams.is_empty() {
        None
    } else {
        normalize_optional(public_host)
    };
    let public_host_line = runtime_public_host
        .as_deref()
        .map(|value| format!("public_host = \"{value}\"\n"))
        .unwrap_or_default();
    let runtime_public_p2p_port = public_p2p_port_override.unwrap_or(runtime_ports.public_p2p_port);
    let runtime_public_address = if use_static_validator_mesh {
        node_address.trim().to_string()
    } else {
        runtime_public_host
            .as_deref()
            .map(|value| format!("{value}:{runtime_public_p2p_port}"))
            .unwrap_or_else(|| format!("127.0.0.1:{p2p_port}"))
    };
    let runtime_discovery_public_address = if use_static_validator_mesh {
        node_address.trim().to_string()
    } else {
        runtime_public_host
            .as_deref()
            .map(|value| format!("{value}:{}", runtime_ports.public_discovery_port))
            .unwrap_or_else(|| format!("127.0.0.1:{discovery_port}"))
    };
    let (bootnodes, seeds, bootstrap_dns_records) = if role.id == "validator" {
        (String::new(), String::new(), String::new())
    } else {
        (
            render_toml_string_array(&endpoint_socket_entries(&network_profile.bootnodes)),
            render_toml_string_array(&endpoint_http_entries(&network_profile.seed_servers)),
            render_toml_string_array(&[TESTNET_BOOTSTRAP_DNS_RECORD.to_string()]),
        )
    };
    let additional_dial_targets = if use_static_validator_mesh {
        canonical_foundation_validator_dial_targets_toml(&canonical_validator_peers, node_address)
    } else if !public_validator_upstreams.is_empty() {
        render_toml_string_array(&public_validator_upstreams)
    } else if use_sentry_upstreams {
        render_toml_string_array(&sentry_upstreams)
    } else {
        String::new()
    };
    let persistent_peers = if use_static_validator_mesh {
        additional_dial_targets.clone()
    } else if !public_validator_upstreams.is_empty() {
        additional_dial_targets.clone()
    } else {
        String::new()
    };
    let validator_vpn_transport_blocks = if use_static_validator_mesh {
        render_validator_vpn_transport_blocks(&canonical_validator_vpn_transport_pairs(
            &canonical_validator_peers,
            node_address,
        ))
    } else {
        String::new()
    };
    let auto_register_validator = "false";
    let enable_discovery = if role.id == "validator" {
        "false"
    } else {
        "true"
    };
    let enable_seed_registration = "false";
    let enable_peer_exchange = if role.id == "validator" {
        "false"
    } else {
        "true"
    };
    let reject_private_advertise_addrs = if use_static_validator_mesh {
        "false"
    } else {
        "true"
    };
    let strict_validator_allowlist = "false";
    let p2p_listen_address = if role.id == "validator" {
        format!("127.0.0.1:{p2p_port}")
    } else {
        format!("0.0.0.0:{p2p_port}")
    };
    let discovery_listen_address = if role.id == "validator" {
        format!("127.0.0.1:{discovery_port}")
    } else {
        format!("0.0.0.0:{discovery_port}")
    };
    let allowed_validator_addresses = if role.id == "validator" {
        let mut allowed = canonical_validator_peers
            .iter()
            .map(|entry| entry.address.clone())
            .collect::<Vec<_>>();
        if !allowed
            .iter()
            .any(|address| address.eq_ignore_ascii_case(node_address.trim()))
        {
            allowed.push(node_address.to_string());
        }
        format!("[{}]", render_toml_string_array(&allowed))
    } else {
        "[]".to_string()
    };
    let bootstrap_note = if use_static_validator_mesh {
        "Foundation validators use the coordinator-managed Innernet mesh: synv1 validator peer identities with validator_vpn_transports for 10.70.10.x routes, plus relayer support targets on 10.70.20.x."
    } else if !public_validator_upstreams.is_empty() {
        "Public validators use DNS bootnodes, DNS seed services, seed registration, and peer exchange while signing stays disabled until explicit activation."
    } else if role.id == "rpc_gateway" {
        "RPC Gateway dials the public P2P mesh through relay1/relay2.synergynode.xyz, all six validator public endpoints, archive.synergynode.xyz:5615, and the observer."
    } else if use_sentry_upstreams {
        "Public edge nodes pin their upstreams to the public sentry pair and do not dial validators directly."
    } else if role.id == "validator" {
        "New validators remain loopback-only with no peers until coordinator-signed Innernet enrollment installs private validator routes."
    } else {
        "Node will resolve peers from DNS bootnodes and DNS seed services at startup."
    };

    // RPC Gateway JSON-RPC stays loopback-only; nginx is the public
    // testnet-core-rpc.synergy-network.io router. Its public P2P address is
    // rpc.synergynode.xyz:5623 and must not be treated as JSON-RPC.
    let is_public_rpc_proxy_role = role.id == "rpc_gateway";
    let is_public_rpc_role = matches!(role.id.as_str(), "indexer" | "observer");
    let rpc_bind_address = if is_public_rpc_proxy_role {
        format!("127.0.0.1:{rpc_port}")
    } else if is_public_rpc_role {
        format!("0.0.0.0:{rpc_port}")
    } else {
        format!("127.0.0.1:{rpc_port}")
    };
    let cors_enabled = is_public_rpc_role;
    let cors_origins = if is_public_rpc_role { r#"["*"]"# } else { "[]" };

    let rendered = format!(
        "[identity]\nnode_id = \"{config_node_id}\"\nrole = \"{role_id}\"\nrole_display = \"{role_display}\"\nenvironment = \"{environment_id}\"\ndisplay_environment = \"{display_name}\"\naddress = \"{node_address}\"\nlabel = \"{display_label}\"\n\n[network]\nid = {chain_id}\nname = \"{chain_name}\"\nchain_name = \"{chain_name}\"\nchain_id = {chain_id}\nnetwork_id = \"{network_id}\"\np2p_port = {p2p_port}\nrpc_port = {rpc_port}\nws_port = {ws_port}\np2p_listen = \"0.0.0.0:{p2p_port}\"\nlisten_addr = \"0.0.0.0:{p2p_port}\"\npublic_p2p_address = \"{runtime_public_address}\"\nbootnodes = [{bootnodes}]\nseed_servers = [{seeds}]\nbootstrap_dns_records = [{bootstrap_dns_records}]\nadditional_dial_targets = [{additional_dial_targets}]\npersistent_peers = [{persistent_peers}]\n{validator_vpn_transport_blocks}quic = true\nmax_peers = 128\nbootstrap_connectivity_required = false\nbootstrap_mode = \"multi-source-signed\"\n{public_host_line}\n[blockchain]\nblock_time = {block_time_secs}\nmax_gas_limit = \"0x2fefd8\"\nchain_id = {chain_id}\nnetwork_id = \"{network_id}\"\n\n[consensus]\nalgorithm = \"Proof of Synergy\"\nnew_consensus_algorithm = \"{consensus_algorithm}\"\nvalidator_key_algorithm = \"{validator_key_algorithm}\"\nblock_time_secs = {block_time_secs}\nepoch_length = {epoch_length}\nmin_validators = {min_validators}\nvalidator_cluster_size = {validator_cluster_size}\nvalidator_vote_threshold = {validator_vote_threshold}\nmax_validators = {max_validators}\nstatus_ready_gate_enabled = {status_ready_gate_enabled}\nstatus_ready_min_validators = {status_ready_min_validators}\nstatus_ready_genesis_grace_secs = {status_ready_genesis_grace_secs}\nallow_genesis_status_bypass = {allow_genesis_status_bypass}\nmesh_settle_secs = {mesh_settle_secs}\nleader_timeout_secs = {leader_timeout_secs}\nvote_timeout_secs = {vote_timeout_secs}\nblock_timeout_secs = {block_timeout_secs}\npenalization_enabled = {penalization_enabled}\nsynergy_score_decay_rate = 0.05\nvrf_enabled = true\nvrf_seed_epoch_interval = 1000\nmax_synergy_points_per_epoch = 100\nmax_tasks_per_validator = 10\n\n[consensus.fork]\nchain_id = {chain_id}\nnetwork_id = \"{network_id}\"\nfork_height = {fork_height}\nfork_parent_height = {fork_parent_height}\nparent_hash = \"{fork_parent_hash}\"\nnew_consensus_algorithm = \"{consensus_algorithm}\"\nvalidator_key_algorithm = \"{validator_key_algorithm}\"\nparser_mode = \"{parser_mode}\"\n\n[consensus.reward_weighting]\ntask_accuracy = 0.5\nuptime = 0.3\ncollaboration = 0.2\n\n[logging]\nlog_level = \"debug\"\nlog_file = \"{log_path}\"\nenable_console = true\nmax_file_size = 10485760\nmax_files = 5\n\n[rpc]\nbind_address = \"{rpc_bind_address}\"\nenable_http = true\nhttp_port = {rpc_port}\nenable_ws = true\nws_port = {ws_port}\nenable_grpc = true\ngrpc_port = {rpc_port}\ncors_enabled = {cors_enabled}\ncors_origins = {cors_origins}\n\n[p2p]\nlisten_address = \"0.0.0.0:{p2p_port}\"\npublic_address = \"{runtime_public_address}\"\npublic_p2p_address = \"{runtime_public_address}\"\nnode_name = \"{config_node_id}\"\nenable_discovery = {enable_discovery}\nenable_seed_registration = {enable_seed_registration}\nenable_peer_exchange = {enable_peer_exchange}\nreject_private_advertise_addrs = {reject_private_advertise_addrs}\ndiscovery_port = {discovery_port}\ndiscovery_listen_address = \"0.0.0.0:{discovery_port}\"\ndiscovery_public_address = \"{runtime_discovery_public_address}\"\nheartbeat_interval = {heartbeat_interval_secs}\nbootstrap_refresh_secs = {bootstrap_refresh_secs}\n\n[storage]\ndatabase = \"rocksdb\"\nengine = \"rocksdb\"\npath = \"{data_path}\"\nmode = \"role-bounded\"\nenable_pruning = false\npruning_interval = 86400\n\n[node]\nbootstrap_only = false\nauto_register_validator = {auto_register_validator}\nvalidator_address = \"{node_address}\"\nstrict_validator_allowlist = {strict_validator_allowlist}\nallowed_validator_addresses = {allowed_validator_addresses}\n\n[telemetry]\nmetrics_bind = \"0.0.0.0:{metrics_port}\"\nstructured_logs = true\nlog_level = \"debug\"\n\n[policy]\nallow_remote_admin = false\nrequire_signed_updates = true\nquarantine_on_policy_failure = true\nquarantine_on_key_role_mismatch = true\nconnectivity_fail_mode = \"warn-and-continue\"\nparser_mode = \"{parser_mode}\"\n\n[wallet]\nreward_address = \"{node_address}\"\nsponsored_stake_snrg = \"{sponsored_stake_snrg}\"\nsponsored_stake_nwei = \"{sponsored_stake_nwei}\"\ntreasury_wallet = \"{treasury_wallet}\"\nstake_vault_wallet = \"{stake_wallet}\"\n[bootstrap]\nstatus = \"configured\"\nnote = \"{bootstrap_note}\"\n\n{role_overlay}",
        role_id = role.id,
        role_display = role.display_name,
        environment_id = TESTNET_ENVIRONMENT_ID,
        display_name = TESTNET_DISPLAY_NAME,
        config_node_id = config_node_id,
        chain_name = network_profile.chain_name,
        chain_id = network_profile.chain_id,
        network_id = network_profile.network_id,
        fork_height = TESTNET_FORK_HEIGHT,
        fork_parent_height = TESTNET_FORK_PARENT_HEIGHT,
        fork_parent_hash = TESTNET_FORK_PARENT_HASH,
        consensus_algorithm = TESTNET_CONSENSUS_ALGORITHM,
        validator_key_algorithm = TESTNET_VALIDATOR_KEY_ALGORITHM,
        parser_mode = TESTNET_PARSER_MODE,
        p2p_port = p2p_port,
        rpc_port = rpc_port,
        ws_port = ws_port,
        discovery_port = discovery_port,
        metrics_port = metrics_port,
        bootnodes = bootnodes,
        seeds = seeds,
        bootstrap_dns_records = bootstrap_dns_records,
        additional_dial_targets = additional_dial_targets,
        persistent_peers = persistent_peers,
        validator_vpn_transport_blocks = validator_vpn_transport_blocks,
        data_path = workspace_state_store_directory_for_role(&role.id, workspace_directory)
            .to_string_lossy()
            .replace('\\', "/"),
        log_path = workspace_directory
            .join("logs")
            .join("synergy-testnet.log")
            .to_string_lossy()
            .replace('\\', "/"),
        runtime_public_address = runtime_public_address,
        runtime_discovery_public_address = runtime_discovery_public_address,
        auto_register_validator = auto_register_validator,
        enable_discovery = enable_discovery,
        enable_seed_registration = enable_seed_registration,
        enable_peer_exchange = enable_peer_exchange,
        reject_private_advertise_addrs = reject_private_advertise_addrs,
        strict_validator_allowlist = strict_validator_allowlist,
        allowed_validator_addresses = allowed_validator_addresses,
        rpc_bind_address = rpc_bind_address,
        cors_enabled = cors_enabled,
        cors_origins = cors_origins,
        block_time_secs = TESTNET_BLOCK_TIME_SECS,
        epoch_length = TESTNET_EPOCH_LENGTH,
        min_validators = TESTNET_STATIC_MIN_VALIDATORS,
        validator_cluster_size = dynamic_validator_cluster_size,
        validator_vote_threshold = 0,
        max_validators = 0,
        status_ready_gate_enabled = TESTNET_STATUS_READY_GATE_ENABLED,
        status_ready_min_validators = TESTNET_STATIC_STATUS_READY_MIN_VALIDATORS,
        status_ready_genesis_grace_secs = TESTNET_STATUS_READY_GENESIS_GRACE_SECS,
        allow_genesis_status_bypass = TESTNET_ALLOW_GENESIS_STATUS_BYPASS,
        mesh_settle_secs = TESTNET_MESH_SETTLE_SECS,
        leader_timeout_secs = TESTNET_LEADER_TIMEOUT_SECS,
        vote_timeout_secs = TESTNET_VOTE_TIMEOUT_SECS,
        block_timeout_secs = TESTNET_BLOCK_TIMEOUT_SECS,
        penalization_enabled = TESTNET_CONSENSUS_PENALIZATION_ENABLED,
        bootstrap_refresh_secs = TESTNET_P2P_BOOTSTRAP_REFRESH_SECS,
        heartbeat_interval_secs = TESTNET_P2P_HEARTBEAT_INTERVAL_SECS,
        sponsored_stake_snrg = format_amount(MINIMUM_STAKE_SNRG),
        sponsored_stake_nwei = amount_to_nwei_string(MINIMUM_STAKE_SNRG),
        treasury_wallet = network_profile.treasury_wallet.address,
        stake_wallet = network_profile.stake_vault_wallet.address,
        bootstrap_note = bootstrap_note,
    );
    rendered
        .replace(&format!("0.0.0.0:{p2p_port}"), p2p_listen_address.as_str())
        .replace(
            &format!("0.0.0.0:{discovery_port}"),
            discovery_listen_address.as_str(),
        )
}

fn role_supports_validator_registration(role_id: &str) -> bool {
    matches!(role_id, "validator")
}

fn build_peers_toml(network_profile: &TestnetNetworkProfile) -> String {
    build_peers_toml_with_options(network_profile, &[], false)
}

fn build_peers_toml_with_additional(
    network_profile: &TestnetNetworkProfile,
    additional_dial_targets: &[String],
) -> String {
    build_peers_toml_with_options(network_profile, additional_dial_targets, true)
}

fn build_validator_vpn_peers_toml_with_additional(additional_dial_targets: &[String]) -> String {
    let additional = render_toml_string_array(additional_dial_targets);

    format!(
        "# Testnet validator Innernet peer inputs.\n# Validator peer identities are routable only when coordinator-signed validator_vpn_transports map them to 10.70.10.x.\n[global]\nbootnodes = []\nseed_servers = []\nbootstrap_dns_records = []\nadditional_dial_targets = [{additional}]\npersistent_peers = [{additional}]\n\n[testnet]\ncore_rpc = \"{core_rpc}\"\ncore_ws = \"{core_ws}\"\nwallet_api = \"https://testnet-wallet-api.synergy-network.io\"\nsxcp_api = \"https://testnet-sxcp-api.synergy-network.io\"\n\n[security]\nstrict_tls = true\nallow_unpinned_dev_endpoints = false\nbootstrap_connectivity_required = false\n",
        core_rpc = TESTNET_PUBLIC_RPC_ENDPOINT,
        core_ws = TESTNET_PUBLIC_WS_ENDPOINT,
    )
}

fn build_peers_toml_with_options(
    network_profile: &TestnetNetworkProfile,
    additional_dial_targets: &[String],
    explicit_upstreams: bool,
) -> String {
    let _use_explicit_upstreams = explicit_upstreams && !additional_dial_targets.is_empty();
    let bootnodes = render_toml_string_array(&endpoint_socket_entries(&network_profile.bootnodes));
    let seeds = render_toml_string_array(&endpoint_http_entries(&network_profile.seed_servers));
    let bootstrap_dns_records =
        render_toml_string_array(&[TESTNET_BOOTSTRAP_DNS_RECORD.to_string()]);
    let additional = additional_dial_targets
        .iter()
        .map(|t| format!("\"{}\"", t.replace('"', "\\\"")))
        .collect::<Vec<_>>()
        .join(", ");

    format!(
        "# Testnet peer inputs.\n# Explicit additional_dial_targets take precedence over public bootstrap discovery.\n[global]\nbootnodes = [{bootnodes}]\nseed_servers = [{seeds}]\nbootstrap_dns_records = [{bootstrap_dns_records}]\nadditional_dial_targets = [{additional}]\npersistent_peers = [{additional}]\n\n[testnet]\ncore_rpc = \"{core_rpc}\"\ncore_ws = \"{core_ws}\"\nwallet_api = \"https://testnet-wallet-api.synergy-network.io\"\nsxcp_api = \"https://testnet-sxcp-api.synergy-network.io\"\n\n[security]\nstrict_tls = true\nallow_unpinned_dev_endpoints = false\nbootstrap_connectivity_required = false\n",
        core_rpc = TESTNET_PUBLIC_RPC_ENDPOINT,
        core_ws = TESTNET_PUBLIC_WS_ENDPOINT,
        bootstrap_dns_records = bootstrap_dns_records,
    )
}

fn build_aegis_toml() -> String {
    "[verify]\nenabled = true\nendpoint = \"https://127.0.0.1:3050\"\n\n[kms]\nenabled = true\nendpoint = \"https://127.0.0.1:3051\"\nmtls = true\n\n[lifecycle]\nquarantine_on_key_role_mismatch = true\nrequire_rotation_receipts = true\n".to_string()
}

fn build_node_readme(
    display_label: &str,
    role: &TestnetRoleProfile,
    node_address: &str,
    workspace_directory: &Path,
    network_profile: &TestnetNetworkProfile,
    public_host: Option<&str>,
) -> String {
    let public_host_note = normalize_optional(public_host)
        .map(|value| format!("- Public host: `{value}`\n"))
        .unwrap_or_else(|| "- Public host: pending assignment\n".to_string());
    let responsibilities = role
        .responsibilities
        .iter()
        .map(|entry| format!("- {entry}\n"))
        .collect::<String>();
    let policies = role
        .policy_highlights
        .iter()
        .map(|entry| format!("- {entry}\n"))
        .collect::<String>();
    let root_label = if role.id == "validator" {
        "Validator appliance root"
    } else {
        "Workspace"
    };
    let generated_label = if role.id == "validator" {
        "validator appliance root"
    } else {
        "isolated workspace"
    };

    let validator_mesh = canonical_testnet_validator_peers()
        .into_iter()
        .map(|entry| {
            format!(
                "{}:{}",
                entry.public_host,
                canonical_public_p2p_port_for_validator_slot(entry.slot)
            )
        })
        .collect::<Vec<_>>()
        .join(", ");
    let sentry_upstreams = canonical_sentry_public_dial_targets_for_role(&role.id).join(", ");
    let bootstrap_section = if validator_uses_private_mesh(&role.id, node_address) {
        format!(
            "## Validator bootstrap\n- Public validator peers: {validator_mesh}\n- Direct-IP bootstrap endpoints remain available.\n\nThe generated validator configuration is wired for public validator routing.\n"
        )
    } else if role.id == "validator" {
        format!(
            "## Validator bootstrap\n- Bootnodes: {}\n- Seeds: {}\n- Bootstrap DNS: {TESTNET_BOOTSTRAP_DNS_RECORD}\n\nThe generated validator configuration starts from DNS bootnodes, DNS seed services, seed registration, and peer exchange. P2P reachability does not grant consensus activation.\n",
            endpoint_socket_entries(&network_profile.bootnodes).join(", "),
            endpoint_http_entries(&network_profile.seed_servers).join(", "),
        )
    } else if role_uses_sentry_upstreams(&role.id) && !sentry_upstreams.is_empty() {
        format!(
            "## Sentry upstreams\n- Public sentry peers: {sentry_upstreams}\n- Direct validator dialing: disabled\n\nThe generated public-edge configuration is pinned to the sentry pair so public services do not join the validator quorum plane directly.\n"
        )
    } else {
        format!(
            "## Bootstrap endpoints\n- Bootnodes: {}\n- Seeds: {}\n- Bootstrap DNS: {TESTNET_BOOTSTRAP_DNS_RECORD}\n\nThe generated node configuration is wired for DNS bootstrap on startup.\n",
            endpoint_socket_entries(&network_profile.bootnodes).join(", "),
            endpoint_http_entries(&network_profile.seed_servers).join(", "),
        )
    };

    format!(
        "# {display_label}\n\nThis {generated_label} was generated for the `{role_display}` role on `{environment}`.\n\n## {root_label}\n- Path: `{workspace}`\n- Node wallet: `{reward_wallet}`\n- Reserved minimum stake: `{stake}`\n{public_host_note}\n## Role responsibilities\n{responsibilities}\n## Policy guardrails\n{policies}\n{bootstrap_section}",
        role_display = role.display_name,
        environment = TESTNET_DISPLAY_NAME,
        generated_label = generated_label,
        root_label = root_label,
        workspace = workspace_directory.to_string_lossy(),
        reward_wallet = node_address,
        stake = format_amount(MINIMUM_STAKE_SNRG),
        responsibilities = responsibilities,
        policies = policies,
        bootstrap_section = bootstrap_section,
    )
}

