    #[test]
    fn large_chain_boundary_streams_first_block_only() {
        let temp = TempDir::new().expect("temp workspace");
        let data_dir = temp.path().join("data");
        fs::create_dir_all(&data_dir).expect("data dir");
        let chain_path = data_dir.join("chain.json");
        let mut file = File::create(&chain_path).expect("chain file should write");
        file.write_all(
            br#"[{
                "block_index": 307043,
                "hash": "bc5bf7620f2a9f170a32119f2355d8958f4a379dfd56dcb11c80573855c17804",
                "previous_hash": "e209bd7554a06dfb052d5ff7ffd5664efc05e6cd1c5cadc9d139fa5bb9072816"
            },"#,
        )
        .expect("first block should write");
        file.set_len(TESTNET_CHAIN_BOUNDARY_MAX_FULL_PARSE_BYTES + 1)
            .expect("large sparse chain file should size");

        let boundary = workspace_chain_file_boundary(temp.path())
            .expect("large chain boundary should parse")
            .expect("boundary should exist");

        assert_eq!(boundary.height, 307043);
        assert_eq!(
            boundary.hash,
            "bc5bf7620f2a9f170a32119f2355d8958f4a379dfd56dcb11c80573855c17804"
        );
        assert_eq!(
            boundary.parent_hash,
            "e209bd7554a06dfb052d5ff7ffd5664efc05e6cd1c5cadc9d139fa5bb9072816"
        );
    }

    struct EnvVarGuard {
        key: &'static str,
        previous: Option<OsString>,
    }

    struct CurrentDirGuard {
        previous: PathBuf,
    }

    impl EnvVarGuard {
        fn set_value(key: &'static str, value: &str) -> Self {
            let previous = std::env::var_os(key);
            std::env::set_var(key, value);
            Self { key, previous }
        }

        fn set_path(key: &'static str, value: &Path) -> Self {
            let previous = std::env::var_os(key);
            std::env::set_var(key, value);
            Self { key, previous }
        }
    }

    impl CurrentDirGuard {
        fn set(path: &Path) -> Self {
            let previous = std::env::current_dir().expect("current dir should resolve");
            std::env::set_current_dir(path).expect("current dir should update");
            Self { previous }
        }
    }

    impl Drop for EnvVarGuard {
        fn drop(&mut self) {
            if let Some(previous) = &self.previous {
                std::env::set_var(self.key, previous);
            } else {
                std::env::remove_var(self.key);
            }
        }
    }

    impl Drop for CurrentDirGuard {
        fn drop(&mut self) {
            let _ = std::env::set_current_dir(&self.previous);
        }
    }

    fn env_lock() -> MutexGuard<'static, ()> {
        ENV_LOCK
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }

