    #[test]
    fn validator_speed_sync_pause_marker_repairs_legacy_timestamp_and_preserves_evidence() {
        let temp = TempDir::new().expect("temp workspace");
        let node = test_onboarding_node(temp.path());
        let marker_path = validator_consensus_pause_marker_path(temp.path());
        let evidence_path = temp.path().join("evidence").join("speed-sync.json");
        let legacy_detected_at = "2026-07-14T12:34:56-05:00";
        let marker = json!({
            "validator_id": node.node_address.clone(),
            "reason": VALIDATOR_SPEED_SYNC_PAUSE_REASON,
            "detected_height": 9000,
            "detected_hash": "speed-sync-local-height",
            "quorum_majority_height": 10000,
            "quorum_majority_hash": "verified-chain-head",
            "local_conflicting_height": 5000,
            "local_conflicting_hash": "verified-archive-snapshot",
            "evidence_path": evidence_path.to_string_lossy(),
            "detected_at": legacy_detected_at,
            "recovery_state": "QUARANTINED",
            "voting_disabled": true,
            "proposing_disabled": true,
            "qc_aggregation_disabled": true,
            "canonical_source_disabled": true,
            "rejoin_eligibility": false,
            "evidence": {"source": "legacy-validator"}
        });
        write_json_file(&marker_path, &marker).expect("legacy marker should write");

        assert!(repair_validator_speed_sync_pause_marker(&node, temp.path())
            .expect("legacy marker should repair"));
        let repaired = read_json_value(&marker_path).expect("repaired marker should parse");
        let expected_detected_at = DateTime::parse_from_rfc3339(legacy_detected_at)
            .expect("test timestamp should parse")
            .timestamp() as u64;
        assert_eq!(
            repaired.get("detected_at").and_then(Value::as_u64),
            Some(expected_detected_at)
        );
        assert_eq!(
            repaired.get("reason").and_then(Value::as_str),
            Some(VALIDATOR_SPEED_SYNC_PAUSE_REASON)
        );
        assert_eq!(
            repaired.get("evidence_path").and_then(Value::as_str),
            Some(evidence_path.to_string_lossy().as_ref())
        );
        assert_eq!(
            repaired
                .get("evidence")
                .and_then(|value| value.get("source")),
            Some(&json!("legacy-validator"))
        );
        assert!(
            !repair_validator_speed_sync_pause_marker(&node, temp.path())
                .expect("repaired marker should be idempotent")
        );
    }

