    #[test]
    fn cluster_membership_snapshot_accepts_two_five_validator_clusters() {
        let active_validators = (1..=10)
            .map(|index| format!("synv1validator{index:02}"))
            .collect::<Vec<_>>();
        let snapshot = json!({
            "epoch_id": 12,
            "cluster_count": 2,
            "cluster_assignments_complete": true,
            "cluster_assignment_epoch": 12,
            "cluster_assignment_effective_height": 12_002,
            "cluster_randomness_source": "finalized-boundary-qc-seed",
            "cluster_map_hash": "a".repeat(64),
            "membership_bundle_hash": "b".repeat(64),
            "cluster_assignments": [
                {
                    "cluster_id": 0,
                    "cluster_address": "syngrp1cluster0",
                    "validator_ids": active_validators[..5].to_vec(),
                    "quorum_threshold": 4,
                    "fault_tolerance_f": 1,
                    "assignment_epoch": 12,
                    "assignment_effective_height": 12_002
                },
                {
                    "cluster_id": 1,
                    "cluster_address": "syngrp1cluster1",
                    "validator_ids": active_validators[5..].to_vec(),
                    "quorum_threshold": 4,
                    "fault_tolerance_f": 1,
                    "assignment_epoch": 12,
                    "assignment_effective_height": 12_002
                }
            ]
        });

        let validated = validate_cluster_membership_snapshot(&snapshot, &active_validators)
            .expect("two balanced strict 4-of-5 clusters should validate");

        assert_eq!(validated.cluster_count, 2);
        assert_eq!(validated.assignments.len(), 2);
        assert!(validated
            .assignments
            .iter()
            .all(|assignment| assignment.quorum_threshold == 4));
    }

