    fn sign_innernet_receipt_for_test(
        signing_key: &SigningKey,
        receipt: &mut innernet::InnernetMembershipReceipt,
    ) {
        let payload = serde_json::to_vec(&json!({
            "version": receipt.version,
            "network": receipt.network,
            "migration_id": receipt.migration_id,
            "enrollment_id": receipt.enrollment_id,
            "node_id": receipt.node_id,
            "peer_name": receipt.peer_name,
            "peer_type": receipt.peer_type,
            "assigned_ip": receipt.assigned_ip,
            "interface_name": receipt.interface_name,
            "configuration_version": receipt.configuration_version,
            "confirmed_at": receipt.confirmed_at,
        }))
        .expect("receipt payload should serialize");
        receipt.signature = format!(
            "ed25519:{}",
            general_purpose::STANDARD.encode(signing_key.sign(&payload).to_bytes())
        );
    }

    fn sign_innernet_transport_snapshot_for_test(
        signing_key: &SigningKey,
        snapshot: &mut innernet::InnernetValidatorTransportSnapshot,
    ) {
        let payload = serde_json::to_vec(&json!({
            "version": snapshot.version,
            "network": snapshot.network,
            "migration_id": snapshot.migration_id,
            "configuration_version": snapshot.configuration_version,
            "transports": snapshot.transports,
        }))
        .expect("transport snapshot payload should serialize");
        snapshot.signature = format!(
            "ed25519:{}",
            general_purpose::STANDARD.encode(signing_key.sign(&payload).to_bytes())
        );
    }

    #[test]
    fn testnet_backup_keys_exports_encrypted_key_material_without_plaintext_private_key() {
        with_temp_home(|home| {
            let root = ensure_testnet_root().expect("testnet root should exist");
            let workspace = home.join("validator-workspace");
            let identity_directory = workspace.join("identity");
            let config_directory = workspace.join("config");
            fs::create_dir_all(&identity_directory).expect("identity directory should exist");
            fs::create_dir_all(&config_directory).expect("config directory should exist");

            fs::write(identity_directory.join("private.key"), "plain-private-key")
                .expect("plaintext key fixture should write");
            fs::write(
                identity_directory.join("private.key.enc"),
                "{\"ciphertext\":\"encrypted\"}",
            )
            .expect("encrypted key fixture should write");
            fs::write(identity_directory.join("public.key"), "public-key")
                .expect("public key fixture should write");
            write_json_file(
                &identity_directory.join("identity.json"),
                &json!({
                    "address": "synv11onboardingvalidatorxxxxxxxxxxxxxx",
                    "public_key": "public-key"
                }),
            )
            .expect("identity metadata should write");
            write_json_file(
                &config_directory.join("identity.json"),
                &json!({
                    "address": "synv11onboardingvalidatorxxxxxxxxxxxxxx"
                }),
            )
            .expect("config identity metadata should write");

            let mut node = test_onboarding_node(&workspace);
            node.public_key_path = identity_directory
                .join("public.key")
                .to_string_lossy()
                .to_string();
            node.private_key_path = identity_directory
                .join("private.key")
                .to_string_lossy()
                .to_string();
            node.encrypted_private_key_path = Some(
                identity_directory
                    .join("private.key.enc")
                    .to_string_lossy()
                    .to_string(),
            );
            save_registry(
                &root,
                &TestnetRegistryFile {
                    version: STATE_VERSION,
                    nodes: vec![node.clone()],
                },
            )
            .expect("registry should save");

            let target = home.join("validator-backup.tar.gz");
            let result = testnet_backup_keys(TestnetFilesystemTargetInput {
                node_id: node.id,
                target: Some(target.to_string_lossy().to_string()),
                source: None,
            })
            .expect("encrypted key backup should succeed");
            assert_eq!(result.status, "created");

            let file = File::open(&target).expect("backup archive should exist");
            let decoder = GzDecoder::new(file);
            let mut archive = Archive::new(decoder);
            let entries = archive
                .entries()
                .expect("archive entries should read")
                .map(|entry| {
                    entry
                        .expect("archive entry should read")
                        .path()
                        .expect("archive path should read")
                        .to_string_lossy()
                        .to_string()
                })
                .collect::<Vec<_>>();

            assert!(entries
                .iter()
                .any(|entry| entry == "identity/private.key.enc"));
            assert!(!entries.iter().any(|entry| entry == "identity/private.key"));
        });
    }

