    #[derive(Serialize)]
    struct TestValidatorVpnSnapshotSigningPayload<'a> {
        generation: u64,
        network: &'a str,
        cidr: &'a str,
        created_at: &'a str,
        relayers: &'a [ValidatorVpnPeerRecord],
        validators: &'a [ValidatorVpnPeerRecord],
        removed: &'a [crate::validator_vpn::ValidatorVpnRemovedPeer],
    }

    fn sign_test_validator_vpn_snapshot(snapshot: &mut Value) {
        let typed_snapshot = serde_json::from_value::<ValidatorVpnPeerSnapshot>(snapshot.clone())
            .expect("test snapshot should deserialize to production snapshot");
        let payload = TestValidatorVpnSnapshotSigningPayload {
            generation: typed_snapshot.generation,
            network: &typed_snapshot.network,
            cidr: &typed_snapshot.cidr,
            created_at: &typed_snapshot.created_at,
            relayers: &typed_snapshot.relayers,
            validators: &typed_snapshot.validators,
            removed: &typed_snapshot.removed,
        };
        let bytes = serde_json::to_vec(&payload).expect("test snapshot payload should encode");
        let mut hasher = Sha256::new();
        hasher.update(TEST_VALIDATOR_VPN_SIGNING_KEY.as_bytes());
        hasher.update(b":");
        hasher.update(bytes);
        snapshot["signature"] = json!(format!("sha256:{:x}", hasher.finalize()));
    }

