    fn env_var_guard(key: &'static str, value: &str) -> EnvVarGuard {
        let previous = std::env::var_os(key);
        std::env::set_var(key, value);
        EnvVarGuard { key, previous }
    }

    #[test]
    fn configured_archive_snapshot_catalog_sources_can_be_overridden_with_fallback_urls() {
        let _lock = env_lock();
        std::env::remove_var("SYNERGY_ARCHIVE_SNAPSHOT_CATALOG_URL");
        std::env::remove_var("SYNERGY_ARCHIVE_SNAPSHOT_BASE_URL");
        let catalog_urls_guard = env_var_guard(
            "SYNERGY_ARCHIVE_SNAPSHOT_CATALOG_URLS",
            "https://example.com/archive-a/catalog.json , https://example.com/archive-b/catalog.json",
        );
        let base_urls_guard = env_var_guard(
            "SYNERGY_ARCHIVE_SNAPSHOT_BASE_URLS",
            "https://example.com/archive-a-root , https://example.com/archive-b-root",
        );

        let sources = archive_snapshot_sources();

        assert_eq!(sources.len(), 2);
        assert_eq!(
            sources[0].catalog_url,
            "https://example.com/archive-a/catalog.json"
        );
        assert_eq!(sources[0].base_url, "https://example.com/archive-a-root");
        assert_eq!(
            sources[1].catalog_url,
            "https://example.com/archive-b/catalog.json"
        );
        assert_eq!(sources[1].base_url, "https://example.com/archive-b-root");

        drop(catalog_urls_guard);
        drop(base_urls_guard);
    }

    #[test]
    fn configured_archive_snapshot_sources_use_public_catalog_without_env_vars() {
        let _lock = env_lock();
        std::env::remove_var("SYNERGY_ARCHIVE_SNAPSHOT_CATALOG_URLS");
        std::env::remove_var("SYNERGY_ARCHIVE_SNAPSHOT_CATALOG_URL");
        std::env::remove_var("SYNERGY_ARCHIVE_SNAPSHOT_BASE_URLS");
        std::env::remove_var("SYNERGY_ARCHIVE_SNAPSHOT_BASE_URL");

        let catalog_urls = configured_archive_snapshot_catalog_urls();
        assert_eq!(
            catalog_urls,
            vec![TESTNET_PUBLIC_ARCHIVE_SNAPSHOT_CATALOG_URL.to_string()]
        );
        assert!(
            catalog_urls
                .iter()
                .all(|value| !value.contains("10.69.0.") && !value.contains("127.0.0.1")),
            "public defaults must not require VPN or loopback archive access"
        );

        let sources = archive_snapshot_sources();
        assert_eq!(sources.len(), 1);
        assert_eq!(
            sources[0].catalog_url,
            TESTNET_PUBLIC_ARCHIVE_SNAPSHOT_CATALOG_URL
        );
        assert_eq!(
            sources[0].base_url,
            "https://archive-store.synergynode.xyz/snapshots"
        );
    }

