    #[test]
    fn archive_snapshot_freshness_requires_recent_catalog_and_verified_snapshot() {
        let now = 1_800_000_000;
        let mut catalog = complete_test_archive_snapshot_catalog(vec![]);
        catalog["updated_at"] = json!(now);
        let mut snapshot = catalog
            .get("snapshots")
            .and_then(Value::as_array)
            .and_then(|snapshots| {
                snapshots.iter().find(|entry| {
                    entry.get("snapshot_id").and_then(Value::as_str) == Some("snapshot-000239900")
                })
            })
            .cloned()
            .expect("selected snapshot");
        snapshot["last_verified_at"] = json!(now);

        assert!(validate_archive_snapshot_freshness(&catalog, &snapshot, now).is_ok());

        catalog["updated_at"] = json!(now - TESTNET_ARCHIVE_SNAPSHOT_MAX_AGE_SECS - 1);
        assert!(
            validate_archive_snapshot_freshness(&catalog, &snapshot, now)
                .expect_err("stale catalog must be rejected")
                .contains("snapshot catalog")
        );

        catalog["updated_at"] = json!(now);
        snapshot["last_verified_at"] = json!(now - TESTNET_ARCHIVE_SNAPSHOT_MAX_AGE_SECS - 1);
        assert!(
            validate_archive_snapshot_freshness(&catalog, &snapshot, now)
                .expect_err("stale snapshot must be rejected")
                .contains("validator-pruned snapshot")
        );
    }

