    #[test]
    fn setup_sync_gate_requires_snapshot_restore_catch_up_and_activation_confirmation() {
        with_temp_home(|home| {
            let root = ensure_testnet_root().expect("testnet root should exist");
            let workspace = home.join("validator-workspace");
            let node = test_onboarding_node(&workspace);
            save_registry(
                &root,
                &TestnetRegistryFile {
                    version: STATE_VERSION,
                    nodes: vec![node.clone()],
                },
            )
            .expect("registry should save");

            let state = testnet_get_state().expect("state should load");
            assert_eq!(state.nodes.len(), 1);
            assert!(state.nodes[0].setup_sync_required);
            assert!(
                state.nodes[0]
                    .setup_sync_reason
                    .as_deref()
                    .is_some_and(
                        |reason| reason.contains("verified normal peer synchronization")
                            && reason.contains("validator-pruned snapshot restore")
                    ),
                "missing restore reason: {:?}",
                state.nodes[0].setup_sync_reason
            );

            let missing_restore_error =
                testnet_mark_setup_sync_complete(TestnetSetupSyncCompleteInput {
                    node_id: node.id.clone(),
                    local_chain_height: Some(5001),
                    sync_target_height: Some(5002),
                    sync_gap: Some(1),
                    sync_mode: None,
                })
                .expect_err("sync completion should require snapshot restore evidence");
            assert!(
                missing_restore_error.contains("snapshot restore evidence is verified"),
                "{missing_restore_error}"
            );

            write_test_validator_snapshot_restore_evidence(&node);

            let state = testnet_get_state().expect("state should reload");
            assert!(
                state.nodes[0].setup_sync_required,
                "verified snapshot restore alone must not clear Jarvis onboarding: {:?}",
                state.nodes[0].setup_sync_reason
            );
            assert!(
                state.nodes[0]
                    .setup_sync_reason
                    .as_deref()
                    .is_some_and(|reason| reason.contains("snapshot-backed catch-up")),
                "missing catch-up reason: {:?}",
                state.nodes[0].setup_sync_reason
            );

            let large_gap_error = testnet_mark_setup_sync_complete(TestnetSetupSyncCompleteInput {
                node_id: node.id.clone(),
                local_chain_height: Some(5001),
                sync_target_height: Some(5008),
                sync_gap: Some(7),
                sync_mode: None,
            })
            .expect_err("sync completion should reject validators that are still behind");
            assert!(
                large_gap_error.contains("sync gap is above"),
                "{large_gap_error}"
            );

            let result = testnet_mark_setup_sync_complete(TestnetSetupSyncCompleteInput {
                node_id: node.id.clone(),
                local_chain_height: Some(5006),
                sync_target_height: Some(5008),
                sync_gap: Some(2),
                sync_mode: None,
            })
            .expect("sync completion should succeed after verified restore and catch-up");

            let evidence_path = PathBuf::from(&result.evidence_path);
            let evidence = read_json_value(&evidence_path).expect("sync evidence should parse");
            assert_eq!(evidence.get("status").and_then(Value::as_str), Some("ok"));
            assert_eq!(
                evidence.get("snapshot_class").and_then(Value::as_str),
                Some("validator-pruned")
            );
            assert_eq!(
                evidence
                    .get("snapshot_restore_verified")
                    .and_then(Value::as_bool),
                Some(true)
            );
            assert_eq!(
                evidence.get("local_chain_height").and_then(Value::as_u64),
                Some(5006)
            );

            let state = testnet_get_state().expect("state should reload after sync completion");
            assert!(
                state.nodes[0].setup_sync_required,
                "snapshot restore and catch-up must still keep Jarvis open before funding/staking/activation"
            );
            assert!(
                state.nodes[0]
                    .setup_sync_reason
                    .as_deref()
                    .is_some_and(|reason| reason.contains(
                        "funding, staking, shadow evidence, and activation confirmation"
                    )),
                "missing activation reason: {:?}",
                state.nodes[0].setup_sync_reason
            );

            write_test_validator_activation_confirmation_evidence(&node);

            let state =
                testnet_get_state().expect("state should reload after activation confirmation");
            assert!(!state.nodes[0].setup_sync_required);
            assert!(state.nodes[0].setup_sync_reason.is_none());
        });
    }

