    #[test]
    fn normal_sync_completion_requires_fresh_local_canonical_head_evidence() {
        with_temp_home(|home| {
            let root = ensure_testnet_root().expect("testnet root should exist");
            let workspace = home.join("normal-sync-validator-workspace");
            let node = test_onboarding_node(&workspace);
            save_registry(
                &root,
                &TestnetRegistryFile {
                    version: STATE_VERSION,
                    nodes: vec![node.clone()],
                },
            )
            .expect("registry should save");

            let missing_head_error =
                testnet_mark_setup_sync_complete(TestnetSetupSyncCompleteInput {
                    node_id: node.id.clone(),
                    local_chain_height: Some(5008),
                    sync_target_height: Some(5008),
                    sync_gap: Some(0),
                    sync_mode: Some("normal".to_string()),
                })
                .expect_err("normal mode selection must not count as setup completion");
            assert!(
                missing_head_error.contains("Normal peer sync cannot complete setup sync"),
                "{missing_head_error}"
            );

            write_test_normal_sync_head_evidence(&node, 5008);
            let listener = TcpListener::bind("127.0.0.1:0")
                .expect("normal-sync account RPC listener should bind");
            let rpc_port = listener
                .local_addr()
                .expect("normal-sync account RPC listener address should resolve")
                .port();
            let config_directory = workspace.join("config");
            fs::create_dir_all(&config_directory)
                .expect("normal-sync config directory should exist");
            fs::write(
                config_directory.join("node.toml"),
                format!("[rpc]\nhttp_port = {rpc_port}\n"),
            )
            .expect("normal-sync RPC config should write");
            let public_endpoint = EnvVarGuard::set_value(
                "SYNERGY_TEST_NORMAL_SYNC_PUBLIC_RPC_ENDPOINT",
                &format!("http://127.0.0.1:{rpc_port}"),
            );
            let rpc_server = thread::spawn(move || {
                for _ in 0..12 {
                    let (mut stream, _) = listener
                        .accept()
                        .expect("normal-sync account RPC request should connect");
                    let mut request = [0u8; 16 * 1024];
                    let length = stream
                        .read(&mut request)
                        .expect("normal-sync account RPC request should read");
                    let request = String::from_utf8_lossy(&request[..length]);
                    let result = if request.contains("synergy_getTokenBalance") {
                        json!(101)
                    } else if request.contains("synergy_getStakedBalance") {
                        json!(202)
                    } else {
                        json!([])
                    };
                    let body = json!({
                        "jsonrpc": "2.0",
                        "id": 1,
                        "result": result,
                    })
                    .to_string();
                    let response = format!(
                        "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
                        body.len(),
                        body
                    );
                    stream
                        .write_all(response.as_bytes())
                        .expect("normal-sync account RPC response should write");
                }
            });

            let mismatch_error = testnet_mark_setup_sync_complete(TestnetSetupSyncCompleteInput {
                node_id: node.id.clone(),
                local_chain_height: Some(5007),
                sync_target_height: Some(5008),
                sync_gap: Some(1),
                sync_mode: Some("normal".to_string()),
            })
            .expect_err("normal mode must reject a local height below the verified head");
            assert!(
                mismatch_error.contains("verified canonical head is h5008"),
                "{mismatch_error}"
            );

            let result = testnet_mark_setup_sync_complete(TestnetSetupSyncCompleteInput {
                node_id: node.id.clone(),
                local_chain_height: Some(5008),
                sync_target_height: Some(5008),
                sync_gap: Some(0),
                sync_mode: Some("normal".to_string()),
            })
            .expect("verified normal peer sync should complete setup sync");
            let evidence = read_json_value(Path::new(&result.evidence_path))
                .expect("normal setup completion evidence should parse");
            assert_eq!(
                evidence.get("sync_mode").and_then(Value::as_str),
                Some("normal")
            );
            assert_eq!(
                evidence
                    .get("snapshot_restore_verified")
                    .and_then(Value::as_bool),
                Some(false)
            );
            assert_eq!(
                evidence
                    .get("head_match_evidence_verified")
                    .and_then(Value::as_bool),
                Some(true)
            );
            assert_eq!(
                evidence
                    .get("account_state_parity_verified")
                    .and_then(Value::as_bool),
                Some(true)
            );
            assert_eq!(
                evidence
                    .get("account_state_parity_proof")
                    .and_then(|proof| proof.get("local_balance_nwei"))
                    .and_then(Value::as_u64),
                Some(101)
            );
            assert!(validator_setup_sync_complete_evidence_is_verified(&node));

            drop(public_endpoint);
            rpc_server
                .join()
                .expect("normal-sync account RPC server should exit");

            let state = testnet_get_state()
                .expect("state should accept verified normal synchronization evidence");
            assert!(state.nodes[0].setup_sync_required);
            assert!(
                state.nodes[0]
                    .setup_sync_reason
                    .as_deref()
                    .is_some_and(|reason| reason.contains(
                        "funding, staking, shadow evidence, and activation confirmation"
                    )),
                "verified normal sync must advance beyond the snapshot gate: {:?}",
                state.nodes[0].setup_sync_reason
            );
        });
    }

    #[test]
    fn validator_pruned_snapshot_apply_copies_linux_state_layout_files() {
        let temp = TempDir::new().expect("temp workspace");
        let workspace = temp.path().join("validator-workspace");
        let snapshot_root = temp.path().join("snapshot-root");
        fs::create_dir_all(&snapshot_root).expect("snapshot root should exist");
        fs::write(snapshot_root.join("chain.json"), "[]").expect("chain should write");
        fs::write(snapshot_root.join("committed_blocks.jsonl"), "{}\n")
            .expect("committed blocks should write");
        fs::write(snapshot_root.join("canonical_locks.json"), "{}")
            .expect("canonical locks should write");
        fs::write(snapshot_root.join("committed_qcs.json"), "[]")
            .expect("committed qcs should write");
        fs::write(snapshot_root.join("committed_qcs.jsonl"), "{}\n")
            .expect("committed qcs jsonl should write");
        fs::write(snapshot_root.join("dag_state.json"), "{}").expect("dag should write");
        fs::write(snapshot_root.join("token_state.json"), "{}").expect("token should write");
        fs::write(snapshot_root.join("validator_registry.json"), "[]")
            .expect("registry should write");
        fs::create_dir_all(snapshot_root.join("consensus_proposals"))
            .expect("consensus proposals should exist");
        fs::write(
            snapshot_root
                .join("consensus_proposals")
                .join("proposal.json"),
            "{}",
        )
        .expect("proposal should write");
        fs::create_dir_all(snapshot_root.join("testnet15")).expect("testnet15 should exist");
        fs::write(snapshot_root.join("testnet15").join("state.db"), "state")
            .expect("testnet15 state should write");
        let legacy_data = workspace.join("data");
        let stale_store = workspace_state_store_directory(&workspace);
        fs::create_dir_all(&stale_store).expect("existing state store should exist");
        fs::write(stale_store.join("unmanaged-stale-state.json"), "stale")
            .expect("stale state should write");
        fs::create_dir_all(&legacy_data).expect("legacy data should exist");
        fs::write(
            legacy_data.join("validator_registry.json"),
            "stale registry",
        )
        .expect("legacy registry should write");
        fs::write(legacy_data.join("synergy-testnet.pid"), "1234")
            .expect("legacy pid should write");

        let apply_result =
            apply_validator_pruned_snapshot_state(&workspace, &snapshot_root, 675736)
                .expect("snapshot state should apply");
        let copied_paths = apply_result
            .get("copied_paths")
            .and_then(Value::as_array)
            .expect("copied paths should be recorded")
            .iter()
            .filter_map(Value::as_str)
            .collect::<Vec<_>>();
        let data_directory = workspace_state_store_directory(&workspace);

        assert!(copied_paths.contains(&"committed_blocks.jsonl"));
        assert!(copied_paths.contains(&"consensus_proposals/"));
        assert!(copied_paths.contains(&"testnet15/"));
        assert!(data_directory.join("committed_blocks.jsonl").is_file());
        assert!(data_directory
            .join("consensus_proposals")
            .join("proposal.json")
            .is_file());
        assert!(data_directory.join("testnet15").join("state.db").is_file());
        assert!(
            !data_directory.join("unmanaged-stale-state.json").exists(),
            "the active state store must be an exact staged snapshot, not a partial overlay"
        );
        let backup_store = apply_result
            .get("backup_store_directory")
            .and_then(Value::as_str)
            .expect("existing state should be retained as a complete backup");
        assert!(Path::new(backup_store)
            .join("unmanaged-stale-state.json")
            .is_file());
        assert!(
            !legacy_data.exists(),
            "snapshot apply should purge stale managed legacy data state"
        );
        assert!(apply_result
            .get("purged_legacy_paths")
            .and_then(Value::as_array)
            .is_some_and(|paths| !paths.is_empty()));
    }

    #[test]
    fn validator_pruned_snapshot_apply_rejects_missing_token_state_before_mutation() {
        let temp = TempDir::new().expect("temp workspace");
        let workspace = temp.path().join("validator-workspace");
        let snapshot_root = temp.path().join("snapshot-root");
        fs::create_dir_all(&snapshot_root).expect("snapshot root should exist");
        for (name, contents) in [
            ("chain.json", "[]"),
            ("committed_blocks.jsonl", "{}\n"),
            ("canonical_locks.json", "{}"),
            ("committed_qcs.jsonl", "{}\n"),
            ("validator_registry.json", "[]"),
        ] {
            fs::write(snapshot_root.join(name), contents).expect("snapshot file should write");
        }
        let active_store = workspace_state_store_directory(&workspace);
        fs::create_dir_all(&active_store).expect("active store should exist");
        let sentinel = active_store.join("sentinel.json");
        fs::write(&sentinel, "preserve").expect("sentinel should write");

        let error = apply_validator_pruned_snapshot_state(&workspace, &snapshot_root, 675736)
            .expect_err("snapshot without token state must fail closed");

        assert!(
            error.contains("token_state.json"),
            "unexpected error: {error}"
        );
        assert_eq!(
            fs::read_to_string(sentinel).expect("active state must remain untouched"),
            "preserve"
        );
        assert!(!workspace.join("snapshot-restore-backups").exists());
    }

