    #[test]
    fn shadow_height_accepts_local_plus_two_of_three_relayers() {
        let height = 246_001;
        let hash = "canonical-hash";
        let result = evaluate_shadow_epoch_height(
            height,
            vec![
                (
                    test_shadow_rpc_source("local-validator"),
                    Ok(test_shadow_block(height, hash)),
                ),
                (
                    test_shadow_rpc_source("relayer-1"),
                    Ok(test_shadow_block(height, hash)),
                ),
                (
                    test_shadow_rpc_source("relayer-2"),
                    Err("temporary RPC timeout".to_string()),
                ),
                (
                    test_shadow_rpc_source("relayer-3"),
                    Ok(test_shadow_block(height, hash)),
                ),
            ],
        );

        assert!(result.observed);
        assert!(!result.mismatch);
        assert!(!result.missed);
        assert_eq!(
            result
                .sample
                .as_ref()
                .and_then(|sample| sample.get("responding_relayers"))
                .and_then(Value::as_u64),
            Some(2)
        );
    }

