    #[test]
    fn unfinished_shadow_observation_resets_after_stale_window() {
        let stale = json!({
            "status": "observing",
            "required_full_shadow_epoch_start": 246_001,
            "required_full_shadow_epoch_end": 247_000
        });
        assert!(
            unfinished_shadow_state_is_stale(&stale, 269_700),
            "unfinished shadow windows far behind the local head must reset"
        );

        let current = json!({
            "status": "observing",
            "required_full_shadow_epoch_start": 270_001,
            "required_full_shadow_epoch_end": 271_000
        });
        assert!(
            !unfinished_shadow_state_is_stale(&current, 269_700),
            "current or future shadow windows should continue observing"
        );

        let completed = json!({
            "status": "pass",
            "required_full_shadow_epoch_start": 246_001,
            "required_full_shadow_epoch_end": 247_000
        });
        assert!(
            !unfinished_shadow_state_is_stale(&completed, 269_700),
            "completed shadow evidence should not be reset by the observation helper"
        );
    }

