    #[test]
    fn validator_set_rpc_snapshot_rejects_inconsistent_hashes() {
        let source = OnboardingRpcSource {
            label: "local-validator".to_string(),
            role: "local_validator".to_string(),
            endpoint: "http://127.0.0.1:5640".to_string(),
            public_rpc: false,
        };
        let snapshot = json!({
            "chain_id": TESTNET_CHAIN_ID,
            "snapshot_format_version": TESTNET_VALIDATOR_SET_SNAPSHOT_FORMAT_VERSION,
            "protocol_version": TESTNET_VALIDATOR_PROTOCOL_VERSION,
            "binary_version": env!("CARGO_PKG_VERSION"),
            "epoch_id": 42,
            "validator_set_version": 7,
            "effective_from_height": 247_000,
            "active_validators": ["synv11yc4cjehqjm6fp0ey4ppjptv0p3cwdy6r79t"],
            "quorum_threshold": 1,
            "validator_set_hash": "canonical-hash",
            "local_validator_set_hash": "different-hash",
            "network_validator_set_hash": "canonical-hash",
        });

        let error = validate_validator_set_rpc_snapshot(&source, snapshot)
            .expect_err("inconsistent hashes must fail closed");
        assert!(error.contains("internally inconsistent"));
    }

    #[test]
    fn validator_runtime_binary_version_reads_nested_snapshot() {
        let response = json!({
            "snapshot": {
                "binary_version": "19.0.45"
            }
        });

        assert_eq!(
            validator_runtime_binary_version(&response).as_deref(),
            Some("19.0.45")
        );
        assert_eq!(
            validator_runtime_binary_version(&json!({"runtimeVersion": "19.0.44"})).as_deref(),
            Some("19.0.44")
        );
        assert_eq!(validator_runtime_binary_version(&json!({})), None);
    }

