    #[test]
    fn stake_transaction_proof_requires_the_canonical_amount_field() {
        let wallet = "syn1owner";
        let validator = "synv1validator";
        let required = MINIMUM_STAKE_SNRG * TOKEN_SCALE;
        let required_funding = VALIDATOR_FUNDING_SNRG * TOKEN_SCALE;
        let canonical = json!({
            "sender": wallet,
            "chain_id": TESTNET_CHAIN_ID,
            "network_id": TESTNET_NETWORK_ID_V2,
            "data": format!(
                "stake:{{\"validator\":\"{validator}\",\"token\":\"SNRG\",\"amount\":{required},\"amountNwei\":\"{required}\"}}"
            ),
        });
        assert_eq!(
            stake_transaction_amount_from_payload(&canonical, wallet, validator, required),
            Ok(required)
        );

        let legacy_funding = json!({
            "sender": wallet,
            "receiver": validator,
            "chain_id": TESTNET_CHAIN_ID,
            "network_id": TESTNET_NETWORK_ID_V2,
            "data": format!(
                "stake:{{\"validator\":\"{validator}\",\"token\":\"SNRG\",\"amountNwei\":\"{required_funding}\"}}"
            ),
        });
        let (kind, amount) = validator_transaction_from_payload(
            &legacy_funding,
            wallet,
            validator,
            required,
            required_funding,
        )
        .expect("legacy amountNwei transfer should be recognized as validator funding");
        assert_eq!(kind, ValidatorTransactionKind::ValidatorFunding);
        assert_eq!(amount, required_funding);
        let error =
            stake_transaction_amount_from_payload(&legacy_funding, wallet, validator, required)
                .expect_err("legacy amountNwei funding must never count as bonded stake");
        assert!(error.contains("not a validator stake"));
    }

