    #[test]
    fn setup_node_honors_node_address_override() {
        with_temp_home(|_| {
            let runtime = tokio::runtime::Runtime::new().expect("tokio runtime");
            let override_address = "synv11s7hag82s6d9f8urrv5cl40lyeamxelthpeg".to_string();
            let result = runtime
                .block_on(testnet_setup_node(TestnetSetupInput {
                    role_id: "validator".to_string(),
                    display_label: Some("Validator Override".to_string()),
                    intended_directory: None,
                    public_host: None,
                    public_p2p_port: None,
                    nat_mode: None,
                    node_address_override: Some(override_address.clone()),
                    identity_passphrase: Some("test-passphrase".to_string()),
                    packaged_validator_identity: None,
                    skip_canonical_manifests: false,
                }))
                .expect("setup should succeed");

            assert_eq!(result.node.node_address, override_address);

            let node_toml = fs::read_to_string(config_path_for(&result.node, "node.toml"))
                .expect("node.toml should exist");
            assert!(
                node_toml
                    .contains("validator_address = \"synv11s7hag82s6d9f8urrv5cl40lyeamxelthpeg\""),
                "node.toml should be rendered with the override address"
            );
            assert!(
                result
                    .node
                    .connectivity_status
                    .contains("Secure network enrollment required"),
                "new validators should remain closed until Innernet enrollment"
            );

            let node_value: toml::Value =
                toml::from_str(&node_toml).expect("node.toml should parse");
            assert_eq!(
                node_value
                    .get("node")
                    .and_then(|section| section.get("auto_register_validator"))
                    .and_then(toml::Value::as_bool),
                Some(false)
            );
            let bootnodes = node_value
                .get("network")
                .and_then(|section| section.get("bootnodes"))
                .and_then(toml::Value::as_array)
                .expect("bootnodes array should exist");
            assert!(bootnodes.is_empty());
            assert!(
                node_value
                    .get("network")
                    .and_then(|section| section.get("bootstrap_dns_records"))
                    .and_then(toml::Value::as_array)
                    .expect("bootstrap_dns_records array should exist")
                    .is_empty(),
                "validator override must not enable public bootstrap discovery before Innernet enrollment"
            );
            let additional_targets = node_value
                .get("network")
                .and_then(|section| section.get("additional_dial_targets"))
                .and_then(toml::Value::as_array)
                .expect("additional_dial_targets array should exist");
            assert!(
                additional_targets
                    .iter()
                    .filter_map(toml::Value::as_str)
                    .all(|value| !value.contains("10.69.10.") && !value.contains("192.168.")),
                "validator override must not use validator VPN transport routes as direct dial targets"
            );
        });
    }

    #[test]
    fn setup_node_writes_onboarding_monitoring_artifacts() {
        with_temp_home(|_| {
            let runtime = tokio::runtime::Runtime::new().expect("tokio runtime");
            let result = runtime
                .block_on(testnet_setup_node(TestnetSetupInput {
                    role_id: "validator".to_string(),
                    display_label: Some("Validator Monitoring Test".to_string()),
                    intended_directory: None,
                    public_host: Some("93.184.216.37".to_string()),
                    public_p2p_port: None,
                    nat_mode: None,
                    node_address_override: None,
                    identity_passphrase: Some("test-passphrase".to_string()),
                    packaged_validator_identity: None,
                    skip_canonical_manifests: false,
                }))
                .expect("setup should succeed");

            assert_eq!(result.monitoring.runtime_metrics_port, TESTNET_METRICS_PORT);
            assert_eq!(
                result.monitoring.host_metrics_port,
                TESTNET_NODE_EXPORTER_PORT
            );
            assert!(!result.monitoring.qrpc_public);
            assert_eq!(
                result.monitoring.runtime_metrics_url.as_deref(),
                Some("http://93.184.216.37:6030/metrics")
            );
            assert_eq!(
                result.monitoring.host_metrics_url.as_deref(),
                Some("http://93.184.216.37:9100/metrics")
            );
            for path in &result.monitoring.generated_paths {
                assert!(
                    Path::new(path).is_file(),
                    "missing monitoring artifact: {path}"
                );
            }

            let registration: Value = serde_json::from_str(
                &fs::read_to_string(&result.monitoring.registration_path)
                    .expect("registration should read"),
            )
            .expect("registration should parse");
            assert_eq!(
                registration
                    .get("qrpc")
                    .and_then(|value| value.get("public"))
                    .and_then(Value::as_bool),
                Some(false)
            );
            assert_eq!(
                registration
                    .get("host_metrics")
                    .and_then(|value| value.get("port"))
                    .and_then(Value::as_u64),
                Some(u64::from(TESTNET_NODE_EXPORTER_PORT))
            );

            let proof = runtime
                .block_on(testnet_run_validator_onboarding(
                    &AppContext::from_env(),
                    TestnetValidatorOnboardingInput {
                        node_id: result.node.id.clone(),
                        dry_run: Some(true),
                        auto_start: Some(false),
                        auto_resync_time: Some(false),
                        auto_stake: Some(false),
                        auto_activate: Some(false),
                        sync_mode: None,
                    },
                ))
                .expect("proof-only onboarding should run");
            assert!(
                proof
                    .steps
                    .iter()
                    .any(|step| { step.id == "monitoring-registration" && step.status == "pass" }),
                "proof-only onboarding should verify monitoring registration"
            );
        });
    }

