    #[test]
    fn canonical_validator_config_uses_vpn_identity_targets() {
        with_temp_home(|_| {
            let root = ensure_testnet_root().expect("testnet root should exist");
            let workspace = root.join("validator-vpn-routing");
            let network_profile =
                load_or_create_network_profile(&root).expect("network profile should exist");
            let role = find_role_profile("validator").expect("validator role should exist");
            let peers = canonical_testnet_validator_peers();
            let canonical_address = peers
                .first()
                .expect("canonical validator peers should exist")
                .address
                .clone();

            let node_toml = build_node_toml(
                "testnet-private-validator",
                "VPN Routing Validator",
                &role,
                &canonical_address,
                &workspace,
                Some("62.146.182.207"),
                &network_profile,
                role_overlay_for("validator").as_str(),
                4,
                None,
                None,
            );
            let value: toml::Value = toml::from_str(&node_toml).expect("node.toml should parse");

            assert_eq!(
                value
                    .get("p2p")
                    .and_then(|section| section.get("public_address"))
                    .and_then(toml::Value::as_str),
                Some(canonical_address.as_str())
            );
            let bootnodes = extract_toml_string_array(&value, "network", "bootnodes");
            let seed_servers = extract_toml_string_array(&value, "network", "seed_servers");
            let bootstrap_dns_records =
                extract_toml_string_array(&value, "network", "bootstrap_dns_records");
            assert!(bootnodes.is_empty());
            assert!(seed_servers.is_empty());
            assert!(bootstrap_dns_records.is_empty());

            let targets = extract_toml_string_array(&value, "network", "persistent_peers");
            assert!(
                targets.iter().any(|target| target.starts_with("synv1")),
                "validator peer targets must use stable synv1 identities: {targets:?}"
            );
            assert!(
                targets.contains(&"10.70.20.1:5622".to_string())
                    && targets.contains(&"10.70.20.2:5622".to_string())
                    && targets.contains(&"10.70.20.3:5622".to_string()),
                "validators must retain relayer support targets over the VPN: {targets:?}"
            );
            assert!(
                !targets.iter().any(|target| target.starts_with("10.69.10.")),
                "validator peer targets must not use validator VPN transport routes: {targets:?}"
            );

            let transports = value
                .get("network")
                .and_then(|section| section.get("validator_vpn_transports"))
                .and_then(toml::Value::as_array)
                .expect("validator_vpn_transports should exist");
            assert_eq!(
                transports.len(),
                peers.len().saturating_sub(1),
                "every other canonical validator needs a VPN transport mapping"
            );
            assert!(
                transports.iter().all(|transport| transport
                    .get("dial_address")
                    .and_then(toml::Value::as_str)
                    .is_some_and(|address| address.starts_with("10.70.10."))),
                "canonical validator transport mappings must use the active Innernet validator subnet: {transports:?}"
            );
            assert!(
                transports.iter().all(|transport| transport
                    .get("dial_address")
                    .and_then(toml::Value::as_str)
                    .is_none_or(|address| !address.starts_with("10.69."))),
                "retired static VPN routes must not appear in generated validator config: {transports:?}"
            );
        });
    }

