    #[test]
    fn validator_funding_record_round_trips_and_clears_only_matching_hash() {
        let temp = TempDir::new().expect("temporary evidence root");
        let path = temp.path().join("validator-funding-pending.json");
        let record = ValidatorFundingPendingRecord {
            version: 1,
            node_id: "validator-1".to_string(),
            validator_address: "synv1validator".to_string(),
            owner_wallet_address: "synw1operator".to_string(),
            tx_hash: "0x0123456789abcdef".to_string(),
            expected_amount_nwei: (VALIDATOR_FUNDING_SNRG * TOKEN_SCALE).to_string(),
            recorded_at_utc: "2026-07-10T00:00:00Z".to_string(),
        };

        write_validator_funding_pending(&path, &record).expect("write funding record");
        assert_eq!(
            read_validator_funding_pending(&path)
                .expect("read funding record")
                .expect("record should exist")
                .tx_hash,
            record.tx_hash
        );
        clear_validator_funding_pending(&path, "0xdifferent").expect("non-matching clear");
        assert!(
            path.exists(),
            "different transaction must not clear the pending record"
        );
        clear_validator_funding_pending(&path, &record.tx_hash).expect("matching clear");
        assert!(
            !path.exists(),
            "matching transaction should clear the pending record"
        );
    }

    #[test]
    fn validator_self_bond_file_lock_serializes_remote_processes() {
        let temp = TempDir::new().expect("temporary evidence root");
        let submission_path = temp.path().join("validator-self-bond-pending.json");
        let first = ValidatorBondFileLock::acquire_path(&submission_path, "synv1validator")
            .expect("first process should reserve the self-bond operation");
        let second = ValidatorBondFileLock::acquire_path(&submission_path, "synv1validator")
            .expect_err("a concurrent process must not reserve the same self-bond operation");
        assert!(second.contains("already running"));
        drop(first);
        ValidatorBondFileLock::acquire_path(&submission_path, "synv1validator")
            .expect("reservation should be released when the operation exits");
    }

