    #[test]
    fn validator_bond_and_funding_requirements_are_distinct() {
        assert_eq!(MINIMUM_STAKE_SNRG, 50_000);
        assert_eq!(VALIDATOR_FUNDING_SNRG, 50_001);
        assert_eq!(VALIDATOR_FEE_RESERVE_SNRG, 1);
        assert_eq!(
            validator_funding_status(MINIMUM_STAKE_SNRG * TOKEN_SCALE, 0),
            FEE_RESERVE_REQUIRED_STATUS
        );
        assert_eq!(
            validator_funding_status(VALIDATOR_FUNDING_SNRG * TOKEN_SCALE, 0),
            "pass"
        );
        assert_eq!(
            validator_funding_status(
                VALIDATOR_FEE_RESERVE_SNRG * TOKEN_SCALE,
                MINIMUM_STAKE_SNRG * TOKEN_SCALE,
            ),
            "pass"
        );
        assert_eq!(
            validator_funding_status(0, MINIMUM_STAKE_SNRG * TOKEN_SCALE),
            FEE_RESERVE_REQUIRED_STATUS
        );
        assert_eq!(
            validator_fee_reserve_required_message(),
            "Validator funding requires 50,001 SNRG: 50,000 SNRG bond plus 1 SNRG fee reserve."
        );
    }

    #[test]
    fn exact_bond_funding_is_rejected_but_exact_bond_stake_is_valid() {
        let funding = |amount: u64| {
            json!({
                "sender": "synw1operator",
                "receiver": "synv1validator",
                "chain_id": TESTNET_CHAIN_ID,
                "network_id": TESTNET_NETWORK_ID_V2,
                "data": format!(
                    "token_transfer:{}",
                    json!({
                        "to": "synv1validator",
                        "token": TOKEN_SYMBOL,
                        "amount": amount,
                    })
                ),
            })
        };
        let error = validator_transaction_from_payload(
            &funding(MINIMUM_STAKE_SNRG * TOKEN_SCALE),
            "synw1operator",
            "synv1validator",
            MINIMUM_STAKE_SNRG * TOKEN_SCALE,
            VALIDATOR_FUNDING_SNRG * TOKEN_SCALE,
        )
        .expect_err("50,000 SNRG funding must leave a fee reserve");
        assert_eq!(error, validator_fee_reserve_required_message());

        let (kind, amount) = validator_transaction_from_payload(
            &funding(VALIDATOR_FUNDING_SNRG * TOKEN_SCALE),
            "synw1operator",
            "synv1validator",
            MINIMUM_STAKE_SNRG * TOKEN_SCALE,
            VALIDATOR_FUNDING_SNRG * TOKEN_SCALE,
        )
        .expect("50,001 SNRG funding should be accepted");
        assert_eq!(kind, ValidatorTransactionKind::ValidatorFunding);
        assert_eq!(amount, VALIDATOR_FUNDING_SNRG * TOKEN_SCALE);

        let bond = json!({
            "sender": "synv1validator",
            "chain_id": TESTNET_CHAIN_ID,
            "network_id": TESTNET_NETWORK_ID_V2,
            "data": format!(
                "stake:{}",
                json!({
                    "validator": "synv1validator",
                    "token": TOKEN_SYMBOL,
                    "amount": MINIMUM_STAKE_SNRG * TOKEN_SCALE,
                })
            ),
        });
        let (kind, amount) = validator_transaction_from_payload(
            &bond,
            "synv1validator",
            "synv1validator",
            MINIMUM_STAKE_SNRG * TOKEN_SCALE,
            VALIDATOR_FUNDING_SNRG * TOKEN_SCALE,
        )
        .expect("the protocol bond remains exactly 50,000 SNRG");
        assert_eq!(kind, ValidatorTransactionKind::ProtocolStake);
        assert_eq!(amount, MINIMUM_STAKE_SNRG * TOKEN_SCALE);

        let oversized_bond = json!({
            "sender": "synv1validator",
            "chain_id": TESTNET_CHAIN_ID,
            "network_id": TESTNET_NETWORK_ID_V2,
            "data": format!(
                "stake:{}",
                json!({
                    "validator": "synv1validator",
                    "token": TOKEN_SYMBOL,
                    "amount": VALIDATOR_FUNDING_SNRG * TOKEN_SCALE,
                })
            ),
        });
        let error = validator_transaction_from_payload(
            &oversized_bond,
            "synv1validator",
            "synv1validator",
            MINIMUM_STAKE_SNRG * TOKEN_SCALE,
            VALIDATOR_FUNDING_SNRG * TOKEN_SCALE,
        )
        .expect_err("the validator fee reserve must not be included in the self-bond");
        assert!(error.contains("required self-bond is exactly 50000 SNRG"));
    }

    #[test]
    fn exact_bond_surfaces_fee_reserve_status_in_repair_and_blocked_state() {
        let required_stake_nwei = MINIMUM_STAKE_SNRG * TOKEN_SCALE;
        let preflight = ValidatorActivationPreflightResult {
            node_id: "validator-fee-reserve".to_string(),
            generated_at_utc: "2026-07-14T00:00:00Z".to_string(),
            can_stake: false,
            can_activate: false,
            onboarding_policy: None,
            balance_nwei: Some(required_stake_nwei),
            staked_balance_nwei: Some(0),
            required_stake_snrg: MINIMUM_STAKE_SNRG,
            required_stake_nwei,
            required_funding_snrg: VALIDATOR_FUNDING_SNRG,
            required_funding_nwei: validator_funding_requirement_nwei(),
            funding_ready_to_bond: false,
            checks: vec![
                preflight_check(
                    "post-fork-fndsa-metadata",
                    "Post-fork FN-DSA metadata",
                    true,
                    "ready",
                    "",
                ),
                preflight_check(
                    "fndsa-consensus-key",
                    "FN-DSA consensus key",
                    true,
                    "ready",
                    "",
                ),
                NodeReadinessCheck {
                    id: "liquid-balance".to_string(),
                    label: "Validator funding".to_string(),
                    status: FEE_RESERVE_REQUIRED_STATUS.to_string(),
                    detail: validator_fee_reserve_required_message(),
                    suggestion: Some(validator_fee_reserve_required_message()),
                },
            ],
        };

        let actions = repair_actions_for_preflight(&preflight);
        let repair = actions
            .iter()
            .find(|action| action.id == "approve-mobile-wallet-stake")
            .expect("fee reserve should produce a funding repair action");
        assert_eq!(repair.label, "Add Validator Fee Reserve");
        assert_eq!(repair.detail, validator_fee_reserve_required_message());

        let (state, message, next_action) = validator_onboarding_blocked_state(&preflight);
        assert_eq!(state, "PAUSED");
        assert_eq!(message, validator_fee_reserve_required_message());
        assert_eq!(next_action, "fund_validator");
    }

