    #[test]
    fn preserved_validator_workspace_reconstructs_missing_registry_entry() {
        with_temp_home(|home| {
            let runtime = tokio::runtime::Runtime::new().expect("tokio runtime");
            let result = runtime
                .block_on(testnet_setup_node(TestnetSetupInput {
                    role_id: "validator".to_string(),
                    display_label: Some("Preserved Validator".to_string()),
                    intended_directory: None,
                    public_host: Some("93.184.216.37".to_string()),
                    public_p2p_port: Some(TESTNET_P2P_PORT),
                    nat_mode: Some("router_port_forward".to_string()),
                    node_address_override: None,
                    identity_passphrase: Some("preserved-passphrase".to_string()),
                    packaged_validator_identity: None,
                    skip_canonical_manifests: false,
                }))
                .expect("validator workspace should provision");
            let workspace = PathBuf::from(&result.node.workspace_directory);
            let identity_before = fs::read_to_string(workspace.join("identity/identity.json"))
                .expect("identity should exist before registry loss");
            let chain_before = workspace.join("state/store");
            fs::create_dir_all(&chain_before).expect("state store should exist");
            fs::write(chain_before.join("preserved.marker"), "do-not-delete")
                .expect("preserved chain marker should write");

            let root = ensure_testnet_root().expect("testnet root should exist");
            fs::remove_file(registry_path(&root)).expect("registry should be removed");
            let state = testnet_get_state().expect("state should reconstruct from workspace");
            assert_eq!(state.nodes.len(), 1);
            assert_eq!(state.nodes[0].node_address, result.node.node_address);
            assert_eq!(
                fs::read_to_string(workspace.join("identity/identity.json"))
                    .expect("identity should survive reconstruction"),
                identity_before
            );
            assert!(
                workspace.join("state/store/preserved.marker").is_file(),
                "reconstruction must not erase preserved chain data"
            );
            assert!(registry_path(&root).is_file(), "registry should be rebuilt");
            let registry = load_registry(&root).expect("rebuilt registry should parse");
            assert_eq!(registry.nodes[0].node_address, result.node.node_address);
            assert!(home.exists());
        });
    }

